// بيانات السور
Object.assign(quranData, {
    64: { // سورة التغابن
        name: "التغابن",
        basmalaTafsir: ``,
        verses: [
            { text: "يُسَبِّحُ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ لَهُ ٱلْمُلْكُ وَلَهُ ٱلْحَمْدُ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ", tafsir: `لعل التعبير بالماضي في بعض السور باعتبار معنى التسبيح ، وبالمضارع في البعض باعتبار الحال والاستقبال ( لِلَّهِ ) أي ينزهه عن النقائص ( ما فِي السَّماواتِ وَما فِي الْأَرْضِ ) ظرفا ومظروفا ـ كما سبق ـ ( لَهُ الْمُلْكُ ) فهو المالك المطلق الحقيقي ، وسائر المالكين ملكهم محدود ، وإضافي لاختصاص الشيء بتخصيص الله سبحانه لا أنهم ملاك حقيقيون ( وَلَهُ الْحَمْدُ ) ، إذ المحامد كلها راجعة إليه ، فإن الحمد إنما يكون على الجميل الاختياري ، وفاعل كل جميل هو الله سبحانه ، أما سائر من يحمد فهو محمود حمدا مقيدا إضافيا ( وَهُوَ عَلى كُلِّ شَيْءٍ قَدِيرٌ ) يقدر على الإيجاد والإعدام والتصرف كيفما شاء.` },
            { text: "هُوَ ٱلَّذِى خَلَقَكُمْ فَمِنكُمْ كَافِرٌ وَمِنكُم مُّؤْمِنٌ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ", tafsir: `الله ( الَّذِي خَلَقَكُمْ ) أيها البشر ( فَمِنْكُمْ كافِرٌ ) بالله بسوء اختياره بعد وضوح الحجة وظهور المحجة ( وَمِنْكُمْ مُؤْمِنٌ ) بالله وبما جاء به الرسل ، وهذا التفريع لبيان أنه لا ينبغي الكفر بعد كون الملك والخلق له سبحانه ، وبعد تسبيح الكون لعظمته ( وَاللهُ بِما تَعْمَلُونَ ) أنتم أيها البشر ( بَصِيرٌ ) يرى الأشياء ، ثم يجازيكم عليها.` },
            { text: "خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ وَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ وَإِلَيْهِ ٱلْمَصِيرُ", tafsir: `ظرفا ومظروفا ( بِالْحَقِ ) فلم يكن الخلق عبثا ولغوا ، كما يفعل الأطفال ، من صنع التماثيل من طير ونحوه للهو ، فإن خلقها كان لحكمة وغاية ومقصد ( وَصَوَّرَكُمْ ) بأن جعل فَأَحْسَنَ صُوَرَكُمْ وَإِلَيْهِ الْمَصِيرُ (3) يَعْلَمُ ما فِي السَّماواتِ وَالْأَرْضِ وَيَعْلَمُ ما تُسِرُّونَ وَما تُعْلِنُونَ وَاللهُ عَلِيمٌ بِذاتِ الصُّدُورِ (4) أَ لَمْ يَأْتِكُمْ نَبَأُ الَّذِينَ كَفَرُوا مِنْ قَبْلُ فَذاقُوا وَبالَ أَمْرِه ِمْ وَلَهُمْ عَذابٌ أَلِيمٌ (5) لكم الصور الظاهرة من الحواس والكيفيات والصور الباطنة بأن جعل لكم العقل والملكات ( فَأَحْسَنَ صُوَرَكُمْ ) بصورة عامة ، وإن كان في البشر من ليس حسن الصورة ، فإن الأحكام يراد بها النوع لا كل فرد ـ كما قرر في علمي البلاغة والأصول ـ ( وَإِلَيْهِ الْمَصِيرُ ) أي تصيرون إلى حسابه وجزائه بعد الموت ، أو في القيامة.` },
            { text: "يَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَيَعْلَمُ مَا تُسِرُّونَ وَمَا تُعْلِنُونَ وَٱللَّهُ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ", tafsir: `ما في ( الْأَرْضِ ) مما يحدث وما يعدم وما يتصرف فيه كيف يتصرف ( وَيَعْلَمُ ما تُسِرُّونَ ) أي تعملونه سرا عن الناس ( وَما تُعْلِنُونَ ) تعملونه علنا في محضر الناس ، أو المراد من السر الأعم مما يدور في الصدور وما يعمل سرا ( وَاللهُ عَلِيمٌ بِذاتِ الصُّدُورِ ) أي بالأشياء التي تدور في قلوب البشر ، وهذا يؤيد كون « ما تسرون » بمعنى تعملون سرا لا الأعم ، وإلا كان تأكيدا ـ وهو خلاف الأصل ـ . [6] وإذ بين السياق آيات حول الألوهية ، جاء ليهدد الكافرين الذين أعرضوا عن الله والإيمان به بقوله ( أَ لَمْ يَأْتِكُمْ ) أيها الناس ( نَبَأُ ) أي خبر ( الَّذِينَ كَفَرُوا مِنْ قَبْلُ ) هؤلاء الكفار المعاصرين للرسول صلى‌الله‌عليه‌وآله‌وسلم حيث إنهم أعرضوا عن الإيمان ( فَذاقُوا وَبالَ أَمْرِهِمْ ) أي عذبهم الله سبحانه حتى ذاقوا عاقبة كفرهم وتكذيبهم ( وَلَهُمْ عَذابٌ أَلِيمٌ ) أي مؤلم موجع ذلِكَ بِأَنَّهُ كانَتْ تَأْتِيهِمْ رُسُلُهُمْ بِالْبَيِّناتِ فَقالُوا أَ بَشَرٌ يَهْدُونَنا فَكَفَرُوا وَتَوَلَّوْا وَاسْتَغْنَى اللهُ وَاللهُ غَنِيٌّ حَمِيدٌ (6) زَعَمَ الَّذِينَ كَفَرُوا أَنْ لَنْ يُبْعَثُوا قُلْ بَلى في الآخرة بالإضافة إلى العذاب الذي ذاقوه في الدنيا.` },
            { text: "أَلَمْ يَأْتِكُمْ نَبَؤُا۟ ٱلَّذِينَ كَفَرُوا۟ مِن قَبْلُ فَذَاقُوا۟ وَبَالَ أَمْرِهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ", tafsir: `` },
            { text: "ذَٰلِكَ بِأَنَّهُۥ كَانَت تَّأْتِيهِمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَقَالُوٓا۟ أَبَشَرٌ يَهْدُونَنَا فَكَفَرُوا۟ وَتَوَلَّوا۟ وَّٱسْتَغْنَى ٱللَّهُ وَٱللَّهُ غَنِىٌّ حَمِيدٌ", tafsir: `العذاب إنما شملهم وأخذهم بسبب أنه ( كانَتْ تَأْتِيهِمْ رُسُلُهُمْ ) من عند الله ( بِالْبَيِّناتِ ) أي بالأدلة الظاهرة والحجج والمعاجز ( فَقالُوا ) أولئك الكفار ، في رد دعوة الرسل ( أَ بَشَرٌ يَهْدُونَنا ) أي كيف يمكن أن يكون الرسول الذي هو بشر مثلنا يهدينا ؟ و « بشر » جنس ولذا جيء له بصيغة الجمع « يهدوننا » ( فَكَفَرُوا ) بالرسل وبما جاءوا به ( وَتَوَلَّوْا ) أي أعرضوا عن قبول الحق ( وَاسْتَغْنَى اللهُ ) أي فعل فعل المستغني عن الشيء وهو تركه وشأنه ، وهذا بعد أن طلب منهم الهداية والرشاد فلم يقبلوا ، وإنما جيء من باب « الاستفعال » الظاهر في الطلب ، لأن الغناء في المتعارف إنما يأتي بعقب الطلب فهو من باب التشبيه بالمحسوس ، وإذ كان الكلام موهما لاحتياج الله بهم قبل ذلك جاء السياق ليدفع هذا التوهم بقوله ( وَاللهُ غَنِيٌ ) بذاته لا يحتاج إلى شيء ولا أحد ( حَمِيدٌ ) بأفعاله لا يحتاج إلى أن يحمد ولا ينقص عن كونه محمودا بالذات عدم حمد الناس له. [8] إن الكفار تولوا عن الإيمان بالله وعن الإيمان بالرسل ، وكذلك تولوا عن الإيمان بالبعث ( زَعَمَ الَّذِينَ كَفَرُوا ) فلم يكن ذلك تيقنا بل زعما وظنا ( أَنْ لَنْ يُبْعَثُوا ) بعد الموت ، ولن يحيوا للحساب والجزاء ( قُلْ ) يا رسول الله ردّا لزعمهم ( بَلى ) ليس الأمر كما زعمتم وَرَبِّي لَتُبْعَثُنَّ ثُمَّ لَتُنَبَّؤُنَّ بِما عَمِلْتُمْ وَذلِكَ عَلَى اللهِ يَسِيرٌ (7) فَآمِنُوا بِاللهِ وَرَسُولِهِ وَالنُّورِ الَّذِي أَنْزَلْنا وَاللهُ بِما تَعْمَلُونَ خَبِيرٌ (8) يَوْمَ يَجْمَعُكُمْ لِيَوْمِ الْجَمْعِ ذلِكَ يَوْمُ التَّغابُنِ ( وَ ) حق ( رَبِّي ) الله ، بل ( لَتُبْعَثُنَ ) أي لتحشرن أحياء بعد الموت ( ثُمَّ لَتُنَبَّؤُنَ ) أي تخبرن ـ على صيغة المجهول ـ والمخبر هو الله والملائكة والأنبياء ومن يعينونه للحساب والإخبار ( بِما عَمِلْتُمْ ) من الكفر والمعاصي ، فإن المجرم يخبر بعمله ثم يعاقب ( وَذلِكَ ) البعث والإخبار ( عَلَى اللهِ ) تعالى ( يَسِيرٌ ) سهل هين ، فإن من خلق الخلق ابتداء قادر على أن يعيدهم. [9] وإذا تحقق البعث والحساب وتحقق الجزاء ( فَآمِنُوا ) أيها البشر ( بِاللهِ وَرَسُولِهِ ) بالإذعان بهما واتباع أوامرهما ( وَالنُّورِ الَّذِي أَنْزَلْنا ) وهو القرآن إذ هو ينير سبيل الحياة المظلمة ليرى الإنسان طريقه نحو السعادة ومن المعلوم أن الأئمة عليهم‌السلام من مصاديق ذلك النور ـ كما ورد (1) ـ ( وَاللهُ بِما تَعْمَلُونَ ) أيها البشر ( خَبِيرٌ ) عالم مطلع ، فإذا آمنتم جزاكم بالثواب والأجر ولا يذهب إيمانكم هدر. [10] وذلك البعث والجزاء إنما يكون في ( يَوْمَ يَجْمَعُكُمْ ) الله ( لِيَوْمِ ) يسمى بيوم ( الْجَمْعِ ) لاجتماع الخلائق فيه للحساب ( ذلِكَ ) اليوم ( يَوْمُ التَّغابُنِ ) وهو تفاعل من الغبن بأن يغبن كلّ الآخر ، فإن أهل الجنة يغبنون أهل النار باتخاذ منازلهم في الجنة ـ فإن لكل إنسان منزل في الجنة ومنزل في النار ـ وبالعكس يغبن أهل النار أهل الجنة باتخاذ ( 1) التحصين لابن طاووس : ص 585. وَمَنْ يُؤْمِنْ بِاللهِ وَيَعْمَلْ صالِحاً يُكَفِّرْ عَنْهُ سَيِّئاتِهِ وَيُدْخِلْهُ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهارُ خالِدِينَ فِيها أَبَداً ذلِكَ الْفَوْزُ الْعَظِيمُ (9) وَالَّذِينَ كَفَرُوا وَكَذَّبُوا بِآياتِنا أُولئِكَ أَصْحابُ النَّارِ خالِدِينَ فِيها وَبِئْسَ الْمَصِيرُ (10) منازلهم في النار ـ وتسمية هذا الطرف : غبنا من باب الجناس ، من قبيل ( فَمَنِ اعْتَدى عَلَيْكُمْ فَاعْتَدُوا عَلَيْهِ بِمِثْلِ مَا اعْتَدى عَلَيْكُمْ ) (1) ـ . ( وَمَنْ يُؤْمِنْ بِاللهِ ) بأن يعتقد به وينزهه عما لا يليق به ( وَيَعْمَلْ صالِحاً ) أي عملا صالحا ، والمراد به جنس العمل الصالح ، لا عملا واحدا ( يُكَفِّرْ ) الله ( عَنْهُ سَيِّئاتِهِ ) أي يمحي عن ديوانه ما أسلف من الذنوب والمعاصي ، فإن التكفير بمعنى الستر والمحو ( وَيُدْخِلْهُ ) الله سبحانه ( جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا ) أي من تحت قصورها وأشجارها ( الْأَنْهارُ ) من عسل وخمر ولبن وماء ، في حال كونهم ( خالِدِينَ فِيها ) أي دائمين في تلك الجنات ( أَبَداً ) لا زوال لهم عنها إلى غير النهاية ( ذلِكَ ) الدخول في الجنة خالدا ، هو ( الْفَوْزُ الْعَظِيمُ ) والفلاح الذي ليس وراءه فلاح.` },
            { text: "زَعَمَ ٱلَّذِينَ كَفَرُوٓا۟ أَن لَّن يُبْعَثُوا۟ قُلْ بَلَىٰ وَرَبِّى لَتُبْعَثُنَّ ثُمَّ لَتُنَبَّؤُنَّ بِمَا عَمِلْتُمْ وَذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌ", tafsir: `` },
            { text: "فَـَٔامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَٱلنُّورِ ٱلَّذِىٓ أَنزَلْنَا وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ", tafsir: `` },
            { text: "يَوْمَ يَجْمَعُكُمْ لِيَوْمِ ٱلْجَمْعِ ذَٰلِكَ يَوْمُ ٱلتَّغَابُنِ وَمَن يُؤْمِنۢ بِٱللَّهِ وَيَعْمَلْ صَٰلِحًا يُكَفِّرْ عَنْهُ سَيِّـَٔاتِهِۦ وَيُدْخِلْهُ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًا ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ", tafsir: `` },
            { text: "وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ خَٰلِدِينَ فِيهَا وَبِئْسَ ٱلْمَصِيرُ", tafsir: `بالله ورسوله ( وَكَذَّبُوا بِآياتِنا ) أي بحججنا وأدلتنا ( أُولئِكَ أَصْحابُ النَّارِ ) الملازمون لها ، فإن صاحب الشيء هو الملازم له في حال كونهم ( خالِدِينَ فِيها ) أي باقون فيها أبدا ( وَبِئْسَ الْمَصِيرُ ) أي بئس النار مرجعا ومآلا للإنسان. ( 1) البقرة : 195. ما أَصابَ مِنْ مُصِيبَةٍ إِلاَّ بِإِذْنِ اللهِ وَمَنْ يُؤْمِنْ بِاللهِ يَهْدِ قَلْبَهُ وَاللهُ بِكُلِّ شَيْءٍ عَلِيمٌ (11) [12] وإذ دعا سبحانه إلى الإيمان بيّن بعض ثمار الإيمان الطيبة التي ينالها الإنسان في هذه الدنيا قبل الفوز بالجنان في الآخرة ، وقدم لذلك مقدمة بقوله ( ما أَصابَ مِنْ مُصِيبَةٍ ) أي لا تصيب الإنسان مصيبة ولا يقع الإنسان في مشكلة ( إِلَّا بِإِذْنِ اللهِ ) فالله سبحانه هو الذي يقدر الأشياء فلو لا تقديره لم يقع شيء في الكون ، فإن الله سبحانه قادر على أن يسكن الكوارث حتى لا تنزل بالإنسان ، وإنما قرر سبحانه المصائب لتنزل بالإنسان للامتحان والاختبار ، وليس معنى ذلك أن المصائب السيئة ينزلها الله سبحانه ، بل معناه أنه تعالى لا يأخذ أمامها حتى لا تنزل ، فمن يقتل ظلما ـ بإذن الله ـ أي لا يمنع الله القاتل ـ منعا تكوينيا بأن تشل يده ـ حتى لا يتمكن من القتل وإنما يأذن ولا يأخذ بيد القاتل لكون الدنيا دار اختبار ، فلو كان سبحانه يجبر على ترك القبيح لكان الإنسان بمنزلة الحجر والجماد في أفعاله الاضطرارية ويبطل الثواب والعقاب. وإذ قدم السياق هذه المقدمة ، أتى إلى ثمرة الإيمان بقوله ( وَمَنْ يُؤْمِنْ بِاللهِ ) إيمانا صحيحا راسخا ( يَهْدِ ) الله ( قَلْبَهُ ) حتى يطمئن بأن ما يصيبه إنما هو بعلم الله ، وأنه يجازيه بالثواب والأجر على ما أصابه ، وإذا علم الإنسان أن ما أصابه من الضرر يتدارك بأضعاف الخير ، اطمأن قلبه ولم تصدمه المصيبة كثيرا ( وَاللهُ بِكُلِّ شَيْءٍ عَلِيمٌ ) فيجازي كل امرء بما عمل. وَأَطِيعُوا اللهَ وَأَطِيعُوا الرَّسُولَ فَإِنْ تَوَلَّيْتُمْ فَإِنَّما عَلى رَسُولِنَا الْبَلاغُ الْمُبِينُ (12) اللهُ لا إِلهَ إِلاَّ هُوَ وَعَلَى اللهِ فَلْيَتَوَكَّلِ الْمُؤْمِنُونَ (13) يا أَيُّهَا الَّذِينَ آمَنُوا إِنَّ مِنْ أَزْواجِكُمْ وَأَوْلادِكُمْ عَدُوًّا لَكُمْ فَاحْذَرُوهُمْ وَإِنْ تَعْفُوا وَتَصْفَحُوا وَتَغْفِرُوا` },
            { text: "مَآ أَصَابَ مِن مُّصِيبَةٍ إِلَّا بِإِذْنِ ٱللَّهِ وَمَن يُؤْمِنۢ بِٱللَّهِ يَهْدِ قَلْبَهُۥ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌ", tafsir: `` },
            { text: "وَأَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ فَإِن تَوَلَّيْتُمْ فَإِنَّمَا عَلَىٰ رَسُولِنَا ٱلْبَلَٰغُ ٱلْمُبِينُ", tafsir: `أيها البشر في ما أمركم ( وَأَطِيعُوا الرَّسُولَ ) فيما أتاكم به ( فَإِنْ تَوَلَّيْتُمْ ) أي أعرضتم عن الإطاعة ( فَإِنَّما عَلى رَسُولِنَا الْبَلاغُ الْمُبِينُ ) أي أن يبلغكم بلاغا ظاهرا ، وقد بلّغ فليس عليه شيء وإنما يرجع وبال العاقبة إليكم حيث أعرضتم بعد البلاغ.` },
            { text: "ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ", tafsir: `الذي تدعون إلى الإيمان به هو الذي ( لا إِلهَ إِلَّا هُوَ ) فلا شريك له ولا نظير ( وَعَلَى اللهِ فَلْيَتَوَكَّلِ الْمُؤْمِنُونَ ) بأن يكلوا أمورهم إليه ، ويعتمدوا عليه. [15] وإذ دعا السياق الناس إلى الإيمان ، جاء ليبين بعض أعداء المؤمن الذين يثنونه عن الإيمان ليتخذ منهم حذره ( يا أَيُّهَا الَّذِينَ آمَنُوا إِنَّ مِنْ أَزْواجِكُمْ ) أي نسائكم ( وَأَوْلادِكُمْ ) أي بعضهم ، ولذا جيء ب « من » ( عَدُوًّا لَكُمْ ) لأنكم مؤمنون وهم كافرون أو منافقون ( فَاحْذَرُوهُمْ ) أن لا يصدوكم عن الحق والهدى ( وَ ) إذا آذوكم بسبب إيمانكم ف ( إِنْ تَعْفُوا ) عنهم دون الانتقام ( وَتَصْفَحُوا ) وهو أن يعرض الإنسان ويبدي صفحة وجهه أمام المكروه ( وَتَغْفِرُوا ) بأن تستروا ذنبهم فلا تنتقموا منهم ، وكان للأمر ثلاث مراتب : ستر الذنب ، وعدم المقابلة فَإِنَّ اللهَ غَفُورٌ رَحِيمٌ (14) إِنَّما أَمْوالُكُمْ وَأَوْلادُكُمْ فِتْنَةٌ وَاللهُ عِنْدَهُ أَجْرٌ عَظِيمٌ (15) فَاتَّقُوا اللهَ مَا اسْتَطَعْتُمْ حتى بالكلام ، وعدم الانتقام. ( فَإِنَّ اللهَ غَفُورٌ ) لذنوبكم ، أو لذنوبهم ـ إذا تابوا ـ ( رَحِيمٌ ) بعباده ، فعلى المؤمن أن يتعلم الغفران والرحمة منه سبحانه ، وهذا بالإضافة إلى الثواب ، خطة حكيمة في جلب الناس إلى الإيمان ، فإن السلم في مقابل العدو ، يخفف من حدته ويلقي في نفسه حب مبدأ المسالم حتى ينجذب إليه.` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ مِنْ أَزْوَٰجِكُمْ وَأَوْلَٰدِكُمْ عَدُوًّا لَّكُمْ فَٱحْذَرُوهُمْ وَإِن تَعْفُوا۟ وَتَصْفَحُوا۟ وَتَغْفِرُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ", tafsir: `` },
            { text: "إِنَّمَآ أَمْوَٰلُكُمْ وَأَوْلَٰدُكُمْ فِتْنَةٌ وَٱللَّهُ عِندَهُۥٓ أَجْرٌ عَظِيمٌ", tafsir: `أي امتحان لكم ، كي يتبين من يطيع الله فيهما ومن يعصيه وهذا من باب المثال ، وإلا فأقرباء الإنسان وزوجه أيضا فتنة وامتحان ( وَاللهُ عِنْدَهُ أَجْرٌ عَظِيمٌ ) وثواب كبير لمن أطاعه ولم يخالفه لأجل أهله وماله. قال الإمام الباقر عليه‌السلام إن الرجل كان إذا أراد الهجرة إلى رسول الله صلى‌الله‌عليه‌وآله‌وسلم تعلق به ابنه وامرأته وقالوا ننشدك الله أن تذهب عنا وتدعنا فنضيع بعدك ، فمنهم من يطيع أهله فيقيم فحذرهم الله أبناءهم ونساءهم ونهاهم عن طاعتهم ومنهم من يمضي ويذرهم ويقول : أما والله لئن لم تهاجروا معي ثم يجمع الله بيني وبينكم في دار الهجرة لا أنفعكم بشيء أبدا ، فلمّا جمع الله بينه وبينهم أمره الله أن يحسن إليهم ويصلحهم فقال « وإن تعفوا وتصفحوا وتغفروا فإن الله غفور رحيم » (1) .` },
            { text: "فَٱتَّقُوا۟ ٱللَّهَ مَا ٱسْتَطَعْتُمْ وَٱسْمَعُوا۟ وَأَطِيعُوا۟ وَأَنفِقُوا۟ خَيْرًا لِّأَنفُسِكُمْ وَمَن يُوقَ شُحَّ نَفْسِهِۦ فَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ", tafsir: `أي خافوا عقابه ، بامتثال أوامره ( مَا اسْتَطَعْتُمْ ) أي بقدر ( 1) تفسير القمي : ج 2 ص 372. وَاسْمَعُوا وَأَطِيعُوا وَأَنْفِقُوا خَيْراً لِأَنْفُسِكُمْ وَمَنْ يُوقَ شُحَّ نَفْسِهِ فَأُولئِكَ هُمُ الْمُفْلِحُونَ (16) إِنْ تُقْرِضُوا اللهَ قَرْضاً حَسَناً يُضاعِفْهُ لَكُمْ وَيَغْفِرْ لَكُمْ وَاللهُ شَكُورٌ حَلِيمٌ (17) استطاعتكم فإنه لا يكلف الله نفسا إلا وسعها ( وَاسْمَعُوا ) من الرسول ما يأمركم ( وَأَطِيعُوا ) بعد ما سمعتم ، وكأن المراد من السماع أن يستمعوا للعمل ( وَأَنْفِقُوا ) من أموالكم في سبيل الله ( خَيْراً لِأَنْفُسِكُمْ ) أي إنفاقا خيرا ، فإنه عائد لأنفسكم إذ تعطون بدله في الدنيا والآخرة ( وَمَنْ يُوقَ ) أي يحفظ ( شُحَّ نَفْسِهِ ) أي بخلها ، بأن يحفظه الله سبحانه من البخل ، فينفق كما أمر الله سبحانه ( فَأُولئِكَ ) المتصفون بتلك الصفات أو من وقي شح نفسه ( هُمُ الْمُفْلِحُونَ ) الفائزون ، من أفلح بمعنى فاز وظفر بالسعادة. [18] ثم أن هذا المال الذي ينفقه الإنسان لا يذهب ضياعا بلا عوض بل هو بمنزلة قرض يقرضه الإنسان لله سبحانه ، فيرده عليه أضعافا مضاعفة ( إِنْ تُقْرِضُوا اللهَ قَرْضاً حَسَناً ) بأن يكون الإنفاق لله وفي سبيله بلا منّ ولا رياء ولا سمعة ولا حب المدح وما أشبه من مفسدات العمل ( يُضاعِفْهُ ) الله ( لَكُمْ ) أي يعطي بدله أضعافا ، حتى أن الواحد يصل عوضه إلى سبعمائة وأكثر ( وَيَغْفِرْ لَكُمْ ) ذنوبكم بسبب ذلك الإنفاق ( وَاللهُ شَكُورٌ ) أي فاعل الشكر ، فإن الإنسان الشاكر يثني المشكور ويبذل له عوض عمله ، وهكذا الله سبحانه يمدح المعطي ويبذل له عوضه ( حَلِيمٌ ) فلا يعاجل العاصي بالعقوبة ، فهو شاكر للمطيع ، حليم عن العاصي. عالِمُ الْغَيْبِ وَالشَّهادَةِ الْعَزِيزُ الْحَكِيمُ (18) [19] وهو يعلم كل إنفاق وعمل صالح ، فلا يضيع الحسن عنده ، فإنه ( عالِمُ الْغَيْبِ ) ما غاب عن الحواس ( وَالشَّهادَةِ ) ما ظهر ، أي السر والعلانية والمحسوس وغير المحسوس ( الْعَزِيزُ ) الغالب في سلطانه فيقدر على كل شيء ( الْحَكِيمُ ) الذي يفعل الأشياء حسب الحكمة والصلاح. (65)` },
            { text: "إِن تُقْرِضُوا۟ ٱللَّهَ قَرْضًا حَسَنًا يُضَٰعِفْهُ لَكُمْ وَيَغْفِرْ لَكُمْ وَٱللَّهُ شَكُورٌ حَلِيمٌ", tafsir: `` },
            { text: "عَٰلِمُ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ ٱلْعَزِيزُ ٱلْحَكِيمُ", tafsir: `` }
        ]
    },
    65: { // سورة الطلاق
        name: "الطلاق",
        basmalaTafsir: ``,
        verses: [
            { text: "يَٰٓأَيُّهَا ٱلنَّبِىُّ إِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُوا۟ ٱلْعِدَّةَ وَٱتَّقُوا۟ ٱللَّهَ رَبَّكُمْ لَا تُخْرِجُوهُنَّ مِنۢ بُيُوتِهِنَّ وَلَا يَخْرُجْنَ إِلَّآ أَن يَأْتِينَ بِفَٰحِشَةٍ مُّبَيِّنَةٍ وَتِلْكَ حُدُودُ ٱللَّهِ وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَقَدْ ظَلَمَ نَفْسَهُۥ لَا تَدْرِى لَعَلَّ ٱللَّهَ يُحْدِثُ بَعْدَ ذَٰلِكَ أَمْرًا", tafsir: `خطاب للرسول صلى‌الله‌عليه‌وآله‌وسلم وحيث أن خطاب العظيم يراد به هو ومن معه جاء السياق بلفظ الجمع في قوله ( إِذا طَلَّقْتُمُ النِّساءَ ) أي أردتم طلاق النساء ، فإن الفعل يستعمل بمعنى الإرادة ، كما أن الإرادة تستعمل بمعنى الفعل ـ كما سبق ـ ( فَطَلِّقُوهُنَّ لِعِدَّتِهِنَ ) أي وقت عدتهن ، وهي كونهن في طهر غير المواقعة ، فإن « العدة » بمعنى التعداد ، والعدد ، و « لام » لعدتهن ، للتعدية ، أي كون الطلاق في العدة التي هي أيام الطهر ( وَأَحْصُوا الْعِدَّةَ ) أي أحسبوا أيام عدة المرأة التي إذا مرت خرجت من حبالة الزوج الأول وجاز أن تنكح رجلا جديدا ( وَاتَّقُوا اللهَ رَبَّكُمْ ) فلا تخالفوا أمره بالطلاق في حال الحيض ، أو عدم إحصاء العدة حتى تبقى المطلقة تنتظر الانقضاء ، لتكوين بيت جديد ، ولا تعرف ذلك. ( لا تُخْرِجُوهُنَ ) المطلقات ( مِنْ بُيُوتِهِنَ ) أي مساكنهن وقت الطلاق حتى تنقضي العدة ، فإن سكناها ما دامت في العدة على الزوج ( وَلا يَخْرُجْنَ ) هن من البيوت مدة العدة فإن خرجت بلا ضرورة أثمت ( إِلَّا أَنْ يَأْتِينَ بِفاحِشَةٍ ) معصية فاحشة أي متجاوزة في الإثم ( مُبَيِّنَةٍ ) أي ظاهرة كالزنى ، كما روي عن الصادق عليه‌السلام (1) ، فإذا زنت أخرجت عن البيت ليقام عليها الحد ، وفي بعض الروايات تفسيرها بأن ( 1) من لا يحضره الفقيه : ج 3 ص 499. وَتِلْكَ حُدُودُ اللهِ وَمَنْ يَتَعَدَّ حُدُودَ اللهِ فَقَدْ ظَلَمَ نَفْسَهُ لا تَدْرِي لَعَلَّ اللهَ يُحْدِثُ بَعْدَ ذلِكَ أَمْراً (1) فَإِذا بَلَغْنَ أَجَلَهُنَّ فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ أَوْ فارِقُوهُنَّ بِمَعْرُوفٍ وَأَشْهِدُوا ذَوَيْ عَدْلٍ مِنْكُمْ تؤذي أهل البيت بلسانها فإنها تخرج إلى محل آخر وذلك لإيذائها (1) ( وَتِلْكَ ) الأحكام التي ذكرت للطلاق ( حُدُودُ اللهِ وَمَنْ يَتَعَدَّ حُدُودَ اللهِ ) بأن يخالف أحكامه ( فَقَدْ ظَلَمَ نَفْسَهُ ) أي عرضها للعقاب والنكال ، ثم بين سبحانه بعض الحكمة في الأحكام المتقدمة بقوله ( لا تَدْرِي ) النفس ( لَعَلَّ اللهَ ) سبحانه ( يُحْدِثُ بَعْدَ ذلِكَ ) العزم على الطلاق ، أو بعد ذلك الطلاق ، ( أَمْراً ) فإن تأخير الطلاق إلى الطهر الذي لم يواقع فيه ربما يغير من رأي الزوج ، فلا يطلق وجعل العدة وعدم الإخراج من البيت ربما أوجب نزولهما عن الغضب الموجب للطلاق فيتراجعا عما قصدا من الطلاق.` },
            { text: "فَإِذَا بَلَغْنَ أَجَلَهُنَّ فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ أَوْ فَارِقُوهُنَّ بِمَعْرُوفٍ وَأَشْهِدُوا۟ ذَوَىْ عَدْلٍ مِّنكُمْ وَأَقِيمُوا۟ ٱلشَّهَٰدَةَ لِلَّهِ ذَٰلِكُمْ يُوعَظُ بِهِۦ مَن كَانَ يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَمَن يَتَّقِ ٱللَّهَ يَجْعَل لَّهُۥ مَخْرَجًا", tafsir: `النساء المطلقات ( أَجَلَهُنَ ) أي وصلن إلى رأس المدة ـ قبل انقضاء العدة ـ بأن بقيت من العدة شيء ، تخبر الرجل بين أن يرجع إليهن ، أو يذرهن حتى تنقضي العدة ( فَأَمْسِكُوهُنَ ) إن أردتم الرجوع ( بِمَعْرُوفٍ ) أن تعاشروهن كما أمر الله سبحانه بالحسنى ( أَوْ فارِقُوهُنَ ) بأن تدعوهن على حالهن حتى تنقضي العدة ( بِمَعْرُوفٍ ) بدون إيذاء لها ، وأخذ بعض أثاثها ، أو إثارة قلاقل حولها كما هو من فعل الجهال. ( وَأَشْهِدُوا ) إذا أردتم الطلاق ( ذَوَيْ عَدْلٍ مِنْكُمْ ) أي ( 1) وسائل الشيعة : ج 22 ص 220. وَأَقِيمُوا الشَّهادَةَ لِلَّهِ ذلِكُمْ يُوعَظُ بِهِ مَنْ كانَ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ وَمَنْ يَتَّقِ اللهَ يَجْعَلْ لَهُ مَخْرَجاً (2) وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ نفرين عادلين من المسلمين حتى يشهدان على الطلاق ، والعدالة عبارة عن ملكة في النفس تبعث على الإتيان بالواجبات والترك للمحرمات خوفا من الله سبحانه ، والمعنى أنه يلزم حضور شاهدين عادلين عند إجراء صيغة الطلاق « وذوي » جمع أريد به الاثنان فما فوق ، كما فسر في الأحاديث ، ( وَأَقِيمُوا ) أيها الشهود ( الشَّهادَةَ ) إذا احتاج أحد الطرفين إلى الإشهاد ( لِلَّهِ ) فلا تحرفوا فيها ، فإن الأمر إذا جاء به الإنسان لله ، راقبه سبحانه ، كي لا يزيد ولا ينقص ( ذلِكُمْ ) « ذا » إشارة و « كم » خطاب ، أي ذلك الذي تقدم من إقامة الشهادة لله ، ( يُوعَظُ بِهِ مَنْ كانَ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ ) فإنه هو الذي يخاف الله ويقيم الشهادة لله ، أما غيره فلا يهتم بالحقيقة وهذا كناية عن أن الانحراف في الشهادة كاشف عن عدم الإتيان ( وَمَنْ يَتَّقِ اللهَ ) أي يخافه سبحانه ، فيعمل حسب أوامره ( يَجْعَلْ لَهُ مَخْرَجاً ) من مشاكله. [4] فلا يظن الإنسان أنه إذا شهد بالحق وقع في المشكلة حيث يغضب عليه المبطل الذي يريد منه الشهادة بالباطل كما لا يزعم أنه يوجب قطع رزقه حيث أن المبطل ربما كان هو السبب في رزقه أو أن له القدرة في أن يسبب إلى ولي رزقه أن يمنعه عنه ( وَيَرْزُقْهُ ) الله ( مِنْ حَيْثُ لا يَحْتَسِبُ ) أي من مكان لا يظن أن يأتي من ذلك المكان الرزق ، ولصدق هذا الكلام شواهد كثيرة عند المجربين ، ومن الأمثلة البارزة الآن أمامي رجل قتل فاحشة طمعا في مالها وألقاها في النهر ، ثم وَمَنْ يَتَوَكَّلْ عَلَى اللهِ فَهُوَ حَسْبُهُ إِنَّ اللهَ بالِغُ أَمْرِهِ قَدْ جَعَلَ اللهُ لِكُلِّ شَيْءٍ قَدْراً (3) وَاللاَّئِي يَئِسْنَ مِنَ الْمَحِيضِ مِنْ نِسائِكُمْ إِنِ ارْتَبْتُمْ أعطى مرتزقته الشركاء معه في الإثم أموالا لئلا يشهدوا عند القاضي وهددهم إن شهدوا ، وانتشر الخبر وجاء القاضي يحلف الشهود بالقرآن الكريم ، فحلف الكل بالإنكار إلّا واحد منهم كان صاحبا لهذا المجرم ، فإنه قال لا أحلف بالقرآن كاذبا ، وشهد بالحق وفر من المجرم بعد « ومن الغريب » أن القاضي حكم على المجرم بهذا الشاهد الواحد ، وابتلى الكل ، إلا هذا الصادق فإنه تاب من أعماله السابقة وهو إلى اليوم في الحياة يمدحه من يعرفه ، بينما أن أولئك سجنوا وغرموا ، ومات بعضهم في شبابه. ( وَمَنْ يَتَوَكَّلْ عَلَى اللهِ فَهُوَ حَسْبُهُ ) أي من يكل أموره إلى الله يكفيه كل مخوف ومشكلة وينجيه من كل هلكة ( إِنَّ اللهَ بالِغُ أَمْرِهِ ) . أي يبلغ ما يريده ولا يفوته شيء من إرادته ، فلا يزعم الزاعم أن وعده سبحانه يمكن فيه الخلف ( قَدْ جَعَلَ اللهُ لِكُلِّ شَيْءٍ قَدْراً ) أي مقدارا وتقديرا وتسير أموره حسب ذلك فإذا جعل تقدير المتقي الكفاية والرزق لا بد وأن يكون كما أراد بلا خلف. [5] ثم بين سبحانه مقدار العدة التي إذا انقضت حل للزوجة أن تنكح زوجا جديدا ( وَاللَّائِي ) جمع التي أي النساء المطلقات اللائي ( يَئِسْنَ مِنَ الْمَحِيضِ ) أي يئسن من الحيض فلا يحضن ( مِنْ نِسائِكُمْ إِنِ ارْتَبْتُمْ ) أي شككتم في أمرهن فلا تدرون أن انقطاع الحيض لكبرهن ويأسهن أي بلوغهن سن اليأس ، وهو خمسون في غير القرشية والنبطية ، فَعِدَّتُهُنَّ ثَلاثَةُ أَشْهُرٍ وَاللاَّئِي لَمْ يَحِضْنَ وَأُولاتُ الْأَحْمالِ أَجَلُهُنَّ أَنْ يَضَعْنَ حَمْلَهُنَّ وَمَنْ يَتَّقِ اللهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْراً (4) ذلِكَ أَمْرُ اللهِ أَنْزَلَهُ إِلَيْكُمْ وَمَنْ يَتَّقِ اللهَ يُكَفِّرْ عَنْهُ سَيِّئاتِهِ وَيُعْظِمْ لَهُ أَجْراً (5) وستون فيهما أم لعارض ( فَعِدَّتُهُنَّ ثَلاثَةُ أَشْهُرٍ ) فإذا أكملن الثلاثة خرجن من العدة ، أما اليائسة فلا عدة لها إذ يجوز لها الزواج بزوج جديد بمجرد الطلاق ( وَاللَّائِي لَمْ يَحِضْنَ ) بعد لصغر السن ، أو لمرض وغيره ، كذلك عدتهن ثلاثة أشهر ( وَأُولاتُ الْأَحْمالِ ) أي النساء الحاملات إذا طلقن ( أَجَلُهُنَ ) أي مدة انتظار عدتهن ( أَنْ يَضَعْنَ حَمْلَهُنَ ) فإذا وضعن حملهن فقد انقضت العدة سواء طال الزمان بين الطلاق والولادة أم قصر ( وَمَنْ يَتَّقِ اللهَ ) فلا يخالف أوامره ( يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْراً ) أي يسهل أموره حتى لا يقع في المشاكل ، وحيث إن هذه الأحكام توجب كبت الغرائز بالنسبة إلى الرجل الذي يريد نكاحهن ، وبالنسبة إليهن لفّها السياق بلفائف من التقوى تذكيرا وعظة ، لئلا يزلق قدم المرأة أو الرجل المريد للنكاح في مهاوي المخالفة.` },
            { text: "وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ وَمَن يَتَوَكَّلْ عَلَى ٱللَّهِ فَهُوَ حَسْبُهُۥٓ إِنَّ ٱللَّهَ بَٰلِغُ أَمْرِهِۦ قَدْ جَعَلَ ٱللَّهُ لِكُلِّ شَىْءٍ قَدْرًا", tafsir: `` },
            { text: "وَٱلَّٰٓـِٔى يَئِسْنَ مِنَ ٱلْمَحِيضِ مِن نِّسَآئِكُمْ إِنِ ٱرْتَبْتُمْ فَعِدَّتُهُنَّ ثَلَٰثَةُ أَشْهُرٍ وَٱلَّٰٓـِٔى لَمْ يَحِضْنَ وَأُو۟لَٰتُ ٱلْأَحْمَالِ أَجَلُهُنَّ أَن يَضَعْنَ حَمْلَهُنَّ وَمَن يَتَّقِ ٱللَّهَ يَجْعَل لَّهُۥ مِنْ أَمْرِهِۦ يُسْرًا", tafsir: `` },
            { text: "ذَٰلِكَ أَمْرُ ٱللَّهِ أَنزَلَهُۥٓ إِلَيْكُمْ وَمَن يَتَّقِ ٱللَّهَ يُكَفِّرْ عَنْهُ سَيِّـَٔاتِهِۦ وَيُعْظِمْ لَهُۥٓ أَجْرًا", tafsir: `الذي ذكر من أحكام الطلاق ( أَمْرُ اللهِ ) وحكمه ( أَنْزَلَهُ إِلَيْكُمْ ) لمصالحكم ( وَمَنْ يَتَّقِ اللهَ ) أي يخافه فلا يخالفه ( يُكَفِّرْ عَنْهُ سَيِّئاتِهِ ) أي يغفر له ذنوبه ، فإن التكفير هو التغطية والستر ( وَيُعْظِمْ لَهُ أَجْراً ) أي يعطيه الأجر العظيم والثواب الجسيم في الآخرة. [7] ثم بيّن سبحانه حال المطلقة في النفقة والسكنى ، مدة العدة فقال أَسْكِنُوهُنَّ مِنْ حَيْثُ سَكَنْتُمْ مِنْ وُجْدِكُمْ وَلا تُضآرُّوهُنَّ لِتُضَيِّقُوا عَلَيْهِنَّ وَإِنْ كُنَّ أُولاتِ حَمْلٍ فَأَنْفِقُوا عَلَيْهِنَّ حَتَّى يَضَعْنَ حَمْلَهُنَّ فَإِنْ أَرْضَعْنَ لَكُمْ فَآتُوهُنَّ أُجُورَهُنَّ وَأْتَمِرُوا بَيْنَكُمْ بِمَعْرُوفٍ وَإِنْ تَعاسَرْتُ مْ فَسَتُرْضِعُ لَهُ أُخْرى (6) ( أَسْكِنُوهُنَ ) أي النساء المطلقات في بيوتكم ( مِنْ حَيْثُ سَكَنْتُمْ ) أي مكانا من سكناكم ومحلكم ( مِنْ وُجْدِكُمْ ) أي من ما تقدرون عليه ، من وجد بمعنى قدر وتمكن ، أي من سعتكم ( وَلا تُضآرُّوهُنَ ) أي لا تسببوا ضررا عليهن في السكنى ( لِتُضَيِّقُوا عَلَيْهِنَ ) أي طالبين بالإصرار التضييق عليهن لإزعاجهن حتى يضطرون إلى الزوج. ( وَإِنْ كُنَ ) تلك المطلقات ( أُولاتِ حَمْلٍ ) أي حاملات ( فَأَنْفِقُوا عَلَيْهِنَ ) بالكسوة والأكل والشرب وما أشبه ( حَتَّى يَضَعْنَ حَمْلَهُنَ ) فإن انقضاء عدتهن بالوضع ( فَإِنْ أَرْضَعْنَ لَكُمْ ) أولادكم بعد الوضع ( فَآتُوهُنَ ) أي أعطوهن ( أُجُورَهُنَ ) أي أجرة الإرضاع إذ الواجب على الوالد نفقة ولده ( وَأْتَمِرُوا ) أيها الأبوان والمتعلقون بهما ( بَيْنَكُمْ ) بعضكم مع بعض في أمر إرضاع الولد بما هو الأصلح بحال الجميع لئلا يتضرر أحد من الأطراف الثلاثة الأب والأم والولد ، والائتمار قبول الأمر وملاقاته بالتقبل ( بِمَعْرُوفٍ ) مقابل المنكر ، فلا يكون التشاور بقصد الإضرار وإثارة الأحقاد والكوامن ، بل بقصد الإحسان والعدالة ( وَإِنْ تَعاسَرْتُمْ ) أيها المتشاورون في أمر إرضاع الولد ، بأن اختلفتم في أمر الأم المرضعة ومقدار الأجرة وما أشبه ذلك ( فَسَتُرْضِعُ لَهُ ) أي للولد امرأة ( أُخْرى ) غير الأم ، والمعنى لِيُنْفِقْ ذُو سَعَةٍ مِنْ سَعَتِهِ وَمَنْ قُدِرَ عَلَيْهِ رِزْقُهُ فَلْيُنْفِقْ مِمَّا آتاهُ اللهُ لا يُكَلِّفُ اللهُ نَفْساً إِلاَّ ما آتاها سَيَجْعَلُ اللهُ بَعْدَ عُسْرٍ يُسْراً (7) فلتسترضع الولد امرأة غير الأم ، ولعل فيه إشارة إلى معاتبة الأم بأنها لا ينبغي لها المعاسرة. [8] ثم بين سبحانه أن المندوب على الوالد أن يوسع على المطلقة المرضعة ، إن كان له سعة ( لِيُنْفِقْ ذُو سَعَةٍ ) ، في المال ( مِنْ سَعَتِهِ ) بأن يوسع على المرضعة في الأجرة ، ألم تكن زوجته ، وأم ولده ، ومرضعته ؟ ( وَمَنْ قُدِرَ ) أي ضيق ( عَلَيْهِ رِزْقُهُ ) بأن لم يكن للأب سعة ( فَلْيُنْفِقْ ) على المرضعة ( مِمَّا آتاهُ اللهُ ) بقدر التمكن الذي أعطاه الله سبحانه ذلك فلا يطلب من مثل هذا الشخص الزيادة على أجرة المثل ( لا يُكَلِّفُ اللهُ نَفْساً ) أي أحدا ( إِلَّا ما آتاها ) أي بقدر ما أعطاه من الطاقة المالية ، كما لا يكلف إلا بقدر الطاقة الجسدية وسائر الطاقات ، ولا يغتم المملق بأنه ليس له ، كما يكون الأب المملق كثيرا ما يتحسر على أنه لا يجد الزائد حتى يبذل لمربية ولده ومرضعته ، فإنه ( سَيَجْعَلُ اللهُ ) في مستقبل الإملاق ( بَعْدَ عُسْرٍ يُسْراً ) بعد فقر غنى ـ وبعد ذلة عزة ـ وبعد انحطاط ورفعة وهكذا في سائر الأمور. فإن الدهر مختلفا يدور فلا حزن يدوم ولا سرور وقد بنت الملوك به قصورا فما بقي الملوك ولا القصور وَكَأَيِّنْ مِنْ قَرْيَةٍ عَتَتْ عَنْ أَمْرِ رَبِّها وَرُسُلِهِ فَحاسَبْناها حِساباً شَدِيداً وَعَذَّبْناها عَذاباً نُكْراً (8) فَذاقَتْ وَبالَ أَمْرِها وَكانَ عاقِبَةُ أَمْرِها خُسْراً (9) أَعَدَّ اللهُ لَهُمْ عَذاباً شَدِيداً فَاتَّقُوا اللهَ يا أُولِي الْأَلْبابِ [9] وإذ بين الأحكام ، جاء السياق ليبين ، أن العاتي العاصي لهذه الأحكام وغيرها ، مصيره مصير الأقوام السابقين ، الذين أهلكوا بسبب طغيانهم وعتوهم ( وَكَأَيِّنْ ) بمعنى ـ كم ـ الخبرية المفيدة للتكثير ( مِنْ قَرْيَةٍ ) من للتبيين والمراد البلدة ( عَتَتْ ) أي طغت ( عَنْ أَمْرِ رَبِّها ) فلم تطع أوامر الله سبحانه ، والمراد أهل القرية ، بعلاقة الحال والمحل ( وَرُسُلِهِ ) أي عن أمر رسله ، بأن لم يطيعوا رسل الله سبحانه ( فَحاسَبْناها حِساباً شَدِيداً ) مقابل السماح في الحساب ، فإن الإنسان المؤمن العامل بالصالحات يعفى عن جرائمه ويحاسب حسابا يسيرا ، جزاء على إيمانه وعمله ، أما العاتي الطاغي ، فإنه يحاسب على كل عمل عمله ( وَعَذَّبْناها عَذاباً نُكْراً ) أي عذابا منكرا أليما ، والمراد بالمحاسبة في الملأ الأعلى حولهم لا محاسبتهم بالذات إذ الحساب إنما هو بعد الموت ، والسياق يفيد كون حساب أولئك قبل عذابهم في الدنيا.` },
            { text: "أَسْكِنُوهُنَّ مِنْ حَيْثُ سَكَنتُم مِّن وُجْدِكُمْ وَلَا تُضَآرُّوهُنَّ لِتُضَيِّقُوا۟ عَلَيْهِنَّ وَإِن كُنَّ أُو۟لَٰتِ حَمْلٍ فَأَنفِقُوا۟ عَلَيْهِنَّ حَتَّىٰ يَضَعْنَ حَمْلَهُنَّ فَإِنْ أَرْضَعْنَ لَكُمْ فَـَٔاتُوهُنَّ أُجُورَهُنَّ وَأْتَمِرُوا۟ بَيْنَكُم بِمَعْرُوفٍ وَإِن تَعَاسَرْتُمْ فَسَتُرْضِعُ لَهُۥٓ أُخْرَىٰ", tafsir: `` },
            { text: "لِيُنفِقْ ذُو سَعَةٍ مِّن سَعَتِهِۦ وَمَن قُدِرَ عَلَيْهِ رِزْقُهُۥ فَلْيُنفِقْ مِمَّآ ءَاتَىٰهُ ٱللَّهُ لَا يُكَلِّفُ ٱللَّهُ نَفْسًا إِلَّا مَآ ءَاتَىٰهَا سَيَجْعَلُ ٱللَّهُ بَعْدَ عُسْرٍ يُسْرًا", tafsir: `` },
            { text: "وَكَأَيِّن مِّن قَرْيَةٍ عَتَتْ عَنْ أَمْرِ رَبِّهَا وَرُسُلِهِۦ فَحَاسَبْنَٰهَا حِسَابًا شَدِيدًا وَعَذَّبْنَٰهَا عَذَابًا نُّكْرًا", tafsir: `` },
            { text: "فَذَاقَتْ وَبَالَ أَمْرِهَا وَكَانَ عَٰقِبَةُ أَمْرِهَا خُسْرًا", tafsir: `تلك القرية ( وَبالَ أَمْرِها ) أي عاقبة صنيعها الشر ( وَكانَ عاقِبَةُ أَمْرِها خُسْراً ) أي خسرت الدنيا وخسرت الآخرة. [11] ذلك في الدنيا وقد ( أَعَدَّ اللهُ ) أي بقي ( لَهُمْ ) أي لأهل القرية ، ( عَذاباً شَدِيداً ) في الآخرة ( فَاتَّقُوا اللهَ ) أي خافوا عقابه ( يا أُولِي الْأَلْبابِ ) أي أصحاب العقول ، فإن ألباب جمع لب ، وهو العقل اتقوه الَّذِينَ آمَنُوا قَدْ أَنْزَلَ اللهُ إِلَيْكُمْ ذِكْراً (10) رَسُولاً يَتْلُوا عَلَيْكُمْ آياتِ اللهِ مُبَيِّناتٍ لِيُخْرِجَ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحاتِ مِنَ الظُّلُماتِ إِلَى النُّورِ سبحانه حتى لا ينزل بكم مثل ما نزل بأولئك الأمم ( الَّذِينَ آمَنُوا ) وصف لأولي الألباب ، وإنما وصفهم بذلك لأنهم هم المنتفعون بالتحذير ( قَدْ أَنْزَلَ اللهُ إِلَيْكُمْ ذِكْراً ) أي مذكرا يذكركم بأس الله وعذابه ، والانحراف بعد التذكير أقبح. [12] ثم بين سبحانه الذكر المنزل بقوله ( رَسُولاً ) أي محمدا صلى‌الله‌عليه‌وآله‌وسلم وكونه منزلا ، باعتبار أنه مبعوث من طرف الله سبحانه تشبيها للنزول المعنوي الحسي ( يَتْلُوا ) أي يقرأ هذا الرسول ( عَلَيْكُمْ ) أيها الناس ( آياتِ اللهِ ) أدلته وحججه التكوينية ، في حال كونها ( مُبَيِّناتٍ ) أي في حال الآيات تبين وتوضح الأمر وإنما يتلو ( لِيُخْرِجَ الَّذِينَ آمَنُوا ) بالله ورسوله وما جاء به ( وَعَمِلُوا الصَّالِحاتِ مِنَ الظُّلُماتِ ) أي ظلمات الكفر والعصيان ( إِلَى النُّورِ ) أي نور الإيمان والعمل الصالح ، وإنما شبه الإيمان بالنور ، لأنه ينير الإنسان ليدرك الحقيقة ـ في العقيدة والعمل ـ فمن زعم أنه لا إله أو للإله شريك فهو في ظلمة عن الحقيقة كالإنسان الذي في ظلمة الليل لا يدرك ما أمامه من الأشياء ، وكذلك بالنسبة إلى من يشرب الخمر ، يزعم أنها لا تضر ، فإنه في ظلمة من الحقيقة ، وقس على ذلك سائر الاعتقادات والأعمال. وقوله « الذين آمنوا » يراد بهم ذواتهم قبل الإيمان ، وإنما جيء الوصف للإشارة بهم لا أن المراد إخراجهم بعد الإيمان والعمل وَمَنْ يُؤْمِنْ بِاللهِ وَيَعْمَلْ صالِحاً يُدْخِلْهُ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهارُ خالِدِينَ فِيها أَبَداً قَدْ أَحْسَنَ اللهُ لَهُ رِزْقاً (11) اللهُ الَّذِي خَلَقَ سَبْعَ سَماواتٍ وَمِنَ الْأَرْضِ مِثْلَهُنَّ يَتَنَزَّلُ الْأَمْرُ بَيْنَهُنَّ الصالح ، لأنهم مخرجون بعد ذلك حين الاتصاف ـ كما لا يخفى ـ ( وَمَنْ يُؤْمِنْ بِاللهِ ) إيمانا صحيحا ( وَيَعْمَلْ ) عملا ( صالِحاً ) الملازم لعدم العمل الفاسد ( يُدْخِلْهُ ) الله في الآخرة ( جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا ) أي تحت أشجارها وقصورها ( الْأَنْهارُ ) من خمر وعسل ولبن وماء في حال كونهم ( خالِدِينَ ) أي دائمين ( فِيها ) في تلك الجنات ( أَبَداً ) بلا نهاية و ( قَدْ أَحْسَنَ اللهُ لَهُ ) أي لهذا الإنسان المؤمن العامل بالصالحات ( رِزْقاً ) إذ يعطى من ثمار الجنة ومياهها وأزواجها وسائر لوازم العيش الراقية. [13] ثم بين سبحانه وصفه ـ ليخاف العاصي ـ ويطمئن المؤمن لوعده بقوله ( اللهُ الَّذِي خَلَقَ سَبْعَ سَماواتٍ ) لعل المراد بها مدارات الكواكب السيارة ، أو ما أشبه ( وَمِنَ الْأَرْضِ مِثْلَهُنَ ) سبعا ، و قد قال الإمام الرضا عليه‌السلام أرض تحيط بها سماؤها ، ثم أرض تحيط بها سماؤها ، إلى أن عدّ سبعة ، وتفصيل الكلام في كتاب ـ الهيئة والإسلام ـ (1) . وضمير « هن » تأتي للعاقل وغير العاقل كما سبق ( يَتَنَزَّلُ الْأَمْرُ بَيْنَهُنَ ) أي أن أمر الله سبحانه يتنزل من كل سماء إلى أرضها ، وهكذا حتى يصل الأرض الأخيرة ، وإنما خلق سبحانه ما خلق ، مما يشاهده ( 1) للعلامة الشهرستاني. لِتَعْلَمُوا أَنَّ اللهَ عَلى كُلِّ شَيْءٍ قَدِيرٌ وَأَنَّ اللهَ قَدْ أَح اطَ بِكُلِّ شَيْءٍ عِلْماً (12) الإنسان ( لِتَعْلَمُوا ) أيها البشر ( أَنَّ اللهَ عَلى كُلِّ شَيْءٍ قَدِيرٌ ) قادر على العقاب والثواب ، كما قدر على خلق الأفلاك والأرضين ( وَأَنَّ اللهَ قَدْ أَحاطَ بِكُلِّ شَيْءٍ عِلْماً ) فإن الخلق يدل على العلم ، إذ لو لا العلم لم يمكن الخلق ، كما أن سير الكون المشار إليه بقوله ( يَتَنَزَّلُ الْأَمْرُ بَيْنَهُنَّ ) دالّ على العلم ، إذ التسيير محتاج إلى العلم الدقيق. (66)` },
            { text: "أَعَدَّ ٱللَّهُ لَهُمْ عَذَابًا شَدِيدًا فَٱتَّقُوا۟ ٱللَّهَ يَٰٓأُو۟لِى ٱلْأَلْبَٰبِ ٱلَّذِينَ ءَامَنُوا۟ قَدْ أَنزَلَ ٱللَّهُ إِلَيْكُمْ ذِكْرًا", tafsir: `` },
            { text: "رَّسُولًا يَتْلُوا۟ عَلَيْكُمْ ءَايَٰتِ ٱللَّهِ مُبَيِّنَٰتٍ لِّيُخْرِجَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ وَمَن يُؤْمِنۢ بِٱللَّهِ وَيَعْمَلْ صَٰلِحًا يُدْخِلْهُ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًا قَدْ أَحْسَنَ ٱللَّهُ لَهُۥ رِزْقًا", tafsir: `` },
            { text: "ٱللَّهُ ٱلَّذِى خَلَقَ سَبْعَ سَمَٰوَٰتٍ وَمِنَ ٱلْأَرْضِ مِثْلَهُنَّ يَتَنَزَّلُ ٱلْأَمْرُ بَيْنَهُنَّ لِتَعْلَمُوٓا۟ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ وَأَنَّ ٱللَّهَ قَدْ أَحَاطَ بِكُلِّ شَىْءٍ عِلْمًۢا", tafsir: `` }
        ]
    },
    66: { // سورة التحريم
        name: "التحريم",
        basmalaTafsir: ``,
        verses: [
            { text: "يَٰٓأَيُّهَا ٱلنَّبِىُّ لِمَ تُحَرِّمُ مَآ أَحَلَّ ٱللَّهُ لَكَ تَبْتَغِى مَرْضَاتَ أَزْوَٰجِكَ وَٱللَّهُ غَفُورٌ رَّحِيمٌ", tafsir: `خطاب للرسول صلى‌الله‌عليه‌وآله‌وسلم ( لِمَ تُحَرِّمُ ما أَحَلَّ اللهُ لَكَ ) أي لماذا تحلف لتحرم على نفسك بعض ما أحل الله لك ، وقد كان التحريم للحلال بالحلف جائزا ، لكن الله سبحانه بين للرسول أن حلفه حول هذا الموضوع محلولة ـ بهذا التعبير ـ تأنيبا لعائشة وحفصة اللتين آذتا الرسول صلى‌الله‌عليه‌وآله‌وسلم حتى حلف ما حلف. فقد روى البخاري ـ صاحب الصحيح عند العامة ـ عن عائشة قالت : كان النبي صلى‌الله‌عليه‌وآله‌وسلم يشرب عسلا عند زينب بنت جحش ويمكث عندها ، فتوطأت أنا وحفصة على زينب إذ دخل عليها فلنقل له أكلت مغافير وهو صمغ حلو الطعم كريه الرائحة ، إني أجد منك ريح مغافير ، قال صلى‌الله‌عليه‌وآله‌وسلم : لا ولكن كنت أشرب عسلا عند زينب بنت جحش فلن أعود له ، وقد حلفت لا تخبري بذلك أحدا (1) ( تَبْتَغِي مَرْضاتَ أَزْواجِكَ ) أي تطلب بالتحريم رضى زوجاتك ، وقد سبق في بعض الآيات أن الأغراض قد تأتي لا للمخاطب بل تقريع الغير ( وَاللهُ غَفُورٌ ) يستر على عباده ، فإن تحلة اليمين ، تحتاج إلى التحلة حتى لا يقال كيف خالف الرسول حلفه ، وحنث ( رَحِيمٌ ) يتفضل بالرحم ، علاوة على الغفران.` },
            { text: "قَدْ فَرَضَ ٱللَّهُ لَكُمْ تَحِلَّةَ أَيْمَٰنِكُمْ وَٱللَّهُ مَوْلَىٰكُمْ وَهُوَ ٱلْعَلِيمُ ٱلْحَكِيمُ", tafsir: `الظاهر كون الخطاب للرسول ، وإنما أتى بصيغة الجمع احتراما ، وقد تقدم سابقا ، أن الجمع والمفرد يتناوبان في حمل ( 1) الطرائف في معرفة مذاهب الطوائف : ج 1 ص 294. تَحِلَّةَ أَيْمانِكُمْ وَاللهُ مَوْلاكُمْ وَهُوَ الْعَلِيمُ الْحَكِيمُ (2) وَإِذْ أَسَرَّ النَّبِيُّ إِلى بَعْضِ أَزْواجِهِ حَدِيثاً فَلَمَّا نَبَّأَتْ بِهِ وَأَظْهَرَهُ اللهُ عَلَيْهِ عَرَّفَ بَعْضَهُ أحدهما على الآخر ، لنكتة بلاغية ، أي أوجب عليكم ( تَحِلَّةَ أَيْمانِكُمْ ) بأن تحلوها فلا تتبعون مفادها ، والمراد أن يشرب النبي صلى‌الله‌عليه‌وآله‌وسلم العسل فهو له حلال ، وإن الله قد أحل حلفه التي حلفها أنه لا يشرب العسل طلبا لرضى بعض نسائه ( وَاللهُ مَوْلاكُمْ ) فإذا حل اليمين فقد انحلت كما أن للمولى الحق في أن يحل يمين العبد ( وَهُوَ الْعَلِيمُ ) بمصالحكم ( الْحَكِيمُ ) فيما يأمر وينهي ، فإذا عرف الصلاح في شيء كان كما أمر فشرب العسل حلالا للرسول صلى‌الله‌عليه‌وآله‌وسلم وفيه الحكمة والصلاح. [4] ثم يأتي السياق ليشير إلى طرف من القصة بقوله سبحانه : ( وَ ) اذكر يا رسول الله ، ولعل ذلك لإفادة أن الرسول صلى‌الله‌عليه‌وآله‌وسلم كيف كان يؤذى من قبل أزواجه كما كان يؤذى من قبل أناس آخرين تفضيحا لهن في إيذائهن للرسول ، ( إِذْ أَسَرَّ النَّبِيُّ إِلى بَعْضِ أَزْواجِهِ حَدِيثاً ) أي حدثها سرا لتحريم العسل على نفسه ـ والمراد ببعض الأزواج ـ عائشة ـ أو حفصة ـ ولعل إسرار الرسول صلى‌الله‌عليه‌وآله‌وسلم كان لأجل أن لا يقول الناس إنه يحرم شيئا على نفسه لمجرد رضى زوجته ( فَلَمَّا نَبَّأَتْ بِهِ ) أي أخبرت تلك الزوجة امرأة أخرى بذلك الحديث السري ، فقد ورد عن طريق العامة إن الرسول صلى‌الله‌عليه‌وآله‌وسلم أخبر عائشة بحلفه وأمرها بالإسرار لكنها خالفت وأخبرت حفصة ( وَأَظْهَرَهُ اللهُ عَلَيْهِ ) أي أطلع الله نبيه على ما جرى منها في إفشاء سره ( عَرَّفَ ) الرسول « عائشة » ( بَعْضَهُ ) أي بعض ما وَأَعْرَضَ عَنْ بَعْضٍ فَلَمَّا نَبَّأَها بِهِ قالَتْ مَنْ أَنْبَأَكَ هذا قالَ نَبَّأَنِيَ الْعَلِيمُ الْخَبِيرُ (3) إِنْ تَتُوبا إِلَى اللهِ فَقَدْ صَغَتْ قُلُوبُكُما وَإِنْ تَظاهَرا عَلَيْهِ ذكرت « لحفصة » أراد بذلك بيان أنها خالفته في إفشاء سره ( وَأَعْرَضَ ) الرسول صلى‌الله‌عليه‌وآله‌وسلم ( عَنْ بَعْضٍ ) فإن من محامد الأخلاق أن لا يذكر الإنسان جميع جريمة المجرم وإنما يلمح إليها تلميحا تأديبا فإن التغافل من خلق الكرام. ( فَلَمَّا نَبَّأَها ) أي أخبر الرسول صلى‌الله‌عليه‌وآله‌وسلم عائشة ( بِهِ ) أي بما أعلمه الله سبحانه له من إفشائها سره عند « حفصة » ( قالَتْ ) « عائشة » متعجبة من علم الرسول صلى‌الله‌عليه‌وآله‌وسلم بإفشائها سره ( مَنْ أَنْبَأَكَ هذا ) أي من أخبرك بأني أفشيت سرك يا رسول الله ( قالَ ) الرسول صلى‌الله‌عليه‌وآله‌وسلم في جوابها ( نَبَّأَنِيَ ) أي أخبرني ( الْعَلِيمُ ) بجميع الأمور ( الْخَبِيرُ ) بدقائقها ، فإن الخبير غالبا ما يطلق على العالم النحرير المطلع على دقائق الأمور. [5] ثم توجه الخطاب إلى « عائشة » و « حفصة » اللتين دبرتا هذه المؤامرة مهددا لهما بقوله ( إِنْ تَتُوبا ) أيتها المرأتان ( إِلَى اللهِ ) بأن تستغفرا مما سلف منكما من إيذاء الرسول صلى‌الله‌عليه‌وآله‌وسلم والتظاهر ضده والافتراء عليه ( فَقَدْ صَغَتْ قُلُوبُكُما ) أي مالت إلى الإثم والباطل ، من « صغى » بمعنى مال وقد جرت القاعدة على أن التثنية إذا أضيفت إلى التثنية جاز في المضاف الجمع ـ نحو قلوبكما ـ وهو الأفضل والإفراد ، وهو الأوسط ، والتثنية وهو الأدون. ( وَإِنْ تَظاهَرا عَلَيْهِ ) أي تتظاهرا ، حذفت إحدى تائيه للقاعدة في فَإِنَّ اللهَ هُوَ مَوْلاهُ وَجِبْرِيلُ وَصالِحُ الْمُؤْمِنِينَ وَالْمَلائِكَةُ بَعْدَ ذلِكَ ظَهِيرٌ (4) عَسى رَبُّهُ إِنْ طَلَّقَكُنَّ باب المضارع إذا اجتمع في أوله تاءان ، والتظاهر هو أن يقوّي بعض ظهر بعض بالتوحيد بينهم لمطالبة أمر ، أو لمضادة أمر ( فَإِنَّ اللهَ هُوَ مَوْلاهُ ) أي ناصر الرسول يتولى حفظه وحياطته حتى لا يؤثر فيه المكر والمكيدة ( وَجِبْرِيلُ ) معين للرسول ، بإخباره عن قبل الله بما يراد ضده ( وَصالِحُ الْمُؤْمِنِينَ ) أي خيار المؤمنين ، والمراد ب « صالح » الجنس ، يعني أنهم ينصرون الرسول ضد المؤامرات والمظاهرات ( وَ ) سائر ( الْمَلائِكَةُ بَعْدَ ذلِكَ ) أي بعد ما تقدم من نصرة الله وجبرئيل والمؤمنين ( ظَهِيرٌ ) للرسول يقوون ظهره ، والإتيان بالمفرد ، وصفا للجمع باعتبار كل واحد واحد ، نحو ( فَانْظُرْ إِلى طَعامِكَ وَشَرابِكَ لَمْ يَتَسَنَّهْ ) (1) و ( وَحَسُنَ أُولئِكَ رَفِيقاً ) (2) وقد تقدم أن كلّا من المفرد والجمع يقوم مقام الآخر ، باعتبار بلاغي. وقد حذف جواب الشرطين ، والتقدير « أن تتوبا إلى الله كانت التوبة في موقعها إذ قد صغت » « وإن تظاهرا عليه ، لا يضره التظاهر ، إذ الله مولاه » . [6] ثم جاء السياق ليقلل من أهميتهما ، فإن للرسول صلى‌الله‌عليه‌وآله‌وسلم أن يطلقهما ، حتى تبوءا بعار المؤامرة والطلاق ولا يبقى الرسول صلى‌الله‌عليه‌وآله‌وسلم بلا زوجة فإن الله يزوجه بمن هي خير منهما ( عَسى رَبُّهُ ) أي لعل الله سبحانه ولعل ليس للرجاء ، بل بمعنى الاحتمال الراجح ( إِنْ طَلَّقَكُنَ ) المراد إما ( 1) البقرة : 260. ( 2) النساء : 70. أَنْ يُبْدِلَهُ أَزْواجاً خَيْراً مِنْكُنَّ مُسْلِماتٍ مُؤْمِناتٍ قانِتاتٍ تائِباتٍ عابِداتٍ سائِحاتٍ ثَيِّباتٍ وَأَبْكاراً (5) الاثنتان ، أو الكل ، أو من اشتركت في المؤامرة فإن الحديث تفشى في غيرهما أيضا ( أَنْ يُبْدِلَهُ ) أي يعوض للرسول صلى‌الله‌عليه‌وآله‌وسلم ( أَزْواجاً خَيْراً مِنْكُنَ ) في الإيمان ، وفي مراعاة حقوق الرسول صلى‌الله‌عليه‌وآله‌وسلم ثم وصف تلك أزواجا بما فيه تعريض بهن ( مُسْلِماتٍ ) كاملات الإسلام ( مُؤْمِناتٍ ) مصدقات بالله والرسول ، والإسلام هو الاستسلام ، فالإيمان أخص منه ، كما قال ( قالَتِ الْأَعْرابُ آمَنَّا قُلْ لَمْ تُؤْمِنُوا وَلكِنْ قُولُوا أَسْلَمْنا وَلَمَّا يَدْخُلِ الْإِيمانُ فِي قُلُوبِكُمْ ) (1) . ( قانِتاتٍ ) مطيعات لله ، خاضعات للرسول ( تائِباتٍ ) عن المعاصي التي تصدر منهن أحيانا ، فلا إصرار لهن على الذنب ( عابِداتٍ ) يعبدن الله سبحانه فوق القدر اللازم المفروض من العبادة ( سائِحاتٍ ) أي صائمات ـ كما ورد : سياحة أمتي الصوم (2) ـ أو ماضيات في أمر الله والرسول كالسائح الذي يضرب في الأرض ( ثَيِّباتٍ ) قد رأين الزوج قبل الرسول ( وَأَبْكاراً ) أي عذارى لم يكن لهن أزواج ـ كما أنتن حين دخلتن بيت الرسول كنتن على قسمين ـ . [7] ثم توجه السياق إلى الناس موجبا لهم تأديب نسائهم ، قالوا وقد تدرجت الفريضة في البلاغ من النفس إلى العموم حسب الإمكان في خمس آيات وهي النفس أولا بقوله : ( عَلَيْكُمْ أَنْفُسَكُمْ لا يَضُرُّكُمْ مَنْ ضَلَّ إِذَا اهْتَدَيْتُمْ ) (3) والأهل ثانيا بقوله : ( آمَنُوا قُوا أَنْفُسَكُمْ وَأَهْلِيكُمْ ناراً ) (4) ( 1) الحجرات : 15. ( 2) مستدرك الوسائل : ج 16 ص 54. ( 3) المائدة : 106. ( 4) التحريم : 7. يا أَيُّهَا الَّذِينَ آمَنُوا قُوا أَنْفُسَكُمْ وَأَهْلِيكُمْ ناراً وَقُودُهَا النَّاسُ وَالْحِجارَةُ عَلَيْها مَلائِكَةٌ غِلاظٌ شِدادٌ لا يَعْصُونَ اللهَ ما أَمَرَهُمْ و َيَفْعَلُونَ ما يُؤْمَرُونَ (6) والعشيرة ثالثا بقوله : ( وَأَنْذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ ) (1) وأهل البلدة رابعا بقوله ( وَلِيُنْذِرُوا قَوْمَهُمْ إِذا رَجَعُوا إِلَيْهِمْ لَعَلَّهُمْ ) (2) وأهل العالم أجمع خامسا بقوله : ( وَما أَرْسَلْناكَ إِلَّا كَافَّةً لِلنَّاسِ ) (3) والرسول صلى‌الله‌عليه‌وآله‌وسلم أسوة ، وبقوله : ( وَلْتَكُنْ مِنْكُمْ أُمَّةٌ يَدْعُونَ إِلَى الْخَيْرِ ) (4) . ( يا أَيُّهَا الَّذِينَ آمَنُوا قُوا ) أمر للجمع المذكر ، من « وقى » بمعنى حفظ ، أي احفظوا ( أَنْفُسَكُمْ وَأَهْلِيكُمْ ) وهو عائلة الإنسان من أولاده وزوجته وأخوته ومن شابههم ( ناراً ) عن نار جهنم التي هي بهذه الصفة ( وَقُودُهَا ) أي حطبها الموجب لإيقادها وإشعالها ( النَّاسُ وَالْحِجارَةُ ) وهما يزيدان في قوة النار لدسومة الأول وصلابة الثاني ( عَلَيْها ) أي المأمورون على تلك النار ( مَلائِكَةٌ ) جمع ملك وأصله من الألوكة ، بمعنى الرسالة لأن الملائكة رسل من قبله سبحانه إلى الأنبياء ( غِلاظٌ ) جمع غليظ وكأن المراد غليظ القلب فلا يرحم أحدا ( شِدادٌ ) جمع شديد ، وكأن المراد شديد البنية والقوة ، فما أراد تمكن منه ( لا يَعْصُونَ اللهَ ما أَمَرَهُمْ ) من عذاب أهل النار ، فلا يرتشون ولا يميلون نحو الكفار مخالفة لله سبحانه ( وَيَفْعَلُونَ ما يُؤْمَرُونَ ) من قبل الله سبحانه ، وهذا تأكيد لما سبق بأنهم لا يعصون. ( 1) الشعراء : 215. ( 2) التوبة : 122. ( 3) سبأ : 29. ( 4) آل عمران : 105. يا أَيُّهَا الَّذِينَ كَفَرُوا لا تَعْتَذِرُوا الْيَوْمَ إِنَّما تُجْزَوْنَ ما كُنْتُمْ تَعْمَلُونَ (7) يا أَيُّهَا الَّذِينَ آمَنُوا تُوبُوا إِلَى اللهِ تَوْبَةً نَصُوحاً عَسى رَبُّكُمْ أَنْ يُكَفِّرَ عَنْكُمْ سَيِّئاتِكُمْ وَيُدْخِلَكُمْ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهارُ [8] وإذ دخل الكفار النار ، أخذوا يعتذرون على سالف أعمالهم فيقال لهم ( يا أَيُّهَا الَّذِينَ كَفَرُوا ) في الدنيا ( لا تَعْتَذِرُوا الْيَوْمَ ) وأنتم في النار ( إِنَّما تُجْزَوْنَ ما كُنْتُمْ تَعْمَلُونَ ) فهذه النار جزاء أعمالكم السالفة ، ولا يفيد الاعتذار. [9] وإذ قد سمعتم أيها المؤمنون بكيفية النار ، فاللازم أن تتوبوا ـ وأنتم في الدنيا ـ عن معاصيكم لئلا تدخلوها ( يا أَيُّهَا الَّذِينَ آمَنُوا تُوبُوا إِلَى اللهِ ) من معاصيه وارجعوا إلى طاعته ، وتخصيص الخطاب بهم لأنهم المنتفعون به. ( تَوْبَةً نَصُوحاً ) أي خالصة لوجه الله سبحانه ، بمعنى بالغة في النصح وهو صفة التائب لأنه ينصح نفسه بالتوبة وإسناده إلى التوبة مجاز ، فإن الإنسان نصوح في التوبة ، والتوبة النصوح هي عبارة عن أن يندم الإنسان أشد الندم على المعصية ويعزم أقوى العزم على ترك مثلها في المستقبل ، ويأتي بلوازم التوبة من القضاء والكفارة ورد الحقوق وما أشبه ( عَسى رَبُّكُمْ ) أي لعل الله سبحانه إذا تبتم ( أَنْ يُكَفِّرَ عَنْكُمْ ) أي يستر ويمحي ( سَيِّئاتِكُمْ ) أي معاصيكم ، وسمى العصيان سيئة لأنها تسيء إلى الإنسان ( وَيُدْخِلَكُمْ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا ) أي تحت قصورها وأشجارها ( الْأَنْهارُ ) من عسل وخمر ولبن وماء ، يَوْمَ لا يُخْزِي اللهُ النَّبِيَّ وَالَّذِينَ آمَنُوا مَعَهُ نُورُهُمْ يَسْعى بَيْنَ أَيْدِيهِمْ وَبِأَيْمانِهِمْ يَقُولُونَ رَبَّنا أَتْمِمْ لَنا نُورَنا وَاغْفِرْ لَنا إِنَّكَ عَلى كُلِّ شَيْءٍ قَدِيرٌ (8) يا أَيُّهَا النَّبِيُّ جاهِدِ الْكُفَّارَ وَالْمُنافِقِينَ وَاغْلُظْ عَلَيْهِمْ وَمَأْواهُمْ جَهَنَّمُ ويكون إدخال التائب الجنة في ( يَوْمَ لا يُخْزِي اللهُ النَّبِيَّ وَالَّذِينَ آمَنُوا مَعَهُ ) أي لا يذلهم بدخول النار ، وكان الإتيان بهذه الجملة للترغيب في إدخال الإنسان نفسه في هذه الزمرة المفضلة. ( نُورُهُمْ يَسْعى بَيْنَ أَيْدِيهِمْ وَبِأَيْمانِهِمْ ) فإن وجوههم وأيديهم اليمنى ـ التي تحمل الكتاب ـ تشع نورا يخرق ظلمات المحشر ، فإذا تحرك المؤمن كان النور يسبقه من أمامه ومن طرفه الأيمن ( يَقُولُونَ ) مخاطبين لله سبحانه ( رَبَّنا أَتْمِمْ لَنا نُورَنا ) بأن يضاعف ويكثر ، أو يستمر حتى آخر القيامة فلا يطفأ ، أو هو دعاء منهم في الدنيا ، بأن يوفقهم لما يكثر نورهم ، ويبقيه فلا يزول عنهم بالكفر والعصيان ( وَاغْفِرْ لَنا ) معاصينا ( إِنَّكَ عَلى كُلِّ شَيْءٍ قَدِيرٌ ) من إتمام نورنا وغفران ذنوبنا ، وسائر ما تريده وهذا مدح له سبحانه في ضمن الدعاء ، فإنّ الدعاء المتضمن على الثناء أقرب إلى القبول.` },
            { text: "وَإِذْ أَسَرَّ ٱلنَّبِىُّ إِلَىٰ بَعْضِ أَزْوَٰجِهِۦ حَدِيثًا فَلَمَّا نَبَّأَتْ بِهِۦ وَأَظْهَرَهُ ٱللَّهُ عَلَيْهِ عَرَّفَ بَعْضَهُۥ وَأَعْرَضَ عَنۢ بَعْضٍ فَلَمَّا نَبَّأَهَا بِهِۦ قَالَتْ مَنْ أَنۢبَأَكَ هَٰذَا قَالَ نَبَّأَنِىَ ٱلْعَلِيمُ ٱلْخَبِيرُ", tafsir: `` },
            { text: "إِن تَتُوبَآ إِلَى ٱللَّهِ فَقَدْ صَغَتْ قُلُوبُكُمَا وَإِن تَظَٰهَرَا عَلَيْهِ فَإِنَّ ٱللَّهَ هُوَ مَوْلَىٰهُ وَجِبْرِيلُ وَصَٰلِحُ ٱلْمُؤْمِنِينَ وَٱلْمَلَٰٓئِكَةُ بَعْدَ ذَٰلِكَ ظَهِيرٌ", tafsir: `` },
            { text: "عَسَىٰ رَبُّهُۥٓ إِن طَلَّقَكُنَّ أَن يُبْدِلَهُۥٓ أَزْوَٰجًا خَيْرًا مِّنكُنَّ مُسْلِمَٰتٍ مُّؤْمِنَٰتٍ قَٰنِتَٰتٍ تَٰٓئِبَٰتٍ عَٰبِدَٰتٍ سَٰٓئِحَٰتٍ ثَيِّبَٰتٍ وَأَبْكَارًا", tafsir: `` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ قُوٓا۟ أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًا وَقُودُهَا ٱلنَّاسُ وَٱلْحِجَارَةُ عَلَيْهَا مَلَٰٓئِكَةٌ غِلَاظٌ شِدَادٌ لَّا يَعْصُونَ ٱللَّهَ مَآ أَمَرَهُمْ وَيَفْعَلُونَ مَا يُؤْمَرُونَ", tafsir: `` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ كَفَرُوا۟ لَا تَعْتَذِرُوا۟ ٱلْيَوْمَ إِنَّمَا تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ", tafsir: `` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ تُوبُوٓا۟ إِلَى ٱللَّهِ تَوْبَةً نَّصُوحًا عَسَىٰ رَبُّكُمْ أَن يُكَفِّرَ عَنكُمْ سَيِّـَٔاتِكُمْ وَيُدْخِلَكُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ يَوْمَ لَا يُخْزِى ٱللَّهُ ٱلنَّبِىَّ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ نُورُهُمْ يَسْعَىٰ بَيْنَ أَيْدِيهِمْ وَبِأَيْمَٰنِهِمْ يَقُولُونَ رَبَّنَآ أَتْمِمْ لَنَا نُورَنَا وَٱغْفِرْ لَنَآ إِنَّكَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ", tafsir: `` },
            { text: "يَٰٓأَيُّهَا ٱلنَّبِىُّ جَٰهِدِ ٱلْكُفَّارَ وَٱلْمُنَٰفِقِينَ وَٱغْلُظْ عَلَيْهِمْ وَمَأْوَىٰهُمْ جَهَنَّمُ وَبِئْسَ ٱلْمَصِيرُ", tafsir: `بالقتال والمحاربة ( وَالْمُنافِقِينَ ) بالزجر والردع ( وَاغْلُظْ عَلَيْهِمْ ) أي اشدد عليهم في الجهاد والزجر ، فإن اللين إنما هو للمستقيم المعتدل ، أما المنحرف فاللازم معه الشدة حتى يستقيم ( وَمَأْواهُمْ جَهَنَّمُ ) أي مصيرهم ، من « آوى » بمعنى اتخذ المنزل وَبِئْسَ الْمَصِيرُ (9) ضَرَبَ اللهُ مَثَلاً لِلَّذِينَ كَفَرُوا امْرَأَتَ نُوحٍ وَامْرَأَتَ لُوطٍ كانَتا تَحْتَ عَبْدَيْنِ مِنْ عِبادِنا صالِحَيْنِ فَخانَتاهُما فَلَمْ يُغْنِيا عَنْهُما مِنَ اللهِ شَيْئاً وَقِيلَ ادْخُلا النَّارَ مَعَ الدَّاخِلِينَ (10) ( وَبِئْسَ الْمَصِيرُ ) أي بئس المأوى جهنم لهم ، لما فيها من العذاب والنكال. [11] ثم جاء السياق ليضرب مثلا لأزواج الرسول صلى‌الله‌عليه‌وآله‌وسلم مبينا أن صلاح الزوج لا ينفع الزوجة إذا كانت منحرفة ، كما أن فساد الزوج لا يضر الزوجة إذا كانت مستقيمة ، منقادة ، على طاعة الرسول وعدم الهوى في مهوى العصيان والمخالفة ( ضَرَبَ اللهُ مَثَلاً لِلَّذِينَ كَفَرُوا ) مبينا لهم أن صلاح أصحابهم وذويهم لا ينفعهم ( امْرَأَتَ نُوحٍ وَامْرَأَتَ لُوطٍ ) فقد ( كانَتا تَحْتَ ) إدارة وعيلولة ( عَبْدَيْنِ مِنْ عِبادِنا ) هما نوح ولوط ( صالِحَيْنِ ) فهما رسولان من قبل الله سبحانه وأي صلاح أشد من ذلك ( فَخانَتاهُما ) خيانة في الدين ، إذ كانتا تنافقان وتؤذيان زوجيهما. ( فَلَمْ يُغْنِيا ) أي لم ينفع نوح ولوط ( عَنْهُما ) أي عن الزوجتين ( مِنْ ) عذاب ( اللهِ شَيْئاً ) بأن يخفف عنهما ، ولو بعض العذاب ( وَقِيلَ ) للزوجتين حين ماتتا ( ادْخُلَا النَّارَ مَعَ الدَّاخِلِينَ ) فيها ، فهما معذبتان مع كونهما زوجتا نبيين ، وفي هذا تعريض بعائشة وحفصة اللتين آذتا الرسول صلى‌الله‌عليه‌وآله‌وسلم . وَضَرَبَ اللهُ مَثَلاً لِلَّذِينَ آمَنُوا امْرَأَتَ فِرْعَوْنَ إِذْ قالَتْ رَبِّ ابْنِ لِي عِنْدَكَ بَيْتاً فِي الْجَنَّةِ وَنَجِّنِي مِنْ فِرْعَوْنَ وَعَمَلِهِ وَنَجِّنِي مِنَ الْقَوْمِ الظَّالِمِينَ (11) وَمَرْيَمَ ابْنَتَ عِمْرانَ الَّتِي أَحْصَنَتْ فَرْجَها فَنَفَخْنا فِيهِ مِنْ رُوحِنا` },
            { text: "ضَرَبَ ٱللَّهُ مَثَلًا لِّلَّذِينَ كَفَرُوا۟ ٱمْرَأَتَ نُوحٍ وَٱمْرَأَتَ لُوطٍ كَانَتَا تَحْتَ عَبْدَيْنِ مِنْ عِبَادِنَا صَٰلِحَيْنِ فَخَانَتَاهُمَا فَلَمْ يُغْنِيَا عَنْهُمَا مِنَ ٱللَّهِ شَيْـًٔا وَقِيلَ ٱدْخُلَا ٱلنَّارَ مَعَ ٱلدَّٰخِلِينَ", tafsir: `` },
            { text: "وَضَرَبَ ٱللَّهُ مَثَلًا لِّلَّذِينَ ءَامَنُوا۟ ٱمْرَأَتَ فِرْعَوْنَ إِذْ قَالَتْ رَبِّ ٱبْنِ لِى عِندَكَ بَيْتًا فِى ٱلْجَنَّةِ وَنَجِّنِى مِن فِرْعَوْنَ وَعَمَلِهِۦ وَنَجِّنِى مِنَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ", tafsir: `بيانا لأن الإيمان ينفع صاحبه وإن كان امرأة تحت أكفر الناس ( امْرَأَتَ فِرْعَوْنَ ) آسية بنت مزاحم التي آمنت بموسى وكان زوجها يدعي الربوبية ، ويقول أنا ربكم الأعلى ( إِذْ قالَتْ ) في مناجاتها لله تعالى يا ( رَبِّ ابْنِ لِي عِنْدَكَ بَيْتاً فِي الْجَنَّةِ ) فإني لا أرغب في بيوت الدنيا ولا أعمل لها ( وَنَجِّنِي مِنْ فِرْعَوْنَ وَعَمَلِهِ ) فإنه كان يعمل بالكفر والعصيان ( وَنَجِّنِي مِنَ الْقَوْمِ الظَّالِمِينَ ) أتباع فرعون وحاشيته ، فاستجاب الله دعاءها ، فقبضها وأدخلها الجنة ، ولم يكن يضرها عمل زوجها. [13] كما مثل سبحانه للمؤمنين بامرأة أخرى لم يضرها قول الناس فيها ، بعد أن كانت طاهرة ونقية دلالة على أن عمل الغير وقوله السيء لا يؤثر في المؤمن شيئا بعد أن كان هو بنفسه مؤمنا صالحا ( وَ ) ضرب الله مثلا للذين آمنوا ( مَرْيَمَ ابْنَتَ عِمْرانَ الَّتِي أَحْصَنَتْ فَرْجَها ) أي حفظته من البغاء ، وفيه تكذيب أعداء الله اليهود إذ قالوا فيها ما هم أحق به وأحرى. ( فَنَفَخْنا فِيهِ ) أي في فرجها ( مِنْ رُوحِنا ) أي الروح المضاف إلينا ـ تشريفا ـ وذلك كإضافة البيت إليه سبحانه ، في قولنا « بيت الله » والمراد به المسيح عليه‌السلام وكون النفخ فيه باعتبار خروج الولد منه ، أو وَصَدَّقَتْ بِكَلِماتِ رَبِّها وَكُتُبِهِ وَكانَتْ مِنَ الْقانِتِينَ (12) الضمير عائد إلى « الجسم » أي في جسمها أو « الجيب » أي في جيبها ، المعلوم من الخارج ، وقد كان النافخ فيه جبرئيل عليه‌السلام بأمره سبحانه ( وَصَدَّقَتْ ) مريم ( بِكَلِماتِ رَبِّها ) أي بما تكلم الله به وأوحاه إلى أنبيائه من الأصول والفروع ( وَكُتُبِهِ ) النازلة على الرسل ( وَكانَتْ مِنَ ) جملة ( الْقانِتِينَ ) الخاضعين لله سبحانه ، فإنها كانت في بيت المقدس في جملة العباد والزهاد ولذلك قال « القانتين » ولم يقل القانتات. فعلى المرأة إن كانت ذات زوج أن تقتدي بامرأة فرعون ، وإن لم تكن ذات زوج أن تقتدي بمريم الصديقة عليهم‌السلام . تقريب القرآن الى الأذهان من آية ( 1) سورة الملك إلى آية ( 51) سورة المرسلات بسم الله الرحمن الرحيم الحمد لله رب العالمين والصلاة والسلام على أشرف الأنبياء والمرسلين محمد المصطفى وعترته الطاهرين (67)` },
            { text: "وَمَرْيَمَ ٱبْنَتَ عِمْرَٰنَ ٱلَّتِىٓ أَحْصَنَتْ فَرْجَهَا فَنَفَخْنَا فِيهِ مِن رُّوحِنَا وَصَدَّقَتْ بِكَلِمَٰتِ رَبِّهَا وَكُتُبِهِۦ وَكَانَتْ مِنَ ٱلْقَٰنِتِينَ", tafsir: `` }
        ]
    },
    67: { // سورة الملك
        name: "الملك",
        basmalaTafsir: ``,
        verses: [
            { text: "تَبَٰرَكَ ٱلَّذِى بِيَدِهِ ٱلْمُلْكُ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ", tafsir: `من « برك » أي دام في خير ومصدر خير ، ومنه البركة ( الَّذِي بِيَدِهِ الْمُلْكُ ) فهو المالك المطلق لكل شيء في الكون وملك ما عداه إنما هي بتمليكه إياه ، وقوله « بيده » من باب تشبيه المعقول بالمحسوس ( وَهُوَ عَلى كُلِّ شَيْءٍ قَدِيرٌ ) قادر على إيجاده وإفنائه والتصرف فيه كيف يشاء.` },
            { text: "ٱلَّذِى خَلَقَ ٱلْمَوْتَ وَٱلْحَيَوٰةَ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًا وَهُوَ ٱلْعَزِيزُ ٱلْغَفُورُ", tafsir: `فإن الموت إما أمر وجودي ، أو عدم ملكة ، وكلاهما مخلوق ، فإن عدم الملكة له حظ من الوجود كما تقرر في علم الكلام ، وإنما خلق الموت والحياة ( لِيَبْلُوَكُمْ ) من « بلاه » بمعنى اختبره ، أي ليختبركم أيها البشر ( أَيُّكُمْ أَحْسَنُ عَمَلاً ) من الآخر ، والله سبحانه عالم بالإنسان ، وإنما الامتحان لتطبيق علمه على الخارج ، وإلا فهو غني عن الاختبار ، وتعليل الحياة والموت للاختبار باعتبار أن الموت داع إلى حسن العمل وموجب لعدم الوثوق بالدنيا ولذاتها الفانية والحياة توجب قدرة الإنسان على الأعمال الصالحة ( وَهُوَ ) سبحانه ( الْعَزِيزُ ) الغالب في سلطانه ( الْغَفُورُ ) الذي يغفر لمن أذنب إذا تاب ، فأنتم أيها البشر في قبضته بمقتضى كونه « عزيزا » ، فاستغفروه يغفر لكم بمقتضى كونه « غفورا » . [4] وهو ( الَّذِي خَلَقَ سَبْعَ سَماواتٍ طِباقاً ) واحدة فوق الأخرى مطابقة لها ، بلا تفاوت واعوجاج ( ما تَرى ) أيها الرائي ( فِي خَلْقِ الرَّحْمنِ مِنْ تَفاوُتٍ فَارْجِعِ الْبَصَرَ هَلْ تَرى مِنْ فُطُورٍ (3) ثُمَّ ارْجِعِ الْبَصَرَ كَرَّتَيْنِ يَنْقَلِبْ إِلَيْكَ الْبَصَرُ خاسِئاً وَهُوَ حَسِيرٌ (4) وَلَقَدْ زَيَّنَّا السَّماءَ الدُّنْيا بِمَصابِيحَ الرَّحْمنِ مِنْ تَفاوُتٍ ) واختلاف ، من جهة أن الجميع مخلوقة بدقة وإتقان وكمال لائق به ( فَارْجِعِ الْبَصَرَ ) أي رده إلى الكون ، بعد أن كان سابقا إليه ، وكأنه كان ناظرا بلا التفات إلى هذه الجهة ، فقيل له رد بصرك بقصد التفحص والبحث ( هَلْ تَرى مِنْ فُطُورٍ ) ؟ أي شقوق وفوق كالبناء الذي ينفطر لخلل فيه ، فهل في الكون خلل يدل على الوهن والضعف أم كل شيء وضع في محله اللائق به حسب الحكمة والصلاح ؟` },
            { text: "ٱلَّذِى خَلَقَ سَبْعَ سَمَٰوَٰتٍ طِبَاقًا مَّا تَرَىٰ فِى خَلْقِ ٱلرَّحْمَٰنِ مِن تَفَٰوُتٍ فَٱرْجِعِ ٱلْبَصَرَ هَلْ تَرَىٰ مِن فُطُورٍ", tafsir: `` },
            { text: "ثُمَّ ٱرْجِعِ ٱلْبَصَرَ كَرَّتَيْنِ يَنقَلِبْ إِلَيْكَ ٱلْبَصَرُ خَاسِئًا وَهُوَ حَسِيرٌ", tafsir: `أي كرة بعد كرة والمراد مكررا إذ لعل البصر اشتبه في المرة الأولى فلم ير فتقا ـ فإن الإنسان إذا كرر النظر إلى شيء أدرك خلله ـ فانظر إلى الكون مرة أخرى فاحصا عن الخلل ، لكن لا تجده بل ( يَنْقَلِبْ ) أي يرجع ( إِلَيْكَ ) أيها الإنسان ( الْبَصَرَ ) الذي سرحته في الكون ( خاسِئاً ) قد خسأ وطرد وعجز عما طلبه ـ من الفتق ـ ( وَهُوَ حَسِيرٌ ) قد حسر ، أي كلّ وعيّ ولم يجد خللا ووهنا وما يوجد من الأمراض وما أشبه إنما هو للامتحان والعبرة لا لنقص في الخلق.` },
            { text: "وَلَقَدْ زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنْيَا بِمَصَٰبِيحَ وَجَعَلْنَٰهَا رُجُومًا لِّلشَّيَٰطِينِ وَأَعْتَدْنَا لَهُمْ عَذَابَ ٱلسَّعِيرِ", tafsir: `أي جمّلنا السماء القريبة من الأرض ـ وهذا لا يدل على عدم تزيين سائر السماوات ، إذ لا مفهوم للّقب وإنما التخصيص لأنه المدرك المشاهد ـ ( بِمَصابِيحَ ) جمع مصباح ، والمراد وَجَعَلْناها رُجُوماً لِلشَّياطِينِ وَأَعْتَدْنا لَهُمْ عَذابَ السَّعِيرِ (5) وَلِلَّذِينَ كَفَرُوا بِرَبِّهِمْ عَذابُ جَهَنَّمَ وَبِئْسَ الْمَصِيرُ (6) إِذا أُلْقُوا فِيها سَمِعُوا لَها شَهِيقاً وَهِيَ تَفُورُ (7) تَكادُ تَمَي َّزُ مِنَ الْغَيْظِ به الكواكب ( وَجَعَلْناها ) أي جعلنا تلك المصابيح ( رُجُوماً ) مراكز للرجم ( لِلشَّياطِينِ ) فإن الشيطان إذا اقترب من مراكز الملائكة في الملأ الأعلى ليسترق بعض الكلمات رجم بالشهب من النجوم ، فإن النجوم مراصد ينظر منها إلى الشياطين حتى إذا اقتربوا رجموا ، كما سبق في بعض السور ( وَأَعْتَدْنا ) أي هيّأنا ( لَهُمْ ) أي للشياطين المسترقين للسمع ( عَذابَ السَّعِيرِ ) أي عذاب النار المستعرة الملتهبة ، إما بالرجوم ، وإما في الآخرة في النار. [7] وكما هيّأ العذاب للشياطين كذلك هيّأ للكفار ( وَلِلَّذِينَ كَفَرُوا بِرَبِّهِمْ ) بأن أنكروه أو وصفوه بما لا يليق به ( عَذابُ جَهَنَّمَ ) مبتدأ ، خبره « للذين » ( وَبِئْسَ الْمَصِيرُ ) أي المآل والمرجع ، اسم مكان من « صار » .` },
            { text: "وَلِلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ عَذَابُ جَهَنَّمَ وَبِئْسَ ٱلْمَصِيرُ", tafsir: `` },
            { text: "إِذَآ أُلْقُوا۟ فِيهَا سَمِعُوا۟ لَهَا شَهِيقًا وَهِىَ تَفُورُ", tafsir: `أي الكفار ، ألقاهم الملائكة ( فِيها ) أي في جهنم ( سَمِعُوا لَها ) أي لجهنم ( شَهِيقاً ) أي صوتا فضيعا كصوت الحمار وإنما تشهق لتدخل في قلوب الكفار الهول والرعب ( وَهِيَ تَفُورُ ) فوران القدر إذا غلى ، وذلك مما يزيدها هولا.` },
            { text: "تَكَادُ تَمَيَّزُ مِنَ ٱلْغَيْظِ كُلَّمَآ أُلْقِىَ فِيهَا فَوْجٌ سَأَلَهُمْ خَزَنَتُهَآ أَلَمْ يَأْتِكُمْ نَذِيرٌ", tafsir: `أي تقرب جهنم ( تَمَيَّزُ ) أي تتقطع ( مِنَ الْغَيْظِ ) أي شدة الغضب وكثرة اللهب والفوران ، وهذا تمثيل لشدة اشتعالها ، فإن كُلَّما أُلْقِيَ فِيها فَوْجٌ سَأَلَهُمْ خَزَنَتُها أَ لَمْ يَأْتِكُمْ نَذِيرٌ (8) قالُوا بَلى قَدْ جاءَنا نَذِيرٌ فَكَذَّبْنا وَقُلْنا ما نَزَّلَ اللهُ مِنْ شَيْءٍ إِنْ أَنْتُمْ إِلاَّ فِي ضَلالٍ كَبِيرٍ (9) وَقالُوا لَوْ كُنَّا نَسْمَعُ أَوْ نَعْقِلُ ما كُنَّا فِي أَصْحابِ السَّعِيرِ (10) فَاعْتَرَفُوا بِذَنْبِهِمْ فَسُحْقاً الإنسان إذا غضب يكاد ينفجر ويتشقق بعض جلده ، وكذلك النار تكاد تتفرق لشدة استعارها ( كُلَّما أُلْقِيَ فِيها ) أي في جهنم ( فَوْجٌ ) أي جماعة من الكفار والعصاة ( سَأَلَهُمْ خَزَنَتُها ) أي الملائكة الموكلون بالنار ، جمع « خازن » ( أَ لَمْ يَأْتِكُمْ ) أيها المجرمون ( نَذِيرٌ ) ينذركم ويخوفكم من هذه النار ؟ والاستفهام للتبكيت والتقريع.` },
            { text: "قَالُوا۟ بَلَىٰ قَدْ جَآءَنَا نَذِيرٌ فَكَذَّبْنَا وَقُلْنَا مَا نَزَّلَ ٱللَّهُ مِن شَىْءٍ إِنْ أَنتُمْ إِلَّا فِى ضَلَٰلٍ كَبِيرٍ", tafsir: `أي أهل النار في جواب الخزنة ( بَلى قَدْ جاءَنا نَذِيرٌ ) رسول أو مبلغ عن الله سبحانه ( فَكَذَّبْنا ) هذا اليوم وما قاله النذير ( وَقُلْنا ما نَزَّلَ اللهُ مِنْ شَيْءٍ ) من كتاب أو تشريع ( إِنْ أَنْتُمْ ) أي ما أنتم أيها المنذرون ( إِلَّا فِي ضَلالٍ كَبِيرٍ ) حيث تزعمون أنكم رسل الله ، وإن الله أنزل إليكم الحكم والتشريع. [11] ثم يعترف أهل النار بأنهم لم يعملوا عقولهم في الدنيا ، حتى ابتلوا بهذا العذاب ( وَقالُوا لَوْ كُنَّا نَسْمَعُ ) كلام المنذرين ( أَوْ نَعْقِلُ ) أي نعمل عقولنا لنميز بين الحق والباطل بالإسماع ، فإن الإنسان إذا أعمل عقله لا بد وأن يدرك الحق في الجملة ولو لم يسمع شيئا ( ما كُنَّا ) في هذا اليوم ( فِي أَصْحابِ السَّعِيرِ ) اسم لجهنم لاستعار نارها.` },
            { text: "وَقَالُوا۟ لَوْ كُنَّا نَسْمَعُ أَوْ نَعْقِلُ مَا كُنَّا فِىٓ أَصْحَٰبِ ٱلسَّعِيرِ", tafsir: `` },
            { text: "فَٱعْتَرَفُوا۟ بِذَنۢبِهِمْ فَسُحْقًا لِّأَصْحَٰبِ ٱلسَّعِيرِ", tafsir: `الذي أدخلهم النار ، في الوقت الذي لا ينفع الإقرار ( فَسُحْقاً ) أي بعدا ، وهذا دعاء عليهم أي أبعدهم الله بعدا عن لِأَصْحابِ السَّعِيرِ (11) إِنَّ الَّذِينَ يَخْشَوْنَ رَبَّهُمْ بِالْغَيْبِ لَهُمْ مَغْفِرَةٌ وَأَجْرٌ كَبِيرٌ (12) وَأَسِرُّوا قَوْلَكُمْ أَوِ اجْهَرُوا بِهِ إِنَّهُ عَلِيمٌ بِذاتِ الصُّدُورِ (13) أَ لا يَعْلَمُ مَنْ خَلَقَ وَهُوَ اللَّطِيفُ الْخَبِيرُ (14) النجاة ( لِأَصْحابِ السَّعِيرِ ) الملازمين لها. [13] أما المؤمن الذي عمل صالحا فهو في خير وسعادة ( إِنَّ الَّذِينَ يَخْشَوْنَ رَبَّهُمْ ) يخافونه فلا يعصونه ( بِالْغَيْبِ ) في حالة كونه سبحانه غائبا عن حواسهم ( لَهُمْ مَغْفِرَةٌ ) أي غفران لذنوبهم التي صدرت منهم ( وَأَجْرٌ كَبِيرٌ ) ثواب جزيل. [14] ثم يأتي السياق ليبين علم الله سبحانه بكل ما يصدر من الإنسان من قول سواء كان جهرا أو سرا ( وَأَسِرُّوا ) أيها الناس ( قَوْلَكُمْ ) الذي يدور في صدوركم ، بأن تقولونه سرا ( أَوِ اجْهَرُوا بِهِ ) ف ( إِنَّهُ ) سبحانه يعلم ذلك قبل أن يخرج إلى عالم الألفاظ ، إذ هو ( عَلِيمٌ بِذاتِ الصُّدُورِ ) أي بالأشياء التي تدور في صدر الإنسان ، وإنما قال « الصدور » لأن القول في القلب والقلب في الصدر ، فمن يعلم ما في الصدر لا يعلم اللفظ ؟` },
            { text: "إِنَّ ٱلَّذِينَ يَخْشَوْنَ رَبَّهُم بِٱلْغَيْبِ لَهُم مَّغْفِرَةٌ وَأَجْرٌ كَبِيرٌ", tafsir: `` },
            { text: "وَأَسِرُّوا۟ قَوْلَكُمْ أَوِ ٱجْهَرُوا۟ بِهِۦٓ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ", tafsir: `` },
            { text: "أَلَا يَعْلَمُ مَنْ خَلَقَ وَهُوَ ٱللَّطِيفُ ٱلْخَبِيرُ", tafsir: `الخفايا والظواهر ( مَنْ خَلَقَ ) الخلق ؟ وهذا استفهام إنكاري ، أي كيف لا يعلم الله الأشياء وهو الخالق ( وَهُوَ اللَّطِيفُ ) أي العالم بما لطف ودق ، والشيء اللطيف هو الذي ينفذ في الأشياء بسهولة ويسر ، وتوصيفه سبحانه به باعتبار نفوذ علمه وقدرته ( الْخَبِيرُ ) المطلع على الأشياء ، وهو أدق معنى من « العالم » . هُوَ الَّذِي جَعَلَ لَكُمُ الْأَرْضَ ذَلُولاً فَامْشُوا فِي مَناكِبِها وَكُلُوا مِنْ رِزْقِهِ وَإِلَيْهِ النُّشُورُ (15) أَأَمِنْتُمْ مَنْ فِي السَّماءِ أَنْ يَخْسِفَ بِكُمُ الْأَرْضَ روى إن المشركين كانوا يقولون عن النبي صلى‌الله‌عليه‌وآله‌وسلم الأقوال السيئة وكان جبرئيل عليه‌السلام يخبره بما قالوا ، فإذا أراد أحدهم التحدث حوله صلى‌الله‌عليه‌وآله‌وسلم قال بعضهم لبعض : أسروا قولكم لئلا يطلع محمد ، فنزلت هذه الآيات (1) .` },
            { text: "هُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ ذَلُولًا فَٱمْشُوا۟ فِى مَنَاكِبِهَا وَكُلُوا۟ مِن رِّزْقِهِۦ وَإِلَيْهِ ٱلنُّشُورُ", tafsir: `الله ( الَّذِي جَعَلَ لَكُمُ ) أيها البشر ( الْأَرْضَ ذَلُولاً ) أي سهلة مسخرة ، للبناء والزرع ودفن الأموات والسير وإجراء الأنهر والقنوات ، وغيرها ، من « ذل » بمعنى خضع ولان ( فَامْشُوا ) أيها البشر ( فِي مَناكِبِها ) جمع منكب والمراد به الطريق ( وَكُلُوا مِنْ رِزْقِهِ ) الذي حصلتم عليه بالزرع ونحوه ( وَإِلَيْهِ النُّشُورُ ) أي إن بعثكم إليه سبحانه ، فهو المبدأ والمآل ، ومعنى « إليه » إلى حسابه وجزائه. [17] ثم بعد التذكير بنعم الله ليشكر البشر ، جاء السياق للتهديد بأنهم إن بقوا في الكفر والعصيان كانوا مظنة للعذاب والنكال ـ والسائق للناس إلى الخير إما النعمة أو النقمة ـ ( أَ أَمِنْتُمْ ) أي هل أمنتم أيها البشر من ( مَنْ فِي السَّماءِ ) من الملائكة الموكلين بأموركم من قبله سبحانه ( أَنْ يَخْسِفَ ) فاعله « من في السماء » ( بِكُمُ الْأَرْضَ ) حتى تنهار الأرض في الأعماق معكم ، كما فعل بقارون وقوم لوط. ويحتمل أن يراد ( 1) مجمع البيان : ج 10 ص 76. فَإِذا هِيَ تَمُورُ (16) أَمْ أَمِنْتُمْ مَنْ فِي السَّماءِ أَنْ يُرْسِلَ عَلَيْكُمْ حاصِباً فَسَتَعْلَمُونَ كَيْفَ نَذِيرِ (17) وَلَقَدْ كَذَّبَ الَّذِينَ مِنْ قَبْلِهِمْ فَكَيْفَ كانَ نَكِيرِ (18) أَ وَلَمْ يَرَوْا إِلَى الطَّيْرِ فَوْقَهُمْ ب « من في السماء » الله سبحانه ، وكونه في السماء باعتبار أن أمره إلى الأرض يصدر من هناك ، كما قال سبحانه ( وَهُوَ الَّذِي فِي السَّماءِ إِلهٌ وَفِي الْأَرْضِ إِلهٌ ) (1) وقال ( وَفِي السَّماءِ رِزْقُكُمْ وَما تُوعَدُونَ ) (2) ( فَإِذا هِيَ ) أي تفاجئون بأن الأرض ( تَمُورُ ) أي تضطرب وتتحرك ، من « مار » بمعنى تحرك واضطرب.` },
            { text: "ءَأَمِنتُم مَّن فِى ٱلسَّمَآءِ أَن يَخْسِفَ بِكُمُ ٱلْأَرْضَ فَإِذَا هِىَ تَمُورُ", tafsir: `` },
            { text: "أَمْ أَمِنتُم مَّن فِى ٱلسَّمَآءِ أَن يُرْسِلَ عَلَيْكُمْ حَاصِبًا فَسَتَعْلَمُونَ كَيْفَ نَذِيرِ", tafsir: `أيها البشر ، من ( مَنْ فِي السَّماءِ ) على أحد المعنيين ( أَنْ يُرْسِلَ عَلَيْكُمْ ) إن تماديتم في الكفر والعصيان ( حاصِباً ) أي ديما ذات حجارة ، تحصبكم كما حوصب قوم لوط ، وتذكير « حاصب » باعتبار تقدير « شيئا » ( فَسَتَعْلَمُونَ ) حين ذاك ( كَيْفَ نَذِيرِ ) أي كيف كان إنذاري بالعذاب صدقا. [19] وليس ذلك ببعيد من الكفار ، ألم يعرفوا أن الأمم السابقة حيث كذبوا ابتلوا بمثل هذا العذاب ( وَلَقَدْ كَذَّبَ الَّذِينَ مِنْ قَبْلِهِمْ ) بآيات الله ورسله ( فَكَيْفَ كانَ نَكِيرِ ) ؟ أي إنكاري عليهم حيث عذبوا بأنواع العذاب ، من غرق وخسف وحصب وغيرها. [20] وكيف ينكر هؤلاء وجود الله أو قدرته وهم يرون الآيات الكونية بأعينهم ؟ ( أَ وَلَمْ يَرَوْا ) هؤلاء الكفار ( إِلَى الطَّيْرِ فَوْقَهُمْ ) في السماء ( 1) الزخرف : 85. ( 2) الذاريات : 23. صافَّاتٍ وَيَقْبِضْنَ ما يُمْسِكُهُنَّ إِلاَّ الرَّحْمنُ إِنَّهُ بِكُلِّ شَيْءٍ بَصِيرٌ (19) أَمَّنْ هذَا الَّذِي هُوَ جُنْدٌ لَكُمْ يَنْصُرُكُمْ مِنْ دُونِ الرَّحْمنِ ( صافَّاتٍ ) تصف أجنحتها فوق رؤوسهم في حال الطيران ( وَيَقْبِضْنَ ) أجنحتهن بعد البسط ، فذات مرة صافات ، وذات مرة يقبضن وهو الدفيف ، والطير جنس ولذا جيء وصفه بالجمع ، كما أن الجمع بالنون يأتي للعاقل وغيره كما مر سابقا. ( ما يُمْسِكُهُنَ ) أي يحفظهن في الهواء في صفيف أو دفيف ( إِلَّا الرَّحْمنُ ) الذي يتفضل بالرحم لكل شيء ، فمن يا ترى أعطى الطير هذه القدرة ، وأعطى الهواء قابلية الحمل غير الله سبحانه ؟ ( إِنَّهُ ) سبحانه ( بِكُلِّ شَيْءٍ بَصِيرٌ ) فيعرف المناسب لكل شيء والصالح لكل شيء فيعطي حسب الصلاح والحكمة ، وحسب بصيرته سبحانه أعطى الطير هذه القدرة والسماء هذه القابلية ، و « بصير » هنا بمعنى الخبروية في الأمور لا بمعنى النظر.` },
            { text: "وَلَقَدْ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ فَكَيْفَ كَانَ نَكِيرِ", tafsir: `` },
            { text: "أَوَلَمْ يَرَوْا۟ إِلَى ٱلطَّيْرِ فَوْقَهُمْ صَٰٓفَّٰتٍ وَيَقْبِضْنَ مَا يُمْسِكُهُنَّ إِلَّا ٱلرَّحْمَٰنُ إِنَّهُۥ بِكُلِّ شَىْءٍۭ بَصِيرٌ", tafsir: `` },
            { text: "أَمَّنْ هَٰذَا ٱلَّذِى هُوَ جُندٌ لَّكُمْ يَنصُرُكُم مِّن دُونِ ٱلرَّحْمَٰنِ إِنِ ٱلْكَٰفِرُونَ إِلَّا فِى غُرُورٍ", tafsir: `« أم » منقطعة و « من » استفهام مبتدأ ، و « هذا » مبتدأ ثان ، و « الذي » خبره ، و « هو جند لكم » مبتدأ وخبر ، والمجموع صلة الذي ( يَنْصُرُكُمْ ) صفة « جند » والاستفهام إنكاري ، والمعنى من هو الذي تزعمونه جندا لكم ينصركم يوم القيامة من عذاب الله ؟ .. . والمراد أنه لا جند لكم هذه صفته ( مِنْ دُونِ الرَّحْمنِ ) وكأنه يقال للكفار بأي قوة تعصون الله ؟ أ لكم جند يدفع عذاب الله ، حتى تعتمدون عليه في عصيانه ؟ إِنِ الْكافِرُونَ إِلاَّ فِي غُرُورٍ (20) أَمَّنْ هذَا الَّذِي يَرْزُقُكُمْ إِنْ أَمْسَكَ رِزْقَهُ بَلْ لَجُّوا فِي عُتُوٍّ وَنُفُورٍ (21) أَ فَمَنْ يَمْشِي مُكِبًّا عَلى وَجْهِهِ أَهْدى أَمَّنْ يَمْشِي سَوِيًّا عَلى صِراطٍ مُسْتَقِيمٍ (22) قُلْ ثم يأتي السياق ليبين أنه لا جند للكفار ، وإنما غرتهم الحياة الدنيا ( إِنِ الْكافِرُونَ ) أي ليس الكافرون ( إِلَّا فِي غُرُورٍ ) قد غرهم الشيطان بأنه لا عذاب ولا نكال ، فاعتمدوا عليه في الكفر والعصيان.` },
            { text: "أَمَّنْ هَٰذَا ٱلَّذِى يَرْزُقُكُمْ إِنْ أَمْسَكَ رِزْقَهُۥ بَل لَّجُّوا۟ فِى عُتُوٍّ وَنُفُورٍ", tafsir: `؟ فهل هناك أحد يعطيكم الرزق ( إِنْ أَمْسَكَ ) الله ( رِزْقَهُ ) حتى يقوم ذلك الرازق مقام الله في الإعطاء وإذ لا رازق غيره فكيف تعصون الله ولا تخافون أن يقطع رزقكم فتبقون بلا رزق ولا طعام ( بَلْ ) إنهم يعلمون أن لا رازق غيره ، وإنما ( لَجُّوا ) أي استمروا في اللجاج والمخالفة ( فِي عُتُوٍّ ) أي تعد عن الحق ، من « عتى » ( وَنُفُورٍ ) أي تنفر عن الإسلام والحق.` },
            { text: "أَفَمَن يَمْشِى مُكِبًّا عَلَىٰ وَجْهِهِۦٓ أَهْدَىٰٓ أَمَّن يَمْشِى سَوِيًّا عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ", tafsir: `بأن يكون وجهه وبطنه على الأرض يمشي بكل صعوبة ، هل هذا الشخص أحسن وأعلم بالطريق ( أَمَّنْ يَمْشِي سَوِيًّا ) مستويا مستقيما ، على رجليه ، وهو ( عَلى صِراطٍ مُسْتَقِيمٍ ) ؟ أي طريق موصل إلى السعادة في أقصر مسافة ، فالكافر كمن يمشي مكبا على وجهه ، إذ طريقه وعر صعب لا يعرف الخلاص من المشاكل والمكاره ، بخلاف المؤمن الذي يرى طريقه ويسهل عليه المشي ويصل إلى الغاية المتوخاة في أقرب وقت.` },
            { text: "قُلْ هُوَ ٱلَّذِىٓ أَنشَأَكُمْ وَجَعَلَ لَكُمُ ٱلسَّمْعَ وَٱلْأَبْصَٰرَ وَٱلْأَفْـِٔدَةَ قَلِيلًا مَّا تَشْكُرُونَ", tafsir: `يا رسول الله لهؤلاء الجاحدين لله ، والذين يجعلون معه هُوَ الَّذِي أَنْشَأَكُمْ وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصارَ وَالْأَفْئِدَةَ قَلِيلاً ما تَشْكُرُونَ (23) قُلْ هُوَ الَّذِي ذَرَأَكُمْ فِي الْأَرْضِ وَإِلَيْهِ تُحْشَرُونَ (24) وَيَقُولُونَ مَتى هذَا الْوَعْدُ إِنْ كُنْتُمْ صادِقِينَ (25) قُلْ إِنَّمَا الْعِلْمُ عِنْدَ اللهِ وَإِنَّما أَنَا نَذِيرٌ مُبِينٌ (26) شريكا ( هُوَ ) الله وحده ( الَّذِي أَنْشَأَكُمْ ) أي خلقكم أيها البشر ( وَجَعَلَ لَكُمُ ) أي لمنفعتكم ( السَّمْعَ ) أريد به الجنس ( وَالْأَبْصارَ ) أي العيون ( وَالْأَفْئِدَةَ ) جمع « فؤاد » وهو القلب ، وكأن توحيد السمع وتجميع الأبصار والأفئدة للتفنن في التعبير ( قَلِيلاً ما تَشْكُرُونَ ) « ما » مصدرية ، أي قليلا شكركم ، بعد إعطائه سبحانه لكم هذه النعم العظام.` },
            { text: "قُلْ هُوَ ٱلَّذِى ذَرَأَكُمْ فِى ٱلْأَرْضِ وَإِلَيْهِ تُحْشَرُونَ", tafsir: `يا رسول الله لهؤلاء ( هُوَ ) الله وحده ( الَّذِي ذَرَأَكُمْ ) أي خلقكم بالتناسل والتوالد ( فِي الْأَرْضِ ) وأسكنكم إياها ( وَإِلَيْهِ ) أي إلى حساب الله وجناته ( تُحْشَرُونَ ) أي تبعثون وتجمعون في يوم القيامة فمنه المبدأ وإليه المعاد.` },
            { text: "وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ", tafsir: `أي الكفار المنكرون للمعاد ( مَتى هذَا الْوَعْدُ ) أي في أي زمان يكون البعث ( إِنْ كُنْتُمْ ) أيها المؤمنون ( صادِقِينَ ) في أن هناك حشرا وجزاء ؟` },
            { text: "قُلْ إِنَّمَا ٱلْعِلْمُ عِندَ ٱللَّهِ وَإِنَّمَآ أَنَا۠ نَذِيرٌ مُّبِينٌ", tafsir: `يا رسول الله في جواب هؤلاء السائلين عن وقت المعاد ( إِنَّمَا الْعِلْمُ ) بوقت القيامة ( عِنْدَ اللهِ ) فهو العالم به ( وَإِنَّما أَنَا نَذِيرٌ ) لكم أنذركم وأخوفكم عن مجيئه حيث تعذبون إن بقيتم على الكفر والعصيان ( مُبِينٌ ) واضح ظاهر ، أنذركم بكل وضوح وجلاء. فَلَمَّا رَأَوْهُ زُلْفَةً سِيئَتْ وُجُوهُ الَّذِينَ كَفَرُوا وَقِيلَ هذَا الَّذِي كُنْتُمْ بِهِ تَدَّعُونَ (27) قُلْ أَ رَأَيْتُمْ إِنْ أَهْلَكَنِيَ اللهُ وَمَنْ مَعِيَ أَوْ رَحِمَنا فَمَنْ يُجِيرُ الْكافِرِينَ مِنْ عَذابٍ أَلِيمٍ (28)` },
            { text: "فَلَمَّا رَأَوْهُ زُلْفَةً سِيٓـَٔتْ وُجُوهُ ٱلَّذِينَ كَفَرُوا۟ وَقِيلَ هَٰذَا ٱلَّذِى كُنتُم بِهِۦ تَدَّعُونَ", tafsir: `أي رأوا العذاب ( زُلْفَةً ) أي قريبا ، من « زلف » بمعنى قرب ، والمراد من « رأوا » المستقبل ، وإنما نزل منزلة الماضي لتحقق وقوعه ، نحو ( وَنُفِخَ فِي الصُّورِ ) (1) ( سِيئَتْ وُجُوهُ الَّذِينَ كَفَرُوا ) أي علت وجوههم الكآبة ، وظهرت عليها آثار الخوف والحزن من « ساء » ( وَقِيلَ ) للكفار ، والقائل الملائكة والرسل والمؤمنون حين يرى الكفار العذاب ( هذَا ) هو العذاب ( الَّذِي كُنْتُمْ ) أيها الكفار ( بِهِ تَدَّعُونَ ) أي تطلبون وتستعجلون من الدعاء ، قالوا « تدعون » و « تدعون » بمعنى ، فقد كان الكفار يقولون ( مَتى هذَا الْوَعْدُ ) ؟ ويطلبون عجلة العذاب استهزاء.` },
            { text: "قُلْ أَرَءَيْتُمْ إِنْ أَهْلَكَنِىَ ٱللَّهُ وَمَن مَّعِىَ أَوْ رَحِمَنَا فَمَن يُجِيرُ ٱلْكَٰفِرِينَ مِنْ عَذَابٍ أَلِيمٍ", tafsir: `يا رسول الله لهؤلاء الكفار ( أَ رَأَيْتُمْ ) أي أخبروني ( إِنْ أَهْلَكَنِيَ اللهُ ) أي أماتني ( وَمَنْ مَعِيَ ) من المؤمنين قبل تعذيبكم ( أَوْ رَحِمَنا ) بتأخير الموت عنا لنرى عذابكم ( فَمَنْ يُجِيرُ الْكافِرِينَ مِنْ عَذابٍ أَلِيمٍ ) أي أن موتي لا ينفعكم في عدم نزول العذاب بكم ، فقد كانوا يتمنون موت الرسول والمؤمنين ليستريحوا إلى كفرهم وأصنامهم ، فجاء السياق ليبين أن موت الرسول لا يفيدهم في إجارتهم من عذاب الله الذي استحقوه بسبب الكفر والآثام. ( 1) الكهف : 100. قُلْ هُوَ الرَّحْمنُ آمَنَّا بِهِ وَعَلَيْهِ تَوَكَّلْنا فَسَتَعْلَمُونَ مَنْ هُوَ فِي ضَلالٍ مُبِينٍ (29) قُلْ أَ رَأَيْتُمْ إِنْ أَصْبَحَ ماؤُكُمْ غَوْراً فَمَنْ يَأْتِيكُمْ بِماءٍ مَعِينٍ (30)` },
            { text: "قُلْ هُوَ ٱلرَّحْمَٰنُ ءَامَنَّا بِهِۦ وَعَلَيْهِ تَوَكَّلْنَا فَسَتَعْلَمُونَ مَنْ هُوَ فِى ضَلَٰلٍ مُّبِينٍ", tafsir: `يا رسول الله لهؤلاء الكفار ( هُوَ الرَّحْمنُ ) الذي ندعو إليه ( آمَنَّا بِهِ ) وصدقنا وجوده وصفاته وأوامره ووعوده ( وَعَلَيْهِ تَوَكَّلْنا ) في أمورنا وفوضنا إليه حوائجنا ( فَسَتَعْلَمُونَ ) أيها الكفار في يوم القيامة ( مَنْ هُوَ فِي ضَلالٍ ) وانحراف ( مُبِينٍ ) واضح ؟ هل نحن أم أنتم ؟` },
            { text: "قُلْ أَرَءَيْتُمْ إِنْ أَصْبَحَ مَآؤُكُمْ غَوْرًا فَمَن يَأْتِيكُم بِمَآءٍ مَّعِينٍۭ", tafsir: `` }
        ]
    },
    68: { // سورة القلم
        name: "القلم",
        basmalaTafsir: ``,
        verses: [
            { text: "نٓ وَٱلْقَلَمِ وَمَا يَسْطُرُونَ", tafsir: `من جنس هذا الحرف ـ وهي حروف التهجي ـ يتركب القرآن المعجز الذي لو اجتمعت الجن والإنس على أن يأتوا بمثله لا يقدرون أو رمز بين الله وبين الرسول ، و في رواية أنها نهر في الجنة جمد فصار مدادا ، وبه وبالقلم كتب على اللوح المحفوظ ما كان وما هو كائن إلى يوم القيامة (1) . ( وَالْقَلَمِ ) أي قسما بالقلم الذي يكتب الناس به ، وإنما أقسم به لما تقدم من أن كل خلق من خلق الله جليل عظيم ، والله يحلف بمختلف صنوف خلقه ، إشارة إلى العظمة الكامنة فيه ، أو المراد القلم الذي كتب في اللوح المحفوظ ( وَما يَسْطُرُونَ ) أي قسما بما يكتب الناس ، أو الملائكة ، من « سطر » بمعنى كتب.` },
            { text: "مَآ أَنتَ بِنِعْمَةِ رَبِّكَ بِمَجْنُونٍ", tafsir: `يا رسول الله ( بِنِعْمَةِ رَبِّكَ ) أي بسبب نعمة الله عليك بالرسالة ( بِمَجْنُونٍ ) كما يزعم الكفار ، فإنهم كانوا يرمونه صلى‌الله‌عليه‌وآله‌وسلم بالجنون بسبب أن الله أنعم عليه بالرسالة.` },
            { text: "وَإِنَّ لَكَ لَأَجْرًا غَيْرَ مَمْنُونٍ", tafsir: `يا رسول الله ( لَأَجْراً ) وجزاء على قيامك بمهمة البلاغ ( غَيْرَ مَمْنُونٍ ) أي غير مقطوع ، فإنّ « منّ » بمعنى قطع.` },
            { text: "وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٍ", tafsir: `يا رسول الله ( لَعَلى خُلُقٍ عَظِيمٍ ) إذ تحتمل المشاق والمتاعب في سبيل التبليغ بكل رحابة صدر ، وقد أوذي صلى‌الله‌عليه‌وآله‌وسلم حتى قال « ما أوذي نبي مثل ما أوذيت » . ( 1) بحار الأنوار : ج 54 ص 368. فَسَتُبْصِرُ وَيُبْصِرُونَ (5) بِأَيِّكُمُ الْمَفْتُونُ (6) إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَنْ ضَلَّ عَنْ سَبِيلِهِ وَهُوَ أَعْلَمُ بِالْمُهْتَدِينَ (7) فَلا تُطِعِ الْمُكَذِّبِينَ (8) وَدُّوا لَوْ تُدْهِنُ فَيُدْهِنُونَ (9)` },
            { text: "فَسَتُبْصِرُ وَيُبْصِرُونَ", tafsir: `أي سترى أنت يا رسول الله ( وَيُبْصِرُونَ ) أي يرون هؤلاء الكفار الذين يرمونك بالجنون.` },
            { text: "بِأَييِّكُمُ ٱلْمَفْتُونُ", tafsir: `أنت أم هم ( الْمَفْتُونُ ) أي المجنون ، أي هل حل الجنون بك أم حل بهم حتى أعرضوا عن الحق فهل المجنون الذي يترك نافعه ويأخذ ضاره ؟ والمفتون مصدر أو اسم مفعول تشبيها بأن شخصا مفتونا حل فيه ـ وهذا من بديع البلاغة.` },
            { text: "إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ", tafsir: `يا رسول الله ( هُوَ أَعْلَمُ بِمَنْ ضَلَّ عَنْ سَبِيلِهِ ) هل هو أنت ـ كما يقولون ـ أم هم ـ كما هو الواقع ؟ ومعنى الضلال عن سبيله الانحراف عن الطريقة التي قررها سبحانه للوصول إلى سعادة الدنيا والآخرة ( وَهُوَ أَعْلَمُ بِالْمُهْتَدِينَ ) الذين اهتدوا إلى السبيل الصحيح وهو سبيل الإسلام. [9] وإذ قد تبين لك الطريق الواضح ( فَلا تُطِعِ ) يا رسول الله ( الْمُكَذِّبِينَ ) بتوحيدك وبشريعتك ، بل ذرهم وشأنهم.` },
            { text: "فَلَا تُطِعِ ٱلْمُكَذِّبِينَ", tafsir: `` },
            { text: "وَدُّوا۟ لَوْ تُدْهِنُ فَيُدْهِنُونَ", tafsir: `أي أحب هؤلاء الكفار ( لَوْ تُدْهِنُ ) أي تجامل الكفار وتلين لهم ، فكأن المجامل يستعمل الدهن ليتلائم مع الطرف المقابل ، كما يستعمل الدهن لتلائم الشيئين الخشنين حتى لا يصطدما ولا يصطكا بعنف ( فَيُدْهِنُونَ ) أي فيجاملونك وبذلك يخففوا من وقع التبليغ على أنفسهم. وَلا تُطِعْ كُلَّ حَلاَّفٍ مَهِينٍ (10) هَمَّازٍ مَشَّاءٍ بِنَمِيمٍ (11) مَنَّاعٍ لِلْخَيْرِ مُعْتَدٍ أَثِيمٍ (12) عُتُلٍّ بَعْدَ ذلِكَ زَنِيمٍ (13)` },
            { text: "وَلَا تُطِعْ كُلَّ حَلَّافٍ مَّهِينٍ", tafsir: `يا رسول الله ، وهو عطف على « فلا تطع » ( كُلَّ حَلَّافٍ ) أي كثير الحلف بالباطل لقلة مبالاته ( مَهِينٍ ) أي ذليل من « هان » بمعنى ذلّ. وهذان من صفات الكفار لأنهم لما لا يجدون سبيلا إلى إثبات باطلهم يتمسكون بالحلف ، ومثل هذا الإنسان يشعر في نفسه بذلة المغلوبية ، وإن هرج وتشدّق وصاح وحلف.` },
            { text: "هَمَّازٍ مَّشَّآءٍۭ بِنَمِيمٍ", tafsir: `كثير الهمز للناس ، والهمز هو الطعن في الغير بشدة ( مَشَّاءٍ ) كثير المشي بين الناس ( بِنَمِيمٍ ) أي بالنميمة والفتنة والإفساد ليضرب بعض الناس ببعض ، والنميم والنميمة بمعنى واحد.` },
            { text: "مَّنَّاعٍ لِّلْخَيْرِ مُعْتَدٍ أَثِيمٍ", tafsir: `كثير المنع للخير فكلما رأى إرادة الإنسان للخير منعه ، لدناءة نفسه ( مُعْتَدٍ ) أي مجاوز عن الحق ، من اعتدى بمعنى تجاوز وظلم ( أَثِيمٍ ) أي كثير الإثم والعصيان.` },
            { text: "عُتُلٍّۭ بَعْدَ ذَٰلِكَ زَنِيمٍ", tafsir: `جاف غليظ ( بَعْدَ ذلِكَ ) الذي ذكر له من الصفات ( زَنِيمٍ ) أي دعي ملصق إلى قوم ليس منهم بالنسب. قالوا : والمعنى بذلك « الوليد بن المغيرة » (1) وهذه غالبة في الأشرار الذين يصدون عن الحق ، ويحضرون كل شر ، وقد رأيناهم في عصرنا ، إبان المد الأحمر ـ وكأن النفس إذا انحرفت عن جادة الهدى تجمعت فيها كل تلك الصفات. ( 1) مجمع البيان : ج 10 ص 89. أَنْ كانَ ذا مالٍ وَبَنِينَ (14) إِذا تُتْلى عَلَيْهِ آياتُنا قالَ أَساطِيرُ الْأَوَّلِينَ (15) سَنَسِمُهُ عَلَى الْخُرْطُومِ (16) إِنَّا بَلَوْناهُمْ كَما بَلَوْنا أَصْحابَ الْجَنَّةِ` },
            { text: "أَن كَانَ ذَا مَالٍ وَبَنِينَ", tafsir: `أي لأنا أعطيناه المال والبنين يكذب بآياتنا جزاء للإحسان بالإساءة ، فهو متعلق بما يأتي في قوله « قال أساطير » .` },
            { text: "إِذَا تُتْلَىٰ عَلَيْهِ ءَايَٰتُنَا قَالَ أَسَٰطِيرُ ٱلْأَوَّلِينَ", tafsir: `تقرأ عليه آيات القرآن ( قالَ ) في شأنها ( أَساطِيرُ الْأَوَّلِينَ ) أي أحاديث الأقوام السابقين التي سطرت بلا أن يكون لها أصل ، و « أساطير » جمع أسطورة ، وهي القصة الخيالية الوهمية بلا أن يكون لها حقيقة. ومن الغريب شباهة هذا القول من مكذبي عصر الرسول بما يقوله المكذبون في عصرنا ، من أن الإسلام رجعية و ارتجاع.` },
            { text: "سَنَسِمُهُۥ عَلَى ٱلْخُرْطُومِ", tafsir: `أي سنعلمه يوم القيامة بعلامة يعرف بها أنه مجرم ، فالسين للاستقبال ، و « نسم » مضارع من « وسم » بمعنى نعلمه بعلامة ( عَلَى الْخُرْطُومِ ) أي على أنفه ، وسمي خرطوما تشبيها بخرطوم الفيل تحقيرا له ، كما أن الوسم على الخرطوم من جهة أن الأنف مظهر الكبر والإعراض.` },
            { text: "إِنَّا بَلَوْنَٰهُمْ كَمَا بَلَوْنَآ أَصْحَٰبَ ٱلْجَنَّةِ إِذْ أَقْسَمُوا۟ لَيَصْرِمُنَّهَا مُصْبِحِينَ", tafsir: `أي اختبرنا أهل مكة ( كَما بَلَوْنا أَصْحابَ الْجَنَّةِ ) أي أصحاب البستان الذي كان قرب صنعاء. فقد قال الإمام الباقر عليه‌السلام : إن أهل مكة ابتلوا بالجوع كما ابتلى أصحاب الجنة ـ وهي جنة كانت في الدنيا وكانت باليمن يقال لها « الرضوان » على تسعة أميال من صنعاء (1) ، وقصة أصحاب الجنة كما رواها القمي عن ابن عباس : انه كان شيخ له جنة ، وكان لا يدخل بيته ثمرة منها ولا إلى منزله حتى يعطي كل ذي حق حقه ، فلما قبض الشيخ ورثه بنوه وكان له خمسة من البنين ، فحملت جنته في تلك السنة التي هلك فيها أبوهم حملا لم يكن حملت قبل ذلك ، فراحوا الفتية إلى جنتهم بعد صلاة العصر فأشرفوا على ثمر ورزق فاضل لم يعاينوا مثله في حياة أبيهم ، فلما نظروا إلى الفضل طغوا وبغوا ، وقال بعضهم لبعض : إن أبانا كان شيخا كبيرا قد ذهب عقله وخرف فهلموا نتعاقد عهدا فيما بيننا أن لا نعطي أحدا من فقراء المسلمين « أي مسلمي زمانهم » في عامنا هذا شيئا حتى نستغني وتكثر أموالنا ، ثم نستأنف الصنعة فيما يستقبل من السنين المقبلة. فرضي بذلك أربعة وسخط الخامس ، وهو الذي قال الله فيه « قال أوسطهم ألم أقل لكم لو لا تسبحون » .. فقال لهم أوسطهم اتقوا الله وكونوا على منهاج أبيكم تسلموا وتغنموا ، فبطشوا به وضربوه ضربا مبرحا ، فلما أيقن الأخ أنهم يريدون قتله دخل معهم في مشورتهم كارها لأمرهم غير طائع ، فراحوا إلى منازلهم ثم حلفوا بالله أن يصرموا إذا أصبحوا ولم يقولوا « إن شاء الله » ، فابتلاهم الله بذلك الذنب ، وحال بينهم وبين ذلك الرزق الذي كانوا أشرفوا عليه ، فأخبر عنهم في الكتاب فقال « إنا بلوناهم » إلى آخر القصة ـ كما يأتي ـ ولعل تشبيه كفار مكة بأولئك الأخوة من حيث إنهم كفروا نعمة الله سبحانه ، ( 1) تفسير القمي : ج 2 ص 382. وَلا يَسْتَثْنُونَ (18) فَطافَ عَلَيْها طائِفٌ مِنْ رَبِّكَ وَهُمْ نائِمُونَ (19) فَأَصْبَحَتْ كَالصَّرِيمِ (20) فَتَنادَوْا فابتلاهم بالقحط والجدب ، كما أن الأخوة لما أرادوا منع الفقراء خلافا لأمره سبحانه ابتلاهم الله بالنار التي أحرقت جنتهم (1) . ( إِذْ أَقْسَمُوا ) أي حلفوا بالله ( لَيَصْرِمُنَّها ) أي يقطعون ثمرها من « الصرم » بمعنى القطع ( مُصْبِحِينَ ) أي في حال كونهم داخلين في الصباح قبل أن يجلو النهار ، ليخفوا الأمر على الفقراء والمساكين.` },
            { text: "وَلَا يَسْتَثْنُونَ", tafsir: `أي لم يستثنوا عند الحلف بإتيان كلمة إن شاء الله ، وإنما يقال لهذه الكلمة : الاستثناء ، لأن القائل يقول أفعل كذا إلا أن يشاء الله منعي ، وفي معنى ذلك إن شاء الله ، وبعدم الاستثناء كانوا قد أساؤوا أولا بنية المنع عن الفقراء ، وثانيا بعدم الاستثناء بالنسبة إلى ما عزموا عليه في المستقبل.` },
            { text: "فَطَافَ عَلَيْهَا طَآئِفٌ مِّن رَّبِّكَ وَهُمْ نَآئِمُونَ", tafsir: `أي على الجنة ( طائِفٌ ) أي شيء من العذاب طاف على البستان ( مِنْ ) قبل ( رَبِّكَ ) يا رسول الله ( وَهُمْ نائِمُونَ ) بعد في فراشهم ، قالوا بعث الله نارا على البستان فأحرقت.` },
            { text: "فَأَصْبَحَتْ كَٱلصَّرِيمِ", tafsir: `الجنة ( كَالصَّرِيمِ ) أي كالمقطوع ثماره ، من « صرم » بمعنى قطع ، أو كالليل المظلم ، ويقال الليل والنهار صريمان لانصرام أحدهما عن الآخر.` },
            { text: "فَتَنَادَوْا۟ مُصْبِحِينَ", tafsir: `أي الأخوة أصحاب الجنة ، نادى بعضهم بعضا ( 1) تفسير القمي : ج 2 ص 381. مُصْبِحِينَ (21) أَنِ اغْدُوا عَلى حَرْثِكُمْ إِنْ كُنْتُمْ صارِمِينَ (22) فَانْطَلَقُوا وَهُمْ يَتَخافَتُونَ (23) أَنْ لا يَدْخُلَنَّهَا الْيَوْمَ عَلَيْكُمْ مِسْكِينٌ (24) وَغَدَوْا عَلى حَرْدٍ قادِرِينَ (25) فَلَمَّا رَأَوْها قالُوا إِنَّا لَضَالُّونَ (26) ( مُصْبِحِينَ ) أي حال كونهم داخلين في الصباح. [23] وكان النداء من بعضهم لبعض ( أَنِ اغْدُوا ) أيها الأخوة ، أي أسرعوا غدوة ( عَلى حَرْثِكُمْ ) أي زرعكم وثمركم ( إِنْ كُنْتُمْ صارِمِينَ ) من « صرم » بمعنى قطع ، أي إن تريدون قطع الثمار.` },
            { text: "أَنِ ٱغْدُوا۟ عَلَىٰ حَرْثِكُمْ إِن كُنتُمْ صَٰرِمِينَ", tafsir: `` },
            { text: "فَٱنطَلَقُوا۟ وَهُمْ يَتَخَٰفَتُونَ", tafsir: `مضوا إلى البستان ( وَهُمْ يَتَخافَتُونَ ) أي يتسارون بينهم ، وأصله من خفت فلان نفسه ، إذا أخفى نفسه لئلا يراه أحد ، ومنه يسمى مقابل الجهر إخفاتا. [25] وكان التخافت بسبب ( أَنْ لا يَدْخُلَنَّهَا ) أي الجنة ( الْيَوْمَ عَلَيْكُمْ ) أي في يوم الصرم وقطع الثمر ( مِسْكِينٌ ) فاعل يدخل. [26] وهكذا ذهبوا حتى وصلوا إلى الجنة ( وَغَدَوْا ) أي أصبحوا ( عَلى حَرْدٍ ) بمعنى المنع يقال حاردت السنة : إذا منعت قطرها ( قادِرِينَ ) أي قدروا على المنع عن الثمر لا على الثمر ، وهذا كالاستهزاء بهم كما يقال فلان امتلأت كفه من الهواء عوض امتلائها من المال ، يعني أنهم أصبحوا ممنوعين من الثمر ، فقد قدروا على الحرد والحرمان لا على الثمار والأعناب.` },
            { text: "أَن لَّا يَدْخُلَنَّهَا ٱلْيَوْمَ عَلَيْكُم مِّسْكِينٌ", tafsir: `` },
            { text: "وَغَدَوْا۟ عَلَىٰ حَرْدٍ قَٰدِرِينَ", tafsir: `` },
            { text: "فَلَمَّا رَأَوْهَا قَالُوٓا۟ إِنَّا لَضَآلُّونَ", tafsir: `أي رأوا الجنة على تلك الصفة ( قالُوا ) أي قال بعضهم لبعض ( إِنَّا لَضَالُّونَ ) أي ضللنا الطريق ، فليست هذه جنتنا. [28] ولما تأملوا ورأوا أنها جنتهم بعينها ، أضربوا عن كلامهم الأول وقالوا بَلْ نَحْنُ مَحْرُومُونَ (27) قالَ أَوْسَطُهُمْ أَ لَمْ أَقُلْ لَكُمْ لَوْ لا تُسَبِّحُونَ (28) قالُوا سُبْحانَ رَبِّنا إِنَّا كُنَّا ظالِمِينَ (29) فَأَقْبَلَ بَعْضُهُمْ عَلى بَعْضٍ يَتَلاوَمُونَ (30) قالُوا يا وَيْلَنا إِنَّا كُنَّا طاغِينَ (31) عَسى رَبُّنا أَنْ يُبْدِلَنا خَيْراً مِنْها ( بَلْ نَحْنُ مَحْرُومُونَ ) عن الثمار وعن خير الجنة ، فلقد احترقت.` },
            { text: "بَلْ نَحْنُ مَحْرُومُونَ", tafsir: `` },
            { text: "قَالَ أَوْسَطُهُمْ أَلَمْ أَقُل لَّكُمْ لَوْلَا تُسَبِّحُونَ", tafsir: `أي أعقلهم ، ويقال للأعقل أوسط ، لأنه لا إفراط في أمره ولا تفريط ( أَ لَمْ أَقُلْ لَكُمْ ) حينما أردتم منع الفقراء ( لَوْ لا ) أي هلا ( تُسَبِّحُونَ ) وتنزهون الله سبحانه ؟ فقد قال لهم حين ما تواطأوا على منع الفقراء : أيها الأخوة اذكروا الله ونزهوه عن القبيح فإنه منزه عن أن يعطي الأغنياء ويحرم الفقراء ، لكنكم ركبتم رؤوسكم وأعرضتم عن النصح ، فهذا جزاء نيتكم السيئة. [30] وبعد انتهاء كل شيء ( قالُوا سُبْحانَ رَبِّنا ) فإنه تعالى ليس ظالما في إحراق بستاننا ، بل ( إِنَّا كُنَّا ظالِمِينَ ) حيث قصدنا منع الحقوق عن الفقراء.` },
            { text: "قَالُوا۟ سُبْحَٰنَ رَبِّنَآ إِنَّا كُنَّا ظَٰلِمِينَ", tafsir: `` },
            { text: "فَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍ يَتَلَٰوَمُونَ", tafsir: `أي بعض الأخوة ( عَلى بَعْضٍ يَتَلاوَمُونَ ) أي يلوم بعضهم بعضا على ما سبق منهم من النية السيئة.` },
            { text: "قَالُوا۟ يَٰوَيْلَنَآ إِنَّا كُنَّا طَٰغِينَ", tafsir: `أي يا قوم ويلنا ، أو يا ويلنا أحضر فهذا وقتك ، والويل هي الحالة السيئة ( إِنَّا كُنَّا طاغِينَ ) في عزمنا على منع الفقراء حقوقهم ، والطغيان هو الظلم المتجاوز حده.` },
            { text: "عَسَىٰ رَبُّنَآ أَن يُبْدِلَنَا خَيْرًا مِّنْهَآ إِنَّآ إِلَىٰ رَبِّنَا رَٰغِبُونَ", tafsir: `أي لعل الله سبحانه ( أَنْ يُبْدِلَنا خَيْراً مِنْها ) أي خيرا من إِنَّا إِلى رَبِّنا راغِبُونَ (32) كَذلِكَ الْعَذابُ وَلَعَذابُ الْآخِرَةِ أَكْبَرُ لَوْ كانُوا يَعْلَمُونَ (33) إِنَّ لِلْمُتَّقِينَ عِنْدَ رَبِّهِمْ جَنَّاتِ النَّعِيمِ (34) أَ فَنَجْعَلُ الْمُسْلِمِينَ كَالْمُجْرِمِينَ (35) ما لَكُمْ كَيْفَ تَحْكُمُونَ (36) أَمْ لَكُمْ كِتابٌ هذه الجنة ، بأن يتفضل علينا ببدلها وعوضها ، ف ( إِنَّا إِلى رَبِّنا راغِبُونَ ) نرغب إليه ونطلب غفرانه ونسأله أن يعوضنا بدل الجنة.` },
            { text: "كَذَٰلِكَ ٱلْعَذَابُ وَلَعَذَابُ ٱلْـَٔاخِرَةِ أَكْبَرُ لَوْ كَانُوا۟ يَعْلَمُونَ", tafsir: `أي كعذاب أصحاب الجنة ، يكون عذاب العاصين في الدنيا ( وَلَعَذابُ الْآخِرَةِ أَكْبَرُ ) من عذاب الدنيا ( لَوْ كانُوا يَعْلَمُونَ ) أي لو علموا مقدار عذاب الآخرة ، لعلموا أنه أكبر من عذاب الدنيا. [35] وفي مقابل هؤلاء المتقون ( إِنَّ لِلْمُتَّقِينَ ) الذين اتقوا الكفر والمعاصي ، بأن خافوا عقاب الله سبحانه ( عِنْدَ رَبِّهِمْ ) أي في الآخرة وكونه عند الله باعتبار القرب إلى رضاه لا القرب المكاني ( جَنَّاتِ النَّعِيمِ ) أي بساتين يتنعمون فيها.` },
            { text: "إِنَّ لِلْمُتَّقِينَ عِندَ رَبِّهِمْ جَنَّٰتِ ٱلنَّعِيمِ", tafsir: `` },
            { text: "أَفَنَجْعَلُ ٱلْمُسْلِمِينَ كَٱلْمُجْرِمِينَ", tafsir: `الذين أسلموا لله سبحانه ( كَالْمُجْرِمِينَ ) الذين أذنبوا وعصوا الله سبحانه ؟ وهذا استفهام إنكاري ، أي كيف نجعل المسلم والمجرم ـ في الآخرة ـ سواء ؟ وقد كان الكفار يقولون : إن كان بعث وجزاء لكان حالنا في الآخرة أفضل من أحوال محمد وأصحابه.` },
            { text: "مَا لَكُمْ كَيْفَ تَحْكُمُونَ", tafsir: `أيها الكفار ؟ ( كَيْفَ تَحْكُمُونَ ) حكما جائرا في أن المجرم كالمسلم عند الله تعالى ؟ وهل يعقل هذا الحكم ؟` },
            { text: "أَمْ لَكُمْ كِتَٰبٌ فِيهِ تَدْرُسُونَ", tafsir: `أي هل أن حكمكم بذلك ليس اعتباطا ، بل ( لَكُمْ كِتابٌ ) فِيهِ تَدْرُسُونَ (37) إِنَّ لَكُمْ فِيهِ لَما تَخَيَّرُونَ (38) أَمْ لَكُمْ أَيْمانٌ عَلَيْنا بالِغَةٌ إِلى يَوْمِ الْقِيامَةِ إِنَّ لَكُمْ لَما تَحْكُمُونَ (39) سَلْهُمْ أَيُّهُمْ بِذلِكَ زَعِيمٌ (40) أَمْ لَهُمْ شُرَكاءُ فَلْيَأْتُوا بِشُرَكائِهِمْ إِنْ كانُوا صادِقِينَ (41) سماوي نزل على الأنبياء السابقين ( فِيهِ تَدْرُسُونَ ) وتقرؤون مساواة المجرم والمسلم ؟ [39] تدرسون ب ( إِنَّ لَكُمْ ) أنتم الكفار ( فِيهِ ) أي في ذلك الكتاب ( لَما تَخَيَّرُونَ ) أي للشيء الذي تختارونه من الثواب في الآخرة ، وجملة « إن لكم .. . » أول الكلام على سبيل الاستهزاء ، ولذا كسرت همزة إن ، وإن كان في الحقيقة من متعلقات « تدرسون » كما فسرنا.` },
            { text: "إِنَّ لَكُمْ فِيهِ لَمَا تَخَيَّرُونَ", tafsir: `` },
            { text: "أَمْ لَكُمْ أَيْمَٰنٌ عَلَيْنَا بَٰلِغَةٌ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ إِنَّ لَكُمْ لَمَا تَحْكُمُونَ", tafsir: `أي عهود ومواثيق علينا بأن أخذتم منا عهودا ( بالِغَةٌ ) تلك العهود ( إِلى يَوْمِ الْقِيامَةِ ) تكون هي لكم جيلا بعد جيل ( إِنَّ لَكُمْ لَما تَحْكُمُونَ ) أي أن تلك العهود هي أن لكم أنتم كلما حكمتم من تساوي المؤمنين بكم ، وإدخالكم الجنة ؟` },
            { text: "سَلْهُمْ أَيُّهُم بِذَٰلِكَ زَعِيمٌ", tafsir: `يا رسول الله ، أصله « اسأل » حذفت الهمزة تخفيفا ( أَيُّهُمْ بِذلِكَ ) الذي ذكروا من أن لهم مثل ما للمسلمين ( زَعِيمٌ ) كفيل ؟ فمن الكفيل بأن يكون لهم مثل ما للمسلمين ؟ وإذ لا كتاب ولا إيمان ، ولا كفيل فليعرفوا أن كلامهم فارغ خال من كل حجة ودليل.` },
            { text: "أَمْ لَهُمْ شُرَكَآءُ فَلْيَأْتُوا۟ بِشُرَكَآئِهِمْ إِن كَانُوا۟ صَٰدِقِينَ", tafsir: `أي آلهة أخرى هم يعطون هؤلاء الكفار في الآخرة مثل ما يعطي الله المؤمنين ؟ ( فَلْيَأْتُوا بِشُرَكائِهِمْ ) في يوم القيامة ليأخذوا منهم ـ وهذا استهزاء بهم ـ ( إِنْ كانُوا صادِقِينَ ) في كلامهم يَوْمَ يُكْشَفُ عَنْ ساقٍ وَيُدْعَوْنَ إِلَى السُّجُودِ فَلا يَسْتَطِيعُونَ (42) خاشِعَةً أَبْصارُهُمْ تَرْهَقُهُمْ ذِلَّةٌ وَقَدْ كانُوا يُدْعَوْنَ إِلَى السُّجُودِ وَهُمْ سالِمُونَ (43) فَذَرْنِي وَمَنْ يُكَذِّبُ بِهذَا الْحَدِيثِ سَنَسْتَدْرِجُهُمْ إن لهم مثل ما للمؤمنين. [43] فليأتوا بشركائهم في ( يَوْمَ ) القيامة الذي تظهر فيه الأهوال والشدائد حتى أنه ( يُكْشَفُ عَنْ ساقٍ ) فإن الخوف إذا كان شديدا كشف الإنسان عن ساقه ، بأن رفع ثوبه ليكون أسهل في الهرب ، فلا يأخذ فاضل ثوبه رجله ، وهذا كناية عن الهول ـ كما إن « كثير الرماد » كناية الجود ( وَيُدْعَوْنَ ) هؤلاء الكفار في ذلك اليوم ( إِلَى السُّجُودِ ) فيقال لهم على سبيل التقريع والتوبيخ « اسجدوا » ( فَلا يَسْتَطِيعُونَ ) لأن فقار ظهرهم تتداخل وتصلب حتى لا يتمكنون من الانحناء للسجود كما يظهر من الأحاديث.` },
            { text: "يَوْمَ يُكْشَفُ عَن سَاقٍ وَيُدْعَوْنَ إِلَى ٱلسُّجُودِ فَلَا يَسْتَطِيعُونَ", tafsir: `` },
            { text: "خَٰشِعَةً أَبْصَٰرُهُمْ تَرْهَقُهُمْ ذِلَّةٌ وَقَدْ كَانُوا۟ يُدْعَوْنَ إِلَى ٱلسُّجُودِ وَهُمْ سَٰلِمُونَ", tafsir: `لا يرفعون نظرهم من الأرض ذلة ومهانة ووجلا ( تَرْهَقُهُمْ ) أي تغشاهم ( ذِلَّةٌ ) فإنها تظهر من حركاتهم وسكناتهم ووجناتهم ( وَقَدْ كانُوا يُدْعَوْنَ ) هؤلاء الكفار ـ في دار الدنيا ـ ( إِلَى السُّجُودِ ) والخضوع لله سبحانه ( وَهُمْ سالِمُونَ ) فلا يسجدون ، ولذا جوزوا بتلك الذلة ، وبعدم تمكنهم من السجود يوم القيامة.` },
            { text: "فَذَرْنِى وَمَن يُكَذِّبُ بِهَٰذَا ٱلْحَدِيثِ سَنَسْتَدْرِجُهُم مِّنْ حَيْثُ لَا يَعْلَمُونَ", tafsir: `أي دعني يا رسول الله ( وَمَنْ ) أي مع الكافر الذي ( يُكَذِّبُ بِهذَا الْحَدِيثِ ) أي بحديث التوحيد والرسالة والمعاد وهذا تهديد ، معناه اني سأجازيهم ، كما يقول القائل « دعني وإياه » أي اتركه فإني سوف أحاسبه ( سَنَسْتَدْرِجُهُمْ ) الاستدراج هو طلب الشيء درجة مِنْ حَيْثُ لا يَعْلَمُونَ (44) وَأُمْلِي لَهُمْ إِنَّ كَيْدِي مَتِينٌ (45) أَمْ تَسْئَلُهُمْ أَجْراً فَهُمْ مِنْ مَغْرَمٍ مُثْقَلُونَ (46) أَمْ عِنْدَهُمُ الْغَيْبُ فَهُمْ يَكْتُبُونَ (47) درجة حتى يصل إلى النهاية المقصودة ، أي نوجب على هؤلاء العقوبة بإعطائهم الحياة والمال حتى يتدرجوا في الكفر والعصيان ، ويستحقوا بذلك أشد العذاب ( مِنْ حَيْثُ لا يَعْلَمُونَ ) إنه استدراج إلى العذاب والعقاب ، بل يظنون إنها نعمة وصحة ومال وجاه.` },
            { text: "وَأُمْلِى لَهُمْ إِنَّ كَيْدِى مَتِينٌ", tafsir: `أي أمهلهم ، فإن الإملاء والإمهال بمعنى واحد ( إِنَّ كَيْدِي مَتِينٌ ) أي ما أدبّره لعذاب الأشقياء متين مستحكم لا ينفصم ولا يدخله النقص والخلل. [47] ثم عطف على قوله ( أَمْ لَكُمْ كِتابٌ ) قوله : ( أَمْ تَسْئَلُهُمْ ) أي تسأل يا رسول الله من هؤلاء الكفار ( أَجْراً ) على أداء الرسالة والدعاء إلى الإسلام ( فَهُمْ مِنْ مَغْرَمٍ ) أي من لزوم تلك الغرامة ، والمال الذي تطلبه منهم ( مُثْقَلُونَ ) قد أثقلهم ذلك المطلوب ، ولذا يريدون الفرار من تلك الغرامة ، فعدم إيمانهم هل لأنهم يقولون لا فائدة في الإيمان ، لأنهم مطمئنون ، من كتاب قرءوه أنهم في الجنان مثل المسلمين ـ أم لأنهم يعرفون الفائدة في الإيمان ، وأن الجنة تتوقف عليه ، ولكن في الإيمان غرامة وهم يفرون من تلك الغرامة ؟` },
            { text: "أَمْ تَسْـَٔلُهُمْ أَجْرًا فَهُم مِّن مَّغْرَمٍ مُّثْقَلُونَ", tafsir: `` },
            { text: "أَمْ عِندَهُمُ ٱلْغَيْبُ فَهُمْ يَكْتُبُونَ", tafsir: `أي أن الوحي ينزل عليهم بأن ما هم فيه من الكفر والعصيان هو الصحيح ( فَهُمْ يَكْتُبُونَ ) ذلك الغيب ويعملون به ، ولذا لا يرضخون للإسلام ، لأن عندهم مثل ما عندك من الوحي والكتاب ؟ فَاصْبِرْ لِحُكْمِ رَبِّكَ وَلا تَكُنْ كَصاحِبِ الْحُوتِ إِذْ نادى وَهُوَ مَكْظُومٌ (48) لَوْ لا أَنْ تَدارَكَهُ نِعْمَةٌ مِنْ رَبِّهِ لَنُبِذَ بِالْعَراءِ وَهُوَ مَذْمُومٌ (49) فَاجْتَباهُ [49] وإذ ترى يا رسول الله من الكفار الإعراض بلا حجة أو دليل ( فَاصْبِرْ لِحُكْمِ رَبِّكَ ) في إبلاغ الرسالة ، وتحمل المشاق في سبيله ( وَلا تَكُنْ ) يا رسول الله ( كَصاحِبِ الْحُوتِ ) أي يونس عليه‌السلام الذي طلب العذاب لقومه ، وخرج من بينهم ، لما رأى عدم الفائدة في دعوتهم فقد كان عمله ذلك ترك الأولى بمثل مقام الرسالة ( إِذْ نادى ) الله سبحانه بإنزال العذاب على قومه ( وَهُوَ مَكْظُومٌ ) قد كظم غيظه على القوم فهو مكظوم الغيظ ، يقال كظم غيظه : إذا حبسه ، أو المعنى نادى في بطن الحوت ( لا إِلهَ إِلَّا أَنْتَ سُبْحانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ ) (1) وهو محبوس في بطن الحوت ، لكن المعنى الأول أقرب إلى قوله ( وَلا تَكُنْ كَصاحِبِ الْحُوتِ ) .` },
            { text: "فَٱصْبِرْ لِحُكْمِ رَبِّكَ وَلَا تَكُن كَصَاحِبِ ٱلْحُوتِ إِذْ نَادَىٰ وَهُوَ مَكْظُومٌ", tafsir: `` },
            { text: "لَّوْلَآ أَن تَدَٰرَكَهُۥ نِعْمَةٌ مِّن رَّبِّهِۦ لَنُبِذَ بِٱلْعَرَآءِ وَهُوَ مَذْمُومٌ", tafsir: `بقبول توبته واستغفاره فان التوبة نعمة من الله سبحانه على العبد ( لَنُبِذَ ) يونس ، أي طرح من بطن الحوت ( بِالْعَراءِ ) أي الأرض الجرداء الخالية عن الشجر والسقف حتى يهلك من الحر والبرد والجوع ( وَهُوَ مَذْمُومٌ ) لما ارتكبه من الدعاء على قومه ، فقد كان ذلك تركا للأولى ، وذلك ـ وإن لم يكن عصيانا ـ إلا أنه ليس مناسبا لمقام الأنبياء ، ولذا يحتاجون إلى التوبة والتطهير من ذلك. [51] وإذا تداركته نعمة من ربه فاستغفر وتاب ( فَاجْتَباهُ ) أي اصطفاه ( 1) الأنبياء : 88. رَبُّهُ فَجَعَلَهُ مِنَ الصَّالِحِينَ (50) وَإِنْ يَكادُ الَّذِينَ كَفَرُوا لَيُزْلِقُونَكَ بِأَبْصارِهِمْ لَمَّا سَمِعُوا الذِّكْرَ وَيَقُولُونَ إِنَّهُ لَمَجْنُونٌ (51) وَما هُوَ إِلاَّ ذِكْرٌ لِلْعالَمِينَ (52) واختاره ( رَبُّهُ ) بأن قبل توبته وأرجعه إلى مكانه الأول ( فَجَعَلَهُ مِنَ الصَّالِحِينَ ) الذين يصلحون لأداء رسالته سبحانه. [52] فاصبر يا رسول الله لحكم ربك ، ولا تكن كيونس ، واعلم بأن الكفار يريدون إزالتك عن دعوتك ( وَإِنْ يَكادُ الَّذِينَ كَفَرُوا لَيُزْلِقُونَكَ ) « إن » مخففة من الثقيلة ، أي أنه يقرب الكفار من أن يزلقوك ، و « زلق » بمعنى لم يتماسك على الأرض بل وقع لتمايل رجله ، أي يريد الكفار أن يوقعوك فلا تقوم للتبليغ ، وهذا للتشبيه ، فإن الذي يترك القيام بالبلاغ كالإنسان الذي وقع فلا وقوف له على رجليه ( بِأَبْصارِهِمْ ) أي بأعينهم ، فقد كانوا ينظرون إلى الرسول شزرا ، والنظر العدائي يوجب انقطاع الإنسان عما قام به ، فإن الشخص إذ رأى الازدراء من السامع لم يتقدم بالكلام ( لَمَّا سَمِعُوا ) أولئك الكفار ( الذِّكْرَ ) أي القرآن ( وَيَقُولُونَ إِنَّهُ ) أي الرسول صلى‌الله‌عليه‌وآله‌وسلم ( لَمَجْنُونٌ ) قد خلط عقله وزال ، فكلامه باطل لغو.` },
            { text: "فَٱجْتَبَٰهُ رَبُّهُۥ فَجَعَلَهُۥ مِنَ ٱلصَّٰلِحِينَ", tafsir: `` },
            { text: "وَإِن يَكَادُ ٱلَّذِينَ كَفَرُوا۟ لَيُزْلِقُونَكَ بِأَبْصَٰرِهِمْ لَمَّا سَمِعُوا۟ ٱلذِّكْرَ وَيَقُولُونَ إِنَّهُۥ لَمَجْنُونٌ", tafsir: `` },
            { text: "وَمَا هُوَ إِلَّا ذِكْرٌ لِّلْعَٰلَمِينَ", tafsir: `` }
        ]
    },
    69: { // سورة الحاقة
        name: "الحاقة",
        basmalaTafsir: ``,
        verses: [
            { text: "ٱلْحَآقَّةُ", tafsir: `هي من أسماء القيامة ، وإنما سمي المحشر بها لأنها ساعة تحق وتتحقق ، من « حق » بمعنى ثبت وصدق ووجب ، وهي في الإعراب مبتدأ خبره :` },
            { text: "مَا ٱلْحَآقَّةُ", tafsir: `كما تقول : زيد ما زيد ؟ وهو استفهام معناه التفخيم ، أي أيّ شيء هي ؟ وما أكثر أهوالها وشدائدها.` },
            { text: "وَمَآ أَدْرَىٰكَ مَا ٱلْحَآقَّةُ", tafsir: `يا رسول الله ، أو أيها الإنسان ( مَا الْحَاقَّةُ ) أيّ أيّ شيء هي ، فإنك إذا لم تعاينها لم تعلم شدائدها ، وهذا ليس نفيا بعلم الرسول ـ لو كان الخطاب موجها إليه ـ بل كناية عن شدتها. [5] ثم جاء السياق ليبين أحوال جملة من الأمم الماضية الذين كذبوا بالقيامة فأخذهم الله سبحانه وأهلكهم ( كَذَّبَتْ ثَمُودُ ) أي قبيلة ثمود ، وهم قوم صالح عليه‌السلام ( وَ ) قبيلة ( عادٌ ) قوم هود عليه‌السلام ( بِالْقارِعَةِ ) أي بالقيامة ، وتسمى « قارعة » لأنها تقرع الأشياء وتدكها وتقرع القلوب وتخفيفها.` },
            { text: "كَذَّبَتْ ثَمُودُ وَعَادٌۢ بِٱلْقَارِعَةِ", tafsir: `` },
            { text: "فَأَمَّا ثَمُودُ فَأُهْلِكُوا۟ بِٱلطَّاغِيَةِ", tafsir: `فقد جوزوا على تكذيبهم بأنهم أهلكوا ( بِالطَّاغِيَةِ ) أي بالصيحة الطاغية التي طغت عليهم فخلعت قلوبهم وأهلكتهم.` },
            { text: "وَأَمَّا عَادٌ فَأُهْلِكُوا۟ بِرِيحٍ صَرْصَرٍ عَاتِيَةٍ", tafsir: `فقد جوزوا على تكذيبهم بأنهم أهلكوا ( بِرِيحٍ صَرْصَرٍ ) أي باردة شديدة العصوف ( عاتِيَةٍ ) قد عتت عند حدها المألوف ، والريح مؤنث سماعي. سَخَّرَها عَلَيْهِمْ سَبْعَ لَيالٍ وَثَمانِيَةَ أَيَّامٍ حُسُوماً فَتَرَى الْقَوْمَ فِيها صَرْعى كَأَنَّهُمْ أَعْجازُ نَخْلٍ خاوِيَةٍ (7) فَهَلْ تَرى لَهُمْ مِنْ باقِيَةٍ (8) وَجاءَ فِرْعَوْنُ وَمَنْ قَبْلَهُ وَالْمُؤْتَفِكاتُ بِالْخاطِئَةِ (9)` },
            { text: "سَخَّرَهَا عَلَيْهِمْ سَبْعَ لَيَالٍ وَثَمَٰنِيَةَ أَيَّامٍ حُسُومًا فَتَرَى ٱلْقَوْمَ فِيهَا صَرْعَىٰ كَأَنَّهُمْ أَعْجَازُ نَخْلٍ خَاوِيَةٍ", tafsir: `الله ( عَلَيْهِمْ ) بأن كانت مرسلة نحوهم ( سَبْعَ لَيالٍ وَثَمانِيَةَ أَيَّامٍ ) فكانت تهلكهم ببردها وصريرها ( حُسُوماً ) أي في حال كون تلك الليالي والأيام ولاء متتابعة ، مأخوذ من « حسم الداء بمتابعة الكي » ، أو بمعنى أنها حسمتهم أي قطعت نسلهم بحيث لم يبق منهم أحد ( فَتَرَى ) أيها الرائي ( الْقَوْمَ ) أي قبيلة عاد ( فِيها ) أي في تلك الأيام ( صَرْعى ) مصروعين ، جمع صريع ، وهو الشخص الواقع ميتا ( كَأَنَّهُمْ أَعْجازُ نَخْلٍ خاوِيَةٍ ) أي أصول نخل بالية ، فإن أعجاز جمع عجز وهو أصل النخل والخاوي الخالي الذي لا شيء في جوفه ، وشبهوا بذلك لأن استطالة جسمهم وبقائهم في الأرض يشبه ذلك.` },
            { text: "فَهَلْ تَرَىٰ لَهُم مِّنۢ بَاقِيَةٍ", tafsir: `أيها الرائي ( لَهُمْ ) أي لأولئك الأقوام المكذبين ( مِنْ باقِيَةٍ ) أي من نفس باقية ؟ وهذا استفهام للإيقاظ ، أي لم يبق منهم أحد ، وكذلك كل أمة كذبت لا بد لهم من الفناء حتى لا يبقى منهم أحد.` },
            { text: "وَجَآءَ فِرْعَوْنُ وَمَن قَبْلَهُۥ وَٱلْمُؤْتَفِكَٰتُ بِٱلْخَاطِئَةِ", tafsir: `وقومه العاصون لموسى عليه‌السلام ( وَمَنْ قَبْلَهُ ) من قوم نوح عليه‌السلام ونحوهم ( وَالْمُؤْتَفِكاتُ ) أي قرى لوط التي قلبت ـ من « ائتفك » أي انقلب ـ والمراد أهل تلك القرى ( بِالْخاطِئَةِ ) أي بالخطإ ، فإنها مصدر « خطأ » أو المراد بالخصلة الخاطئة نسبت الخطأ إليها مجازا بعد ما كان منسوبا إلى القوم. فَعَصَوْا رَسُولَ رَبِّهِمْ فَأَخَذَهُمْ أَخْذَةً رابِيَةً (10) إِنَّا لَمَّا طَغَى الْماءُ حَمَلْناكُمْ فِي الْجارِيَةِ (11) لِنَجْعَلَها لَكُمْ تَذْكِرَةً وَتَعِيَها أُذُنٌ واعِيَةٌ (12) فَإِذا نُفِخَ فِي الصُّورِ نَفْخَةٌ واحِدَةٌ (13) وَحُمِلَتِ الْأَرْضُ وَالْجِبالُ` },
            { text: "فَعَصَوْا۟ رَسُولَ رَبِّهِمْ فَأَخَذَهُمْ أَخْذَةً رَّابِيَةً", tafsir: `أولئك الأقوام ( رَسُولَ رَبِّهِمْ ) أي كل قوم رسوله ، والمراد بالرسول الجنس لا الواحد ـ كما تقدم وجهه سابقا ـ ( فَأَخَذَهُمْ ) الله بالعقوبة ( أَخْذَةً رابِيَةً ) أي زائدة في الشدة من « ربي » بمعنى زاد وطغى. [12] لقد أخذنا الأقوام المكذبين وأنجينا المصدقين ، كما إنا أنجينا المؤمنين بنوح عليه‌السلام الذين هم أجدادكم أيها الناس ( إِنَّا لَمَّا طَغَى الْماءُ ) أي جاوز الحد المألوف حتى أغرق الأرض كلها ( حَمَلْناكُمْ ) إنما نسب الحمل إليهم باعتبار أنهم من أولاد من حملوا ( فِي الْجارِيَةِ ) أي في السفينة التي كانت تجري في تلك المياه الكثيرة.` },
            { text: "إِنَّا لَمَّا طَغَا ٱلْمَآءُ حَمَلْنَٰكُمْ فِى ٱلْجَارِيَةِ", tafsir: `` },
            { text: "لِنَجْعَلَهَا لَكُمْ تَذْكِرَةً وَتَعِيَهَآ أُذُنٌ وَٰعِيَةٌ", tafsir: `أي نجعل تلك الفعلة التي فعلنا بكم حين آمنتم ( لَكُمْ ) أيها الناس ( تَذْكِرَةً ) تتذكرون بها نعم الله سبحانه ( وَتَعِيَها ) من « وعى » بمعنى أدرك ، أي تحفظها وتدركها ( أُذُنٌ واعِيَةٌ ) أي أذن تعي المواعظ وتستمع للعبر بقصد التفهم والعمل. [14] وإذا رأيتم عاقبة المكذبين وعاقبة المصدقين في الدنيا فاسمعوا عاقبتهما في الآخرة ( فَإِذا نُفِخَ فِي الصُّورِ ) أي نفخ إسرافيل في البوق لأجل إحياء البشر نفخته الثانية ( نَفْخَةٌ واحِدَةٌ ) بلا زيادة عليها إذ لا حاجة إلى أكثر منها ، فإن البشر يحيون بمجرد النفخة.` },
            { text: "فَإِذَا نُفِخَ فِى ٱلصُّورِ نَفْخَةٌ وَٰحِدَةٌ", tafsir: `` },
            { text: "وَحُمِلَتِ ٱلْأَرْضُ وَٱلْجِبَالُ فَدُكَّتَا دَكَّةً وَٰحِدَةً", tafsir: `أما حمل الأرض فباعتبار رفع منحدراتها فَدُكَّتا دَكَّةً واحِدَةً (14) فَيَوْمَئِذٍ وَقَعَتِ الْواقِعَةُ (15) وَانْشَقَّتِ السَّماءُ فَهِيَ يَوْمَئِذٍ واهِيَةٌ (16) وَالْمَلَكُ عَلى أَرْجائِها وَيَحْمِلُ عَرْشَ رَبِّكَ فَوْقَهُمْ يَوْمَئِذٍ ثَمانِيَةٌ (17) حتى تستوي مع سائر بقاعها ، وأما رفع الجبال فباعتبار أنها تنسف حتى تكون كالهباء لتستوي ظهر الأرض كلها بلا رفع ولا خفض ، وتكون ساحة القيامة عليها ( فَدُكَّتا ) أي كسرتا ودك بعضها على بعض ( دَكَّةً واحِدَةً ) فإن « الدك » يشمل الأرض والجبال مرة واحدة لا تدريجا.` },
            { text: "فَيَوْمَئِذٍ وَقَعَتِ ٱلْوَاقِعَةُ", tafsir: `أي في ذلك اليوم ( وَقَعَتِ الْواقِعَةُ ) أي القيامة ، وسميت « واقعة » لأنها تقع قطعا.` },
            { text: "وَٱنشَقَّتِ ٱلسَّمَآءُ فَهِىَ يَوْمَئِذٍ وَاهِيَةٌ", tafsir: `بمعنى انفرجت حتى ينظر الإنسان إليها فيراها متفطرة كانفطار الجدار ونحوه ( فَهِيَ ) أي السماء ( يَوْمَئِذٍ ) أي في يوم القيامة ( واهِيَةٌ ) من « وهى » بمعنى ضعف ، لأن نظامها يختل ، ومداراتها تتداخل وتخرب.` },
            { text: "وَٱلْمَلَكُ عَلَىٰٓ أَرْجَآئِهَا وَيَحْمِلُ عَرْشَ رَبِّكَ فَوْقَهُمْ يَوْمَئِذٍ ثَمَٰنِيَةٌ", tafsir: `يرى ( الْمَلَكُ ) النازل للحساب وسائر الأعمال ( عَلى أَرْجائِها ) أي على أطراف السماء ونواحيها ، و « أرجاء » جمع « رجا » بمعنى الطرف والناحية ( وَيَحْمِلُ عَرْشَ رَبِّكَ ) يا رسول الله ، وهو محل سمي بالعرش يصدر منه أوامر الله سبحانه ، كما أن البيت الحرام محل مضاف إليه سبحانه تشريفا ( فَوْقَهُمْ ) أي فوق أكتافهم ( يَوْمَئِذٍ ) أي في يوم القيامة ( ثَمانِيَةٌ ) من الملائكة العظام ، وكل ذلك لتكثير الهول ، والتناسب مع مدارك الإنسان الذي يرى العظمة ويشعر الخوف من هذه الأمور. يَوْمَئِذٍ تُعْرَضُونَ لا تَخْفى مِنْكُمْ خافِيَةٌ (18) فَأَمَّا مَنْ أُوتِيَ كِتابَهُ بِيَمِينِهِ فَيَقُولُ هاؤُمُ اقْرَؤُا كِتابِيَهْ (19) إِنِّي ظَنَنْتُ أَنِّي مُلاقٍ حِسابِيَهْ (20) فَهُوَ فِي عِيشَةٍ راضِيَةٍ (21)` },
            { text: "يَوْمَئِذٍ تُعْرَضُونَ لَا تَخْفَىٰ مِنكُمْ خَافِيَةٌ", tafsir: `أي في هذا اليوم ( تُعْرَضُونَ ) أنتم أيها البشر في ذلك العرض الهائل الرهيب ( لا تَخْفى مِنْكُمْ ) نفس ( خافِيَةٌ ) فليس أحد هناك مخفيا لأنه لا محل للاختفاء ، بل كلهم بارزون يراهم الناس معهم أعمالهم إن خيرا فخير وإن شرا فشر. [20] وهناك ينقسم الخلق إلى قسمين : ( فَأَمَّا مَنْ أُوتِيَ كِتابَهُ ) أي صحيفة أعماله التي أدرج فيها الملائكة كل ما عمل في دار الدنيا ( بِيَمِينِهِ ) أي بيده اليمنى ، وذلك علامة الفلاح والنجاة ( فَيَقُولُ ) لأهل القيامة ـ في فرح وسرور ـ ( هاؤُمُ ) أي تعالوا وخذوا ، اسم فعل أمر بصيغة الجمع ، مفرده « ها » ( اقْرَؤُا كِتابِيَهْ ) وانظروا ما فيه من الحسنات ، والهاء في « كتابيه » ونحوه للسكت ، يقرأ في الوقف ولا يقرأ في الوصل ، وكأنه جيء به للتنفس بأن لا يحبس النفس على الياء.` },
            { text: "فَأَمَّا مَنْ أُوتِىَ كِتَٰبَهُۥ بِيَمِينِهِۦ فَيَقُولُ هَآؤُمُ ٱقْرَءُوا۟ كِتَٰبِيَهْ", tafsir: `` },
            { text: "إِنِّى ظَنَنتُ أَنِّى مُلَٰقٍ حِسَابِيَهْ", tafsir: `في الدنيا ( أَنِّي مُلاقٍ حِسابِيَهْ ) في الآخرة ، ولذا عملت صالحا حتى حصلت على هذه المرتبة الرفيعة من الفلاح والنجاح والإتيان ب « ظننت » لعله لإفادة أن مجرد الظن كاف في العمل الصالح إذ رفع الضرر المظنون واجب بحكم العقل.` },
            { text: "فَهُوَ فِى عِيشَةٍ رَّاضِيَةٍ", tafsir: `أي صاحب الكتاب الذي أعطي كتابه بيمينه ( فِي عِيشَةٍ راضِيَةٍ ) نسبة الرضا إلى العيش مجاز ، فإن صاحب العيش هو الراضي أو أن اسم الفاعل بمعنى اسم المفعول ـ كما قالوا في أن هذين يأتي كل واحد منهما فِي جَنَّةٍ عالِيَةٍ (22) قُطُوفُها دانِيَةٌ (23) كُلُوا وَاشْرَبُوا هَنِيئاً بِما أَسْلَفْتُمْ فِي الْأَيَّامِ الْخالِيَةِ (24) وَأَمَّا مَنْ أُوتِيَ كِتابَهُ بِشِمالِهِ فَيَقُولُ يا لَيْتَنِي لَمْ أُوتَ كِتابِيَهْ (25) وَلَمْ أَدْرِ ما حِسابِيَهْ (26) يا لَيْتَها كانَتِ الْقاضِيَةَ (27) في مكان الآخر ، ف ( حِجاباً مَسْتُوراً ) (1) بمعنى ساترا كما تقدم ـ .` },
            { text: "فِى جَنَّةٍ عَالِيَةٍ", tafsir: `أي بستان ( عالِيَةٍ ) رفيعة القدر والمكان.` },
            { text: "قُطُوفُهَا دَانِيَةٌ", tafsir: `جمع « قطف » وهو ما يجتنى بسرعة ، أي ثمارها الناضجة أو أن القطف والقطع ( دانِيَةٌ ) أي قريبة إلى الشخص ، حتى لا يحتاج في قطفها إلى التجشم والتعب ، فإذا أرادها قربت من يده ليقطعها. [25] ويقال لهم ـ على وجه التكريم والإجلال ـ ( كُلُوا ) من ثمار الجنة ولحومها وسائر مأكولاتها ( وَاشْرَبُوا ) من أنهارها ( هَنِيئاً ) لكم أي تهنئون هنيئا ، بلا داء ولا علة يوجبها الأكل والشرب بسبب ما ( أَسْلَفْتُمْ ) أي قدمتم من أعمالكم الصالحة ( فِي الْأَيَّامِ الْخالِيَةِ ) أي الماضية ، والمراد بها أيام الدنيا التي خلت ومضت. [26] وإذ رأينا أحوال أهل الجنة فلننظر إلى أحوال أهل النار ( وَأَمَّا مَنْ أُوتِيَ ) أي أعطي ( كِتابَهُ ) أي كتاب أعماله التي أدرجها الملائكة فيه ( بِشِمالِهِ ) أي بيساره ، وذلك علامة أهل النار ( فَيَقُولُ يا لَيْتَنِي لَمْ أُوتَ ) أي لم أعط ( كِتابِيَهْ ) حتى أرى ما يسوؤني فيه.` },
            { text: "كُلُوا۟ وَٱشْرَبُوا۟ هَنِيٓـًٔۢا بِمَآ أَسْلَفْتُمْ فِى ٱلْأَيَّامِ ٱلْخَالِيَةِ", tafsir: `` },
            { text: "وَأَمَّا مَنْ أُوتِىَ كِتَٰبَهُۥ بِشِمَالِهِۦ فَيَقُولُ يَٰلَيْتَنِى لَمْ أُوتَ كِتَٰبِيَهْ", tafsir: `` },
            { text: "وَلَمْ أَدْرِ مَا حِسَابِيَهْ", tafsir: `أي يا ليتني لم أعرف ( ما حِسابِيَهْ ) أي أيّ شيء حسابي.` },
            { text: "يَٰلَيْتَهَا كَانَتِ ٱلْقَاضِيَةَ", tafsir: `أي ليت الموتة التي متها في الدنيا ( كانَتِ الْقاضِيَةَ ) تقضي ( 1) الإسراء : 46. ما أَغْنى عَنِّي مالِيَهْ (28) هَلَكَ عَنِّي سُلْطانِيَهْ (29) خُذُوهُ فَغُلُّوهُ (30) ثُمَّ الْجَحِيمَ صَلُّوهُ (31) ثُمَّ فِي سِلْسِلَةٍ ذَرْعُها سَبْعُونَ ذِراعاً فَاسْلُكُوهُ (32) إِنَّهُ كانَ لا يُؤْمِنُ بِاللهِ الْعَظِيمِ (33) على حياتي إلى الأبد فلم أبعث بعدها لأرى سيئات أعمالي وأبتلي بالخزي والعذاب.` },
            { text: "مَآ أَغْنَىٰ عَنِّى مَالِيَهْ", tafsir: `أي ما دفع عني مالي من عذاب الله شيئا.` },
            { text: "هَلَكَ عَنِّى سُلْطَٰنِيَهْ", tafsir: `وسلطنتي وجاهي ذهبتا ، فلا مال ينفع ولا سلطان ينجع ـ مما كرست حياتي وجهودي لهما ـ . [31] ثم يأتي الخطاب من المصدر الأعلى للملائكة الموكلين بهذا المجرم ( خُذُوهُ ) فلا تتركوه يفر ويهرب ( فَغُلُّوهُ ) أي أوثقوه بالغل ، وهو الحديد الذي يربط أعضاء الإنسان بعضها ببعض لئلا يتمكن من الفرار.` },
            { text: "خُذُوهُ فَغُلُّوهُ", tafsir: `` },
            { text: "ثُمَّ ٱلْجَحِيمَ صَلُّوهُ", tafsir: `بعد إغلاله بالغل ( صَلُّوهُ ) أي أدخلوه فيها والجحيم هي النار العظيمة.` },
            { text: "ثُمَّ فِى سِلْسِلَةٍ ذَرْعُهَا سَبْعُونَ ذِرَاعًا فَٱسْلُكُوهُ", tafsir: `أي طولها بالذراع ( سَبْعُونَ ذِراعاً ) والطول لتشديد العذاب والغم عليه ( فَاسْلُكُوهُ ) أي اربطوه بها ، وقيل تدخل من حلقه وتخرج من دبره ، وهذا هو سلكه فيها. [34] ثم يأتي السياق ليبين علة هذه الأنواع من العذاب ( إِنَّهُ ) أي هذا المجرم ( كانَ ) في الدنيا ( لا يُؤْمِنُ بِاللهِ الْعَظِيمِ ) مع عظمته سبحانه ، كان يعاند ولا يؤمن. وَلا يَحُضُّ عَلى طَعامِ الْمِسْكِينِ (34) فَلَيْسَ لَهُ الْيَوْمَ هاهُنا حَمِيمٌ (35) وَلا طَعامٌ إِلاَّ مِنْ غِسْلِينٍ (36) لا يَأْكُلُهُ إِلاَّ الْخاطِؤُنَ (37) فَلا أُقْسِمُ بِما تُبْصِرُونَ (38) وَما لا تُبْصِرُونَ (39)` },
            { text: "إِنَّهُۥ كَانَ لَا يُؤْمِنُ بِٱللَّهِ ٱلْعَظِيمِ", tafsir: `` },
            { text: "وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ", tafsir: `أي لا يحث الناس ـ من باب الأمر بالمعروف ـ أو هو كناية عن منعه بنفسه ، لأن المانع لا يحث ، فأتى بالمسبب وأريد السبب ( عَلى طَعامِ الْمِسْكِينِ ) أي إطعام الفقراء ، الذين يجب الحض على إطعامهم لأنهم في معرض الهلكة.` },
            { text: "فَلَيْسَ لَهُ ٱلْيَوْمَ هَٰهُنَا حَمِيمٌ", tafsir: `هذا الكافر ( الْيَوْمَ ) أي في يوم القيامة ( هاهُنا ) في المحشر ( حَمِيمٌ ) صديق ينفعه.` },
            { text: "وَلَا طَعَامٌ إِلَّا مِنْ غِسْلِينٍ", tafsir: `له ( طَعامٌ ) يأكله ( إِلَّا مِنْ غِسْلِينٍ ) وهو صديد قيح أهل النار ، أي غسالتهم.` },
            { text: "لَّا يَأْكُلُهُۥٓ إِلَّا ٱلْخَٰطِـُٔونَ", tafsir: `أي لا يأكل الغسلين ( إِلَّا الْخاطِؤُنَ ) الذين اخطأوا في الدنيا بالكفر والعصيان. [39] وبعد استعراض أحوال المؤمنين والكافرين في الآخرة يأتي السياق ، ليستدل على الرسالة وينفي مزاعم القوم حول الرسول صلى‌الله‌عليه‌وآله‌وسلم ( فَلا أُقْسِمُ بِما تُبْصِرُونَ ) أيها البشر.` },
            { text: "فَلَآ أُقْسِمُ بِمَا تُبْصِرُونَ", tafsir: `` },
            { text: "وَمَا لَا تُبْصِرُونَ", tafsir: `ب ( ما لا تُبْصِرُونَ ) أي بالمشاهدات والمغيبات ، والإتيان ب « لا » للطيفة ، هي الحلف ، وإفادة أن الحلف لعظيم ، فإذا أردت أن تحلف ، وأردت أن تبين أن الحلف عظيم تقول « لا أقسم بحياتك إن الأمر كذا » فأنت لم تحلف مع الإلماع إلى الحلف ، وعلى هذا ف « لا » للنفي ، لا أنها زائدة. إِنَّهُ لَقَوْلُ رَسُولٍ كَرِيمٍ (40) وَما هُوَ بِقَوْلِ شاعِرٍ قَلِيلاً ما تُؤْمِنُونَ (41) وَلا بِقَوْلِ كاهِنٍ قَلِيلاً ما تَذَكَّرُونَ (42) تَنْزِيلٌ مِنْ رَبِّ الْعالَمِينَ (43) وَلَوْ تَقَوَّلَ عَلَيْنا بَعْضَ الْأَقاوِيلِ (44) لَأَخَذْنا مِنْهُ بِالْيَمِينِ (45) [41] ثم بين متعلق الحلف بقوله : ( إِنَّهُ ) أي إن القرآن ( لَقَوْلُ رَسُولٍ كَرِيمٍ ) عند الله سبحانه ، فهو من قبله ، إذ الرسول لا يقول إلّا من عنده سبحانه.` },
            { text: "إِنَّهُۥ لَقَوْلُ رَسُولٍ كَرِيمٍ", tafsir: `` },
            { text: "وَمَا هُوَ بِقَوْلِ شَاعِرٍ قَلِيلًا مَّا تُؤْمِنُونَ", tafsir: `أي ليس القرآن ( بِقَوْلِ شاعِرٍ ) فقد كانوا يقولون : إن محمدا شاعر والقرآن شعر ( قَلِيلاً ما تُؤْمِنُونَ ) أي قليل إيمانكم ، أو يؤمن منكم بالرسول أشخاص قليلون ، وهذا للاستنكار والتقريع ، أي لم تكونون هكذا ؟` },
            { text: "وَلَا بِقَوْلِ كَاهِنٍ قَلِيلًا مَّا تَذَكَّرُونَ", tafsir: `القرآن ( بِقَوْلِ كاهِنٍ ) فقد كان بعضهم يقول : إن الرسول كاهن ، وأن القرآن كهانة ، والكاهن من له اتصال بالشياطين فيأتون إليه بأخبار ملفقة مسجعة باطلها أكثر من حقّها ( قَلِيلاً ما تَذَكَّرُونَ ) فلا تتذكرون الحق المودوع في فطرتكم إلّا قليلا ، أو قليل منكم يتذكرون الحق. [44] إنه ( تَنْزِيلٌ ) أي منزل ( مِنْ ) عند ( رَبِّ الْعالَمِينَ ) على الرسول صلى‌الله‌عليه‌وآله‌وسلم .` },
            { text: "تَنزِيلٌ مِّن رَّبِّ ٱلْعَٰلَمِينَ", tafsir: `` },
            { text: "وَلَوْ تَقَوَّلَ عَلَيْنَا بَعْضَ ٱلْأَقَاوِيلِ", tafsir: `أي افترى الرسول علينا ( بَعْضَ الْأَقاوِيلِ ) المكذوبة ، والتقوّل اختلاق القول ونسبته إلى من ليس منه.` },
            { text: "لَأَخَذْنَا مِنْهُ بِٱلْيَمِينِ", tafsir: `أي من الرسول صلى‌الله‌عليه‌وآله‌وسلم ( بِالْيَمِينِ ) أي بيمينه بأن ثُمَّ لَقَطَعْنا مِنْهُ الْوَتِينَ (46) فَما مِنْكُمْ مِنْ أَحَدٍ عَنْهُ حاجِزِينَ (47) وَإِنَّهُ لَتَذْكِرَةٌ لِلْمُتَّقِينَ (48) وَإِنَّا لَنَعْلَمُ أَنَّ مِنْكُمْ مُكَذِّبِينَ (49) قطعناها ، لأن من يفسد في الأرض جزاؤه أن تقطع يده. ولا يخفى أن هذا الكلام للإنكار على الكفار ، لأنه يمس ساحة قدس الرسول صلى‌الله‌عليه‌وآله‌وسلم ، وهذا من قبيل ( وَأَخَذَ بِرَأْسِ أَخِيهِ يَجُرُّهُ إِلَيْهِ ) (1) كما سبق الكلام فيه.` },
            { text: "ثُمَّ لَقَطَعْنَا مِنْهُ ٱلْوَتِينَ", tafsir: `أي من الرسول ( الْوَتِينَ ) أي قطعنا عرق قلبه ، وهو كناية عن إهلاكه ، أو المعنى لأخذنا يده اليمنى لنقتله كما يفعل الجلاد بالمجرم يأخذ يده ليسهل قتله. [48] ولو كان كاذبا ، وفعلنا به ذلك ( فَما مِنْكُمْ ) أيها البشر ( مِنْ أَحَدٍ ) « من » زيادة لتعميم النفي ( عَنْهُ ) أي عن الرسول ( حاجِزِينَ ) أي لا يقدر أحد منكم أن يدفعنا ويحجز بيننا وبين الرسول حتى لا تحل به عقوبتنا.` },
            { text: "فَمَا مِنكُم مِّنْ أَحَدٍ عَنْهُ حَٰجِزِينَ", tafsir: `` },
            { text: "وَإِنَّهُۥ لَتَذْكِرَةٌ لِّلْمُتَّقِينَ", tafsir: `أي القرآن ( لَتَذْكِرَةٌ ) مذكّر لما أودع في فطرتهم من التوحيد وسائر الأصول ( لِلْمُتَّقِينَ ) الذين يتقون الآثام ، فإن الإنسان المحافظ للحدود الذي يتقي ويخاف الزلة يتذكر بالقرآن ، والتخصيص بهم لأنهم المنتفعون بالقرآن دون سواهم.` },
            { text: "وَإِنَّا لَنَعْلَمُ أَنَّ مِنكُم مُّكَذِّبِينَ", tafsir: `أيها الناس ( مُكَذِّبِينَ ) يكذبون بالله وبالرسول ، وبالمعاد ، وبالقرآن. وهذا تهديد لهم بأنهم سوف يحاسبون ويعذبون بسبب تكذيبهم. ( 1) الأعراف : 151. وَإِنَّهُ لَحَسْرَةٌ عَلَى الْكافِرِينَ (50) وَإِنَّهُ لَحَقُّ الْيَقِينِ (51) فَسَبِّحْ بِاسْمِ رَبِّكَ الْعَظِيمِ (52)` },
            { text: "وَإِنَّهُۥ لَحَسْرَةٌ عَلَى ٱلْكَٰفِرِينَ", tafsir: `أي القرآن ( لَحَسْرَةٌ عَلَى الْكافِرِينَ ) يوجب الحسرة عليهم يوم القيامة حيث لم يعملوا به مع أنه في متناول أيديهم.` },
            { text: "وَإِنَّهُۥ لَحَقُّ ٱلْيَقِينِ", tafsir: `أي القرآن ( لَحَقُّ الْيَقِينِ ) أي هذا القسم من اليقين وهو اليقين البالغ درجة راقية لمطابقته للواقع ، فإن هناك علم اليقين وهو ما يعلم بغير أن يشاهد ، وحق اليقين وهو ما يعلم ويشاهد ـ وقد سبق المثال بالنار لذلك ـ .` },
            { text: "فَسَبِّحْ بِٱسْمِ رَبِّكَ ٱلْعَظِيمِ", tafsir: `` }
        ]
    },
    70: { // سورة المعارج
        name: "المعارج",
        basmalaTafsir: ``,
        verses: [
            { text: "سَأَلَ سَآئِلٌۢ بِعَذَابٍ وَاقِعٍ", tafsir: `يعني استدعى مستدع وطلب العذاب ، وقد عرفت أنه « الفهري » ، ومن المحتمل أن المراد به أعم منه ليشمل الكفار الذين كانوا يستعجلون بالعذاب ـ استهزاء ـ .` },
            { text: "لِّلْكَٰفِرِينَ لَيْسَ لَهُۥ دَافِعٌ", tafsir: `أي أن ذلك العذاب للكافرين ، فهو واقع بهم سواء طلبوه أم لم يطلبوه ( لَيْسَ لَهُ ) أي لذلك العذاب ( دافِعٌ ) يدفعه.` },
            { text: "مِّنَ ٱللَّهِ ذِى ٱلْمَعَارِجِ", tafsir: `فإن العذاب من قبله سبحانه ( ذِي الْمَعارِجِ ) جمع « معراج » وهو محل العروج والصعود ، ولعل المراد بها السماوات التي هي معارج للملائكة ولأرواح المؤمنين ، وهذا كناية عن علو شأنه سبحانه ، فإذا أراد شيئا لا بد وأن يقع. [5] ثم بين مقدار ارتفاع المعارج ، حتى لا يتوهم أن مقدار ارتفاعها كالمألوف في الأذهان من الارتفاعات القليلة ( تَعْرُجُ الْمَلائِكَةُ وَالرُّوحُ ) الذي هو أعظم الملائكة ، أو المراد أرواح المؤمنين ( إِلَيْهِ ) أي إلى المحل الذي جعله سبحانه مصدرا لأمره ومحلا لتشريفه ، كالبيت الحرام الذي جعله محلا لعنايته ـ فإنه سبحانه منزه عن المكان ـ ( فِي يَوْمٍ كانَ مِقْدارُهُ ) أي مقدار ذلك اليوم ( خَمْسِينَ أَلْفَ سَنَةٍ ) فطول ذلك اليوم ـ إذا سير فيه بالسير العادي ـ خمسون ألف سنة من سني الدنيا ، وبمعرفة طول ذلك اليوم يعرف مقدار بعد محل تشريفاته سبحانه من الأرض. فَاصْبِرْ صَبْراً جَمِيلاً (5) إِنَّهُمْ يَرَوْنَهُ بَعِيداً (6) وَنَراهُ قَرِيباً (7) يَوْمَ تَكُونُ السَّماءُ كَالْمُهْلِ (8) وَتَكُونُ الْجِبالُ كَالْعِهْنِ (9) وَلا يَسْئَلُ حَمِيمٌ حَمِيماً (10) يُبَصَّرُونَهُمْ ويحتمل في العبارة معنى آخر ، وهو أن العروج إلى محل تشريفاته إنما هو في يوم القيامة الذي مقداره خمسين ألف سنة ، فهو إما لبيان مقدار بعد محل التشريفات عن الأرض وإما لبيان مقدار ذلك اليوم ، وفي الأحاديث كلا المعنيين.` },
            { text: "تَعْرُجُ ٱلْمَلَٰٓئِكَةُ وَٱلرُّوحُ إِلَيْهِ فِى يَوْمٍ كَانَ مِقْدَارُهُۥ خَمْسِينَ أَلْفَ سَنَةٍ", tafsir: `` },
            { text: "فَٱصْبِرْ صَبْرًا جَمِيلًا", tafsir: `يا رسول الله ( صَبْراً جَمِيلاً ) لا جزع فيه ولا شكوى مما تقاسيه من الأتعاب وتكذيب الكفار.` },
            { text: "إِنَّهُمْ يَرَوْنَهُۥ بَعِيدًا", tafsir: `أي الكفار ( يَرَوْنَهُ ) أي ذلك اليوم وهو يوم القيامة ـ بناء على المعنى الثاني ـ أو العذاب ( بَعِيداً ) ولذا يعملون بالكفر والمعاصي.` },
            { text: "وَنَرَىٰهُ قَرِيبًا", tafsir: `أي نعلمه نحن ( قَرِيباً ) فإن كل آت قريب ، وإن طال الأمد في مقاييس الناس. [9] ثم بين السياق وقت العذاب ، أو وقت ذلك اليوم ( يَوْمَ تَكُونُ السَّماءُ كَالْمُهْلِ ) أي الصفر المذاب ، وكأنه للصب على الناس المجرمين.` },
            { text: "يَوْمَ تَكُونُ ٱلسَّمَآءُ كَٱلْمُهْلِ", tafsir: `` },
            { text: "وَتَكُونُ ٱلْجِبَالُ كَٱلْعِهْنِ", tafsir: `كالصوف المنفوش ، فإنها تطير في الجو هباء ، كما يطير الصوف.` },
            { text: "وَلَا يَسْـَٔلُ حَمِيمٌ حَمِيمًا", tafsir: `في ذلك اليوم ( حَمِيمٌ ) أي صديق ( حَمِيماً ) أي عن صديقه لشغل كل إنسان بنفسه.` },
            { text: "يُبَصَّرُونَهُمْ يَوَدُّ ٱلْمُجْرِمُ لَوْ يَفْتَدِى مِنْ عَذَابِ يَوْمِئِذٍۭ بِبَنِيهِ", tafsir: `أي يرى بعض الأصدقاء بعضا ولكن لا يسألون عنهم يَوَدُّ الْمُجْرِمُ لَوْ يَفْتَدِي مِنْ عَذابِ يَوْمِئِذٍ بِبَنِيهِ (11) وَصاحِبَتِهِ وَأَخِيهِ (12) و َفَصِيلَتِهِ الَّتِي تُؤْوِيهِ (13) وَمَنْ فِي الْأَرْضِ جَمِيعاً ثُمَّ يُنْجِيهِ (14) كَلاَّ إِنَّها لَظى (15) نَزَّاعَةً لِلشَّوى (16) كيف أنتم ؟ والفعل مجهول من باب التفعيل ، كأنه يحصل منهم الإبصار قهرا ، إشارة إلى أنهم لا يريدون أن يبصروا أصدقاءهم ، وإنما تقع عينهم عليهم بدون إرادة ( يَوَدُّ الْمُجْرِمُ ) أي يتمنى ويحب العاصي ( لَوْ يَفْتَدِي ) أي يعطي الفدية عن نفسه لينجيها ( مِنْ عَذابِ يَوْمِئِذٍ ) أي يوم القيامة ( بِبَنِيهِ ) بأن يدفع عوضه أولاده الذين هم أعز الناس عنده فينزل بهم العذاب دونه.` },
            { text: "وَصَٰحِبَتِهِۦ وَأَخِيهِ", tafsir: `ب ( صاحِبَتِهِ ) أي يعطي زوجته للعذاب لينجو بنفسه ( وَ ) ب ( أَخِيهِ ) حتى ينجو.` },
            { text: "وَفَصِيلَتِهِ ٱلَّتِى تُـْٔوِيهِ", tafsir: `يفتدي ب ( فَصِيلَتِهِ الَّتِي تُؤْوِيهِ ) أي عشيرته ـ التي انفصل منهم بالولادة ـ التي كانت تؤوي ، أي تعطي المأوى لهذا الإنسان في الشدائد.` },
            { text: "وَمَن فِى ٱلْأَرْضِ جَمِيعًا ثُمَّ يُنجِيهِ", tafsir: `يفتدي ب ( مَنْ فِي الْأَرْضِ جَمِيعاً ) أي يعطي بدله جميع الخلائق ( ثُمَّ يُنْجِيهِ ) ذلك الفداء عن العذاب. [16] وهل يفيد الفداء ـ ولو فرضنا أنه تمكن من كل ذلك ـ ؟ ( كَلَّا ) لا ينجيه شيء ولا يفيده الفداء ( إِنَّها ) أي نار جهنم ( لَظى ) أي لهب خالص ، والمعنى للمجرم اللهب فلا يفيده الفداء. [17] في حال كونها ( نَزَّاعَةً لِلشَّوى ) أي تنزع كثير الأطراف فلا تترك جلدا ولا لحما. « وشوى » الأكارع والأطراف ، وتسميتها بالشوى لأنها تَدْعُوا مَنْ أَدْبَرَ وَتَوَلَّى (17) وَجَمَعَ فَأَوْعى (18) إِنَّ الْإِنْسانَ خُلِقَ هَلُوعاً (19) إِذا مَسَّهُ الشَّرُّ جَزُوعاً (20) وَإِذا مَسَّهُ الْخَيْرُ مَنُوعاً (21) إِلاَّ الْمُصَلِّينَ (22) الَّذِينَ هُمْ عَلى صَلاتِهِمْ دائِمُونَ (23) تشوى بالنار.` },
            { text: "كَلَّآ إِنَّهَا لَظَىٰ", tafsir: `` },
            { text: "نَزَّاعَةً لِّلشَّوَىٰ", tafsir: `` },
            { text: "تَدْعُوا۟ مَنْ أَدْبَرَ وَتَوَلَّىٰ", tafsir: `النار إلى نفسها ، بالالتهاب والالتهام ( مَنْ أَدْبَرَ ) عن الحق ، أي أعطاه دبره ليعرض عنه ( وَتَوَلَّى ) أي أعرض عن الدين.` },
            { text: "وَجَمَعَ فَأَوْعَىٰٓ", tafsir: `المال ( فَأَوْعى ) أي أمسكه في الوعاء ـ كالصندوق ونحوه ـ فلم ينفقه في طاعة الله.` },
            { text: "إِنَّ ٱلْإِنسَٰنَ خُلِقَ هَلُوعًا", tafsir: `أي شديد الحرص ، من « الهلع » وهو الحرص. [21] ثم بين سبحانه معنى الهلوع بقوله : ( إِذا مَسَّهُ الشَّرُّ ) أي لامسة ونزل به شر من فقر ومرض وخوف وما أشبه ( جَزُوعاً ) أي كان كثير الجزع ، بدون أن يصبر وينتظر الفرج.` },
            { text: "إِذَا مَسَّهُ ٱلشَّرُّ جَزُوعًا", tafsir: `` },
            { text: "وَإِذَا مَسَّهُ ٱلْخَيْرُ مَنُوعًا", tafsir: `أي لامسة ونزل به كالغنى والصحة والأمن والجاه ( مَنُوعاً ) أي كان كثير المنع لخيره عن الناس ولا يقوم بواجب الشكر من بذل ماله وجاهه ، والقيام في الخدمات بصحته وأمنه. [23] إن ذلك طبيعة الإنسان وفطرته التي ركبت فيه ( إِلَّا الْمُصَلِّينَ ) الذين اتصلوا بالله سبحانه وارتفعوا عن مهاوي النفس ، بالصلاة ـ والإتيان بها لأنها تلازم الإيمان وسائر الصفات الحسنة ـ .` },
            { text: "إِلَّا ٱلْمُصَلِّينَ", tafsir: `` },
            { text: "ٱلَّذِينَ هُمْ عَلَىٰ صَلَاتِهِمْ دَآئِمُونَ", tafsir: `يقيمونها باستمرار ، فإن إقامة وَالَّذِينَ فِي أَمْوالِهِمْ حَقٌّ مَعْلُومٌ (24) لِلسَّائِلِ وَالْمَحْرُومِ (25) وَالَّذِينَ يُصَدِّقُونَ بِيَوْمِ الدِّينِ (26) وَالَّذِينَ هُمْ مِنْ عَذابِ رَبِّهِمْ مُشْفِقُونَ (27) إِنَّ عَذابَ رَبِّهِمْ غَيْرُ مَأْمُونٍ (28) الصّلاة بصورة مستمرة توحي إلى النفس معاني الخير ، لما يحصل من الإيماء المكرر الموجب لتهذيب النفس كما قال في آية أخرى ( وَالَّذِينَ هُمْ عَلى صَلَواتِهِمْ يُحافِظُونَ ) (1) .` },
            { text: "وَٱلَّذِينَ فِىٓ أَمْوَٰلِهِمْ حَقٌّ مَّعْلُومٌ", tafsir: `وهو مقدار منه يعطيه للفقراء ، وقد ورد أن الحق المعلوم يراد به غير الزكاة مما يفرضه الرجل على نفسه فيخرجه من ماله في كل يوم أو في كل جمعة.` },
            { text: "لِّلسَّآئِلِ وَٱلْمَحْرُومِ", tafsir: `الذي يسأل لافتقاره ومسكنته ( وَالْمَحْرُومِ ) وهو الفقير الذي حرم من الثروة ولا يسأل الناس لعفته.` },
            { text: "وَٱلَّذِينَ يُصَدِّقُونَ بِيَوْمِ ٱلدِّينِ", tafsir: `أي يؤمنون بالقيامة الذي هو يوم الجزاء ـ إذ الدين بمعنى الجزاء ، كما قال « ولا أنت ديّاني فتخزوني » ـ ولعل الإتيان من باب التفعيل لإفادة كثرة تصديقهم بكل ما يقع في ذلك اليوم.` },
            { text: "وَٱلَّذِينَ هُم مِّنْ عَذَابِ رَبِّهِم مُّشْفِقُونَ", tafsir: `في الدنيا وفي الآخرة ( مُشْفِقُونَ ) أي خائفون ، من « أشفق » بمعنى خاف. [29] وإنما يخافون ف ( إِنَّ عَذابَ رَبِّهِمْ ) بالكفار والعاصين ( غَيْرُ مَأْمُونٍ ) أي لا يؤمن حلوله ، فلا ينبغي لأحد أن يأمن منه فيتمادى في الكفر ( 1) المؤمنون : 10. وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حافِظُونَ (29) إِلاَّ عَلى أَزْواجِهِمْ أَوْ ما مَلَكَتْ أَيْمانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ (30) فَمَنِ ابْتَغى وَراءَ ذلِكَ فَأُولئِكَ هُمُ العادُونَ (31) وَالَّذِينَ هُمْ لِأَماناتِهِمْ وَعَهْدِهِمْ راعُونَ (32) وَالَّذِينَ هُمْ بِشَهاداتِهِمْ قائِمُونَ (33) والعصيان اغترارا.` },
            { text: "إِنَّ عَذَابَ رَبِّهِمْ غَيْرُ مَأْمُونٍ", tafsir: `` },
            { text: "وَٱلَّذِينَ هُمْ لِفُرُوجِهِمْ حَٰفِظُونَ", tafsir: `جمع « فرج » وهو القبل والدبر وسمي بذلك لانفراج وانشقاق فيهما ( حافِظُونَ ) فلا يستحلونها في المعاصي.` },
            { text: "إِلَّا عَلَىٰٓ أَزْوَٰجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَٰنُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ", tafsir: `أي زوجاتهم ويعرف العكس بالتلازم ( أَوْ ما مَلَكَتْ أَيْمانُهُمْ ) أي إمائهم ، ونسب الملك إلى اليمين لأنها آلة اكتساب المال الموجبة لشراء الإماء ، والمتعة والتحليل داخلان في الأزواج أو الثاني داخل في ما ملكت أيمانهم ( فَإِنَّهُمْ غَيْرُ مَلُومِينَ ) لا يلامون على استعمال فروجهم في هذا النوع الخاص من اللذة.` },
            { text: "فَمَنِ ٱبْتَغَىٰ وَرَآءَ ذَٰلِكَ فَأُو۟لَٰٓئِكَ هُمُ ٱلْعَادُونَ", tafsir: `أي طلب اللذة في ( وَراءَ ذلِكَ ) الذي ذكر بأن استعمله في الحرام في زنى ولواط وسحق واستمناء ( فَأُولئِكَ ) المبتغون ( هُمُ العادُونَ ) الذين تعدوا الحق وحدود الشريعة ، المستحقون بذلك النكال والعذاب.` },
            { text: "وَٱلَّذِينَ هُمْ لِأَمَٰنَٰتِهِمْ وَعَهْدِهِمْ رَٰعُونَ", tafsir: `التي تودع عندهم ( وَعَهْدِهِمْ ) مع من عاهدوا ( راعُونَ ) فلا يخونون الأمانات ، ولا ينقضون العهود.` },
            { text: "وَٱلَّذِينَ هُم بِشَهَٰدَٰتِهِمْ قَآئِمُونَ", tafsir: `أي يقومون بالشهادة التي تحمّلوها ، فإذا صار موقع أن يشهدوا شهدوا بالحق لا بالباطل ، ولا يهربون من وَالَّذِينَ هُمْ عَلى صَلاتِهِمْ يُحافِظُونَ (34) أُولئِكَ فِي جَنَّاتٍ مُكْرَمُونَ (35) فَما لِ الَّذِينَ كَفَرُوا قِبَلَكَ مُهْطِعِينَ (36) عَنِ الْيَمِينِ وَعَنِ الشِّمالِ عِزِينَ (37) أَ يَطْمَعُ كُلُّ امْرِئٍ مِنْهُمْ أَنْ يُدْخَلَ جَنَّةَ نَعِيمٍ (38) الشهادة لخوف أو طمع.` },
            { text: "وَٱلَّذِينَ هُمْ عَلَىٰ صَلَاتِهِمْ يُحَافِظُونَ", tafsir: `وكأن المحافظة أداؤها بحدودها وآدابها ، « دائمون » الاستمرار عليها ، أو الآية السابقة في النوافل وهذه في الفرائض ، كما روي عن الإمام الباقر عليه‌السلام .` },
            { text: "أُو۟لَٰٓئِكَ فِى جَنَّٰتٍ مُّكْرَمُونَ", tafsir: `المؤمنون المتصفون بتلك الصفات ( فِي جَنَّاتٍ ) أي بساتين تجنها الأشجار والقصور ( مُكْرَمُونَ ) أي يكرمهم الله سبحانه والملائكة ، فهم في نعمة مادية ومعنوية. [37] وبعد وضوح الحق ( فَما لِ الَّذِينَ كَفَرُوا قِبَلَكَ ) يا رسول الله أي أيّ شيء لهم وما حملهم على أن يفعلوا ما فعلوا ؟ ( مُهْطِعِينَ ) من « أهطع » إذا نظر ببصره إلى الشيء لا يزيله عنه ، ويكون ذلك عن حب أو عداوة ، والمراد هنا الثاني ، أي ما لهم ينظرون إليك شزرا نظر عداوة وشنآن ؟` },
            { text: "فَمَالِ ٱلَّذِينَ كَفَرُوا۟ قِبَلَكَ مُهْطِعِينَ", tafsir: `` },
            { text: "عَنِ ٱلْيَمِينِ وَعَنِ ٱلشِّمَالِ عِزِينَ", tafsir: `أي من طرف يمينك وطرف شمالك ( عِزِينَ ) جمع « عزة » أي جماعات متفرقين عصبة عصبة ، فإن « عزة » بمعنى الجماعة ، وهذا هو الغالب في الناس إذا ظهر فيهم مصطلح أو مبدع ، فإنهم ينظرون إليه جماعات من كل صوب إذا كان في محل أو مر بمحل.` },
            { text: "أَيَطْمَعُ كُلُّ ٱمْرِئٍ مِّنْهُمْ أَن يُدْخَلَ جَنَّةَ نَعِيمٍ", tafsir: `أي من هؤلاء الكفار ( أَنْ يُدْخَلَ جَنَّةَ نَعِيمٍ ) ؟ كَلاَّ إِنَّا خَلَقْناهُمْ مِمَّا يَعْلَمُونَ (39) فَلا أُقْسِمُ بِرَبِّ الْمَشارِقِ وَالْمَغارِبِ إِنَّا لَقادِرُونَ (40) عَلى أَنْ نُبَدِّلَ خَيْراً مِنْهُمْ وَما نَحْنُ بِمَسْبُوقِينَ (41) فَذَرْهُمْ يَخُوضُوا فما هذا الطمع السخيف بعد كفرهم وعنادهم ؟ فكأنهم إذا أبغضوا الرسول ونظروا إليه نظرا شزرا توقعوا بذلك نيل رضى الله سبحانه ودخول جنته.` },
            { text: "كَلَّآ إِنَّا خَلَقْنَٰهُم مِّمَّا يَعْلَمُونَ", tafsir: `لا يدخلون الجنة ، ف ( إِنَّا خَلَقْناهُمْ مِمَّا يَعْلَمُونَ ) من نطفة قذرة ، وهل من أصله نطفة صالح لدخول الجنة بدون الإيمان والعمل الصالح ؟ فإن الشيء إما بأصله أو بعمله ، وهؤلاء أصلهم نطفة قذرة ، وعملهم كفر وعصيان ، فلا صلوح لهم لدخول الجنان.` },
            { text: "فَلَآ أُقْسِمُ بِرَبِّ ٱلْمَشَٰرِقِ وَٱلْمَغَٰرِبِ إِنَّا لَقَٰدِرُونَ", tafsir: `« لا » للنفي ، وهذا إلماع إلى حلف ، في صورة عدم الحلف ـ كما سبق ـ والمشارق باعتبار شروق الشمس في كل يوم من نقطة من الفلك ، وكذا المغارب بالنسبة إلى غروبها ( إِنَّا لَقادِرُونَ ) .` },
            { text: "عَلَىٰٓ أَن نُّبَدِّلَ خَيْرًا مِّنْهُمْ وَمَا نَحْنُ بِمَسْبُوقِينَ", tafsir: `أي أن نهلكهم ونأتي بدلهم خيرا منهم أناسا يؤمنون ولا يعصون ( وَما نَحْنُ بِمَسْبُوقِينَ ) بأن يسبقنا الكفار في الهرب ، حتى نبقى وراءهم لا نلحق بهم فلا نتمكن من تعذيبهم كالحاكم الذي يبقى ويهرب منه المجرم فلا يتمكن من إنزال العقوبة به.` },
            { text: "فَذَرْهُمْ يَخُوضُوا۟ وَيَلْعَبُوا۟ حَتَّىٰ يُلَٰقُوا۟ يَوْمَهُمُ ٱلَّذِى يُوعَدُونَ", tafsir: `أي دع يا رسول الله هؤلاء الكفار ( يَخُوضُوا ) في باطلهم ، وأصل الخوض الارتماس في الماء ، وشبه به الإنسان الذي وَيَلْعَبُوا حَتَّى يُلاقُوا يَوْمَهُمُ الَّذِي يُوعَدُونَ (42) يَوْمَ يَخْرُجُونَ مِنَ الْأَجْداثِ سِراعاً كَأَنَّهُمْ إِلى نُصُبٍ يُوفِضُونَ (43) خاشِعَةً أَبْصارُهُمْ تَرْهَقُهُمْ ذِلَّةٌ ذلِكَ الْيَوْمُ الَّذِي كانُوا يُوعَدُونَ (44) يتكلم ويعمل بالباطل ، كأنه خائض فيه ( وَيَلْعَبُوا ) أي يفعلوا فعل اللاعب الذي لا يريد غاية من عمله وإنما يقضي الوقت بذلك ( حَتَّى يُلاقُوا يَوْمَهُمُ الَّذِي يُوعَدُونَ ) وهو يوم القيامة. [44] ثم بين سبحانه ذلك اليوم بقوله : ( يَوْمَ يَخْرُجُونَ مِنَ الْأَجْداثِ ) جمع جدث وهو القبر ( سِراعاً ) أي مسرعين ، لشدة هولهم فإن الخائف يسرع في المشي ليجد مأمنا قبل أن ينزل به العذاب ( كَأَنَّهُمْ إِلى نُصُبٍ ) جمع نصب كسقف جمع سقف ، وهو الصنم ( يُوفِضُونَ ) أي يسرعون ، فقد كانوا في الدنيا يسرعون إلى أصنامهم في مواسم شركهم وهناك كذلك يسرعون عند خروجهم من القبر. [45] في حال كونهم ( خاشِعَةً ) أي خاضعة ذليلة ( أَبْصارُهُمْ ) فإن أثر الذلة يظهر في العين لا يستطيعون مدّ بصرهم خوفا وفزعا ( تَرْهَقُهُمْ ) أي تغشاهم وتحيط بهم ( ذِلَّةٌ ) لأنهم قد علموا جرمهم وأنهم محكوم عليهم بالعذاب ( ذلِكَ الْيَوْمُ الَّذِي كانُوا يُوعَدُونَ ) في الدنيا فينكرونه والآن قد وصلوا إليه ووجدوا عذابه وهوله. (71)` },
            { text: "يَوْمَ يَخْرُجُونَ مِنَ ٱلْأَجْدَاثِ سِرَاعًا كَأَنَّهُمْ إِلَىٰ نُصُبٍ يُوفِضُونَ", tafsir: `` },
            { text: "خَٰشِعَةً أَبْصَٰرُهُمْ تَرْهَقُهُمْ ذِلَّةٌ ذَٰلِكَ ٱلْيَوْمُ ٱلَّذِى كَانُوا۟ يُوعَدُونَ", tafsir: `` }
        ]
    },
    71: { // سورة نوح
        name: "نوح",
        basmalaTafsir: ``,
        verses: [
            { text: "إِنَّآ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦٓ أَنْ أَنذِرْ قَوْمَكَ مِن قَبْلِ أَن يَأْتِيَهُمْ عَذَابٌ أَلِيمٌ", tafsir: `أي بعثنا ( نُوحاً ) رسولا ( إِلى قَوْمِهِ ) وأوحينا إليه ( أَنْ أَنْذِرْ قَوْمَكَ ) بأنهم إن تمادوا في الكفر والعصيان ابتلوا بعذاب الدنيا وعذاب الآخرة ( مِنْ قَبْلِ أَنْ يَأْتِيَهُمْ عَذابٌ أَلِيمٌ ) أي موجع مؤلم. [3] فامتثل نوح عليه‌السلام و ( قالَ يا قَوْمِ إِنِّي لَكُمْ نَذِيرٌ ) أنذركم وأخوفكم ( مُبِينٌ ) أي واضح ظاهر.` },
            { text: "قَالَ يَٰقَوْمِ إِنِّى لَكُمْ نَذِيرٌ مُّبِينٌ", tafsir: `` },
            { text: "أَنِ ٱعْبُدُوا۟ ٱللَّهَ وَٱتَّقُوهُ وَأَطِيعُونِ", tafsir: `فلا تكفروا به ( وَاتَّقُوهُ ) فلا تعصوه ( وَأَطِيعُونِ ) فيما آمركم به من الشريعة ، وأصله « أطيعوني » حذف الياء تخفيفا وتنسيقا. [5] فإنكم إن عبدتموه واتقيتم ( يَغْفِرْ ) الله ( لَكُمْ مِنْ ذُنُوبِكُمْ ) أي جنس ذنوبكم ، ف « من » للجنس ( وَيُؤَخِّرْكُمْ ) ، فلا يهلككم عاجلا ( إِلى أَجَلٍ مُسَمًّى ) أي مدة قد سميت في كتابه ، في مقابل الكافر الذي يعذبه بعذاب الاستئصال ( إِنَّ أَجَلَ اللهِ ) أي الأجل الذي عينه الله ( إِذا جاءَ ) وقته ( لا يُؤَخَّرُ ) فبادروا بالإيمان والتوبة قبل فوات الأوان ( لَوْ كُنْتُمْ تَعْلَمُونَ ) أي لو كنتم عاملين بالأمور لعلمتم بذلك. [6] ودعا نوح قومه مدة مديدة بمثل تلك الإرشادات والنصائح ، لكن دعاءه لم يكن ينفع فيهم ، فتوجه إلى الله سبحانه داعيا ( قالَ ) نوح عليه‌السلام : يا رَبِّ إِنِّي دَعَوْتُ قَوْمِي لَيْلاً وَنَهاراً (5) فَلَمْ يَزِدْهُمْ دُعائِي إِلاَّ فِراراً (6) وَإِنِّي كُلَّما دَعَوْتُهُمْ لِتَغْفِرَ لَهُمْ جَعَلُوا أَصابِعَهُمْ فِي آذانِهِمْ وَاسْتَغْشَوْا ثِيابَهُمْ وَأَصَرُّوا وَاسْتَكْبَرُوا اسْتِكْباراً (7) ثُمَّ إِنِّي دَعَوْتُهُمْ جِهاراً (8) ثُمَّ إِنِّي أَعْلَنْتُ لَهُمْ وَأَسْرَرْتُ لَهُمْ إِسْراراً (9) ( رَبِّ إِنِّي دَعَوْتُ قَوْمِي ) إلى الإيمان ( لَيْلاً وَنَهاراً ) أي في كل الأوقات.` },
            { text: "يَغْفِرْ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرْكُمْ إِلَىٰٓ أَجَلٍ مُّسَمًّى إِنَّ أَجَلَ ٱللَّهِ إِذَا جَآءَ لَا يُؤَخَّرُ لَوْ كُنتُمْ تَعْلَمُونَ", tafsir: `` },
            { text: "قَالَ رَبِّ إِنِّى دَعَوْتُ قَوْمِى لَيْلًا وَنَهَارًا", tafsir: `` },
            { text: "فَلَمْ يَزِدْهُمْ دُعَآءِىٓ إِلَّا فِرَارًا", tafsir: `فإن دعوتي صارت سببا لأن يرص الكفار صفوفهم ، ويجاهروا بالكفر والطغيان والفرار من الحق.` },
            { text: "وَإِنِّى كُلَّمَا دَعَوْتُهُمْ لِتَغْفِرَ لَهُمْ جَعَلُوٓا۟ أَصَٰبِعَهُمْ فِىٓ ءَاذَانِهِمْ وَٱسْتَغْشَوْا۟ ثِيَابَهُمْ وَأَصَرُّوا۟ وَٱسْتَكْبَرُوا۟ ٱسْتِكْبَارًا", tafsir: `إلى الإيمان والطاعة ( لِتَغْفِرَ لَهُمْ ) ذنوبهم إن آمنوا وأطاعوا ( جَعَلُوا أَصابِعَهُمْ فِي آذانِهِمْ ) حتى لا يسمعوا كلامي ( وَاسْتَغْشَوْا ثِيابَهُمْ ) أي غطوا بها وجوههم ورؤوسهم لئلا يروني ( وَأَصَرُّوا ) أي داموا على كفرهم وطغيانهم ( وَاسْتَكْبَرُوا اسْتِكْباراً ) أي تكبروا وأنفوا عن قبول الحق ، وكأن الإتيان بصيغة الاستفعال لإفادة أنهم طلبوا الكبر ، وإن لم يكونوا كبراء حقيقة.` },
            { text: "ثُمَّ إِنِّى دَعَوْتُهُمْ جِهَارًا", tafsir: `لترتيب الكلام لا لترتيب المطلب في الخارج ( إِنِّي دَعَوْتُهُمْ جِهاراً ) أي جهرا بأعلى صوتي.` },
            { text: "ثُمَّ إِنِّىٓ أَعْلَنتُ لَهُمْ وَأَسْرَرْتُ لَهُمْ إِسْرَارًا", tafsir: `إعلانا بالدعوة ( وَأَسْرَرْتُ لَهُمْ إِسْراراً ) أي علانية وسرا ، والمراد الدعوة بكل وجه محتمل ، والجهر قسم من الإعلان ـ فليس في ذكر الإعلان بعد الإجهار تكرارا. فَقُلْتُ اسْتَغْفِرُوا رَبَّكُمْ إِنَّهُ كانَ غَفَّاراً (10) يُرْسِلِ السَّماءَ عَلَيْكُمْ مِدْراراً (11) وَيُمْدِدْكُمْ بِأَمْوالٍ وَبَنِينَ وَيَجْعَلْ لَكُمْ جَنَّاتٍ وَيَجْعَلْ لَكُمْ أَنْهاراً (12) ما لَكُمْ لا تَرْجُونَ لِلَّهِ وَقاراً (13) وَقَدْ خَلَقَكُمْ أَطْواراً (14)` },
            { text: "فَقُلْتُ ٱسْتَغْفِرُوا۟ رَبَّكُمْ إِنَّهُۥ كَانَ غَفَّارًا", tafsir: `أيها القوم ( رَبَّكُمْ ) أي اطلبوا غفرانه بالإيمان والطاعة ( إِنَّهُ كانَ غَفَّاراً ) كثير المغفرة لمن استغفر. [12] فإن استغفرتم ( يُرْسِلِ ) الله ( السَّماءَ عَلَيْكُمْ مِدْراراً ) أي كثيرة الدرور بالمطر ، قيل إن الغيث قد منع عنهم حتى ابتلوا بالقحط ولذا رغبهم نوح عليه‌السلام في ذلك.` },
            { text: "يُرْسِلِ ٱلسَّمَآءَ عَلَيْكُم مِّدْرَارًا", tafsir: `` },
            { text: "وَيُمْدِدْكُم بِأَمْوَٰلٍ وَبَنِينَ وَيَجْعَل لَّكُمْ جَنَّٰتٍ وَيَجْعَل لَّكُمْ أَنْهَٰرًا", tafsir: `أي يكثر أموالكم وأولادكم الذكور ( وَيَجْعَلْ لَكُمْ جَنَّاتٍ ) أي بساتين ، بسبب المطر والأموال ( وَيَجْعَلْ لَكُمْ أَنْهاراً ) تسقون جناتكم ، فإن المطر إذا كثر اختزن في الأرض ثم تفجر من العيون وجرى منها.` },
            { text: "مَّا لَكُمْ لَا تَرْجُونَ لِلَّهِ وَقَارًا", tafsir: `يا معاشر الكفار ( لا تَرْجُونَ لِلَّهِ وَقاراً ) أي لا تعظمون الله تعالى ، فإن « الوقار » بمعنى العظمة ، والرجاء هو الطمع في شيء مرغوب ، فإن من لا يعرف عظمة شخص لا يرجوه ، فكأنه قال : ما لكم لا ترجون الله ، إذ لا تعترفون له بالوقار والعظمة ؟` },
            { text: "وَقَدْ خَلَقَكُمْ أَطْوَارًا", tafsir: `الحال أنكم ترون آثار عظمته في أنفسكم ، إذ ( قَدْ خَلَقَكُمْ أَطْواراً ) جمع « طور » فقد انتقلتم من حال إلى حال حتى وصلتم إلى هذا الحال الذي أنتم فيه ، أو المراد خلقكم مختلفين ، فكل واحد أَ لَمْ تَرَوْا كَيْفَ خَلَقَ اللهُ سَبْعَ سَماواتٍ طِباقاً (15) وَجَعَلَ الْقَمَرَ فِيهِنَّ نُوراً وَجَعَلَ الشَّمْسَ سِراجاً (16) وَاللهُ أَنْبَتَكُمْ مِنَ الْأَرْضِ نَباتاً (17) ثُمَّ يُعِيدُكُمْ فِيها وَيُخْرِجُكُمْ إِخْراجاً (18) وَاللهُ جَعَلَ لَكُمُ الْأَرْضَ بِساطاً (19) يختلف عن الآخر مما يدل على كمال القدرة. [16] إن آثار عظمة الله سبحانه كما هي ظاهرة في أنفسكم كذلك هي ظاهرة في الكون ( أَ لَمْ تَرَوْا ) أيها الكفار ( كَيْفَ خَلَقَ اللهُ سَبْعَ سَماواتٍ ) فإن علم الفلك معترف بوجود سبع مدارات للكواكب السيارة ( طِباقاً ) أي بعضها فوق الآخر ؟` },
            { text: "أَلَمْ تَرَوْا۟ كَيْفَ خَلَقَ ٱللَّهُ سَبْعَ سَمَٰوَٰتٍ طِبَاقًا", tafsir: `` },
            { text: "وَجَعَلَ ٱلْقَمَرَ فِيهِنَّ نُورًا وَجَعَلَ ٱلشَّمْسَ سِرَاجًا", tafsir: `أي في تلك السماوات ، ويجوز الإتيان بضمير غير العاقل مفردا وجمعا ( نُوراً ) ينير الظلام بأشعته ( وَجَعَلَ الشَّمْسَ سِراجاً ) أي مصباحا يشع ضياؤها حتى تنير الأكوان.` },
            { text: "وَٱللَّهُ أَنۢبَتَكُم مِّنَ ٱلْأَرْضِ نَبَاتًا", tafsir: `أيها البشر ( مِنَ الْأَرْضِ نَباتاً ) فإن الإنسان ينبت من الأرض كما أن النبات ينبت منها ، ولكن الفرق هو أن الأرض تتحول إلى النبات ، والنبات يأكله الإنسان فيصير منيا ثم إنسانا والنبات ينبت ابتداء ، وفي الحقيقة أن الإنسان نبات الأرض المتحرك ، كما أن النبات نباتها الساكن.` },
            { text: "ثُمَّ يُعِيدُكُمْ فِيهَا وَيُخْرِجُكُمْ إِخْرَاجًا", tafsir: `أي في الأرض ، فالميت لا يلبث أن يبلى ويكون ترابا كما كان سابقا ( وَيُخْرِجُكُمْ ) من الأرض لدى البعث في يوم القيامة ( إِخْراجاً ) وإنما ذكر المصدر تأكيدا لبيان أنه كائن لا محالة.` },
            { text: "وَٱللَّهُ جَعَلَ لَكُمُ ٱلْأَرْضَ بِسَاطًا", tafsir: `مبسوطة لتتمكنوا من المشي عليها لِتَسْلُكُوا مِنْها سُبُلاً فِجاجاً (20) قالَ نُوحٌ رَبِّ إِنَّهُمْ عَصَوْنِي وَاتَّبَعُوا مَنْ لَمْ يَزِدْهُ مالُهُ وَوَلَدُهُ إِلاَّ خَساراً (21) وَمَكَرُوا مَكْراً كُبَّاراً (22) والبناء فوقها ، وتقضوا سائر مآربكم عليها. [21] ثم أشار السياق إلى واحدة من النعم التي هيأها الله للإنسان على الأرض المنبسطة ( لِتَسْلُكُوا ) يقال سلك في الطريق إذا مشى فيه وسرى ( مِنْها ) أي من الأرض والمراد في بعض الأرض ( سُبُلاً ) أي طرقا ، جمع « سبيل » ( فِجاجاً ) « الفجاج » هي الطرق المتسعة المتفرقة ، واحدها « فج » يعني حتى تتمكنوا من السير في طرق الأرض المختلفة إلى حاجاتكم هنا وهنالك. [22] وبعد كل هذه التذكيرات والإلفات إلى هذه النعم العظام ، لم يستجب القوم لدعوة نوح عليه‌السلام ، فتوجه نوح إلى ربه ( قالَ نُوحٌ ) : يا ( رَبِّ إِنَّهُمْ ) أي القوم ( عَصَوْنِي ) فلم يؤمنوا بك ، ولم يطيعوا أمري ( وَاتَّبَعُوا مَنْ لَمْ يَزِدْهُ مالُهُ وَوَلَدُهُ إِلَّا خَساراً ) أي اتبعوا كبراء قومهم الذين هم رأس الفساد ، فكلما ازدادوا مالا صرفوه في الشر وكلما ازدادوا ولدا حرفوه عن سنن الحق ، فمالهم وولدهم لا يزيدهم إلا خسارة وضررا ، مما يوجب كثرة عقوبتهم وزيادة عذابهم.` },
            { text: "لِّتَسْلُكُوا۟ مِنْهَا سُبُلًا فِجَاجًا", tafsir: `` },
            { text: "قَالَ نُوحٌ رَّبِّ إِنَّهُمْ عَصَوْنِى وَٱتَّبَعُوا۟ مَن لَّمْ يَزِدْهُ مَالُهُۥ وَوَلَدُهُۥٓ إِلَّا خَسَارًا", tafsir: `` },
            { text: "وَمَكَرُوا۟ مَكْرًا كُبَّارًا", tafsir: `في قبال نوح ( مَكْراً كُبَّاراً ) أي كبيرا للغاية فإن إطفاء سنن الرسول يحتاج إلى التدابير الكثيرة ، وإلا فالناس بطبيعتهم الساذجة يتبعون الحق. وفاعل المكر إما الكبار المشار إليهم ب « من » أو المراد القوم ـ في الجملة ـ . وَقالُوا لا تَذَرُنَّ آلِهَتَكُمْ وَلا تَذَرُنَّ وَدًّا وَلا سُواعاً وَلا يَغُوثَ وَيَعُوقَ وَنَسْراً (23) وَقَدْ أَضَلُّوا كَثِيراً وَلا تَزِدِ الظَّالِمِينَ إِلاَّ ضَلالاً (24) مِمَّا خَطِيئاتِهِمْ` },
            { text: "وَقَالُوا۟ لَا تَذَرُنَّ ءَالِهَتَكُمْ وَلَا تَذَرُنَّ وَدًّا وَلَا سُوَاعًا وَلَا يَغُوثَ وَيَعُوقَ وَنَسْرًا", tafsir: `أي الماكرون ، لسائر الناس ( لا تَذَرُنَ ) أي لا تتركن ( آلِهَتَكُمْ ) الأصنام التي تعبدونها إطاعة لنوح في عبادة إله واحد ، ثم خصوا جماعة من الآلهة كانت الأصنام الكبيرة لديهم ( وَلا تَذَرُنَّ وَدًّا وَلا سُواعاً وَلا يَغُوثَ وَ ) لا ( يَعُوقَ وَ ) لا ( نَسْراً ) ويغوث ويعوق غير منصرفين للعجمة والعلمية ، أو للعلمية والتأنيث كما أن عدم إتيان « لا » على البعض للتفنن في الكلام الذي هو من فنون البلاغة ، وهذه كانت أسامي أصنام لهم يعبدونها من دون الله سبحانه. وذكر بعض أن هذه أسماء كانت لرجال صالحين ، فلما ماتوا مثلوا لهم تمثالا يعظمونها باعتبار أنها رموز لأولئك الصالحين ، ثم عبدوها ـ بإغواء الشيطان ـ .` },
            { text: "وَقَدْ أَضَلُّوا۟ كَثِيرًا وَلَا تَزِدِ ٱلظَّٰلِمِينَ إِلَّا ضَلَٰلًا", tafsir: `هذه الأصنام ، يا رب ( كَثِيراً ) من الناس ونسبة الضلال إلى الأصنام باعتبار أنها الوسيلة في الإضلال ، والإتيان بضمير العاقل تماشيا لوحدة السياق بين كلام المؤمنين والكافرين ( وَلا تَزِدِ ) يا رب ( الظَّالِمِينَ ) الذين ظلموا أنفسهم بالكفر والعصيان وغيرهم بالإضلال والإفساد ( إِلَّا ضَلالاً ) جزاء على عنادهم ، وإزادة ضلالهم بمنع الألطاف الخفية عنهم ، أو المعنى « لا تزد هذه الأصنام إلا ضلالا لهم » فعلى الأول نهي ، وعلى الثاني نفي. [26] ثم أتى السياق إلى بيان عاقبة هؤلاء الكفار بقوله : ( مِمَّا خَطِيئاتِهِمْ ) أي من جهة خطيئة هؤلاء الكفار ، و « ما » زائدة والزيادة هنا لأجل أُغْرِقُوا فَأُدْخِلُوا ناراً فَلَمْ يَجِدُوا لَهُمْ مِنْ دُونِ اللهِ أَنْصاراً (25) وَقالَ نُوحٌ رَبِّ لا تَذَرْ عَلَى الْأَرْضِ مِنَ الْكافِرِينَ دَيَّاراً (26) إِنَّكَ إِنْ تَذَرْهُمْ يُضِلُّوا عِبادَكَ وَلا يَلِدُوا إِلاَّ فاجِراً كَفَّاراً (27) رَبِّ اغْفِرْ لِي وَلِوالِدَيَّ تزيين الكلام ( أُغْرِقُوا ) بالماء في الدنيا ( فَأُدْخِلُوا ناراً ) في الآخرة ، فقد عوقبوا بعقوبتين متضادتين ( فَلَمْ يَجِدُوا ) أولئك الكفار ( لَهُمْ مِنْ دُونِ اللهِ ) أي غير الله سبحانه ( أَنْصاراً ) فلم يكن هناك من يمنع عنهم عذاب الله تعالى ، فقد ضل عنهم من كان يعدهم النصر.` },
            { text: "مِّمَّا خَطِيٓـَٰٔتِهِمْ أُغْرِقُوا۟ فَأُدْخِلُوا۟ نَارًا فَلَمْ يَجِدُوا۟ لَهُم مِّن دُونِ ٱللَّهِ أَنصَارًا", tafsir: `` },
            { text: "وَقَالَ نُوحٌ رَّبِّ لَا تَذَرْ عَلَى ٱلْأَرْضِ مِنَ ٱلْكَٰفِرِينَ دَيَّارًا", tafsir: `قبل أن يغرقوا ـ في دعائه عليهم ـ وإنما أخر ذلك عن الغرق ، في الكلام ، لتعجيل توصيل العقاب بالانحراف ، حتى كأنه انحراف وعقاب بلا فاصلة ، يا ( رَبِّ لا تَذَرْ ) أي لا تدع ولا تبق سالما ( عَلَى الْأَرْضِ مِنَ الْكافِرِينَ دَيَّاراً ) أي أحدا يعمر الديار ، أو ينزل الدار ، بل عمم عقابك على جميعهم. [28] ثم بين عليه‌السلام علة هذا الدعاء بقوله : ( إِنَّكَ إِنْ تَذَرْهُمْ يُضِلُّوا عِبادَكَ ) من نسل المؤمنين ( وَلا يَلِدُوا ) هم بأنفسهم ( إِلَّا فاجِراً ) يفجر ويعصي ( كَفَّاراً ) كثير الكفر ، يعني أن أولادهم فاسد والعقيدة والعمل ، فلا خير فيهم ، وقد علم نوح عليه‌السلام ذلك من طريق الوحي. [29] يا ( رَبِّ اغْفِرْ لِي ) وقد سبق أن استغفار الأنبياء والأئمة لما يصدر منهم من المباحات الضرورية ، فإنهم يرون ذلك خلافا للأدب أمام الله الملك العظيم ، كما أن من مدّ رجله ـ لمرض أو نحوه ـ أمام الملك رآه سوء أدب وإن كان مضطرا إليه ، واعتذر من فعله ذلك ( وَلِوالِدَيَ ) وَلِمَنْ دَخَلَ بَيْتِيَ مُؤْمِناً وَلِلْمُؤْمِنِينَ وَالْمُؤْمِناتِ وَلا تَزِدِ ال ظَّالِمِينَ إِلاَّ تَباراً (28) بغفران ذنوبهما ( وَلِمَنْ دَخَلَ بَيْتِيَ مُؤْمِناً ) وكأن الدخول في البيت كناية عن الدخول في حوزته وأنصاره ، فقد آمن به عليه‌السلام عدة قليلة بين سبعين وثمانين ـ على ما ذكروا ـ ( وَ ) اغفر ( لِلْمُؤْمِنِينَ وَالْمُؤْمِناتِ ) من سائر الأمم السابقين واللاحقين ( وَلا تَزِدِ الظَّالِمِينَ إِلَّا تَباراً ) أي هلاكا وخسارة ، وذلك بمنع الألطاف عنهم ، حتى يكون بقاؤهم موجبا لزيادة عذابهم وخسارتهم جزاء لعنادهم. (72)` },
            { text: "إِنَّكَ إِن تَذَرْهُمْ يُضِلُّوا۟ عِبَادَكَ وَلَا يَلِدُوٓا۟ إِلَّا فَاجِرًا كَفَّارًا", tafsir: `` },
            { text: "رَّبِّ ٱغْفِرْ لِى وَلِوَٰلِدَىَّ وَلِمَن دَخَلَ بَيْتِىَ مُؤْمِنًا وَلِلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ وَلَا تَزِدِ ٱلظَّٰلِمِينَ إِلَّا تَبَارًۢا", tafsir: `` }
        ]
    },
    72: { // سورة الجن
        name: "الجن",
        basmalaTafsir: ``,
        verses: [
            { text: "قُلْ أُوحِىَ إِلَىَّ أَنَّهُ ٱسْتَمَعَ نَفَرٌ مِّنَ ٱلْجِنِّ فَقَالُوٓا۟ إِنَّا سَمِعْنَا قُرْءَانًا عَجَبًا", tafsir: `يا رسول الله للناس ( أُوحِيَ إِلَيَ ) والوحي هو الإلهام إلى الرسول من قبله سبحانه بواسطة ملك أو إلقاء في القلب بلا واسطة ، ويستعمل أيضا بمعنى مطلق الإلهام ، كقوله ( وَأَوْحى رَبُّكَ إِلَى النَّحْلِ ) (1) وقوله ( وَأَوْحَيْنا إِلى أُمِّ مُوسى ) (2) ( أَنَّهُ اسْتَمَعَ نَفَرٌ مِنَ الْجِنِ ) أي استمع إلى القرآن طائفة من الجن ـ فإن نفر بمعنى الطائفة ـ والجن مخلوقة من النار رقاق الأجسام كالهواء ، ولها أن تتشكل في أبدان غليظة كأبدان الإنسان ( فَقالُوا ) بعضهم لبعض ( إِنَّا سَمِعْنا ) من الرسول ( قُرْآناً عَجَباً ) أي ما يدعو إلى التعجب ، لأنه بأسلوب غريب في لفظه ومعناه ، وقد سبقت قصتهم في سورة الأحقاف.` },
            { text: "يَهْدِىٓ إِلَى ٱلرُّشْدِ فَـَٔامَنَّا بِهِۦ وَلَن نُّشْرِكَ بِرَبِّنَآ أَحَدًا", tafsir: `أي يدل على الهدى الذي من سلكه رشد ( فَآمَنَّا ) نحن الجن ( بِهِ ) أي بذلك القرآن ( وَلَنْ نُشْرِكَ ) بعد سماع القرآن ( بِرَبِّنا أَحَداً ) أي لم نجعل له شريكا.` },
            { text: "وَأَنَّهُۥ تَعَٰلَىٰ جَدُّ رَبِّنَا مَا ٱتَّخَذَ صَٰحِبَةً وَلَا وَلَدًا", tafsir: `« الجد » هو الحظ ، والمراد به هنا العظمة ، أي تعالت وارتفعت عظمته ، من أن يكون له شريك أو زوجة أو أولاد ( مَا اتَّخَذَ ) أي لم يتخذ الله سبحانه ( صاحِبَةً ) أي زوجة ( وَلا وَلَداً ) فقد كان بعض الكفار يقولون أنه سبحانه اتخذ زوجة من الجن ، كما قال ( 1) النحل : 69. ( 2) القصص : 8. وَأَنَّهُ كانَ يَقُولُ سَفِيهُنا عَلَى اللهِ شَطَطاً (4) وَأَنَّا ظَنَنَّا أَنْ لَنْ تَقُولَ الْإِنْسُ وَالْجِنُّ عَلَى اللهِ كَذِباً (5) وَأَنَّهُ كانَ رِجالٌ مِنَ الْإِنْسِ يَعُوذُونَ بِرِجالٍ مِنَ الْجِنِّ فَزادُوهُمْ رَهَقاً (6) سبحانه ( وَجَعَلُوا بَيْنَهُ وَبَيْنَ الْجِنَّةِ نَسَباً ) (1) ، فنفت الجن هذا الكلام.` },
            { text: "وَأَنَّهُۥ كَانَ يَقُولُ سَفِيهُنَا عَلَى ٱللَّهِ شَطَطًا", tafsir: `أي جاهلنا ، والمراد به جنس الجهال منهم ( عَلَى اللهِ شَطَطاً ) أي كذبا وبعدا عن الحق ، وكأن المراد بذلك ما شاع بينهم من أنه تزوج بالجنية ، أو المراد « بسفيه منا » إبليس ـ لأنه من الجن ـ والمراد أقواله حول الله سبحانه ، من نسبة الشريك إليه وما أشبه.` },
            { text: "وَأَنَّا ظَنَنَّآ أَن لَّن تَقُولَ ٱلْإِنسُ وَٱلْجِنُّ عَلَى ٱللَّهِ كَذِبًا", tafsir: `ظهر لنا الآن كذب ذلك السفيه بعد ما كنا ( ظَنَنَّا أَنْ لَنْ تَقُولَ الْإِنْسُ وَالْجِنُ ) الإتيان بالفعل مؤنثا باعتبار « الجماعة » ( عَلَى اللهِ كَذِباً ) فقد كنا نحسب أن ما يقولون من أن له سبحانه صاحبة وشريكا وولدا صدق ، والآن تبين لنا كذبه.` },
            { text: "وَأَنَّهُۥ كَانَ رِجَالٌ مِّنَ ٱلْإِنسِ يَعُوذُونَ بِرِجَالٍ مِّنَ ٱلْجِنِّ فَزَادُوهُمْ رَهَقًا", tafsir: `أي يعتصمون ويستجيرون ، وكان الرجل من العرب إذا نزل الوادي في سفره ليلا قال « أعوذ بعزيز هذا الوادي من شر سفهاء قومه » و قد روي عن الإمام الباقر عليه‌السلام أنه قال : في هذه الآية « كان الرجل ينطلق إلى الكاهن الذي يوحي إليه الشيطان فيقول قل لشيطانك فلان قد عاذ بك » (2) ( فَزادُوهُمْ ) أي زاد الجن الإنس العائذين بهم ( رَهَقاً ) أي طغيانا ( 1) الصافات : 159. ( 2) بحار الأنوار : ج 60 ص 98. وَأَنَّهُمْ ظَنُّوا كَما ظَنَنْتُمْ أَنْ لَنْ يَبْعَثَ اللهُ أَحَداً (7) وَأَنَّا لَمَسْنَا السَّماءَ فَوَجَدْناها مُلِئَتْ حَرَساً شَدِيداً وَشُهُباً (8) وَأَنَّا كُنَّا نَقْعُدُ مِنْها مَقاعِدَ لِلسَّمْعِ فَمَنْ يَسْتَمِعِ الْآنَ يَجِدْ لَهُ شِهاباً رَصَداً (9) حيث إنهم رأوا الجن ظهيرا لهم ، أو زاد الإنس الجن طغيانا حيث إنهم ظنوا أن لهم مدخلا في الأمور الكونية حتى استعاذ بهم الإنس ، وأصل الرهق اللحوق ، ومنه غلام مراهق ، فكأن الإثم والطغيان يلحق الإنسان ، ولذا قيل له رهق.` },
            { text: "وَأَنَّهُمْ ظَنُّوا۟ كَمَا ظَنَنتُمْ أَن لَّن يَبْعَثَ ٱللَّهُ أَحَدًا", tafsir: `أي الإنس ( ظَنُّوا كَما ظَنَنْتُمْ ) أنتم معاشر الجن ( أَنْ لَنْ يَبْعَثَ اللهُ أَحَداً ) رسولا ، وهذا من تتمة كلام الجن الذين آمنوا بالرسول.` },
            { text: "وَأَنَّا لَمَسْنَا ٱلسَّمَآءَ فَوَجَدْنَٰهَا مُلِئَتْ حَرَسًا شَدِيدًا وَشُهُبًا", tafsir: `معاشر الجن ( لَمَسْنَا السَّماءَ ) أي مسسناها بإرادة الصعود في طبقات الجو ( فَوَجَدْناها ) أي ألفينا السماء ( مُلِئَتْ حَرَساً شَدِيداً ) أي حفظة من الملائكة شدادا ، « وحرس » جمع حارس وهو الحافظ ، وشديد باعتبار كل واحد من الحفظة ( وَشُهُباً ) جمع « شهاب » وهو نور يمتد في السماء حتى يطفأ ، أنها هيأت لرجم من يريد استراق السمع من الشياطين.` },
            { text: "وَأَنَّا كُنَّا نَقْعُدُ مِنْهَا مَقَٰعِدَ لِلسَّمْعِ فَمَن يَسْتَمِعِ ٱلْـَٔانَ يَجِدْ لَهُۥ شِهَابًا رَّصَدًا", tafsir: `معاشر الجن ( كُنَّا نَقْعُدُ مِنْها ) أي من السماء ( مَقاعِدَ لِلسَّمْعِ ) أي محلات قريبة من مراكز الملائكة لنستمع ما يدار بينهم من أخبار الأرض لنعلم الأخبار ونأتي بها إلى الكهنة ، وهذا إلى قبل ميلاد الرسول صلى‌الله‌عليه‌وآله‌وسلم أو بعثته ( فَمَنْ يَسْتَمِعِ الْآنَ ) منا إلى كلام الملائكة ( يَجِدْ لَهُ ) أي لنفسه ( شِهاباً رَصَداً ) يرمى به ويرصد له ، ففي النجوم وَأَنَّا لا نَدْرِي أَ شَرٌّ أُرِيدَ بِمَنْ فِي الْأَرْضِ أَمْ أَرادَ بِهِمْ رَبُّهُمْ رَشَداً (10) عيّن مواضع لحراسة السماء من الجن والشياطين ، فمن يتقدم منهم ليسترق الكلام قذف بالشهاب حتى يحترق أو يطرد. و قد روي عن الإمام الصادق عليه‌السلام أنه قال ـ في حديث يذكر فيه سبب إخبار الكاهن ـ : وأما أخبار السماء فإن الشياطين كانت تقعد مقاعد استراق السمع إذ ذاك ، وهي لا تحجب ولا ترجم بالنجوم وإنما منعت من استراق السمع لئلا يقع في الأرض سبب يشاكل الوحي من خبر السماء ويلبس على أهل الأرض ما جاءهم من الله لإثبات الحجة ونفي الشبهة ، وكان الشيطان يسترق الكلمة الواحدة من خبر السماء بما يحدث من الله في خلقه فيختطفها ثم يهبط بها إلى الأرض فيقذفها إلى الكاهن ، فإذا قد زاد كلمات من عنده يختلط الحق بالباطل ، فما أصاب الكاهن من خبر مما كان يخبر به فهو ما أداه إليه شيطانه مما سمعه ، وما أخطأ فيه فهو من باطل ما زاد فيه ، فمذ منعت الشياطين من استراق السمع انقطعت الكهانة (1) .` },
            { text: "وَأَنَّا لَا نَدْرِىٓ أَشَرٌّ أُرِيدَ بِمَن فِى ٱلْأَرْضِ أَمْ أَرَادَ بِهِمْ رَبُّهُمْ رَشَدًا", tafsir: `حيث يرجم الشياطين ، حتى تقطع الأخبار عن أهل الأرض بعذابهم ، فيفاجئون بالعذاب ( أَمْ أَرادَ بِهِمْ رَبُّهُمْ رَشَداً ) بأن يبعث فيهم نبيا ؟ والحاصل أن رجم الشياطين لأحد أمرين إما لشر أو لخير ؟ وهذا يؤيد كون المراد من الرجم وقت ولادة الرسول ، وأن هذا الكلام من الجن حكاية حال ماضية ، وإلا فقد عرفوا النبأ بعد فترة وخصوصا عند وصولهم إلى خدمة الرسول صلى‌الله‌عليه‌وآله‌وسلم . ( 1) بحار الأنوار : ج 60 ص 76. وَأَنَّا مِنَّا الصَّالِحُونَ وَمِنَّا دُونَ ذلِكَ كُنَّا طَرائِقَ قِدَداً (11) وَأَنَّا ظَنَنَّا أَنْ لَنْ نُعْجِزَ اللهَ فِي الْأَرْضِ وَلَنْ نُعْجِزَهُ هَرَباً (12) وَأَنَّا لَمَّا سَمِعْنَا الْهُدى آمَنَّا بِهِ فَمَنْ يُؤْمِنْ بِرَبِّهِ فَلا يَخافُ بَخْساً وَلا رَهَقاً (13)` },
            { text: "وَأَنَّا مِنَّا ٱلصَّٰلِحُونَ وَمِنَّا دُونَ ذَٰلِكَ كُنَّا طَرَآئِقَ قِدَدًا", tafsir: `معاشر الجن ( مِنَّا ) أي بعضنا ( الصَّالِحُونَ ) بالإيمان والعمل الصالح ( وَمِنَّا دُونَ ذلِكَ ) الصلاح ، وإنما عبر بهذا التعبير ليشمل الفرق المختلفة ( كُنَّا ) في السابق ( طَرائِقَ قِدَداً ) أي على طرائق مختلفة « وقدد » جمع قدة وهي القطعة ، كأن لكل مذهب لونا مختلفا ، فهم قطعة مخالفة لقطعة أخرى ، وكأن هذه التفصيلات المنقولة من كلام الجن لبيان حقيقتهم ، وتوضيح ما يرتبط بهم من المزايا والأحوال.` },
            { text: "وَأَنَّا ظَنَنَّآ أَن لَّن نُّعْجِزَ ٱللَّهَ فِى ٱلْأَرْضِ وَلَن نُّعْجِزَهُۥ هَرَبًا", tafsir: `معاشر الجن ( ظَنَنَّا أَنْ لَنْ نُعْجِزَ اللهَ فِي الْأَرْضِ ) بأن نجمع جموعا ونهيئ قوى حتى يعجز سبحانه من التصرف فينا كيف يشاء ، وإنما جاء بلفظ الظن ، إما لأنهم ظنوا ذلك ولم يتيقنوا ، أو لبيان أن الظن كاف في عدم إرادة المخالفة معه سبحانه ( وَلَنْ نُعْجِزَهُ هَرَباً ) أي لا نتمكن من تعجيزه بهربنا من قدرته ، فإن قدرته شاملة منبسطة لا يمكن الفرار منها.` },
            { text: "وَأَنَّا لَمَّا سَمِعْنَا ٱلْهُدَىٰٓ ءَامَنَّا بِهِۦ فَمَن يُؤْمِنۢ بِرَبِّهِۦ فَلَا يَخَافُ بَخْسًا وَلَا رَهَقًا", tafsir: `حيث سمعنا قرآن الرسول صلى‌الله‌عليه‌وآله‌وسلم ( آمَنَّا بِهِ ) أي بالهدى وهو الإسلام ( فَمَنْ يُؤْمِنْ بِرَبِّهِ ) إيمانا صحيحا فإنه لا ( يَخافُ بَخْساً ) أي تنقيصا لحقه في الدنيا وفي الآخرة ( وَلا رَهَقاً ) أي ظلما وطغيانا بالنسبة إليه ، فإنه سبحانه عادل لا يظلم أحدا ، أما غير وَأَنَّا مِنَّا الْمُسْلِمُونَ وَمِنَّا الْقاسِطُونَ فَمَنْ أَسْلَمَ فَأُولئِكَ تَحَرَّوْا رَشَداً (14) وَأَمَّا الْقاسِطُونَ فَكانُوا لِجَهَنَّمَ حَطَباً (15) وَأَنْ لَوِ اسْتَقامُوا عَلَى الطَّرِيقَةِ لَأَسْقَيْناهُمْ ماءً غَدَقاً (16) لِنَفْتِنَهُمْ فِيهِ المؤمن فإنه يخاف البخس ، إذ حسناته تمحى بسبب سيئاته ، ويخاف الرهق بمعنى تبعة الإثم ـ كما سبق في معنى الرهق.` },
            { text: "وَأَنَّا مِنَّا ٱلْمُسْلِمُونَ وَمِنَّا ٱلْقَٰسِطُونَ فَمَنْ أَسْلَمَ فَأُو۟لَٰٓئِكَ تَحَرَّوْا۟ رَشَدًا", tafsir: `الذين دخلوا في دين الله الذي جاء به الرسول صلى‌الله‌عليه‌وآله‌وسلم ( وَمِنَّا الْقاسِطُونَ ) من « قسط » بمعنى جار ، أي الجائرون الحائدون عن طريق الحق ( فَمَنْ أَسْلَمَ ) أي دخل في الإسلام ( فَأُولئِكَ تَحَرَّوْا ) أي طلبوا والتمسوا ( رَشَداً ) أي هداية وحقا فيه الرشد والعقل ، والتحري هو التطلب والتماس الشيء.` },
            { text: "وَأَمَّا ٱلْقَٰسِطُونَ فَكَانُوا۟ لِجَهَنَّمَ حَطَبًا", tafsir: `العادلون عن طريق الحق ( فَكانُوا ) أي يكونون ـ أو كان : لمجرد الربط ـ ( لِجَهَنَّمَ حَطَباً ) يلقون فيها فيوقدونها كما يوقد الحطب النار ، كما قال سبحانه ( وَقُودُهَا النَّاسُ وَالْحِجارَةُ ) (1) .` },
            { text: "وَأَلَّوِ ٱسْتَقَٰمُوا۟ عَلَى ٱلطَّرِيقَةِ لَأَسْقَيْنَٰهُم مَّآءً غَدَقًا", tafsir: `هؤلاء القاسطون ( عَلَى الطَّرِيقَةِ ) الحقة بأن لم يحيدوا عنها ( لَأَسْقَيْناهُمْ ماءً غَدَقاً ) يقال ماء غدق : أي كثير وهذا كناية عن الإفضال عليهم ، وهذا ابتداء من كلام الله سبحانه.` },
            { text: "لِّنَفْتِنَهُمْ فِيهِ وَمَن يُعْرِضْ عَن ذِكْرِ رَبِّهِۦ يَسْلُكْهُ عَذَابًا صَعَدًا", tafsir: `أي كنا نسقيهم الماء الكثير لامتحانهم في ذلك السقي ، فإن النعم للامتحان ، كما أن النقم للاختبار ، وليس المقصود من ( 1) البقرة : 25. وَمَنْ يُعْرِضْ عَنْ ذِكْرِ رَبِّهِ يَسْلُكْهُ عَذاباً صَعَداً (17) وَأَنَّ الْمَساجِدَ لِلَّهِ فَلا تَدْعُوا مَعَ اللهِ أَحَداً (18) وَأَنَّهُ لَمَّا قامَ عَبْدُ اللهِ يَدْعُوهُ كادُوا يَكُونُونَ عَلَيْهِ لِبَداً (19) قُلْ الامتحان إلا ظهور السرائر ، لتبيين مقادير الاستحقاق في الآخرة ، أو أنه تعليل لمجيء الهدى ، أي أنا إنما أرسلنا الرسول وأنزلنا الهدى للامتحان ( وَمَنْ يُعْرِضْ عَنْ ذِكْرِ رَبِّهِ ) بأن اتخذ طريقة الكفر والعصيان ( يَسْلُكْهُ ) أي يدخله الله سبحانه ( عَذاباً صَعَداً ) أي عذابا يصعد عليه ويعلوه ، بحيث يشمل جميع جسمه من قرنه إلى قدمه ، أو عذابا غليظا صعبا. [19] وإذ بين كون الهدى إنما هو للامتحان ، جاء السياق ليبين أنه لا يحق لأحد أن يخضع لغير الله سبحانه ( وَأَنَّ الْمَساجِدَ ) جمع « مسجد » وهو مواضع السجود من الوجه والكفين وغيرهما ( لِلَّهِ ) فإنها مخلوقة له مملوكة لذاته المقدسة ( فَلا تَدْعُوا ) أيها الإنسان ( مَعَ اللهِ أَحَداً ) وكيف تدعو غيره بعضو هو له ؟ ويحتمل أن يكون المساجد أعم مما تقدم ومن المساجد المبنية ، وفيه نهي عن الدعاء لغيره سبحانه فيها ، كما كان المشركون يدعون الأصنام في بيت الله تعالى.` },
            { text: "وَأَنَّ ٱلْمَسَٰجِدَ لِلَّهِ فَلَا تَدْعُوا۟ مَعَ ٱللَّهِ أَحَدًا", tafsir: `` },
            { text: "وَأَنَّهُۥ لَمَّا قَامَ عَبْدُ ٱللَّهِ يَدْعُوهُ كَادُوا۟ يَكُونُونَ عَلَيْهِ لِبَدًا", tafsir: `أي الرسول صلى‌الله‌عليه‌وآله‌وسلم ( يَدْعُوهُ ) يدعو الله سبحانه وحده ( كادُوا ) أي الكفار ( يَكُونُونَ عَلَيْهِ ) على الرسول ( لِبَداً ) أي متكاثرين عليه ليمنعوه عن الدعوة ، والظاهر أن هذه الجمل كلها من كلام الجن ، وأن قوله « لنفتنهم » معترضة.` },
            { text: "قُلْ إِنَّمَآ أَدْعُوا۟ رَبِّى وَلَآ أُشْرِكُ بِهِۦٓ أَحَدًا", tafsir: `يا رسول الله لهؤلاء الكفار الذين كادوا يكونون لبدا عليك : إِنَّما أَدْعُوا رَبِّي وَلا أُشْرِكُ بِهِ أَحَداً (20) قُلْ إِنِّي لا أَمْلِكُ لَكُمْ ضَرًّا وَلا رَشَداً (21) قُلْ إِنِّي لَنْ يُجِيرَنِي مِنَ اللهِ أَحَدٌ وَلَنْ أَجِدَ مِنْ دُونِهِ مُلْتَحَداً (22) إِلاَّ بَلاغاً مِنَ اللهِ وَرِسالاتِهِ ( إِنَّما أَدْعُوا رَبِّي ) وحده لا شريك له ( وَلا أُشْرِكُ بِهِ ) أي بربي ( أَحَداً ) فليس ذلك بدعا جديدا يوجب تكاثركم علي وإرادتكم منعي منه.` },
            { text: "قُلْ إِنِّى لَآ أَمْلِكُ لَكُمْ ضَرًّا وَلَا رَشَدًا", tafsir: `يا رسول الله لهؤلاء الكفار ( إِنِّي لا أَمْلِكُ لَكُمْ ضَرًّا ) بأن أضركم ( وَلا ) أملك لكم ( رَشَداً ) بأن أرشدكم ، وإنما الضرر والإرشاد بيد الله ، وأنه هو الذي أمرني بإرشادكم ، فإن لم تقبلوا فهو الذي ينزل الضر بكم ، وهذا لبيان أني رسول الله فقط لا شيء بيدي سوى الهداية والإرشاد. [23] حتى أنا فليس ضري وخيري بيدي ( قُلْ ) يا رسول الله لهؤلاء : ( إِنِّي لَنْ يُجِيرَنِي ) أي لن يحفظني ( مِنَ ) تقدير ( اللهِ أَحَدٌ ) إذا أراد سبحانه بي ضررا ( وَلَنْ أَجِدَ مِنْ دُونِهِ ) سبحانه ( مُلْتَحَداً ) أي ملجأ ألجأ إليه ، من التحد بمعنى مال ، والإنسان الخائف دائما يطلب الملجأ في منعطفات الطريق. [24] إني لا أملك شيئا ( إِلَّا بَلاغاً ) أي تبليغا ( مِنَ ) قبل ( اللهِ ) سبحانه بأن أبلغكم آياته ( وَرِسالاتِهِ ) وهذا استثناء منقطع من « لا أملك » وما بعده ، وقد سبق أن الاستثناء المنقطع ينحل إلى ثلاث جمل ، ففي المقام هكذا « لا أملك شيئا » « إلا بلاغا » « ولا أملك لكم أو لي ضرا أو خيرا » وكأنه قال « لا أملك كذا » و « أملك كذا » ، وحق البلاغ منه وَمَنْ يَعْصِ اللهَ وَرَسُولَهُ فَإِنَّ لَهُ نارَ جَهَنَّمَ خالِدِينَ فِيها أَبَداً (23) حَتَّى إِذا رَأَوْا ما يُوعَدُونَ فَسَيَعْلَمُونَ مَنْ أَضْعَفُ ناصِراً وَأَقَلُّ عَدَداً (24) قُلْ إِنْ أَدْرِي أَ قَرِيبٌ ما سبحانه حق لا يكون لكل أحد ، كما أن رسالاته سبحانه شيء والرسول يملك ذلك الحق كما يعرف الرسالات ، فهما شيئان لا شيء واحد حتى يقال : إن العطف للبيان. ( وَمَنْ يَعْصِ اللهَ ) بعدم إطاعة أوامره ( وَرَسُولَهُ ) بعدم امتثاله فيما يأمر وينهي ( فَإِنَّ لَهُ نارَ جَهَنَّمَ ) جزاء لعصيانه ( خالِدِينَ فِيها ) أي في حال كونهم دائمين في النار ( أَبَداً ) وتوحيد الضمير في « له » باعتبار لفظ « من » وتجميعه في « خالدين » باعتبار معناه ، وقد قالوا يجوز في ضمير « من وما » مراعاة اللفظ والمعنى. [25] لكن الكفار لا يبالون اليوم بالنار ( حَتَّى إِذا رَأَوْا ) هؤلاء الكفار ( ما يُوعَدُونَ ) أي العذاب الذي وعدوا به في الدنيا ( فَسَيَعْلَمُونَ ) إذا رأوا ( مَنْ أَضْعَفُ ناصِراً ) هل ناصر الرسول أضعف أم ناصرهم ( وَأَقَلُّ عَدَداً ) فهل جيش الرسول وأعوانه أقل أم جيشهم وأعوانهم ، فقد كان الكفار يفتخرون على الرسول بكثرة جموعهم وضعف أصحابه صلى‌الله‌عليه‌وآله‌وسلم فأتى السياق ليبين أن في الآخرة تنقلب الكفة ، وأنه يتبدد عددهم ويضعف ناصرهم ، فلا يقوى من إنجائهم من عذاب الله سبحانه. [26] وقد كان الكفار يستعجلون الرسول صلى‌الله‌عليه‌وآله‌وسلم في إنزال العذاب بهم ـ استهزاء به صلى‌الله‌عليه‌وآله‌وسلم ـ فجاء السياق لردهم بقوله : ( قُلْ ) يا رسول الله لهؤلاء الكفار المستعجلين : ( إِنْ أَدْرِي ) أي ما أدري ( أَ قَرِيبٌ ما تُوعَدُونَ أَمْ يَجْعَلُ لَهُ رَبِّي أَمَداً (25) عالِمُ الْغَيْبِ فَلا يُظْهِرُ عَلى غَيْبِهِ أَحَداً (26) إِلاَّ مَنِ ارْتَضى مِنْ رَسُولٍ فَإِنَّهُ يَسْلُكُ مِنْ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِ رَصَداً (27) لِيَعْلَمَ تُوعَدُونَ ) أي هل قريب العذاب الذي وعدتم به لكفركم وعصيانكم ( أَمْ يَجْعَلُ لَهُ ) أي ل « ما توعدون » ( رَبِّي أَمَداً ) أي مدة ، فهو بعيد عنكم ؟ فإن عذاب القيامة مجهول الوقت إلا عنده سبحانه ، فعنده علم الساعة. [27] فإنه وحده ( عالِمُ الْغَيْبِ ) يعلم ما غاب عن الحواس ( فَلا يُظْهِرُ ) أي لا يعلم ( عَلى غَيْبِهِ ) أي الغيب الذي يعلمه هو ( أَحَداً ) من عباده ، فإن علم الغيب خاص به.` },
            { text: "قُلْ إِنِّى لَن يُجِيرَنِى مِنَ ٱللَّهِ أَحَدٌ وَلَنْ أَجِدَ مِن دُونِهِۦ مُلْتَحَدًا", tafsir: `` },
            { text: "إِلَّا بَلَٰغًا مِّنَ ٱللَّهِ وَرِسَٰلَٰتِهِۦ وَمَن يَعْصِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ لَهُۥ نَارَ جَهَنَّمَ خَٰلِدِينَ فِيهَآ أَبَدًا", tafsir: `` },
            { text: "حَتَّىٰٓ إِذَا رَأَوْا۟ مَا يُوعَدُونَ فَسَيَعْلَمُونَ مَنْ أَضْعَفُ نَاصِرًا وَأَقَلُّ عَدَدًا", tafsir: `` },
            { text: "قُلْ إِنْ أَدْرِىٓ أَقَرِيبٌ مَّا تُوعَدُونَ أَمْ يَجْعَلُ لَهُۥ رَبِّىٓ أَمَدًا", tafsir: `` },
            { text: "عَٰلِمُ ٱلْغَيْبِ فَلَا يُظْهِرُ عَلَىٰ غَيْبِهِۦٓ أَحَدًا", tafsir: `` },
            { text: "إِلَّا مَنِ ٱرْتَضَىٰ مِن رَّسُولٍ فَإِنَّهُۥ يَسْلُكُ مِنۢ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِۦ رَصَدًا", tafsir: `أي اختاره للاطلاع على الغيب ( مِنْ رَسُولٍ ) أو المعنى إلا من ارتضاه للرسالة من أفراد الرسل ، فإنه تعالى يظهره على قدر من الغيب ـ حسب الحكمة والصلاح ـ والتي يخبر الإمام أو سائر الناس بقدر ما أذن له في الإخبار ، وإذ أعلمه الله سبحانه بالغيب أحاطه بجملة من الحفظة حتى يكونوا مراقبين عليه في البلاغ ، مع أنه مأمون في نفسه ، وأن الله عالم به ، ولكن هذا للتشريفات ، كما وكل بالعباد حفظة مع أنه عالم بما يصدر منهم. ( فَإِنَّهُ ) سبحانه ( يَسْلُكُ ) أي يجعل في الطريق ( مِنْ بَيْنِ يَدَيْهِ ) أي من أمام الرسول ( وَمِنْ خَلْفِهِ ) أي ورائه ( رَصَداً ) من الملائكة يرصدونه في أعماله ، تشريفا للغيب والوحي الذي أعلم الرسول به. [29] وإنما يرصد ( لِيَعْلَمَ ) الله سبحانه ، والمراد ليقع متعلق علمه في أَنْ قَدْ أَبْلَغُوا رِسالاتِ رَبِّهِمْ وَأَحاطَ بِما لَدَيْهِمْ وَأ َحْصى كُلَّ شَيْءٍ عَدَداً (28) الخارج ، كقوله ( حَتَّى نَعْلَمَ الْمُجاهِدِينَ ) (1) إلى غير ذلك ( أَنْ قَدْ أَبْلَغُوا ) أولئك الرسل الذين أطلعهم على علم الغيب ( رِسالاتِ رَبِّهِمْ ) فكل ما أوحي إليه رسالة ، ومجموع الوحي رسالات ( وَ ) ذلك ليس لأنه لا يعلم ـ بل للتشريفات ، كما ذكرنا ـ إذ قد ( أَحاطَ ) الله سبحانه ( بِما لَدَيْهِمْ ) أي بما يفعله الأنبياء من تبليغ الرسالة ( وَأَحْصى كُلَّ شَيْءٍ عَدَداً ) فعلم أعداد الأشياء كلها ، فإحاطته بما لدى الأنبياء من مصاديق إحصائه سبحانه عدد كل شيء من الخلائق والأعمال والأحوال. هذا هو المعنى الذي استظهرته من الآيات المباركة حسب ما يظهر من السياق ، وهناك قول آخر في معانيها ليس بهذا القرب إلى الظاهر ، والله سبحانه أعلم بمراده. ( 1) محمد : 32. (73)` },
            { text: "لِّيَعْلَمَ أَن قَدْ أَبْلَغُوا۟ رِسَٰلَٰتِ رَبِّهِمْ وَأَحَاطَ بِمَا لَدَيْهِمْ وَأَحْصَىٰ كُلَّ شَىْءٍ عَدَدًۢا", tafsir: `` }
        ]
    },
    73: { // سورة المزمل
        name: "المزمل",
        basmalaTafsir: ``,
        verses: [
            { text: "يَٰٓأَيُّهَا ٱلْمُزَّمِّلُ", tafsir: `المراد به الرسول صلى‌الله‌عليه‌وآله‌وسلم ، أصله « المتزمل » من باب التفعيل ، ثم أدغمت التاء في الزاء ، وجيء بهمزة الوصل لتعذر الابتداء بالساكن ، ومعنى « تزمل » تلفف في ثوب ونحوه ، فقد كان الرسول صلى‌الله‌عليه‌وآله‌وسلم يتزمل بثوبه وينام ، فخوطب بهذا الخطاب لمناسبة الحالة للأمر المتوجه إليه في قيام الليل.` },
            { text: "قُمِ ٱلَّيْلَ إِلَّا قَلِيلًا", tafsir: `في ( اللَّيْلَ ) لأداء صلاة الليل ( إِلَّا قَلِيلاً ) منه فلك أن تنام فيه. [4] ثم بين سبحانه مقدار القليل الذي سمح للرسول صلى‌الله‌عليه‌وآله‌وسلم بالنوم فيه بقوله : ( نِصْفَهُ ) أي نم في مقدار نصف الليل ( أَوِ انْقُصْ مِنْهُ ) أي من النصف ( قَلِيلاً ) بأن تضيف على سهرك ، فيكون نومك أقل من النصف.` },
            { text: "نِّصْفَهُۥٓ أَوِ ٱنقُصْ مِنْهُ قَلِيلًا", tafsir: `` },
            { text: "أَوْ زِدْ عَلَيْهِ وَرَتِّلِ ٱلْقُرْءَانَ تَرْتِيلًا", tafsir: `أي على النصف ، بأن تضيف على نومك فيكون نومك أكثر من النصف ، والحاصل أن المأمور به السهر بمقدار نصف الليل ، أو أكثر من النصف ، أو أقل من النصف ـ والمحور النصف ـ ( وَرَتِّلِ الْقُرْآنَ ) أي اقرأه قراءة متوسطة لا بسرعة ولا ببطئ زائد ( تَرْتِيلاً ) تأكيد ل « رتل » . و قد سئل الإمام أمير المؤمنين عليه‌السلام عن هذه الآية فقال : بيّنه بيانا ولا تهذه هذو الشعر « أي لا تسرعون في قراءته كما تسرعون في قراءة الشعر » ولا تنثره نثر الرمل « أي لا تفرقوا بعضه عن بعض كثير الرمل » ولكن أفزعوا قلوبكم القاسية ، ولا يكن همّ أحدكم آخر السورة (1) . ( 1) الكافي : ج 2 ص 614. إِنَّا سَنُلْقِي عَلَيْكَ قَوْلاً ثَقِيلاً (5) إِنَّ ناشِئَةَ اللَّيْلِ هِيَ أَشَدُّ وَطْئاً وَأَقْوَمُ قِيلاً (6) إِنَّ لَكَ فِي النَّهارِ سَبْحاً طَوِيلاً (7) وَاذْكُرِ اسْمَ رَبِّكَ وَتَبَتَّلْ إِلَيْهِ تَبْتِيلاً (8)` },
            { text: "إِنَّا سَنُلْقِى عَلَيْكَ قَوْلًا ثَقِيلًا", tafsir: `أي سنوحي ( عَلَيْكَ ) يا رسول الله ( قَوْلاً ثَقِيلاً ) أي كلاما يثقل عليك القيام به ، والمراد به القرآن ، فإنه يثقل على الإنسان العمل به ، أو الرسالة فإنه يثقل أداؤها ، أو القيام بالليل. [7] كما فسر قوله تعالى : ( إِنَّ ناشِئَةَ اللَّيْلِ ) أي ساعات الليل لأنها تنشأ ساعة بعد ساعة ، والمقصود العمل فيها أو المراد العبادة التي تنشأ في الليل. ( هِيَ أَشَدُّ وَطْئاً ) أي أكثر ثقلا وكلفة ، لصعوبة القيام ليلا شتاء لبرد الهواء ، وصيفا لقصر الليالي ، ولعل المراد كونها أشد من ناشئة النهار ( وَأَقْوَمُ قِيلاً ) أي قول الليل وعبادته أكثر قواما واستمساكا لأنه يؤدى بحضور القلب وتوجه الذهن ، ولأن أفضل الأعمال أحمزها.` },
            { text: "إِنَّ نَاشِئَةَ ٱلَّيْلِ هِىَ أَشَدُّ وَطْـًٔا وَأَقْوَمُ قِيلًا", tafsir: `` },
            { text: "إِنَّ لَكَ فِى ٱلنَّهَارِ سَبْحًا طَوِيلًا", tafsir: `يا رسول الله ( فِي النَّهارِ سَبْحاً ) « السبح » التقلب ومنه يسمى المتقلب في الماء سابحا : أي تقلبا في أشغالك ( طَوِيلاً ) من إراءة الطريق ، والإرشاد ، وسائر الأعمال فلا يتأتى منك أن تعبد كما ينبغي ، ولذا جعل الليل للعبادة. و قد روي إن الإمام أمير المؤمنين عليه‌السلام كان يعمل طول النهار ، ويعبد طول الليل ، فقيل له : يا أمير المؤمنين ألا تهدأ ؟ قال : إذا هدأت النهار كان فيه ضياع الأمة ، وإذا هدأت الليل كان فيه ضياع نفسي.` },
            { text: "وَٱذْكُرِ ٱسْمَ رَبِّكَ وَتَبَتَّلْ إِلَيْهِ تَبْتِيلًا", tafsir: `يا رسول الله ( اسْمَ رَبِّكَ ) بأن تعبده وتخضع له ( وَتَبَتَّلْ إِلَيْهِ تَبْتِيلاً ) « التبتل » هو الانقطاع إلى الله عزوجل وإخلاص العبادة له ، رَبُّ الْمَشْرِقِ وَالْمَغْرِبِ لا إِلهَ إِلاَّ هُوَ فَاتَّخِذْهُ وَكِيلاً (9) وَاصْبِرْ عَلى ما يَقُولُونَ وَاهْجُرْهُمْ هَجْراً جَمِيلاً (10) وَذَرْنِي وَالْمُكَذِّبِينَ أُولِي النَّعْمَةِ وَمَهِّلْهُمْ قَلِيلاً (11) إِنَّ لَدَيْنا من « بتل » بمعنى قطع ، وإنما قال « إليه » لأن الانقطاع عن الخلق إليه ، لا كون الانقطاع عنه. [10] ثم بين « ربك » بقوله : ( رَبُّ الْمَشْرِقِ وَالْمَغْرِبِ ) هو كناية عن الكون ، لأن من بيده المشرق والمغرب كان بيده العالم كله ( لا إِلهَ إِلَّا هُوَ ) فلا شريك له كما يزعم المشركون ، ولذا لا يحق العبادة لغيره ( فَاتَّخِذْهُ ) يا رسول الله ( وَكِيلاً ) أي حفيظا للقيام بأمرك وفوض إليه أمرك.` },
            { text: "رَّبُّ ٱلْمَشْرِقِ وَٱلْمَغْرِبِ لَآ إِلَٰهَ إِلَّا هُوَ فَٱتَّخِذْهُ وَكِيلًا", tafsir: `` },
            { text: "وَٱصْبِرْ عَلَىٰ مَا يَقُولُونَ وَٱهْجُرْهُمْ هَجْرًا جَمِيلًا", tafsir: `يا رسول الله في توحيدك ونبذ الأصنام ( عَلى ما يَقُولُونَ ) أي الكفار حولك من أنك ساحر أو كاهن أو مجنون أو ما أشبه ذلك ( وَاهْجُرْهُمْ ) أي ابتعد عنهم ( هَجْراً جَمِيلاً ) بأن تدعوهم إلى الهدى في عين حالة الهجر ، بالحكمة والموعظة الحسنة والمجادلة بالتي هي أحسن.` },
            { text: "وَذَرْنِى وَٱلْمُكَذِّبِينَ أُو۟لِى ٱلنَّعْمَةِ وَمَهِّلْهُمْ قَلِيلًا", tafsir: `أي دعني لهم فأنا أكفيك شرهم ( وَالْمُكَذِّبِينَ ) برسالتك وما جئت به ( أُولِي النَّعْمَةِ ) أي أصحاب الثروة وغيرها من سائر النعم ، فكل جزاءهم أليّ ( وَمَهِّلْهُمْ قَلِيلاً ) أي إنهم بعد قليل سيقعون في العذاب ، عذاب الدنيا في قصة بدر ، وعذاب الآخرة. وقوله « مهلهم » كناية عن الصبر معهم ، وهذا تهديد للكفار.` },
            { text: "إِنَّ لَدَيْنَآ أَنكَالًا وَجَحِيمًا", tafsir: `في الآخرة ، والمراد ب « لدينا » لدى حسابنا وجزائنا أَنْكالاً وَجَحِيماً (12) وَطَعاماً ذا غُصَّةٍ وَعَذاباً أَلِيماً (13) يَوْمَ تَرْجُفُ الْأَرْضُ وَالْجِبالُ وَكانَتِ الْجِبالُ كَثِيباً مَهِيلاً (14) إِنَّا أَرْسَلْنا إِلَيْكُمْ رَسُولاً شاهِداً عَلَيْكُمْ كَما أَرْسَلْنا إِلى فِرْعَوْنَ رَسُولاً (15) ( أَنْكالاً ) جمع « نكل » ، وهي القيود والأغلال ( وَجَحِيماً ) أي نارا كثيرة ، فإن جحيم بمعنى ذلك ، وهي من أسماء جهنم.` },
            { text: "وَطَعَامًا ذَا غُصَّةٍ وَعَذَابًا أَلِيمًا", tafsir: `« الغصة » تردد اللقمة في الحلق بحيث لا يتمكن الإنسان من إساغتها ، أي أن أطعمة النار المهيئة لهم ذات غصة فلا يتمكن المجرم من إساغتها إلا بعد علاج وصعوبة ( وَعَذاباً أَلِيماً ) مؤلما موجعا. [15] إن هذه الألوان من العذاب إنما هي في ( يَوْمَ تَرْجُفُ الْأَرْضُ ) أي تتحرك وتضطرب ، فإن الزلزال من علائم القيامة ، كما قال سبحانه ( إِنَّ زَلْزَلَةَ السَّاعَةِ شَيْءٌ عَظِيمٌ ) (1) ( وَالْجِبالُ ) لتكثير الهول ( وَكانَتِ الْجِبالُ ) في ذلك اليوم ( كَثِيباً مَهِيلاً ) « الكثيب » الرمل المجتمع الكثير « والمهيل » هو السائل المتناثر ، من هال : إذا حرك أسفله فتحرك وسال أعلاه ، أي تكون الجبال هكذا سائلة في الأرض.` },
            { text: "يَوْمَ تَرْجُفُ ٱلْأَرْضُ وَٱلْجِبَالُ وَكَانَتِ ٱلْجِبَالُ كَثِيبًا مَّهِيلًا", tafsir: `` },
            { text: "إِنَّآ أَرْسَلْنَآ إِلَيْكُمْ رَسُولًا شَٰهِدًا عَلَيْكُمْ كَمَآ أَرْسَلْنَآ إِلَىٰ فِرْعَوْنَ رَسُولًا", tafsir: `أيها الكفار ( رَسُولاً ) يعني محمد صلى‌الله‌عليه‌وآله‌وسلم ( شاهِداً عَلَيْكُمْ ) بما تعملون من الاعتقاد والعمل ، الصحيح أو الفاسد ( كَما أَرْسَلْنا إِلى فِرْعَوْنَ رَسُولاً ) وهو موسى عليه‌السلام . ( 1) الحج : 2. فَعَصى فِرْعَوْنُ الرَّسُولَ فَأَخَذْناهُ أَخْذاً وَبِيلاً (16) فَكَيْفَ تَتَّقُونَ إِنْ كَفَرْتُمْ يَوْماً يَجْعَلُ الْوِلْدانَ شِيباً (17) السَّماءُ مُنْفَطِرٌ بِهِ كانَ وَعْدُهُ مَفْعُولاً (18) إِنَّ هذِهِ تَذْكِرَةٌ` },
            { text: "فَعَصَىٰ فِرْعَوْنُ ٱلرَّسُولَ فَأَخَذْنَٰهُ أَخْذًا وَبِيلًا", tafsir: `بأن لم يطع أوامره ، بل خالفه وعانده ( فَأَخَذْناهُ ) أي أخذنا فرعون ( أَخْذاً وَبِيلاً ) أي شديدا ثقيلا بإغراقه في البحر ، وهكذا أنتم إن لم تؤمنوا أخذناكم بصنوف العذاب.` },
            { text: "فَكَيْفَ تَتَّقُونَ إِن كَفَرْتُمْ يَوْمًا يَجْعَلُ ٱلْوِلْدَٰنَ شِيبًا", tafsir: `أيها الكفار ، أي تجتنبون ( إِنْ كَفَرْتُمْ ) في الدنيا ( يَوْماً ) أي من عذاب يوم ـ وهو مفعول « تتقون » ( يَجْعَلُ الْوِلْدانَ ) جمع ولد ( شِيباً ) جمع أشيب ، وهو البالغ سن الشيب والشيخوخة فإن يوم القيامة لشدة أهوالها يجعل الأولاد في صورة الشيوخ ببياض الشعر ونحوه ، أي هل تتمكنون من الاتقاء عن عذاب يوم القيامة ؟ وإذ لا تتمكنون فكيف تكفرون حتى تبتلوا به ؟` },
            { text: "ٱلسَّمَآءُ مُنفَطِرٌۢ بِهِۦ كَانَ وَعْدُهُۥ مَفْعُولًا", tafsir: `أي بذلك اليوم ، أي أن السماء تنفطر بسبب أهوال ذلك اليوم ، والسماء يجوز فيها التذكير والتأنيث ، ولذا قال في مقام آخر ( إِذَا السَّماءُ انْفَطَرَتْ ) (1) والانفطار هو الانشقاق ، بأن يرى السماء كالشيء المنشق ، لاختلال نظام المدارات ، ولون الهواء وغير ذلك ( كانَ وَعْدُهُ ) سبحانه بمجيء هذه الأمور ( مَفْعُولاً ) أي كأنه لا خلف فيه ولا تبديل.` },
            { text: "إِنَّ هَٰذِهِۦ تَذْكِرَةٌ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلًا", tafsir: `أي صفة الأمور التي ذكرناها لأهوال ذلك اليوم ( تَذْكِرَةٌ ) ( 1) الإنفطار : 2. فَمَنْ شاءَ اتَّخَذَ إِلى رَبِّهِ سَبِيلاً (19) إِنَّ رَبَّكَ يَعْلَمُ أَنَّكَ تَقُومُ أَدْنى مِنْ ثُلُثَيِ اللَّيْلِ وَنِصْفَهُ وَثُلُثَهُ وَطائِفَةٌ مِنَ الَّذِينَ مَعَكَ وَاللهُ يُقَدِّرُ اللَّيْلَ وَالنَّهارَ عَلِمَ أَنْ لَنْ تُحْصُوهُ فَتابَ عَلَيْكُمْ فَاقْرَؤُا ما تَيَسَّرَ مِنَ الْقُرْآنِ وموعظة لكم أيها البشر ( فَمَنْ شاءَ اتَّخَذَ إِلى رَبِّهِ سَبِيلاً ) أي سلك سبيلا يؤدي إلى رضوانه ، وهو سبيل الدين والإسلام. [21] ثم عطف السياق نحو قيام الليل الذي ابتدأ به الكلام فقال ( إِنَّ رَبَّكَ ) يا رسول الله ( يَعْلَمُ أَنَّكَ تَقُومُ أَدْنى ) أي في الوقت الذي هو أقرب ( مِنْ ثُلُثَيِ اللَّيْلِ وَنِصْفَهُ وَثُلُثَهُ ) ففي بعض الليالي كان الرسول يقوم قبل ثلثي الليل بأن كان الباقي إلى الفجر ثلثان ، وفي بعض الليالي قبل النصف ، وفي بعض الليالي قبل الثلث ( وَ ) تقوم ( طائِفَةٌ مِنَ الَّذِينَ مَعَكَ ) من المؤمنين كالإمام المرتضى عليه‌السلام والصديقة الطاهرة عليهم‌السلام وسائر الخواص. ( وَاللهُ يُقَدِّرُ اللَّيْلَ وَالنَّهارَ ) أي أن مقدار الليل والنهار بيده ، فهو المقدر لها ، والمقدر يعلم الأمور المرتبطة بما قدره ، ولذا ( عَلِمَ ) الله سبحانه ( أَنْ لَنْ تُحْصُوهُ ) أي لا تتمكنون من إحصاء الليل كله ، بأن تقوموا فيه من أوله إلى آخره في العبادة والطاعة ( فَتابَ عَلَيْكُمْ ) بأن لم يفرض القيام في الليل عليكم عطفا وتفضلا ، مع أن المقتضي للإيجاب كان موجودا ( فَاقْرَؤُا ) في الليل ( ما تَيَسَّرَ مِنَ الْقُرْآنِ ) أي من الشيء الذي يقرأ ، والمراد به الصلاة والدعاء ونحوهما ، والمعنى أنه حيث لا تقدرون على القراءة كل الليل فاقرؤوا ما سهل عليكم وتيسر عندكم. عَلِمَ أَنْ سَيَكُونُ مِنْكُمْ مَرْضى وَآخَرُونَ يَضْرِبُونَ فِي الْأَرْضِ يَبْتَغُونَ مِنْ فَضْلِ اللهِ وَآخَرُونَ يُقاتِلُونَ فِي سَبِيلِ اللهِ فَاقْرَؤُا ما تَيَسَّرَ مِنْهُ وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكاةَ وَأَقْرِضُوا اللهَ قَرْضاً حَسَناً وَما تُقَدِّمُوا لِأَنْفُسِكُمْ مِن ْ خَيْرٍ تَجِدُوهُ عِنْدَ اللهِ ثم بين سبحانه حكمة التسهيل بقوله : ( عَلِمَ ) الله تعالى ( أَنْ سَيَكُونُ مِنْكُمْ مَرْضى ) جمع « مريض » ، والمريض لا يقدر على قيام الليل ( وَآخَرُونَ ) منكم ( يَضْرِبُونَ فِي الْأَرْضِ ) أي يسافرون ( يَبْتَغُونَ مِنْ فَضْلِ اللهِ ) أي يطلبون الفضل والتجارة ( وَآخَرُونَ ) منكم ( يُقاتِلُونَ فِي سَبِيلِ اللهِ ) لإعلاء كلمته وسبيل دينه ، والمسافر والمحارب حيث تعبا في النهار لا يسهل عليهما قيام الليل ، ولذا خفف سبحانه عنكم ولم يلزمكم بالقيام ، أو بمقدار خاص كالنصف والثلث والثلثين ( فَاقْرَؤُا ما تَيَسَّرَ ) وسهل ( مِنْهُ ) أي من القرآن ، والمراد به الصلاة والدعاء والقرآن الحكيم فإن القرآن مطلق ما يقرأ ، فإن هذه العلل الخاصة أوجبت تخفيفا عاما ـ على نحو الحكمة ـ ( وَأَقِيمُوا الصَّلاةَ ) في أوقاتها كما فرض سبحانه ( وَآتُوا الزَّكاةَ ) أي أعطوها واجبها ومندوبها ( وَأَقْرِضُوا اللهَ قَرْضاً حَسَناً ) بإنفاق المال في مراضيه ، بلا من أو رياء أو سمعة أو عجب ، وكونه إقراضا باعتبار أنه سبحانه يرده على الإنسان في الدنيا والآخرة أضعافا مضاعفة. ( وَما تُقَدِّمُوا لِأَنْفُسِكُمْ ) إلى الآخرة ( مِنْ خَيْرٍ ) أي طاعة وعبادة فإن ما يعمله الإنسان من الخير يقدم له إلى الجنة حتى إذا ذهب إليها وجد فيها ثواب ما عمل ( تَجِدُوهُ ) أي ذلك الخير ( عِنْدَ اللهِ ) في دار هُوَ خَيْراً وَأَعْظَمَ أَجْراً وَاسْتَغْفِرُوا اللهَ إ ِنَّ اللهَ غَفُورٌ رَحِيمٌ (20) كرامته ( هُوَ ) أي تجدوه هو ـ بعينه بلا نقصان أو اختلاف ـ ( خَيْراً ) أي في حال كونه خيرا ، أو بحذف « تجدوا » أي تجدوا خيرا ، أو أنه بيان لهاء « تجدوه » ، ( وَ ) في حال كونه ( أَعْظَمَ أَجْراً ) أي ثوابا مما كان هو ، فثوابه في الآخرة أعظم من نفسه في الدنيا ، إذا كان في الدنيا يساوي عشرة ، فتجدون في الآخرة ثوابه مائة ـ مثلا ـ أو أعظم أجرا من الذي يبقى في الدنيا ( وَاسْتَغْفِرُوا اللهَ ) اطلبوا غفرانه ( إِنَّ اللهَ غَفُورٌ ) للذنوب ( رَحِيمٌ ) يتفضل بالرحمة فوق غفران الذنوب. (74)` },
            { text: "إِنَّ رَبَّكَ يَعْلَمُ أَنَّكَ تَقُومُ أَدْنَىٰ مِن ثُلُثَىِ ٱلَّيْلِ وَنِصْفَهُۥ وَثُلُثَهُۥ وَطَآئِفَةٌ مِّنَ ٱلَّذِينَ مَعَكَ وَٱللَّهُ يُقَدِّرُ ٱلَّيْلَ وَٱلنَّهَارَ عَلِمَ أَن لَّن تُحْصُوهُ فَتَابَ عَلَيْكُمْ فَٱقْرَءُوا۟ مَا تَيَسَّرَ مِنَ ٱلْقُرْءَانِ عَلِمَ أَن سَيَكُونُ مِنكُم مَّرْضَىٰ وَءَاخَرُونَ يَضْرِبُونَ فِى ٱلْأَرْضِ يَبْتَغُونَ مِن فَضْلِ ٱللَّهِ وَءَاخَرُونَ يُقَٰتِلُونَ فِى سَبِيلِ ٱللَّهِ فَٱقْرَءُوا۟ مَا تَيَسَّرَ مِنْهُ وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَأَقْرِضُوا۟ ٱللَّهَ قَرْضًا حَسَنًا وَمَا تُقَدِّمُوا۟ لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ ٱللَّهِ هُوَ خَيْرًا وَأَعْظَمَ أَجْرًا وَٱسْتَغْفِرُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌۢ", tafsir: `` }
        ]
    },
    74: { // سورة المدثر
        name: "المدثر",
        basmalaTafsir: ``,
        verses: [
            { text: "يَٰٓأَيُّهَا ٱلْمُدَّثِّرُ", tafsir: `المراد به الرسول صلى‌الله‌عليه‌وآله‌وسلم ، والمدثر أصله من « تدثر » باب التفعل ، أدغمت التاء في الدال ، وجيء بهمزة الوصل لتعذر الابتداء بالساكن ، والمدثر هو لابس الدثار ، والدثار هو ما يلبسه الإنسان فوق الثوب الملاصق لجسده لأجل التدفئة ، وفي مقابله الشعار وهو الثوب اللاصق بالبدن ، يسمى به لأنه لاصق بشعر الإنسان. و قد روي أن الرسول صلى‌الله‌عليه‌وآله‌وسلم لما أوحي إليه أخذته الرعدة من الهيبة فقال لخديجة عليها‌السلام : دثريني ، فدثرته ، فجاء النداء ( يا أَيُّهَا الْمُدَّثِّرُ ) .` },
            { text: "قُمْ فَأَنذِرْ", tafsir: `من استراحتك ( فَأَنْذِرْ ) الناس وخوفهم من العقاب إن تمادوا في الكفر والعصيان.` },
            { text: "وَرَبَّكَ فَكَبِّرْ", tafsir: `أي كبر الله وعظمه ـ وحده دون الأصنام ـ .` },
            { text: "وَثِيَابَكَ فَطَهِّرْ", tafsir: `فإن المسلم يجب عليه تطهير قلبه عن أدران الشرك بتكبير الله وحده ، وتطهير ثيابه عن الأوساخ بتقصير ذيله حتى لا يتسخ ، وتنظيفه من النجاسات. وقد روي في معنى الآية التطهير من النجاسة والتطهير بالتقصير ـ وذلك لأن المراد هو الأعم منهما ـ و في الحديث « قصر ثوبك يكون أتقى وأنقى وأبقى » .` },
            { text: "وَٱلرُّجْزَ فَٱهْجُرْ", tafsir: `أي القذارة بأقسامها الشاملة للأصنام وللنجاسات الظاهرية ، وللرذائل ( فَاهْجُرْ ) أي ابتعد عنها.` },
            { text: "وَلَا تَمْنُن تَسْتَكْثِرُ", tafsir: `في العطاء ( تَسْتَكْثِرُ ) أي تطلب الكثير بعدم المنّة ، فإن ما يراد به وجه الله يضاعف ، أو المعنى لا تعط العطية تلتمس أكثر منها ـ وَلِرَبِّكَ فَاصْبِرْ (7) فَإِذا نُقِرَ فِي النَّاقُورِ (8) فَذلِكَ يَوْمَئِذٍ يَوْمٌ عَسِيرٌ (9) عَلَى الْكافِرِينَ غَيْرُ يَسِيرٍ (10) ذَرْنِي وَمَنْ خَلَقْتُ وَحِيداً (11) وَجَعَلْتُ لَهُ مالاً مَمْدُوداً (12) وَبَنِينَ شُهُوداً (13) كما عن الباقر عليه‌السلام (1) ـ أو لا تمنن بعطائك ، على الناس مستكثرا ما أعطيته.` },
            { text: "وَلِرَبِّكَ فَٱصْبِرْ", tafsir: `أي لأجله سبحانه ( فَاصْبِرْ ) على أذى الكفار والمشركين. [9] فإنه سيأتي يومهم الذي ينتقم فيه منهم ( فَإِذا نُقِرَ فِي النَّاقُورِ ) أي نفخ في الصور ، والنقر هو الضرب في الشيء ، ومنه نقر الغراب ، « والناقور » فاعول ، بمعنى البوق ، لأنه ينقر فيه ، فإن النفخ كالنقر.` },
            { text: "فَإِذَا نُقِرَ فِى ٱلنَّاقُورِ", tafsir: `` },
            { text: "فَذَٰلِكَ يَوْمَئِذٍ يَوْمٌ عَسِيرٌ", tafsir: `النقر ( يَوْمَئِذٍ ) أي يوم ينقر ( يَوْمٌ عَسِيرٌ ) صعب شديد.` },
            { text: "عَلَى ٱلْكَٰفِرِينَ غَيْرُ يَسِيرٍ", tafsir: `بالله ورسوله وما جاء به من عنده ( غَيْرُ يَسِيرٍ ) أي غير سهل ، فإن في ذلك اليوم يعذب الكافر. وهذه الجملة للتأكيد ، وإفادة أن عسر ذلك اليوم إنما هو للكافر ، لا للمؤمن التقي.` },
            { text: "ذَرْنِى وَمَنْ خَلَقْتُ وَحِيدًا", tafsir: `أي دعني يا رسول الله ( وَمَنْ خَلَقْتُ وَحِيداً ) أي في حال كونه وحيدا لا مال له ولا أولاد ، والمعنى انا أكفيك شره ، وأنتقم منه جزاء لتكذيبه.` },
            { text: "وَجَعَلْتُ لَهُۥ مَالًا مَّمْدُودًا", tafsir: `أي ذا مدّ وطول ، فقد كان « وليد » الذي نزلت فيه هذه الآيات صاحب أموال كثيرة.` },
            { text: "وَبَنِينَ شُهُودًا", tafsir: `جعلت له ( بَنِينَ ) أي أولادا ( شُهُوداً ) أي حضورا عنده ، ( 1) بحار الأنوار : ج 93 ص 144. وَمَهَّدْتُ لَهُ تَمْهِيداً (14) ثُمَّ يَطْمَعُ أَنْ أَزِيدَ (15) كَلاَّ إِنَّهُ كانَ لِآياتِنا عَنِيداً (16) سَأُرْهِقُهُ صَعُوداً (17) وهذه نعمة أخرى بأن يكون أولاد الإنسان عنده لا يغيبون عنه.` },
            { text: "وَمَهَّدتُّ لَهُۥ تَمْهِيدًا", tafsir: `أي هيأت له الأمور تمهيدا ، بأن صار ذات جاه في قومه ، ومكانة في البلد ، وهيأت له الأسباب.` },
            { text: "ثُمَّ يَطْمَعُ أَنْ أَزِيدَ", tafsir: `هذا الشخص ( أَنْ أَزِيدَ ) ماله وأولاده.` },
            { text: "كَلَّآ إِنَّهُۥ كَانَ لِـَٔايَٰتِنَا عَنِيدًا", tafsir: `لا أزيد بعد ذلك شيئا له ، فقد كفر بي ، وأبدل مكان الشكر كفرانا ( إِنَّهُ كانَ لِآياتِنا عَنِيداً ) أي معاندا لأدلتنا وحججنا لا يؤمن بها عنادا ومضادة.` },
            { text: "سَأُرْهِقُهُۥ صَعُودًا", tafsir: `أي سأكلفه مشقة من العذاب لا طاقة له بها ، والصعود هي العقبة الشاقة المصعد ، فإن من يكلف صعودها يشق عليه ، فقد شبه العذاب بذلك للتقريب إلى الذهن. و قد ورد في سبب نزول هذه الآيات وما بعدها ما ذكره القمي قال : نزلت في الوليد بن المغيرة ، وكان شيخا مجربا من دهاة العرب وكان من المستهزئين برسول الله صلى‌الله‌عليه‌وآله‌وسلم ، وكان رسول الله يقعد في الحجر ويقرأ القرآن ، فاجتمعت قريش إلى الوليد بن المغيرة ، فقالوا : يا أبا عبد شمس ما هذا الذي يقول محمد صلى‌الله‌عليه‌وآله‌وسلم أشعر هو أم كهانة أم خطب ؟ فقال : دعوني أسمع كلامه ، فدنى من رسول الله صلى‌الله‌عليه‌وآله‌وسلم وقال : يا محمد أنشدني من شعرك ؟ قال صلى‌الله‌عليه‌وآله‌وسلم : ما هو شعر ، ولكنه كلام الله الذي ارتضته ملائكته وأنبياؤه ورسله. فقال : اتل علي منه شيئا ، فقرأ عليه رسول الله صلى‌الله‌عليه‌وآله‌وسلم حم السجدة ، فلما بلغ قوله ( فَإِنْ أَعْرَضُوا فَقُلْ إِنَّهُ فَكَّرَ وَقَدَّرَ (18) فَقُتِلَ كَيْفَ قَدَّرَ (19) أَنْذَرْتُكُمْ صاعِقَةً مِثْلَ صاعِقَةِ عادٍ وَثَمُودَ ) (1) قال : فاقشعر الوليد وقامت كل شعرة في رأسه ولحيته ، ومر إلى بيته ولم يرجع إلى قريش من ذلك اليوم. فمشوا إلى أبي جهل فقالوا : يا أبا الحكم إن أبا عبد شمس صبأ « أي مال إلى دين محمد » أما تراه لم يرجع إلينا ؟ فغدا أبو جهل إلى الوليد ، فقال له : يا عم نكست رؤوسنا وفضحتنا وأشمت بنا عدونا وصبوت إلى دين محمد ؟ فقال : ما صبوت إلى دينه ولكن سمعت منه كلاما صعبا تقشعر منه الجلود ، فقال له أبو جهل : أخطب هو ؟ قال : لا ، إن الخطب كلام متصل وهذا كلام منثور ولا يشبه بعضه بعضا. قال : أ فشعر هو ؟ قال : لا أما إني لقد سمعت أشعار العرب بسيطها ومديدها ورملها ورجزها وما هو بشعر. قال : فما هو ؟ قال : دعني أفكر فيه فلما كان من الغد قالوا له : يا أبا عبد شمس ما تقول فيما قلناه ؟ قال : قولوا هو سحر فإنه آخذ بقلوب الناس ، فأنزل الله على رسوله في ذلك ( ذَرْنِي وَمَنْ خَلَقْتُ وَحِيداً ) وإنما سمي وحيدا لأنه قال لقريش : أنا أتوحد بكسوة البيت سنة وعليكم في جماعتكم سنة ، وكان له مال كثير وحدائق وكان له عشرة بنين بمكة ، وكانت له عشرة عبيد عند كل عبد ألف دينار يتجر بها (2) .` },
            { text: "إِنَّهُۥ فَكَّرَ وَقَدَّرَ", tafsir: `أي الوليد ( فَكَّرَ ) حول القرآن ( وَقَدَّرَ ) القول في نفسه.` },
            { text: "فَقُتِلَ كَيْفَ قَدَّرَ", tafsir: `دعاء عليه ، أي قتله الله ( كَيْفَ قَدَّرَ ) ؟ تقديرا يوافق أهواء المكذبين وأذهان العامة ، فإن الناس يسرعون إلى نسبة السحر إلى كل ( 1) فصلت : 14. ( 2) تفسير القمي : ج 2 ص 393. ثُمَّ قُتِلَ كَيْفَ قَدَّرَ (20) ثُمَّ نَظَرَ (21) ثُمَّ عَبَسَ وَبَسَرَ (22) ثُمَّ أَدْبَرَ وَاسْتَكْبَرَ (23) فَقالَ إِنْ هذا إِلاَّ سِحْرٌ يُؤْثَرُ (24) إِنْ هذا إِلاَّ قَوْلُ الْبَشَرِ (25) سَأُصْلِيهِ سَقَرَ (26) ما خرج عن طورهم ، وهذا تعجب من تفكيره وتقديره.` },
            { text: "ثُمَّ قُتِلَ كَيْفَ قَدَّرَ", tafsir: `للتراخي في الكلام لا في الخارج ( قُتِلَ كَيْفَ قَدَّرَ ) تكرير لشدة التعجب منه ، وإعادة الدعاء عليه.` },
            { text: "ثُمَّ نَظَرَ", tafsir: `في طلب ما يدفع به القرآن ، والنظر هنا التفكر.` },
            { text: "ثُمَّ عَبَسَ وَبَسَرَ", tafsir: `أي قطب وجهه وكلحه ، ( وَبَسَرَ ) البسور بدو التكره في الوجه.` },
            { text: "ثُمَّ أَدْبَرَ وَٱسْتَكْبَرَ", tafsir: `أي أعرض عن الحق ، وأن يقول في القرآن ما علمه منه ( وَاسْتَكْبَرَ ) فقد منعه كبره عن القول بالحق.` },
            { text: "فَقَالَ إِنْ هَٰذَآ إِلَّا سِحْرٌ يُؤْثَرُ", tafsir: `أي ما هذا القرآن ( إِلَّا سِحْرٌ يُؤْثَرُ ) أي يروى عن السحرة.` },
            { text: "إِنْ هَٰذَآ إِلَّا قَوْلُ ٱلْبَشَرِ", tafsir: `أي ما هذا القرآن ( إِلَّا قَوْلُ الْبَشَرِ ) فليس وحيا منزلا من السماء. [27] ثم جاء السياق ليهدده لهذا الكلام المكذوب الذي افتراه ، فإنه لو كان سحرا لقدر السحرة على الإتيان بمثله ، ولقدر المشرعون في العالم أن يضعوا قوانين شبيهة به ، لكنه كلام الله وقد علموا به وإنما منعهم عن ذلك كبرهم وتمردهم ( سَأُصْلِيهِ سَقَرَ ) أي سأدخله جهنم ، وألزمه إياها ، فإن « الإصلاء » إلزام موضع النار. وَما أَدْراكَ ما سَقَرُ (27) لا تُبْقِي وَلا تَذَرُ (28) لَوَّاحَةٌ لِلْبَشَرِ (29) عَلَيْها تِسْعَةَ عَشَرَ (30) وَما جَعَلْنا أَصْحابَ النَّارِ إِلاَّ مَلائِكَةً وَما جَعَلْنا عِدَّتَهُمْ إِلاَّ فِتْنَةً لِلَّذِينَ كَفَرُوا` },
            { text: "سَأُصْلِيهِ سَقَرَ", tafsir: `` },
            { text: "وَمَآ أَدْرَىٰكَ مَا سَقَرُ", tafsir: `أيها السامع ( ما سَقَرُ ) أي أنت لا تدري ما هي لشدة عذابها ، حتى كأن الإنسان لا يمكن أن يعرفها على حقيقتها.` },
            { text: "لَا تُبْقِى وَلَا تَذَرُ", tafsir: `شيئا مما يطرح فيها ، بل تأكل اللحم وتحرق الجلد والعظم ( وَلا تَذَرُ ) إما تأكيدا أو بمعنى أنها لا تدعهم يفنون حتى ينجوا من العذاب ، بل تحرق وتعيد ، وهكذا دواليك.` },
            { text: "لَوَّاحَةٌ لِّلْبَشَرِ", tafsir: `من التلويح بمعنى تغيير اللون بواسطة الشمس ونحوها ( لِلْبَشَرِ ) أي أنها تغير الجلود ، و « البشر » جمع بشرة ، وهي ظاهر الجلد.` },
            { text: "عَلَيْهَا تِسْعَةَ عَشَرَ", tafsir: `أي الملائكة الموكلون عليها ( تِسْعَةَ عَشَرَ ) وهذا أحد الأعداد الممكنة ، ولا مجال لأن يقال : لماذا ليسوا أكثر ولا أقل ؟ فإن أي عدد كان محل هذا السؤال ، كما أن في سائر الأعداد أيضا لا إشكال ، كثمانية أبواب للجنة ، وسبعة للنار ، وسبع سماوات طباقا وهكذا.` },
            { text: "وَمَا جَعَلْنَآ أَصْحَٰبَ ٱلنَّارِ إِلَّا مَلَٰٓئِكَةً وَمَا جَعَلْنَا عِدَّتَهُمْ إِلَّا فِتْنَةً لِّلَّذِينَ كَفَرُوا۟ لِيَسْتَيْقِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ وَيَزْدَادَ ٱلَّذِينَ ءَامَنُوٓا۟ إِيمَٰنًا وَلَا يَرْتَابَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ وَٱلْمُؤْمِنُونَ وَلِيَقُولَ ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ وَٱلْكَٰفِرُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَٰذَا مَثَلًا كَذَٰلِكَ يُضِلُّ ٱللَّهُ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ وَمَا يَعْلَمُ جُنُودَ رَبِّكَ إِلَّا هُوَ وَمَا هِىَ إِلَّا ذِكْرَىٰ لِلْبَشَرِ", tafsir: `أي الموكلون بها ( إِلَّا مَلائِكَةً ) لأنهم أقوى ، ولعدم رقتهم لأهل النار ، بخلاف ما لو كانوا آدميين ( وَما جَعَلْنا عِدَّتَهُمْ ) أي تعدادهم بكونهم تسعة عشر ( إِلَّا فِتْنَةً ) وامتحانا ( لِلَّذِينَ كَفَرُوا ) حتى يتبين هل هم يؤمنون أم يضحكون من هذا العدد قائلين لا يكفي هذا العدد القليل لتعذيب الكثرة من الكفار والعصاة فإن لِيَسْتَيْقِنَ الَّذِينَ أُوتُوا الْكِتابَ وَيَزْدادَ الَّذِينَ آمَنُوا إِيماناً وَلا يَرْتابَ الَّذِينَ أُوتُوا الْكِتابَ وَالْمُؤْمِنُونَ وَلِيَقُولَ الَّذِينَ فِي قُلُوبِهِمْ مَرَضٌ وَالْكافِرُونَ م ا ذا أَرادَ اللهُ بِهذا مَثَلاً مخلوقاته سبحانه موجبة للفتنة والامتحان سواء كانت نعما أو نقما في الدنيا أو في الآخرة ، وسواء كان أصل الشيء أو خصوصياته ومزاياه. وقد ذكرنا عدد الملائكة في القرآن ( لِيَسْتَيْقِنَ الَّذِينَ أُوتُوا الْكِتابَ ) أي اليهود والنصارى بأن الرسول حق ، حيث يرون أنه صلى‌الله‌عليه‌وآله‌وسلم أخبر بما هو في كتبهم مما لا يعلمه أحد إلا هم فقط ، فإخبار إنسان لا يطلع على كتبهم ولم يسمع منهم بذلك يوجب تعيينهم بأنه حق وإنما تعلم ذلك بالوحي ( وَيَزْدادَ الَّذِينَ آمَنُوا ) بالرسول ( إِيماناً ) حيث يرون تصديق أهل الكتاب ـ الذين هم أهل الفن ـ للرسول صلى‌الله‌عليه‌وآله‌وسلم فيوجب ذلك زيادة إيمانهم ( وَلا يَرْتابَ ) أي لا يشك ( الَّذِينَ أُوتُوا الْكِتابَ وَالْمُؤْمِنُونَ ) في نبوة النبي صلى‌الله‌عليه‌وآله‌وسلم . وهذا تأكيد للجملة السابقة ، فإن المؤمن قلبا من أهل الكتاب ، والمؤمن ظاهرا من سائر الناس بالرسول صلى‌الله‌عليه‌وآله‌وسلم ، في معرض الشك والزوال ، كما هو الشأن في كل ملكة إذا لم تقو ، فإذا وجد هذا الشاهد تقوت الملكة ، ولم يكن الإنسان معرضا للريب. ( وَلِيَقُولَ ) اللام للعاقبة ، أي أن الغاية من تعريف عدد خزنة النار أمران : الأول زيادة إيمان المؤمنين ، وحصول العلم لأهل الكتاب بصدق الرسول. الثاني شدة نفاق المنافق ، وكفر الكافر ، فيقول ( الَّذِينَ فِي قُلُوبِهِمْ مَرَضٌ ) من المنافقين ( وَالْكافِرُونَ ) بالرسول : ( ما ذا أَرادَ اللهُ بِهذا مَثَلاً ) ؟ فكأنهم زعموا أن هذا العدد الخاص من كَذلِكَ يُضِلُّ اللهُ مَنْ يَشاءُ وَيَهْدِي مَنْ يَشاءُ وَما يَعْلَمُ جُنُودَ رَبِّكَ إِلاَّ هُوَ وَما هِيَ إِلاَّ ذِكْرى لِلْبَشَرِ (31) كَلاَّ وَالْقَمَرِ (32) باب المثل ، لا أنه حقيقة مطابق لعدد الموكلين بالنار ، فأخذوا يستفسرون عن قصد هذا المثل ، فشأن المعاند حيث يستفسر حول كل كلمة من كلمات خصمه لأن التواء قلبه يوجب أن يرى كل شيء متساويا. ثم يأتي السياق ليبين جواب هؤلاء السائلين بقوله : ( كَذلِكَ ) أي ببيان الحقائق ، كما بين عدد ملائكة النار ( يُضِلُّ اللهُ مَنْ يَشاءُ ) فإنه إذا ذكر الحقيقة نفر عنها أناس ، فذلك إضلال لهم ( وَيَهْدِي مَنْ يَشاءُ ) إذ يتعلق بالإيمان أناس آخرون وذلك هداية لهم ، فإن إضلاله وهدايته ليسا بمعنى الجبر ، بل بمعنى إنزال آية أو بيان حكم يوجب الضلال والهدى ليمتحن الناس. وبمناسبة بيان عدد جنوده الموكلين ، بالنار جاء السياق ليقرر حقيقة عامة بقوله : ( وَما يَعْلَمُ جُنُودَ رَبِّكَ ) الموكلين بكل شيء ، المحافظين لكل خلق ( إِلَّا هُوَ ) سبحانه وحده ، إلا إذا أعلم ذلك لبعض ، فليس لأحد أن يقول : أن جند كذا أكثر أو أقل مما يخبر الله سبحانه ( وَما هِيَ ) أي سقر التي تقدم الكلام حولها ( إِلَّا ذِكْرى لِلْبَشَرِ ) أي تذكرة لهم ، بمعنى أن ذكرها يذكرهم بالعذاب فيقلعوا عن المعاصي ، أو ان هذه السورة تذكرة لهم.` },
            { text: "كَلَّا وَٱلْقَمَرِ", tafsir: `ليس الأمر على ما توهم هؤلاء الكفار من أنه لا حساب ولا جزاء ( وَالْقَمَرِ ) أي قسما بالقمر. وَاللَّيْلِ إِذْ أَدْبَرَ (33) وَالصُّبْحِ إِذا أَسْفَرَ (34) إِنَّها لَإِحْدَى الْكُبَرِ (35) نَذِيراً لِلْبَشَرِ (36) لِمَنْ شاءَ مِنْكُمْ أَنْ يَتَقَدَّمَ أَوْ يَتَأَخَّرَ (37) كُلُّ نَفْسٍ بِما كَسَبَتْ رَهِينَةٌ (38)` },
            { text: "وَٱلَّيْلِ إِذْ أَدْبَرَ", tafsir: `قسما ب ( اللَّيْلِ إِذْ أَدْبَرَ ) ولّى وذهب ليأتي مكانه النهار.` },
            { text: "وَٱلصُّبْحِ إِذَآ أَسْفَرَ", tafsir: `قسما ب ( الصُّبْحِ إِذا أَسْفَرَ ) أي إذا أضاء وجاء.` },
            { text: "إِنَّهَا لَإِحْدَى ٱلْكُبَرِ", tafsir: `أي « سقر » التي تقدم الكلام حولها ( لَإِحْدَى ) الآيات ( الْكُبَرِ ) جمع كبري ، أي إحدى آيات الله العظمى ، فإن من قدر على خلق تلك الآيات من القمر والليل والنهار ، لقادر على خلق النار وسقر لتعذيب الكفار وغير المؤمنين ، ولعل اختيار الحلف بهذه الأمور لإيحائها بالظلمة المختلطة بشيء من الضياء ، كالنار التي هي كذلك ، كما أن سكون هذه الأمور يوحي بسكون أهل النار الشبيه بالموت بخلاف أهل الجنة الذين هم أحياء. [37] في حال كونها ( نَذِيراً لِلْبَشَرِ ) تنذرهم بأنهم إن لم يؤمنوا بها ابتلوا بها ، كما تقول : هذه السلاسل تنذر المجرمين.` },
            { text: "نَذِيرًا لِّلْبَشَرِ", tafsir: `` },
            { text: "لِمَن شَآءَ مِنكُمْ أَن يَتَقَدَّمَ أَوْ يَتَأَخَّرَ", tafsir: `أيها البشر ( أَنْ يَتَقَدَّمَ ) إلى الخير لينجو ( أَوْ يَتَأَخَّرَ ) بالعصيان حتى يبتلي ، فلكل إنسان أن يختار مصيره « إما إلى جنة وإما إلى النار » .` },
            { text: "كُلُّ نَفْسٍۭ بِمَا كَسَبَتْ رَهِينَةٌ", tafsir: `من الطاعة أو المعصية ( رَهِينَةٌ ) كالرهن الذي هو محبوس في مقابل الدين ؛ فإن وفي الدين فك وإلا لم يفك ، وكذلك إذا وفى الإنسان بما عليه ـ من الإيمان والطاعة ـ فك وحظي بالثواب ، وإلا كان مصيره النار والبقاء في حبس الأبد. إِلاَّ أَصْحابَ الْيَمِينِ (39) فِي جَنَّاتٍ يَتَساءَلُونَ (40) عَنِ الْمُجْرِمِينَ (41) ما سَلَكَكُمْ فِي سَقَرَ (42) قالُوا لَمْ نَكُ مِنَ الْمُصَلِّينَ (43) وَلَمْ نَكُ نُطْعِمُ الْمِسْكِينَ (44) وَكُنَّا نَخُوضُ مَعَ الْخائِضِينَ (45)` },
            { text: "إِلَّآ أَصْحَٰبَ ٱلْيَمِينِ", tafsir: `الذين يعطى كتابهم بأيمانهم ، ويؤخذ بهم ـ يوم القيامة ـ ذات اليمين نحو الجنان ، فإنهم قد فكوا أنفسهم من الرهن بأعمالهم الصالحة. [41] فإنهم ( فِي جَنَّاتٍ يَتَساءَلُونَ ) أي يسأل بعضهم من بعض ، أو من الملائكة ، أو من نفس المجرمين.` },
            { text: "فِى جَنَّٰتٍ يَتَسَآءَلُونَ", tafsir: `` },
            { text: "عَنِ ٱلْمُجْرِمِينَ", tafsir: `وعلى الأولين ، يلتفتون بعد السؤال إلى المجرمين ، كما قال سبحانه ( إِنِّي كانَ لِي قَرِينٌ .. ) إلى قوله : ( فَاطَّلَعَ فَرَآهُ فِي سَواءِ الْجَحِيمِ* قالَ تَاللهِ إِنْ كِدْتَ لَتُرْدِينِ ) (1) وعلى الثالث يكون المسؤول ابتداء هو المجرم. [43] فيقولون لهم : ( ما سَلَكَكُمْ ) أي ما أدخلكم أيها المجرمون ( فِي سَقَرَ ) في هذه النار العظيمة ؟` },
            { text: "مَا سَلَكَكُمْ فِى سَقَرَ", tafsir: `` },
            { text: "قَالُوا۟ لَمْ نَكُ مِنَ ٱلْمُصَلِّينَ", tafsir: `أي المجرمون في جوابهم ( لَمْ نَكُ ) نحن في الدنيا ( مِنَ الْمُصَلِّينَ ) أي ما كنا نصلي الصلوات المفروضة.` },
            { text: "وَلَمْ نَكُ نُطْعِمُ ٱلْمِسْكِينَ", tafsir: `إطعاما واجبا ، بإعطاء الزكاة ونحوها.` },
            { text: "وَكُنَّا نَخُوضُ مَعَ ٱلْخَآئِضِينَ", tafsir: `في الباطل ( مَعَ الْخائِضِينَ ) أي مع الذين يخوضون في الباطل ، وأصل « الخوض » الدخول في الشيء بجميع الجسم فكأن ( 1) الصافات : 52 ـ 57. وَكُنَّا نُكَذِّبُ بِيَوْمِ الدِّينِ (46) حَتَّى أَتانَا الْيَقِينُ (47) فَما تَنْفَعُهُمْ شَفاعَةُ الشَّافِعِينَ (48) فَما لَهُمْ عَنِ التَّذْكِرَةِ مُعْرِضِينَ (49) كَأَنَّهُمْ حُمُرٌ مُسْتَنْفِرَةٌ (50) فَرَّتْ مِنْ قَسْوَرَةٍ (51) الباطل شيء يخاض فيه.` },
            { text: "وَكُنَّا نُكَذِّبُ بِيَوْمِ ٱلدِّينِ", tafsir: `« الدين » هو الجزاء ، أي لا نعترف بيوم القيامة ، بل نقول أنه كذب لا يكون.` },
            { text: "حَتَّىٰٓ أَتَىٰنَا ٱلْيَقِينُ", tafsir: `أي الموت ، بأن لم نتب قبل أن نموت وسمي الموت يقينا لأنه سبب لانكشاف ذلك العالم لدى الإنسان ، حتى يتيقن بما هناك. [49] وإذا كانوا كذلك في الدنيا ( فَما تَنْفَعُهُمْ شَفاعَةُ الشَّافِعِينَ ) أي الذين يشفعون للمذنبين ، من الأنبياء والملائكة والعلماء ومن أشبههم ، إذ ذنبهم فوق حد الشفاعة ، وهذا من باب السالبة بانتفاء الموضوع ، إذ لا يشفع لهم أحد حتى تنفع. [50] ثم يأتي السياق ليستغرب من عنادهم في الباطل ( فَما لَهُمْ ) أي ما لهؤلاء الكفار ( عَنِ التَّذْكِرَةِ مُعْرِضِينَ ) أي لم أعرضوا عن القرآن الذي يذكرهم بالحقائق وبما فيه نفعهم ؟ وأي خير لهم في هذا الإعراض ؟` },
            { text: "فَمَا تَنفَعُهُمْ شَفَٰعَةُ ٱلشَّٰفِعِينَ", tafsir: `` },
            { text: "فَمَا لَهُمْ عَنِ ٱلتَّذْكِرَةِ مُعْرِضِينَ", tafsir: `` },
            { text: "كَأَنَّهُمْ حُمُرٌ مُّسْتَنفِرَةٌ", tafsir: `جمع « حمار » ( مُسْتَنْفِرَةٌ ) أي وحشية نافرة « واستنفر » بمعنى نفر ، كأنها طلبت من نفسها الفرار ، لما شاهدت من الخوف ، وتشبيههم بالحمار لعدم إدراكهم وبلادتهم.` },
            { text: "فَرَّتْ مِن قَسْوَرَةٍۭ", tafsir: `أي الأسد ، فإن الحمار إذا شاهد الأسد فر منه ، وكذلك الكفار يفرون من الرسول صلى‌الله‌عليه‌وآله‌وسلم . بَلْ يُرِيدُ كُلُّ امْرِئٍ مِنْهُمْ أَنْ يُؤْتى صُحُفاً مُنَشَّرَةً (52) كَلاَّ بَلْ لا يَخافُونَ الْآخِرَةَ (53) كَلاَّ إِنَّهُ تَذْكِرَةٌ (54) فَمَنْ شاءَ ذَكَرَهُ (55) وَما يَذْكُرُونَ إِلاَّ أَنْ يَشاءَ اللهُ` },
            { text: "بَلْ يُرِيدُ كُلُّ ٱمْرِئٍ مِّنْهُمْ أَن يُؤْتَىٰ صُحُفًا مُّنَشَّرَةً", tafsir: `أي يعطى في يوم القيامة ( صُحُفاً مُنَشَّرَةً ) بأن يوحي إليه وينزل عليه الكتاب من الله سبحانه كما قال سبحانه ( لَوْ لا أُنْزِلَ عَلَيْنَا الْمَلائِكَةُ ) (1) ؟ أو المراد أنهم مع هذا الإعراض عن الحق يريد أن يعطى كتابه يوم القيامة منشورا فيه الحسنات ، إذ الكتاب إذا كان فيه سيئات يطوى لئلا يطلع عليه أحد ، أما إذا كان فيه الحسنات ينشر على رؤوس الأشهاد للافتخار والمباهاة ، وكأن الإتيان ب « بل » لإفادة أنهم مع الكفر يتوقعون هذا.` },
            { text: "كَلَّا بَل لَّا يَخَافُونَ ٱلْـَٔاخِرَةَ", tafsir: `لا يعطون كتابا منشورا ، فإنهم لم يعملوا ما يستحقون به ذلك ( بَلْ لا يَخافُونَ الْآخِرَةَ ) حتى يدخلوا في زمرة المؤمنين الموجب لإعطاء كتاب منشور بأيديهم ، أو المراد أنهم حيث لا يخافون الآخرة أعرضوا عن التذكرة.` },
            { text: "كَلَّآ إِنَّهُۥ تَذْكِرَةٌ", tafsir: `ليس الأمر على ما توهموا من أن إعراضهم خير لهم ( إِنَّهُ تَذْكِرَةٌ ) أي القرآن يذكرهم.` },
            { text: "فَمَن شَآءَ ذَكَرَهُۥ", tafsir: `التذكرة والاهتداء والخير ( ذَكَرَهُ ) أي اتعظ به ، ومن لم يشأ فهو وشأنه.` },
            { text: "وَمَا يَذْكُرُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ هُوَ أَهْلُ ٱلتَّقْوَىٰ وَأَهْلُ ٱلْمَغْفِرَةِ", tafsir: `` }
        ]
    },
    75: { // سورة القيامة
        name: "القيامة",
        basmalaTafsir: ``,
        verses: [
            { text: "لَآ أُقْسِمُ بِيَوْمِ ٱلْقِيَٰمَةِ", tafsir: `« لا » للنفي ، وقد سبق أن الإتيان بها لنكتة مليحة ، هي أن الحالف يريد أن يبين ويؤكد المطلب غير حالف مع الإيماء إلى الحلف ، كما تقول « لا أقسم بحياتك إلا أن الأمر كذا » تريد أن لا تحلف به ـ لأمر ـ مع الإلماع إلى الحلف لتحصل فائدة التأكيد.` },
            { text: "وَلَآ أُقْسِمُ بِٱلنَّفْسِ ٱللَّوَّامَةِ", tafsir: `وهي النفس اليقظة التي تلوم صاحبها عن التقصير في خدمة الله سبحانه ، وإن كان الإنسان في أرقى درجات الطاعة. وقيل أن جهة نفي القسم أن الكفار لم يكونوا يقرّون بالمقسمين ، فكأنه قيل لا أحلف بهما لأنكم لا تقرون بذلك.` },
            { text: "أَيَحْسَبُ ٱلْإِنسَٰنُ أَلَّن نَّجْمَعَ عِظَامَهُۥ", tafsir: `أي هل يظن ( أَلَّنْ نَجْمَعَ عِظامَهُ ) بعد الموت لأن يحشر ؟ والمعنى أ يظن أنه لا قيامة ولا معاد ؟. [5] وقد كان زعم الإنسان بعدم الجمع ، من جهة حسبانه انه تعالى غير قادر على ذلك ، ولذا جاء السياق لدفع هذا الزعم الباطل بقوله : ( بَلى ) نجمع عظامه فإنّا نكون ( قادِرِينَ عَلى أَنْ نُسَوِّيَ بَنانَهُ ) أي رؤوس أصابعه ، وهذا في غاية القدرة ، لأن خطوط أصابع الناس يختلف بعضها مع بعض وإن كان البشر عشرات الآلاف من الملايين ، ومن يقدر على صنع وإعادة أدق أجزاء الإنسان قادر على إعادة غير ذلك من سائر أجزائه : قالوا : وأعجب ما في الإنسان أربعة : اختلاف الأصوات ، والوجوه ، وخطوط البنان ، وذبذبات الخطوط حتى أنّ بَلْ يُرِيدُ الْإِنْسانُ لِيَفْجُرَ أَمامَهُ (5) يَسْئَلُ أَيَّانَ يَوْمُ الْقِيامَةِ (6) فَإِذا بَرِقَ الْبَصَرُ (7) وَخَسَفَ الْقَمَرُ (8) وَجُمِعَ الشَّمْسُ وَالْقَمَرُ (9) يَقُولُ الْإِنْسانُ يَوْمَئِذٍ أَيْنَ الْمَفَرُّ (10) إنسانين لو خطّا كان من المستحيل عادة أن يتساوى خطهما ، وإنما يعرف الاختلاف بالمجاهر والآلات الحديثة : [6] إن الإنسان لا يكفر بالمعاد ، لأنه ينكر في قلبه قدرة الله سبحانه على البعث ( بَلْ ) إنما ينكر لأنه ( يُرِيدُ الْإِنْسانُ لِيَفْجُرَ ) أي يعصي ( أَمامَهُ ) أي في مستقبل عمره ، وحيث إن الاعتراف بالآخرة يمنع عن فجوره ، ينكر حتى يكون الطريق مفتوحا لفجوره ، وإذ خوّف من الآخرة أنكرها ليسكت المنكر له : [7] ف ( يَسْئَلُ ) سؤال منكر ( أَيَّانَ يَوْمُ الْقِيامَةِ ) ؟ أي متى يكون ، بمعنى أنه لا يكون ، وإلا فأين هو ؟ [8] ثم يأتي السياق ليبين وقت يوم القيامة ( فَإِذا بَرِقَ الْبَصَرُ ) أي شخص عند معاينة الأهوال ، أو تقلب البرق ، أو خرج منه البرق ، فإن الإنسان لدى الاصطدام يخرج من عينه مثل البرق.` },
            { text: "بَلَىٰ قَٰدِرِينَ عَلَىٰٓ أَن نُّسَوِّىَ بَنَانَهُۥ", tafsir: `` },
            { text: "بَلْ يُرِيدُ ٱلْإِنسَٰنُ لِيَفْجُرَ أَمَامَهُۥ", tafsir: `` },
            { text: "يَسْـَٔلُ أَيَّانَ يَوْمُ ٱلْقِيَٰمَةِ", tafsir: `` },
            { text: "فَإِذَا بَرِقَ ٱلْبَصَرُ", tafsir: `` },
            { text: "وَخَسَفَ ٱلْقَمَرُ", tafsir: `أي ذهب نوره ، فظهر جرما كمدا بلا نور.` },
            { text: "وَجُمِعَ ٱلشَّمْسُ وَٱلْقَمَرُ", tafsir: `بأن يختل نظامهما الفلكي فيرى كل واحد منهما بجنب الآخر.` },
            { text: "يَقُولُ ٱلْإِنسَٰنُ يَوْمَئِذٍ أَيْنَ ٱلْمَفَرُّ", tafsir: `المكذب بيوم القيامة ( يَوْمَئِذٍ ) أي في هذا اليوم ( أَيْنَ الْمَفَرُّ ) أي إلى أين يمكن الفرار من هذه الأهوال ؟ وهذا استفهام للإنكار ، والتحسر ، بأنه لا يمكن الفرار. كَلاَّ لا وَزَرَ (11) إِلى رَبِّكَ يَوْمَئِذٍ الْمُسْتَقَرُّ (12) يُنَبَّؤُا الْإِنْسانُ يَوْمَئِذٍ بِما قَدَّمَ وَأَخَّرَ (13) بَلِ الْإِنْسانُ عَلى نَفْسِهِ بَصِيرَةٌ (14) وَلَوْ أَلْقى مَعاذِيرَهُ (15)` },
            { text: "كَلَّا لَا وَزَرَ", tafsir: `فإنه لا يمكن الفرار ( لا وَزَرَ ) وهو ما يتحصن به الإنسان من جبل ونحوه ، أي لا ملجأ للفرار والهرب.` },
            { text: "إِلَىٰ رَبِّكَ يَوْمَئِذٍ ٱلْمُسْتَقَرُّ", tafsir: `حساب ( رَبِّكَ ) أيها الإنسان ( يَوْمَئِذٍ ) أي في هذا اليوم ( الْمُسْتَقَرُّ ) أي المنتهى ، فالصالحون إلى جنته ، والطالحون إلى ناره.` },
            { text: "يُنَبَّؤُا۟ ٱلْإِنسَٰنُ يَوْمَئِذٍۭ بِمَا قَدَّمَ وَأَخَّرَ", tafsir: `أي يخبر الإنسان ، والمخبر هو الله سبحانه بواسطة الأنبياء والشهداء ( يَوْمَئِذٍ ) أي في يوم القيامة ( بِما قَدَّمَ ) إلى الآخرة في حياته ، من الأعمال الصالحة ( وَ ) ما ( أَخَّرَ ) كما لو أوقف وقفا ومات فجرت الصدقة بعد مماته ، وإنما يخبر بذلك للجزاء والثواب ، أو النكال فإن المحسن أو المجرم ، يقرأ أولا ما عمل ثم يجازى. [15] ومهما اعتذر الإنسان بشتى الأعذار ، فإنه مما لا تقبل منه ( بَلِ الْإِنْسانُ عَلى نَفْسِهِ ) وما عمل في الدنيا ( بَصِيرَةٌ ) التاء للمبالغة ، أي كامل العلم والعرفان ، أو التاء للتأنيث ، أي حجة بصيرة ، فإن الأعضاء تشهد بما صدر منه.` },
            { text: "بَلِ ٱلْإِنسَٰنُ عَلَىٰ نَفْسِهِۦ بَصِيرَةٌ", tafsir: `` },
            { text: "وَلَوْ أَلْقَىٰ مَعَاذِيرَهُۥ", tafsir: `أي ولو اعتذر لم ينفعه عذره ، أو يعلم ما صنع وإن اعتذر في ظاهر لفظه ، فإن الإلقاء بمعنى الإعطاء ، كما يقال فلان ألقى بحجته ، « ومعاذير » جمع معذرة ، أو معذار. [17] ثم يأتي السياق لتوجيه الرسول صلى‌الله‌عليه‌وآله‌وسلم في كيفية تحمل القرآن إذا ما يوحى إليه ، ولعل المناسبة الربط بين أحوال القيامة وبين العمل الذي لا تُحَرِّكْ بِهِ لِسانَكَ لِتَعْجَلَ بِهِ (16) إِنَّ عَلَيْنا جَمْعَهُ وَقُرْآنَهُ (17) فَإِذا قَرَأْناهُ فَاتَّبِعْ قُرْآنَهُ (18) ثُمَّ إِنَّ عَلَيْنا بَيانَهُ (19) كَلاَّ يوجه إليه القرآن. قال ابن عباس : كان النبي إذا نزل عليه القرآن عجل بتحريك لسانه لحبه إياه وحرصه على أخذه وضبطه مخافة أن ينساه ، ونحوه نقل عن سعيد بن جبير ، أقول : ولعل هذا العمل كان منه صلى‌الله‌عليه‌وآله‌وسلم أثناء هذه السورة ، ولذا جاء هذا التوجيه في الأثناء ( لا تُحَرِّكْ ) يا رسول الله ( بِهِ ) أي بالقرآن ( لِسانَكَ ) بأن تقرأه كلمة كلمة بمجرد قراءة جبرئيل قبل أن يتم الوحي ( لِتَعْجَلَ بِهِ ) أي لتأخذه على عجلة مخافة أن تنساه.` },
            { text: "لَا تُحَرِّكْ بِهِۦ لِسَانَكَ لِتَعْجَلَ بِهِۦٓ", tafsir: `` },
            { text: "إِنَّ عَلَيْنَا جَمْعَهُۥ وَقُرْءَانَهُۥ", tafsir: `أن نجمعه ونؤلّفه ( وَقُرْآنَهُ ) أي أن نقرأه عليك.` },
            { text: "فَإِذَا قَرَأْنَٰهُ فَٱتَّبِعْ قُرْءَانَهُۥ", tafsir: `وذلك بقراءة جبرئيل لك ( فَاتَّبِعْ قُرْآنَهُ ) أي قراءته.` },
            { text: "ثُمَّ إِنَّ عَلَيْنَا بَيَانَهُۥ", tafsir: `أي إيضاحه وتفسيره في مجملاته ومتشابهاته فعلينا الجمع والقراءة والبيان ، وعليك الرسالة والتبليغ. وفي الحقيقة الأمر من المدهشات لو لا الرسالة ، فإنه كيف يتسنى للشخص أن يحفظ هذا المقدار الكبير من الكلام بدون تكرار في القراءة عن كتاب. ألا ترى أن أبلغ الخطباء وأذكرهم إذا صعد المنبر وقرأ مقدار صفحتين ، وكان عرفه على حفظه لم يتمكن من قراءته مرة ثانية كما قرأ أولا ، لكن وعد الله سبحانه للرسول بقوله « فلا تنسى » هو الذي أوجب حفظه بمجرد قراءة جبرئيل ، ولو كان الرسول غير صادق في دعواه ـ كما زعم الكفار ـ كيف تسنى له هذا الحفظ المدهش. [21] ثم رجع السياق إلى الكلام السابق بقوله : ( كَلَّا ) لا تتدبرون القرآن ، بَلْ تُحِبُّونَ الْعاجِلَةَ (20) وَتَذَرُونَ الْآخِرَةَ (21) وُجُوهٌ يَوْمَئِذٍ ناضِرَةٌ (22 ) إِلى رَبِّها ناظِرَةٌ (23) وَوُجُوهٌ يَوْمَئِذٍ باسِرَةٌ (24) تَظُنُّ أَنْ يُفْعَلَ بِها فاقِرَةٌ (25) كَلاَّ إِذا بَلَغَتِ التَّراقِيَ (26) ولا تتفكرون في المعاد « إرادة لأن تفجروا أمامكم » ( بَلْ تُحِبُّونَ الْعاجِلَةَ ) أي الدنيا الحاضرة.` },
            { text: "كَلَّا بَلْ تُحِبُّونَ ٱلْعَاجِلَةَ", tafsir: `` },
            { text: "وَتَذَرُونَ ٱلْـَٔاخِرَةَ", tafsir: `أي تتركون ( الْآخِرَةَ ) فلا تعملون لها. [23] فاعلموا أن من عمل هنا للآخرة كان حاله هناك حسنا ، ومن لم يعمل كان حاله سيئا ( وُجُوهٌ يَوْمَئِذٍ ) أي في يوم القيامة ( ناضِرَةٌ ) أي ناعمة بهيجة حسنة وهي وجوه المؤمنين.` },
            { text: "وُجُوهٌ يَوْمَئِذٍ نَّاضِرَةٌ", tafsir: `` },
            { text: "إِلَىٰ رَبِّهَا نَاظِرَةٌ", tafsir: `أي إلى رحمته سبحانه وفضله ولطفه ، وهذا كما تقول « أنظر إلى فلان » وهو بعيد عنك ، تريد إلى فضله ورحمته ، أو إلى حركاته وأعماله.` },
            { text: "وَوُجُوهٌ يَوْمَئِذٍۭ بَاسِرَةٌ", tafsir: `أي في يوم القيامة ( باسِرَةٌ ) شديدة العبوس والتقطيب ، فإن الإنسان المحزون الخائف يبسر وجهه ، وهي وجوه الكافرين والعصاة.` },
            { text: "تَظُنُّ أَن يُفْعَلَ بِهَا فَاقِرَةٌ", tafsir: `أصحاب تلك الوجوه ، ونسبة الظن إلى الوجوه مجاز ( أَنْ يُفْعَلَ بِها فاقِرَةٌ ) أي داهية تكسر فقار الظهر من شدتها ، وإنما قال « تظن » لأن الإنسان مهما رأى العذاب قريبا لا يستعد لأن يعترف بنزوله عليه رجاء أن يدفع عنه ، فهو ظان بالعذاب لا متيقن.` },
            { text: "كَلَّآ إِذَا بَلَغَتِ ٱلتَّرَاقِىَ", tafsir: `ليس الأمر على ما توهم الكفار من أنها دنيا بلا آخرة ، فإنه سيظهر لهم كذب هذا الزعم ( إِذا بَلَغَتِ ) الروح ( التَّراقِيَ ) جمع وَقِيلَ مَنْ راقٍ (27) وَظَنَّ أَنَّهُ الْفِراقُ (28) وَالْتَفَّتِ السَّاقُ بِالسَّاقِ (29) إِلى رَبِّكَ يَوْمَئِذٍ الْمَساقُ (30) فَلا صَدَّقَ وَلا صَلَّى (31) وَلكِنْ كَذَّبَ وَتَوَلَّى (32) ثُمَّ ذَهَبَ إِلى أَهْلِهِ يَتَمَطَّى (33) « ترقوة » ، وهي العظام المكتنفة بالحلق ، وهذا كناية عن الإشراف على الموت.` },
            { text: "وَقِيلَ مَنْ رَاقٍ", tafsir: `لعل المراد أن الملائكة تسأل بعضها بعضا من يرقى بروح هذا الشخص هل ملائكة الرحمة أو ملائكة العذاب ؟` },
            { text: "وَظَنَّ أَنَّهُ ٱلْفِرَاقُ", tafsir: `المحتضر أو من حضره ( أَنَّهُ الْفِراقُ ) أي أن الذي نزل به هو فراقه من الدنيا ، وابتعاده عن الأحبة.` },
            { text: "وَٱلْتَفَّتِ ٱلسَّاقُ بِٱلسَّاقِ", tafsir: `هذا كناية عن عدم الحيلة في إرجاعه إلى الدنيا ، وشفائه من الموت ، فإن الإنسان الذي تلتف رجليه ، لا يتمكن من الهرب والفرار عن المكروه.` },
            { text: "إِلَىٰ رَبِّكَ يَوْمَئِذٍ ٱلْمَسَاقُ", tafsir: `أيها الإنسان ( يَوْمَئِذٍ ) أي في يوم الاحتضار ( الْمَساقُ ) أي السوق ، فلا علاج إلا الذهاب إليه ، وقد تم عمرك في الدنيا. [32] فهل عمل هذا الإنسان الكافر عملا ينجيه هناك ؟ كلا ( فَلا صَدَّقَ ) ما يجب التصديق به ( وَلا صَلَّى ) لله الصلوات المفروضات.` },
            { text: "فَلَا صَدَّقَ وَلَا صَلَّىٰ", tafsir: `` },
            { text: "وَلَٰكِن كَذَّبَ وَتَوَلَّىٰ", tafsir: `عوض ذلك ( كَذَّبَ ) بالله وما يجب الإيمان به ( وَتَوَلَّى ) أي أعرض عن الحق.` },
            { text: "ثُمَّ ذَهَبَ إِلَىٰٓ أَهْلِهِۦ يَتَمَطَّىٰٓ", tafsir: `لترتيب الكلام ، لا لترتيب المطلب في الخارج ( ذَهَبَ إِلى أَهْلِهِ يَتَمَطَّى ) أي يتكبر افتخارا بتكذيبه ، من المط وهو التمدد ، فإن الإنسان أَوْلى لَكَ فَأَوْلى (34) ثُمَّ أَوْلى لَكَ فَأَوْلى (35) أَ يَحْسَبُ الْإِنْسانُ أَنْ يُتْرَكَ سُدىً (36) أَلَمْ يَكُ نُطْفَةً مِنْ مَنِيٍّ يُمْنى (37) المتبختر يمدد بدنه ، ولعل المراد ب « ذهب إلى أهله » أن المتبختر إنما يظهر معظم كبره لأهله حين يرجع إليهم من خارج البيت.` },
            { text: "أَوْلَىٰ لَكَ فَأَوْلَىٰ", tafsir: `الحالة التي أنت عليها من الإيمان والإطاعة ، والإتيان ب « لك » بمعنى أن المتكبر الطاغي أولى له حالته السيئة من الأمر الحسن الذي يدعى إليه ، لأنها تجانسه لا الحسن ( فَأَوْلى ) أي أيضا نقول أولى لك تأكيدا لعدم قابليته للإيمان والهداية.` },
            { text: "ثُمَّ أَوْلَىٰ لَكَ فَأَوْلَىٰٓ", tafsir: `للتأكيد. و قد روى أن رسول الله صلى‌الله‌عليه‌وآله‌وسلم أخذ ذات مرة بيد أبي جهل وقال له : « أولى لك فأولى ثم أولى لك فأولى » فقال أبو جهل : بأي شيء تهددني لا تستطيع أنت ولا ربك أن تفعلا بي شيئا وإني لأعز أهل هذا الوادي ، فأنزل الله سبحانه هذه الآية (1) . أقول : وقد تمكن الرسول صلى‌الله‌عليه‌وآله‌وسلم وربه تعالى أن يفعلا به كل شيء ، فقد قتل أبو جهل في بدر ، والتحق بالسعير. ولفظة « أولى لك » تهديد ، أي إنك سترى عاقبة ما اخترت من الانحراف.` },
            { text: "أَيَحْسَبُ ٱلْإِنسَٰنُ أَن يُتْرَكَ سُدًى", tafsir: `أي هل يظن الإنسان ( أَنْ يُتْرَكَ سُدىً ) أي مهملا بلا أمر ولا نهي ولا حساب ولا جزاء ؟ فإن « سدى » بمعنى « مهمل » .` },
            { text: "أَلَمْ يَكُ نُطْفَةً مِّن مَّنِىٍّ يُمْنَىٰ", tafsir: `الإنسان ( نُطْفَةً مِنْ مَنِيٍّ يُمْنى ) أي يصب ويراق ألا يستدل بذلك وبما اختلف عليه من الأطوار أن الله قادر على أن يعيده. ( 1) بحار الأنوار : ج 18 ص 168. ثُمَّ كانَ عَلَقَةً فَخَلَقَ فَسَوَّى (38) فَجَعَلَ مِنْهُ الزَّوْجَيْنِ الذَّكَرَ وَالْأُنْثى (39) أَ لَيْسَ ذلِكَ بِقادِرٍ عَلى أَنْ يُحْيِيَ الْمَوْتى (40)` },
            { text: "ثُمَّ كَانَ عَلَقَةً فَخَلَقَ فَسَوَّىٰ", tafsir: `وهي القطعة من الدم المنعقد ، فإن النطفة تتبدل إلى تلك ( فَخَلَقَ ) الله منها بشرا سويا ( فَسَوَّى ) أي سوى خلقه بإعطائه الآلات والأجهزة والمشاعر وغير ذلك.` },
            { text: "فَجَعَلَ مِنْهُ ٱلزَّوْجَيْنِ ٱلذَّكَرَ وَٱلْأُنثَىٰٓ", tafsir: `أي من الإنسان ( الزَّوْجَيْنِ ) أي الصنفين ( الذَّكَرَ وَالْأُنْثى ) فمن يا ترى صنع كل ذلك غيره سبحانه ؟` },
            { text: "أَلَيْسَ ذَٰلِكَ بِقَٰدِرٍ عَلَىٰٓ أَن يُحْـِۧىَ ٱلْمَوْتَىٰ", tafsir: `` }
        ]
    },
    76: { // سورة الإنسان
        name: "الإنسان",
        basmalaTafsir: ``,
        verses: [
            { text: "هَلْ أَتَىٰ عَلَى ٱلْإِنسَٰنِ حِينٌ مِّنَ ٱلدَّهْرِ لَمْ يَكُن شَيْـًٔا مَّذْكُورًا", tafsir: `استفهام للتقرير حتى يقر الإنسان بهذه الحقيقة ، فيرتب عليه أنه إذا لم يكن ثم كان ، كان مكوّنه قادرا على أن يعيده بعد أن يفنى ويهلك ( حِينٌ مِنَ الدَّهْرِ ) أي زمان طويل من الأزمنة السالفة ( لَمْ يَكُنْ شَيْئاً مَذْكُوراً ) أي شيئا يذكر ، بأن كان معدوما لا أثر له ؟ والجواب : أنه نعم كان كذلك ، وهل لأحد أن ينكر هذه الحقيقة.` },
            { text: "إِنَّا خَلَقْنَا ٱلْإِنسَٰنَ مِن نُّطْفَةٍ أَمْشَاجٍ نَّبْتَلِيهِ فَجَعَلْنَٰهُ سَمِيعًۢا بَصِيرًا", tafsir: `هي المني ( أَمْشاجٍ ) جمع « مشيج » من مشجت بمعنى خلطت ، أي النطفة أخلاط مختلفة من ماء الرجل وماء المرأة ، ومن الأجزاء المتجمعة من المأكولات المختلفة ، وإنما خلقناه ل ( نَبْتَلِيهِ ) أي نمتحنه بما نكلفه من الأعمال ، هل يحسن أم يسيء ؟ ( فَجَعَلْناهُ ) أي الإنسان ( سَمِيعاً بَصِيراً ) يسمع ويبصر ليتم عليه التكليف.` },
            { text: "إِنَّا هَدَيْنَٰهُ ٱلسَّبِيلَ إِمَّا شَاكِرًا وَإِمَّا كَفُورًا", tafsir: `أي الطريق إلى الحق ببعث الأنبياء وإرسال الكتب ، ف ( إِمَّا ) يكون ( شاكِراً ) لأنعم الله سبحانه بالإيمان والإطاعة ، ( وَإِمَّا ) يكون ( كَفُوراً ) كثير الكفر ، فإن كل كافر هو كفور باعتبار مختلف الأزمنة والأحوال.` },
            { text: "إِنَّآ أَعْتَدْنَا لِلْكَٰفِرِينَ سَلَٰسِلَا۟ وَأَغْلَٰلًا وَسَعِيرًا", tafsir: `أي هيأنا ( لِلْكافِرِينَ سَلاسِلَ ) لأن يجروا بها جمع سلسلة وَأَغْلالاً وَسَعِيراً (4) إِنَّ الْأَبْرارَ يَشْرَبُونَ مِنْ كَأْسٍ كانَ مِزاجُها كافُوراً (5) عَيْناً يَشْرَبُ بِها عِبادُ اللهِ يُفَجِّرُونَها تَفْجِيراً (6) وهي قطعات الحديد المتداخلة ، وهي غير منصرفة ، لأنها على وزن « مفاعل » ( وَأَغْلالاً ) جمع غل لأن يقيدوا بها ( وَسَعِيراً ) أي نارا مستعرة ، أي ذات لهب واتقاد ، والمراد تهيؤ ذلك لهم في الآخرة.` },
            { text: "إِنَّ ٱلْأَبْرَارَ يَشْرَبُونَ مِن كَأْسٍ كَانَ مِزَاجُهَا كَافُورًا", tafsir: `جمع برّ وهو المؤمن الصالح ( يَشْرَبُونَ مِنْ كَأْسٍ ) وهي القدح التي تكون فيه الخمر ، أو سائر أقسام المشروبات ولعل تقديم الشراب لمناسبته مع ما تقدم من « السعير » الموجبة لطلب الإنسان الماء ـ مناسبة الضد للضد ـ ( كانَ مِزاجُها ) أي ما يمزج بشرابها ( كافُوراً ) لبرودته وعذوبته وطيب عرفه ، وإتيان الضمير مؤنثا لأن الكأس مؤنث سماعي. وقد كانت العرب تمزج الخمر بالكافور حينا وبالزنجبيل حينا ، ولذا ذكروا أن خمر الجنة كذلك ، تماشيا مع مداركهم ، وإن كان هناك ما لا يشبه أطعمة الدنيا وأشربتها ، لذة وفضلا.` },
            { text: "عَيْنًا يَشْرَبُ بِهَا عِبَادُ ٱللَّهِ يُفَجِّرُونَهَا تَفْجِيرًا", tafsir: `أي أن تلك الكأس تملأ من عين ، وكأنها منصوبة على تقدير الفعل ، أي نبشركم أو نهنئكم ( يَشْرَبُ بِها ) أي منها ـ والإتيان بالباء لنكتة بلاغية ـ ( عِبادُ اللهِ ) الذين عبدوا الله وأطاعوه حق طاعته ( يُفَجِّرُونَها ) أي يجرونها ويخرجونها حيث شاؤوا من منازلهم وقصورهم ( تَفْجِيراً ) ومن المتعة أن يكون المنزل بحيث يمكن تفجير العين فيه ، فإنه تلهي وتلذذ. يُوفُونَ بِالنَّذْرِ وَيَخافُونَ يَوْماً كانَ شَرُّهُ مُسْتَطِيراً (7) وَيُطْعِمُونَ الطَّعامَ عَلى حُبِّهِ مِسْكِيناً وَيَتِيماً وَأَسِيراً (8) إِنَّما نُطْعِمُكُمْ لِوَجْهِ اللهِ لا نُرِيدُ مِنْكُمْ جَزاءً وَلا شُكُوراً (9) [8] ثم وصف عباد الله بقوله : ( يُوفُونَ بِالنَّذْرِ ) أي كانوا في الدنيا بحيث إذا نذروا نذرا وفوا به ولم يغشّوا ، والنذر هو أن يلتزم الإنسان على نفسه خيرا لأجله سبحانه ، كأن ينذر الصيام أو الصدقة أو ما أشبه ( وَيَخافُونَ يَوْماً ) أي من أهوال ذلك اليوم ، وهو يوم القيامة ( كانَ شَرُّهُ مُسْتَطِيراً ) أي منتشرا في كل جهة ، حتى يشمل كل كافر وآثم ، وليس كشرور الدنيا التي تكون خاصة بأرض أو إنسان أو محل.` },
            { text: "يُوفُونَ بِٱلنَّذْرِ وَيَخَافُونَ يَوْمًا كَانَ شَرُّهُۥ مُسْتَطِيرًا", tafsir: `` },
            { text: "وَيُطْعِمُونَ ٱلطَّعَامَ عَلَىٰ حُبِّهِۦ مِسْكِينًا وَيَتِيمًا وَأَسِيرًا", tafsir: `أي لأجل الله سبحانه ، وعلى حبه تعالى ، أو بمعنى على أنهم يحبون الطعام لجوعهم ( مِسْكِيناً ) وهو الفقير الذي أسكن الفقر حركاته ، فإن الغني يتحرك هنا وهناك أما الفقير فإنه يسكن لعدم مال له يصرفه في أموره ( وَيَتِيماً ) وهو الطفل الذي مات أبوه ، أو أبواه ، وقد يطلق على من ماتت أمه ( وَأَسِيراً ) الذي أسر في الحرب ، وقد كان أهل البيت عليهم‌السلام وفوا بالنذر وأطعموا الثلاثة ـ كما تقدم ـ . [10] وقصدهم حين الإطعام هو ( إِنَّما نُطْعِمُكُمْ ) أيها الفقراء ( لِوَجْهِ اللهِ ) أي لذاته سبحانه وإنما جيء ب « الوجه » كناية عن الاتجاه والقصد ، تشبيها بوجه الإنسان الذي يتوجه الإنسان إليه حين طلب مرضاته ( لا نُرِيدُ مِنْكُمْ ) أيها الفقراء ( جَزاءً ) لنا ، كأن تعملوا بعض أعمالنا جزاء تصدقنا لكم ( وَلا شُكُوراً ) بأن تشكروننا ولو باللسان ـ وإنما الصدقة خالصة لله سبحانه ، للتقرب من رضوانه ـ . إِنَّا نَخافُ مِنْ رَبِّنا يَوْماً عَبُوساً قَمْطَرِيراً (10) فَوَقاهُمُ اللهُ شَرَّ ذلِكَ الْيَوْمِ وَلَقَّاهُمْ نَضْرَةً وَسُرُوراً (11) وَجَزاهُمْ بِما صَبَرُوا جَنَّةً وَحَرِيراً (12) مُتَّكِئِينَ فِيها عَلَى الْأَرائِكِ لا يَرَوْنَ فِيها شَمْساً وَلا زَمْهَرِيراً (13) وَدانِيَةً عَلَيْهِمْ ظِلالُها` },
            { text: "إِنَّمَا نُطْعِمُكُمْ لِوَجْهِ ٱللَّهِ لَا نُرِيدُ مِنكُمْ جَزَآءً وَلَا شُكُورًا", tafsir: `` },
            { text: "إِنَّا نَخَافُ مِن رَّبِّنَا يَوْمًا عَبُوسًا قَمْطَرِيرًا", tafsir: `لو عصيناه بأن لم نف بالنذر ، أو لم نطعم المسكين لوجهه ( يَوْماً عَبُوساً ) أي مكفهرا تعبس فيه الوجوه. ونسبة العبوس إلى اليوم من باب علاقة الحال والمحل ، من قبيل « يا سارق الليلة » ( قَمْطَرِيراً ) أي صعبا شديدا.` },
            { text: "فَوَقَىٰهُمُ ٱللَّهُ شَرَّ ذَٰلِكَ ٱلْيَوْمِ وَلَقَّىٰهُمْ نَضْرَةً وَسُرُورًا", tafsir: `أي حفظهم وكفاهم ( شَرَّ ذلِكَ الْيَوْمِ ) أي يوم القيامة ( وَلَقَّاهُمْ ) أي استقبلهم وأعطاهم ( نَضْرَةً ) في الوجوه ، وهي البهجة والحسن ( وَسُرُوراً ) في القلوب.` },
            { text: "وَجَزَىٰهُم بِمَا صَبَرُوا۟ جَنَّةً وَحَرِيرًا", tafsir: `أي كافأهم وأعطاهم جزاء ( بِما صَبَرُوا ) أي بسبب صبرهم ( جَنَّةً وَحَرِيراً ) مكانا للسكنى ، ولباسا وأثاثا. [14] في حال كونهم ( مُتَّكِئِينَ ) أي مستريحين ( فِيها ) أي في الجنة ( عَلَى الْأَرائِكِ ) جمع أريكة ، وهي سرير العروس في الحجلة ( لا يَرَوْنَ فِيها ) أي في تلك الجنة ( شَمْساً ) تحرقهم ( وَلا زَمْهَرِيراً ) أي بردا يؤذيهم.` },
            { text: "مُّتَّكِـِٔينَ فِيهَا عَلَى ٱلْأَرَآئِكِ لَا يَرَوْنَ فِيهَا شَمْسًا وَلَا زَمْهَرِيرًا", tafsir: `` },
            { text: "وَدَانِيَةً عَلَيْهِمْ ظِلَٰلُهَا وَذُلِّلَتْ قُطُوفُهَا تَذْلِيلًا", tafsir: `يعني أن ظل أشجار الجنة قريبة منهم فإن الضياء الموجود هناك وفيه شيء من الحرارة محجوب بالأشجار وحيطان القصور والسقوف ، ويكون الهواء في ظلالها أهنأ وأطيب ، وإنما جعل كذلك لتطلب الإنسان تغيير الهواء من الظل إلى الحر ، وَذُلِّلَتْ قُطُوفُها تَذْلِيلاً (14) وَيُطافُ عَلَيْهِمْ بِآنِيَةٍ مِنْ فِضَّةٍ وَأَكْوابٍ كانَتْ قَوارِيرَا (15) قَوارِيرَا مِنْ فِضَّةٍ قَدَّرُوها تَقْدِيراً (16) وَيُسْقَو ْنَ فِيها كَأْساً كانَ مِزاجُها وبالعكس ، و « دانية » حال عطف على « متكئين » ( وَذُلِّلَتْ قُطُوفُها ) جمع قطف وهو الثمرة ( تَذْلِيلاً ) أي سهلت أخذ ثمارها باليد ، لقربها ونضجها فتقطف بسرعة.` },
            { text: "وَيُطَافُ عَلَيْهِم بِـَٔانِيَةٍ مِّن فِضَّةٍ وَأَكْوَابٍ كَانَتْ قَوَارِيرَا۠", tafsir: `والطائف هم الوالدان المخلدون ( بِآنِيَةٍ ) أي ظرف كأنها الإبريق ونحوه مما فيه الماء ( مِنْ فِضَّةٍ ) لعل فيها الشراب ( وَأَكْوابٍ ) جمع كوب ، وهو القدح الصغير ، وذلك لصب الشراب من الآنية في الأكواب لتناول الناس الأبرار ( كانَتْ ) تلك الأكواب ( قَوارِيرَا ) أي زجاجات.` },
            { text: "قَوَارِيرَا۟ مِن فِضَّةٍ قَدَّرُوهَا تَقْدِيرًا", tafsir: `فهي من زجاجة بلون الفضة لتجمع بين اللذتين في المشاهدة. قال الصادق عليه‌السلام : ينفذ البصر في فضة الجنة كما ينفذ الزجاج (1) . أقول : فهي جامعة بين صفاء الزجاجة وشفيفها وبياض الفضة ولينها ( قَدَّرُوها ) أي قدروا تلك الأكواب ( تَقْدِيراً ) كأنها صنعت ب « الماكنة » في توحيد أشكالها ومزاياها ، لا كالأواني المصنوعة باليد التي يراها الإنسان مختلفة تنبو عنها العين لاختلافها.` },
            { text: "وَيُسْقَوْنَ فِيهَا كَأْسًا كَانَ مِزَاجُهَا زَنجَبِيلًا", tafsir: `أي في الجنة ، والفاعل هم الأبرار المقدم ذكرهم ( كَأْساً ) أي شرابا في الكأس ـ بعلاقة الحال والمحل ـ ( كانَ مِزاجُها ) ( 1) بحار الأنوار : ج 8 ص 111. زَنْجَبِيلاً (17) عَيْناً فِيها تُسَمَّى سَلْسَبِيلاً (18) وَيَطُوفُ عَلَيْهِمْ وِلْدانٌ مُخَلَّدُونَ إِذا رَأَيْتَهُمْ حَسِبْتَهُمْ لُؤْلُؤاً مَنْثُوراً (19) وَإِذا رَأَيْتَ ثَمَّ رَأَيْتَ نَعِيماً وَمُلْكاً كَبِيراً (20) عالِيَهُمْ ثِيابُ سُندُسٍ خُضْرٌ أي مزج بشرابها ( زَنْجَبِيلاً ) أي ما يشبه الزنجبيل في الطعم وهو عقار معروف كانوا يخلطونه بالشراب ـ كما تقدم ـ .` },
            { text: "عَيْنًا فِيهَا تُسَمَّىٰ سَلْسَبِيلًا", tafsir: `بدل من زنجيل ، أو منصوب على تقدير الفعل كما ذكر سابقا ( فِيها ) أي في الجنة ( تُسَمَّى سَلْسَبِيلاً ) فالشراب الممزوج بالزنجبيل يؤخذ من تلك العين ، وسميت « سلسبيلا » لسيلانه في الأنهار عذبا صافيا رقراقا ، أو لأنه سائغ في الخلق لصفائه وخفته ، فلا يتوهم أن الزنجبيل يوجب لذعا وحرقة.` },
            { text: "وَيَطُوفُ عَلَيْهِمْ وِلْدَٰنٌ مُّخَلَّدُونَ إِذَا رَأَيْتَهُمْ حَسِبْتَهُمْ لُؤْلُؤًا مَّنثُورًا", tafsir: `معنى الطواف هو الذهاب من عند هذا إلى ذاك إلى ذلك ، وهكذا حتى يرجع إلى الأول ، و « الولدان » جمع ولد ، ومعنى مخلدون باقون في الجنة إلى الأبد ، وهم قسيم للحور ، فهم أولاد وتلكم بنات ( إِذا رَأَيْتَهُمْ ) أيها الإنسان ( حَسِبْتَهُمْ ) أي ظننتهم ( لُؤْلُؤاً مَنْثُوراً ) لصفاء ألوانهم وبريقها ، وتفرقهم هنا وهناك يشبههم باللؤلؤ غير المنظوم ، لانتشارهم في الخدمة.` },
            { text: "وَإِذَا رَأَيْتَ ثَمَّ رَأَيْتَ نَعِيمًا وَمُلْكًا كَبِيرًا", tafsir: `يا رسول الله ، أو أيها الرائي ( ثَمَ ) أي الجنة ، فإن ثم بمعنى هنا لك ( رَأَيْتَ نَعِيماً وَمُلْكاً كَبِيراً ) أي وسيعا ، فإنه يعطي لأقل أهل الجنة منزلة من القصور والجنان ما يكفي لأن يضيف الثقلين في ضيافة واحدة.` },
            { text: "عَٰلِيَهُمْ ثِيَابُ سُندُسٍ خُضْرٌ وَإِسْتَبْرَقٌ وَحُلُّوٓا۟ أَسَاوِرَ مِن فِضَّةٍ وَسَقَىٰهُمْ رَبُّهُمْ شَرَابًا طَهُورًا", tafsir: `أي يعلوهم ، والمراد يلبسون ثيابا وَإِسْتَبْرَقٌ وَحُلُّوا أَساوِرَ مِنْ فِضَّةٍ وَسَقاهُمْ رَبُّهُمْ شَراباً طَهُوراً (21) إِنَّ هذا كانَ لَكُمْ جَزاءً وَكانَ سَعْيُكُمْ مَشْكُوراً (22) إِنَّا نَحْنُ نَزَّلْنا عَلَيْكَ الْقُرْآنَ تَنْزِيلاً (23) فَاصْبِرْ لِحُكْمِ رَبِّكَ سندسا ، وهو الحرير الأخضر الرقيق ، ( وَإِسْتَبْرَقٌ ) وهو الحرير الخشن والرقيق أنعم للبدن ، والخشن أجمل في المنظر ( وَحُلُّوا ) أي يحلّون بالزينة ( أَساوِرَ مِنْ فِضَّةٍ ) جمع سوار ، وهو ما يلبس في اليد من الحلي ، والفضة هنا أثمن من الذهب ـ كما قالوا ـ وقد كانت العادة في الملوك والكبراء لبس السوار ( وَسَقاهُمْ رَبُّهُمْ شَراباً طَهُوراً ) فليس كشراب الدنيا نجسا أو موجبا للرذيلة من السكر ونحوه. [23] ويقال لهم : ( إِنَّ هذا ) النعيم الذي أنتم فيه ( كانَ لَكُمْ جَزاءً ) على إيمانكم وأعمالكم الصالحة ، « وكان » لمجرد الربط ( وَكانَ سَعْيُكُمْ ) وتعبكم في الدنيا ( مَشْكُوراً ) شكره الله سبحانه وقدره ، ولذا جزاكم بهذا الثواب. [24] ثم يأتي السياق ليسلي النبي صلى‌الله‌عليه‌وآله‌وسلم عملا يلاقيه من الأذى في سبيل الدعوة إلى مثل هذه الجنات ، بعد ما بين جزاء العالمين ( إِنَّا نَحْنُ نَزَّلْنا عَلَيْكَ ) يا رسول الله ( الْقُرْآنَ تَنْزِيلاً ) والتأكيد ب « نحن » لدفع كلمات الكفار حول القرآن ، بأنه كهانة أو شعر أو يعلمه بشر ، أو ما أشبه ذلك.` },
            { text: "إِنَّ هَٰذَا كَانَ لَكُمْ جَزَآءً وَكَانَ سَعْيُكُم مَّشْكُورًا", tafsir: `` },
            { text: "إِنَّا نَحْنُ نَزَّلْنَا عَلَيْكَ ٱلْقُرْءَانَ تَنزِيلًا", tafsir: `` },
            { text: "فَٱصْبِرْ لِحُكْمِ رَبِّكَ وَلَا تُطِعْ مِنْهُمْ ءَاثِمًا أَوْ كَفُورًا", tafsir: `يا رسول الله في تبليغ القرآن ( لِحُكْمِ رَبِّكَ ) بأن تبلغ رسالاته في وسط هذا الموج العاتي من الإنكار والإيذاء والاستهزاء وَلا تُطِعْ مِنْهُمْ آثِماً أَوْ كَفُوراً (24) وَاذْكُرِ اسْمَ رَبِّكَ بُكْرَةً وَأَصِيلاً (25) وَمِنَ اللَّيْلِ فَاسْجُدْ لَهُ وَسَبِّحْهُ لَيْلاً طَوِيلاً (26) إِنَّ هؤُلاءِ يُح ِبُّونَ الْعاجِلَةَ وَيَذَرُونَ ( وَلا تُطِعْ مِنْهُمْ ) أي من هؤلاء ( آثِماً ) أي عاصيا ( أَوْ كَفُوراً ) أي كافرا ، يعني لا تطع الآثم في إثمه ولا الكفور في كفره ، بأن لا تبلغ الأصول أو الفروع إطاعة لها وجلبا لرضائها فقد ورد أن أبا جهل نهى الرسول عن الصلاة ، كما أن عتبة والوليد قالا له صلى‌الله‌عليه‌وآله‌وسلم : ارجع عن هذا الأمر ونحن نرضيك بالمال والتزويج (1) . والآية عامة تشمل كل كافر يأمر بالكفر وآثم يأمر بالإثم.` },
            { text: "وَٱذْكُرِ ٱسْمَ رَبِّكَ بُكْرَةً وَأَصِيلًا", tafsir: `يا رسول الله ( اسْمَ رَبِّكَ ) بالذكر والدعاء والصلاة ( بُكْرَةً ) أي صباحا ( وَأَصِيلاً ) أي عصرا ، يعني استمر على شأنك والدعاء إليه في طرفي النهار.` },
            { text: "وَمِنَ ٱلَّيْلِ فَٱسْجُدْ لَهُۥ وَسَبِّحْهُ لَيْلًا طَوِيلًا", tafsir: `أي بعض الليل ( فَاسْجُدْ لَهُ ) أي لله سبحانه والمراد بالسجود الصّلاة والعبادة ، أي اخضع لله سبحانه ( وَسَبِّحْهُ ) أي سبح الله ونزهه عما لا يليق به ( لَيْلاً طَوِيلاً ) فإن الليل ربيع العباد يتخذون طوله وسيلة للضراعة والاستكانة ، فإن الخواطر الكامنة لا تجيش إلا بطول الضراعة والابتهال. وقد ورد أن « بكرة » لصلاة الصبح و « أصيل » للظهرين و « اسجد له » للعشائين و « سبّحه » لصلاة الليل.` },
            { text: "إِنَّ هَٰٓؤُلَآءِ يُحِبُّونَ ٱلْعَاجِلَةَ وَيَذَرُونَ وَرَآءَهُمْ يَوْمًا ثَقِيلًا", tafsir: `الكفار الذين تراهم معرضين عن الله مقبلين على شهواتهم ( يُحِبُّونَ الْعاجِلَةَ ) أي الدنيا والشهوات العاجلة ( وَيَذَرُونَ ) ( 1) عين العبرة : ص 60. وَراءَهُمْ يَوْماً ثَقِيلاً (27) نَحْنُ خَلَقْناهُمْ وَشَدَدْنا أَسْرَهُمْ وَإِذا شِئْنا بَدَّلْنا أَمْثالَهُمْ تَبْدِيلاً (28) إِنَّ هذِهِ تَذْكِرَةٌ فَمَنْ شاءَ اتَّخَذَ إِلى رَبِّهِ سَبِيلاً (29) وَما تَشاؤُنَ إِلاَّ أَنْ يَشاءَ اللهُ إِنَّ اللهَ كانَ عَلِيماً حَكِيماً (30) أي يتركون ( وَراءَهُمْ ) في مستقبلهم ( يَوْماً ثَقِيلاً ) هو يوم القيامة الذي يثقل على الإنسان لما فيه من الأهوال والشدائد ، فلا يعملون لذلك اليوم. [29] إنهم يكفرون بالله الذي خلقهم وأعناقهم بيده ( نَحْنُ خَلَقْناهُمْ ) من العدم ( وَشَدَدْنا أَسْرَهُمْ ) أي أحكمنا خلقهم ، بتنظيم الأجهزة ، فإن « الأسر » أصله الشد ، ومنه سمي الأسير أسيرا ، لأنه يشد بالحبال ، فالمعنى أحكمنا شدهم في الخلقة ، بحيث لا ينفصم جزء من جزء ، بل الأجزاء كلها متماسكة مترابطة ( وَإِذا شِئْنا بَدَّلْنا أَمْثالَهُمْ ) مكانهم ( تَبْدِيلاً ) بأن أهلكنا هؤلاء وجئنا بدلهم مكانهم.` },
            { text: "نَّحْنُ خَلَقْنَٰهُمْ وَشَدَدْنَآ أَسْرَهُمْ وَإِذَا شِئْنَا بَدَّلْنَآ أَمْثَٰلَهُمْ تَبْدِيلًا", tafsir: `` },
            { text: "إِنَّ هَٰذِهِۦ تَذْكِرَةٌ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلًا", tafsir: `السورة ، أو هذه العظات والعبر المذكورة في القرآن ( تَذْكِرَةٌ ) تذكر الناس بما أودع في فطرتهم ، وإلفات لهم نحو الكون وآياته ( فَمَنْ شاءَ اتَّخَذَ إِلى رَبِّهِ سَبِيلاً ) أي مضى في طريق مرضاته سبحانه ، بعد ما رأى الحق ، وميّز بين الصدق والكذب.` },
            { text: "وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمًا", tafsir: `أنتم أيها البشر الإيمان والهداية ، ( إِلَّا أَنْ يَشاءَ اللهُ ) بأن يرسل الرسول ويوضح الطريق ، إذ الهداية لها طرفان : طرف من جانبه بنصب الأدلة ، وطرف من جانبكم بالاتباع والاهتداء ( إِنَّ اللهَ كانَ عَلِيماً ) بمصالحكم ( حَكِيماً ) فيما يفعل ، فإن الحكمة وضع يُدْخِلُ مَنْ يَشاءُ فِي رَحْمَتِهِ وَالظَّالِمِينَ أَعَدَّ لَهُمْ عَذاباً أَلِيماً (31) الأشياء موضعها ، والله لا يفعل شيئا إلا بالحكمة والمصلحة.` },
            { text: "يُدْخِلُ مَن يَشَآءُ فِى رَحْمَتِهِۦ وَٱلظَّٰلِمِينَ أَعَدَّ لَهُمْ عَذَابًا أَلِيمًۢا", tafsir: `` }
        ]
    },
    77: { // سورة المرسلات
        name: "المرسلات",
        basmalaTafsir: ``,
        verses: [
            { text: "وَٱلْمُرْسَلَٰتِ عُرْفًا", tafsir: `أي قسما بالملائكة التي أرسلت إرسالا ـ إلى الأرض ـ ( عُرْفاً ) أي في حال كونهم كعرف الفرس في تواليه وتتابعه ، وهو شعرها النابت على رقبتها.` },
            { text: "فَٱلْعَٰصِفَٰتِ عَصْفًا", tafsir: `أي ثم قسما بالملائكة التي تعصف عصف الرياح في امتثال أمره سبحانه ( عَصْفاً ) مصدر تأكيدي.` },
            { text: "وَٱلنَّٰشِرَٰتِ نَشْرًا", tafsir: `قسما ب ( النَّاشِراتِ ) أي الملائكة التي تنشر الكتب وتبسطها ، أو تنشر الآجال والأرزاق وما أمر الله بنشره ( نَشْراً ) مصدر تأكيدي ، وأن الإتيان ب « الواو » للتفنن الذي هو من أنواع البلاغة.` },
            { text: "فَٱلْفَٰرِقَٰتِ فَرْقًا", tafsir: `أي قسما بالملائكة التي تفرق بين الأشياء بأمر الله سبحانه ( فَرْقاً ) مصدر تأكيدي. [6] فقسما بالملائكة الملقيات ( ذِكْراً ) أي تلقي الذكر إلى الأنبياء عليهم‌السلام من قبل الله سبحانه.` },
            { text: "فَٱلْمُلْقِيَٰتِ ذِكْرًا", tafsir: `` },
            { text: "عُذْرًا أَوْ نُذْرًا", tafsir: `أي لأجل إعذار الله سبحانه ، وإنذاره للبشر على كفرهم وعصيانهم. [8] قسما بهؤلاء الطوائف من الملائكة ( إِنَّ ما تُوعَدُونَ ) من أحوال القيامة والجنة والنار ( لَواقِعٌ ) أي يقع لا محالة فلا خلف فيه. [9] ثم بين علامة القيامة بقوله : ( فَإِذَا النُّجُومُ طُمِسَتْ ) أي ذهب نورها وَإِذَا السَّماءُ فُرِجَتْ (9) وَإِذَا الْجِبالُ نُسِفَتْ (10) وَإِذَا الرُّسُلُ أُقِّتَتْ (11) لِأَيِّ يَوْمٍ أُجِّلَتْ (12) لِيَوْمِ الْفَصْلِ (13) وَما أَدْراكَ ما يَوْمُ الْفَصْلِ (14) وَيْلٌ يَوْمَئِذٍ لِلْمُكَذِّبِينَ (15) حتى صارت بلا ضياء أو نور.` },
            { text: "إِنَّمَا تُوعَدُونَ لَوَٰقِعٌ", tafsir: `` },
            { text: "فَإِذَا ٱلنُّجُومُ طُمِسَتْ", tafsir: `` },
            { text: "وَإِذَا ٱلسَّمَآءُ فُرِجَتْ", tafsir: `، أي شقت وصدعت فصار فيها فروج وشقوق ، لاختلال نظام المدارات.` },
            { text: "وَإِذَا ٱلْجِبَالُ نُسِفَتْ", tafsir: `أي قلعت من أماكنها ، وصارت كالهباء سائرة في الفضاء.` },
            { text: "وَإِذَا ٱلرُّسُلُ أُقِّتَتْ", tafsir: `أي جمعت لوقتها في القيامة لتشهد على الأمم ، وهو من الوقت ، وإنما تبدل الواو همزة لكراهة ضم الواو ـ كما قالوا ـ` },
            { text: "لِأَىِّ يَوْمٍ أُجِّلَتْ", tafsir: `هذا حكاية عن الحال ، أي أن الحالة تقتضي أن يقال فيها : لأي يوم أجلت وأخرت الرسل ؟ ولماذا يراد جمعهم وهذا تعظيم لليوم وتعجيب من هوله. [14] ويأتي الجواب ( لِيَوْمِ الْفَصْلِ ) الذي يفصل فيه بين أهل النار وأهل الجنة ، والسعداء والأشقياء.` },
            { text: "لِيَوْمِ ٱلْفَصْلِ", tafsir: `` },
            { text: "وَمَآ أَدْرَىٰكَ مَا يَوْمُ ٱلْفَصْلِ", tafsir: `أيها الإنسان ، أو يا رسول الله ( ما يَوْمُ الْفَصْلِ ) أي لا تدري أنت حقيقة هذا اليوم الهائل ، وهذا تعبير للتهويل والاستعظام.` },
            { text: "وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ", tafsir: `وهي كلمة تقال عند الهول والشدة المتوجهة على أحد ( يَوْمَئِذٍ ) أي في يوم القيامة ( لِلْمُكَذِّبِينَ ) الذين يكذبون بالله ورسوله والمعاد. أَ لَمْ نُهْلِكِ الْأَوَّلِينَ (16) ثُمَّ نُتْبِعُهُمُ الْآخِرِينَ (17) كَذلِكَ نَفْعَلُ بِالْمُجْرِمِينَ (18) وَيْلٌ يَوْمَئِذٍ لِلْمُكَذِّبِينَ (19) أَ لَمْ نَخْلُقْكُمْ مِنْ ماءٍ مَهِينٍ (20) فَجَعَلْناهُ فِي قَرارٍ مَكِينٍ (21) إِلى قَدَرٍ مَعْلُومٍ (22) [17] ثم يأتي السياق لإنذار المكذبين بأنهم في معرض العذاب في الدنيا قبل الآخرة ( أَ لَمْ نُهْلِكِ ) الأمم ( الْأَوَّلِينَ ) الذي كذبوا أنبياءهم ؟` },
            { text: "أَلَمْ نُهْلِكِ ٱلْأَوَّلِينَ", tafsir: `` },
            { text: "ثُمَّ نُتْبِعُهُمُ ٱلْـَٔاخِرِينَ", tafsir: `أي أتبعنا الأولين ب ( الْآخِرِينَ ) فأهلكنا الأمم الآخرين أيضا لما كذبوا الرسل ؟ والأولون كقوم نوح وعاد وثمود ، والآخرون كقوم لوط وفرعون وقومه.` },
            { text: "كَذَٰلِكَ نَفْعَلُ بِٱلْمُجْرِمِينَ", tafsir: `أي إهلاكا كإهلاك أولئك ( نَفْعَلُ بِالْمُجْرِمِينَ ) الذين أجرموا بالكفر والعصيان ، فإن العذاب ينزل بهم ، وهذا تهديد لكفار مكة.` },
            { text: "وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ", tafsir: `أي في يوم القيامة ( لِلْمُكَذِّبِينَ ) الذين يكذبون بالله وآياته وسائر الأصول. [21] ثم يأتي السياق لبيان جملة من نعم الله على البشر ليشكروه ، بعد ما هددهم ليخافوا منه ( أَ لَمْ نَخْلُقْكُمْ ) أيها البشر ( مِنْ ماءٍ مَهِينٍ ) أي النطفة التي هي « مهين » أي حقير ذليل ، من هان بمعنى ذلّ ؟` },
            { text: "أَلَمْ نَخْلُقكُّم مِّن مَّآءٍ مَّهِينٍ", tafsir: `` },
            { text: "فَجَعَلْنَٰهُ فِى قَرَارٍ مَّكِينٍ", tafsir: `أي جعلنا ذلك الماء بعد خروجه من الصلب والترائب ( فِي قَرارٍ ) أي مستقر ( مَكِينٍ ) أي مستحكم ، والمراد به الرحم.` },
            { text: "إِلَىٰ قَدَرٍ مَّعْلُومٍ", tafsir: `أي مقدار من الزمان معين ، وهو مدة الحمل. فَقَدَرْنا فَنِعْمَ الْقادِرُونَ (23) وَيْلٌ يَوْمَئِذٍ لِلْمُكَذِّبِينَ (24) أَ لَمْ نَجْعَلِ الْأَرْضَ كِفاتاً (25) أَحْياءً وَأَمْواتاً (26) وَجَعَلْنا فِيها رَواسِيَ شامِخاتٍ وَأَسْقَيْناكُمْ ماءً فُراتاً (27) وَيْلٌ يَوْمَئِذٍ لِلْمُكَذِّبِينَ (28) انْطَلِقُوا إِلى ما كُنْتُمْ بِهِ تُكَذِّبُونَ (29)` },
            { text: "فَقَدَرْنَا فَنِعْمَ ٱلْقَٰدِرُونَ", tafsir: `على ذلك ( فَنِعْمَ الْقادِرُونَ ) نحن إذ نقدر على كل شيء ، وبعد هذا هل ينكر الكافر قدرتنا على البعث وإعادة الأجسام بعد مماتها ؟` },
            { text: "وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ", tafsir: `أي في يوم القيامة ( لِلْمُكَذِّبِينَ ) وتكرار هذه الجملة للتركيز والإيحاء كما سبق في سورة « الرحمن » وغيرها.` },
            { text: "أَلَمْ نَجْعَلِ ٱلْأَرْضَ كِفَاتًا", tafsir: `يقال كفت الشيء : إذا ضمّه ، أي ضامة للعباد تكفتهم وتشمل عليهم.` },
            { text: "أَحْيَآءً وَأَمْوَٰتًا", tafsir: `فتشمل أحياءهم بالبناء والزرع وسائر لوازم الحياة ، وتشمل أمواتهم في بطنها.` },
            { text: "وَجَعَلْنَا فِيهَا رَوَٰسِىَ شَٰمِخَٰتٍ وَأَسْقَيْنَٰكُم مَّآءً فُرَاتًا", tafsir: `أي في الأرض ( رَواسِيَ ) جمع راسية ، وهي الجبل الشامخ ( شامِخاتٍ ) أي عاليات مرتفعات تحفظ الأرض عن التصدع والانهيار والتفرق في الهواء ( وَأَسْقَيْناكُمْ ) أيها البشر ( ماءً فُراتاً ) أي عذبا سائغا ؟ أ ليست كل هذه النعم شاهدة على إله واحد عالم قدير ؟ وأ ليست هذه النعم موجبة لإيمانكم بالله وتصديقكم لرسوله ؟` },
            { text: "وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ", tafsir: `أي في يوم القيامة ( لِلْمُكَذِّبِينَ ) بما جاء به الرسول صلى‌الله‌عليه‌وآله‌وسلم ، فإنهم يلقون عذابا ونكالا. [30] وإذا قامت القيامة يقال للمكذبين : ( انْطَلِقُوا إِلى ما كُنْتُمْ بِهِ تُكَذِّبُونَ ) انْطَلِقُوا إِلى ظِلٍّ ذِي ثَلاثِ شُعَبٍ (30) لا ظَلِيلٍ وَلا يُغْنِي مِنَ اللهَبِ (31) إِنَّها تَرْمِي بِشَرَرٍ كَالْقَصْرِ (32) كَأَنَّهُ جِمالَتٌ صُفْرٌ (33) وَيْلٌ يَوْمَئِذٍ لِلْمُكَذِّبِينَ (34) أي إلى النار التي كنتم تكذبون بها ، وتقولون أنها غير كائنة.` },
            { text: "ٱنطَلِقُوٓا۟ إِلَىٰ مَا كُنتُم بِهِۦ تُكَذِّبُونَ", tafsir: `` },
            { text: "ٱنطَلِقُوٓا۟ إِلَىٰ ظِلٍّ ذِى ثَلَٰثِ شُعَبٍ", tafsir: `أي اذهبوا أيها الكفار ( إِلى ظِلٍّ ذِي ثَلاثِ شُعَبٍ ) لعل المراد بالظل النار التي فوقها الدخان ، وكونه على ثلاث شعب لأنهم كانوا في الدنيا يطوفون بين الكفر والإيمان والنفاق ، وقيل : شعبة من فوقهم ، وشعبة من يمينهم ، وشعبة من يسارهم.` },
            { text: "لَّا ظَلِيلٍ وَلَا يُغْنِى مِنَ ٱللَّهَبِ", tafsir: `أي لا يظل صاحبه من الحر ( وَلا يُغْنِي مِنَ اللهَبِ ) أي من لهب النار ، وهو ما يعلوها باختلاط الهواء أحمر أو أصفر أو أزرق ، فإن هذا الظل ليس كظلال السقوف يمنع الهواء الحار ولهب النار ، كما أنهم كانوا يعيشون في الدنيا في ظل الكفر والعصيان.` },
            { text: "إِنَّهَا تَرْمِى بِشَرَرٍ كَٱلْقَصْرِ", tafsir: `أي النار ـ التي فهمت من قوله سبحانه ( ما كُنْتُمْ بِهِ تُكَذِّبُونَ ) (1) ـ ( تَرْمِي ) أي تطرح وتطير ( بِشَرَرٍ كَالْقَصْرِ ) الشرر هو ما يتطاير من النار لشدة الحرارة ، وخفة ذلك الشرر ، والقصر هو البيت الجميل من الحجارة ، أو أصل الشجر ، والأول أظهر ، والثاني أنسب.` },
            { text: "كَأَنَّهُۥ جِمَٰلَتٌ صُفْرٌ", tafsir: `أي الشرر المرمي ( جِمالَتٌ صُفْرٌ ) أي أن الشرارة كالجمل الأصفر في لونه ، بعد ما كان بقدر القصر في حجمه ، والتشبيه بالجمالة لتتابعها وتطايرها كالجمالات التي ترتع هنا وهناك ، ونارهن شررها كيف يكون أصلها ومحلها ؟` },
            { text: "وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ", tafsir: `أي يوم القيامة ( لِلْمُكَذِّبِينَ ) الذين يكذبون بهذه الأمور ( 1) المرسلات : 30. هذا يَوْمُ لا يَنْطِقُونَ (35) وَلا يُؤْذَنُ لَهُمْ فَيَعْتَذِرُونَ (36) وَيْلٌ يَوْمَئِذٍ لِلْمُكَذِّبِينَ (37) هذا يَوْمُ الْفَصْلِ جَمَعْناكُمْ وَالْأَوَّلِينَ (38) فَإِنْ كانَ لَكُمْ كَيْدٌ فَكِيدُونِ (39) وَيْلٌ يَوْمَئِذٍ كيف يلقون في النار ، ويقاسون العذاب والنكال ؟` },
            { text: "هَٰذَا يَوْمُ لَا يَنطِقُونَ", tafsir: `أي المجرمون من شدة الهول والفزع.` },
            { text: "وَلَا يُؤْذَنُ لَهُمْ فَيَعْتَذِرُونَ", tafsir: `في الكلام ( فَيَعْتَذِرُونَ ) عن سالف أعمالهم وهذا إنما يكون في موقف من مواقف القيامة ، وفي موقف آخر يتكلمون ويعتذرون ، فللقيامة خمسون موقفا كل موقف يطول ألف سنة ـ كما ورد (1) .` },
            { text: "وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ", tafsir: `أي في هذا اليوم ( لِلْمُكَذِّبِينَ ) الذين كذبوا بالله وبما أرسل. [39] ثم يقال لهم : ( هذا يَوْمُ الْفَصْلِ ) الذي يفصل فيه بين المحسنين والمجرمين ، ويدخل كل إلى محله الذي هيأه لنفسه ( جَمَعْناكُمْ ) أيها الكفار ( وَالْأَوَّلِينَ ) أي مع المكذبين الأولين السابقين عليكم من سائر الأمم.` },
            { text: "هَٰذَا يَوْمُ ٱلْفَصْلِ جَمَعْنَٰكُمْ وَٱلْأَوَّلِينَ", tafsir: `` },
            { text: "فَإِن كَانَ لَكُمْ كَيْدٌ فَكِيدُونِ", tafsir: `في خلاصكم من العقاب ( فَكِيدُونِ ) أي احتالوا وكيدوا لإنجاء أنفسكم ، وهذا استهزاء بهم وتقريع لهم ، فقد كانوا يكيدون للمؤمنين في الدنيا ، فليكيدوا هنا إن كان لهم كيد وحيلة.` },
            { text: "وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ", tafsir: `أي في يوم القيامة ، وأصله يوم إذ كان كذا ، حذفت ( 1) مستدرك وسائل الشيعة : ج 12 ص 155. لِلْمُكَذِّبِينَ (40) إِنَّ الْمُتَّقِينَ فِي ظِلالٍ وَعُيُونٍ (41) وَفَواكِهَ مِمَّا يَشْتَهُونَ (42) كُلُوا وَاشْرَبُوا هَنِيئاً بِما كُنْتُمْ تَعْمَلُونَ (43) إِنَّا كَذلِكَ نَجْزِي الْمُحْسِنِينَ (44) وَيْلٌ يَوْمَئِذٍ لِلْمُكَذِّبِينَ (45) كُلُوا الجملة وقام التنوين مقامها ( لِلْمُكَذِّبِينَ ) بهذا اليوم وبسائر ما جاء به الرسل. [42] وإذا رأينا مقام الكفار ، فلننظر إلى مقام الأخيار ( إِنَّ الْمُتَّقِينَ ) الذين اتقوا الكفر والمعاصي ( فِي ظِلالٍ ) من أشجار الجنة ، وظلال قصورها ( وَعُيُونٍ ) أي أنهم في أرض بين العيون ، أو المراد أنهم يسبحون ويستحمون في نفس العيون.` },
            { text: "إِنَّ ٱلْمُتَّقِينَ فِى ظِلَٰلٍ وَعُيُونٍ", tafsir: `` },
            { text: "وَفَوَٰكِهَ مِمَّا يَشْتَهُونَ", tafsir: `في ( فَواكِهَ ) جمع فاكهة ، وهي الثمرة أي أن الثمار تحيط من كل جوانبهم ( مِمَّا يَشْتَهُونَ ) أي من الأجناس التي يميلون إليها. [44] ويقال لهم : ( كُلُوا ) من الثمار ( وَاشْرَبُوا ) من العيون ، والمراد بالأمر الإباحة ، من قبيل ( وَإِذا حَلَلْتُمْ فَاصْطادُوا ) (1) ( هَنِيئاً ) أي أكلا وشربا خاليا من الأذى ، فإن الهنيء هو النفع الخالص من شائب الأذى ( بِما كُنْتُمْ تَعْمَلُونَ ) أي بمقابل أعمالكم الصالحة في الدنيا.` },
            { text: "كُلُوا۟ وَٱشْرَبُوا۟ هَنِيٓـًٔۢا بِمَا كُنتُمْ تَعْمَلُونَ", tafsir: `` },
            { text: "إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ", tafsir: `أي كالذي ذكرنا من الإنعام والإفضال ( نَجْزِي الْمُحْسِنِينَ ) الذين أحسنوا بالإيمان والعمل الصالح.` },
            { text: "وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ", tafsir: `كيف يرون أن هذه النعم أفلتت من أيديهم بسبب أعمالهم الفاسدة في الدنيا ، وكم يتحسرون لذلك. [47] ثم يأتي السياق ليخاطب المجرمين ـ في الدنيا ـ ( كُلُوا ) أيها الكفار ( 1) المائدة : 3. وَتَمَتَّعُوا قَلِيلاً إِنَّكُمْ مُجْرِمُونَ (46) وَيْلٌ يَوْمَئِذٍ لِلْمُكَذِّبِينَ (47) وَإِذا قِيلَ لَهُمُ ارْكَعُوا لا يَرْكَعُونَ (48) وَيْلٌ يَوْمَئِذٍ لِلْمُكَذِّبِينَ (49) فَبِأَيِّ حَدِيثٍ بَعْدَهُ يُؤْمِنُونَ (50) ( وَتَمَتَّعُوا ) بمتاع الحياة الدنيا ( قَلِيلاً ) فإن أمد الدنيا قصير ( إِنَّكُمْ مُجْرِمُونَ ) وهل من فائدة للأكل والتمتع القليل لمن وراؤه عذاب شديد ؟` },
            { text: "كُلُوا۟ وَتَمَتَّعُوا۟ قَلِيلًا إِنَّكُم مُّجْرِمُونَ", tafsir: `` },
            { text: "وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ", tafsir: `أي في يوم القيامة ( لِلْمُكَذِّبِينَ ) الذين كذبوا بالله وبما جاء من عنده.` },
            { text: "وَإِذَا قِيلَ لَهُمُ ٱرْكَعُوا۟ لَا يَرْكَعُونَ", tafsir: `أي للمكذبين ( ارْكَعُوا ) واخضعوا لله سبحانه ، فإن المراد بالركوع إما مطلق الخضوع ، أو الركوع كناية عن الصّلاة ( لا يَرْكَعُونَ ) عنادا واستكبارا. روى أنها نزلت في وفد ثقيف حين أمرهم رسول الله صلى‌الله‌عليه‌وآله‌وسلم بالصلاة فقالوا : لا ننحني فإن ذلك مسبة علينا ، فقال صلى‌الله‌عليه‌وآله‌وسلم : لا خير في دين ليس فيه ركوع وسجود (1) . أقول : المراد ب « لا نحني » أي لا نعطف ظهورنا ، فقد استقبحوا رفع عجيزتهم.` },
            { text: "وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ", tafsir: `الذين كذبوا بالأحكام ، ولم يصدقوا بالركوع وسائر العبادات ، فإنهم يلاقون جزاء ذلك.` },
            { text: "فَبِأَىِّ حَدِيثٍۭ بَعْدَهُۥ يُؤْمِنُونَ", tafsir: `` }
        ]
    },
    78: { // سورة النبأ
        name: "النبأ",
        basmalaTafsir: ``,
        verses: [
            { text: "عَمَّ يَتَسَآءَلُونَ", tafsir: `أصله « عن ما » مركبة من « عن » الجارة و « ما » الاستفهامية ، ثم أدغمت النون في الميم لقرب مخرجهما ، وحذفت الألف من « ما » على ما هي القاعدة من حذفها مطلقا إذا دخل على « ما » حرف الجر ، فيقال « بم ، ولم ، وعم » وهكذا. والمعنى عما ذا يتساءل الكفار بعضهم عن بعض ، فقد قال في المجمع قالوا : لما بعث رسول الله وأخبرهم بتوحيد الله تعالى وبالبعث بعد الموت وتلا عليهم القرآن جعلوا يتساءلون بينهم ـ أي يسأل بعضهم بعضا على طريق الإنكار والتعجب ـ فيقولون : ماذا جاء به محمد صلى‌الله‌عليه‌وآله‌وسلم وما الذي أتى به ؟ فأنزل الله تعالى « عم يتساءلون » (1) . أقول : والمراد بالاستفهام التفخيم ، كما تقول : أية قصة هذه ؟ إذا أردت تفخيمها ، وورد في جملة من الأحاديث : أن المراد بالنبإ العظيم الإمام أمير المؤمنين عليه‌السلام (2) ، وهذا من باب المصداق ـ إن أريد بالآية الأعم ، ومن باب البطون إن أريد بها القيامة فقط. [3] ثم جاء الجواب ( عَنِ النَّبَإِ الْعَظِيمِ ) أي الخبر المهم ، وهو ما يتعلق بالمبدأ والمعاد.` },
            { text: "عَنِ ٱلنَّبَإِ ٱلْعَظِيمِ", tafsir: `` },
            { text: "ٱلَّذِى هُمْ فِيهِ مُخْتَلِفُونَ", tafsir: `أي النبأ الذي ( هُمْ ) أي هؤلاء الكفار ( فِيهِ ) أي في ذلك النبأ ( مُخْتَلِفُونَ ) فمن مصدق له باعتبار كونه من أهل الكتاب أو من أشبههم ، ومن مكذب له. ( 1) مجمع البيان : ج 10 ص 239. ( 2) الكافي : ج 1 ص 207. كَلاَّ سَيَعْلَمُونَ (4) ثُمَّ كَلاَّ سَيَعْلَمُونَ (5) أَ لَمْ نَجْعَلِ الْأَرْضَ مِهاداً (6) وَالْجِبالَ أَوْتاداً (7) وَخَلَقْناكُمْ أَزْواجاً (8) وَجَعَلْنا نَوْمَكُمْ سُباتاً (9)` },
            { text: "كَلَّا سَيَعْلَمُونَ", tafsir: `ليس الأمر كما قالوا وزعموا ، حيث أنكروا التوحيد والرسالة والمعاد ( سَيَعْلَمُونَ ) عاقبة تكذيبهم وصدق الرسول صلى‌الله‌عليه‌وآله‌وسلم .` },
            { text: "ثُمَّ كَلَّا سَيَعْلَمُونَ", tafsir: `لترتيب الكلام ( كَلَّا ) ليس الأمر كما زعموا ( سَيَعْلَمُونَ ) عند موتهم أو في يوم القيامة : إن الأمر كان كما أخبر الرسول ، وإنهم كانوا في ضلال وانحراف ، وهذا تهديد بعقب تهديد. [7] ثم جاء السياق ليذكر طرفا من نعمه سبحانه الدالة على وجوده وسائر صفاته ، حجة على المنكرين : ( أَ لَمْ نَجْعَلِ الْأَرْضَ مِهاداً ) ؟ أي وطاء وقرارا مهيّأ للتصرف ، كالمهد الذي يستقر فيه الطفل من غير أذية.` },
            { text: "أَلَمْ نَجْعَلِ ٱلْأَرْضَ مِهَٰدًا", tafsir: `` },
            { text: "وَٱلْجِبَالَ أَوْتَادًا", tafsir: `ألم نجعل ( الْجِبالَ أَوْتاداً ) جمع « وتد » وهو « المسمار » أي مسامير للأرض حتى لا تتشقق ولا تتبعثر في الهواء من جراء الحركة والجاذبيات ، كالوتد الذي يربط بعض ألواح الخشب ببعض حتى لا تنفصم.` },
            { text: "وَخَلَقْنَٰكُمْ أَزْوَٰجًا", tafsir: `أيها البشر ( أَزْواجاً ) جمع « زوج » ، وهو الصنف ، أي أصنافا وأشكالا ، باختلاف ألوانكم ، وألسنتكم ، ومدارككم إلى غير ذلك من الاختلافات.` },
            { text: "وَجَعَلْنَا نَوْمَكُمْ سُبَاتًا", tafsir: `أيها البشر ( سُباتاً ) أي قاطعا للعمل لأجل الاستراحة ، ومنه سبت أنفه : إذا قطعه ، فمن يا ترى جعل هذه الأمور غير الله سبحانه ؟! وَجَعَلْنَا اللَّيْلَ لِباساً (10) وَجَعَلْنَا النَّهارَ مَعاشاً (11) وَبَنَيْنا فَوْقَكُمْ سَبْعاً شِداداً (12) وَجَعَلْنا سِراجاً وَهَّاجاً (13) وَأَنْزَلْنا مِنَ الْمُعْصِراتِ ماءً ثَجَّاجاً (14)` },
            { text: "وَجَعَلْنَا ٱلَّيْلَ لِبَاسًا", tafsir: `أي غطاء وسترة يستر كل شيء كما يستر اللباس البدن ، وذلك لحكمة الاستراحة والانصراف عن العمل ، فإن الليل لو كان مثل النهار لم يهدأ الإنسان ولم يهنأ بالراحة ، بالإضافة إلى أن ظلمة الليل تساعد على الراحة والنوم ـ كما قالت الأطباء ـ .` },
            { text: "وَجَعَلْنَا ٱلنَّهَارَ مَعَاشًا", tafsir: `المعاش هو العيش ، أي وقت العيش تتقلبون فيه لتحصيل أسباب العيش والبقاء ، وهذا من الإسناد المجازي ، فإن النهار زمان العيش لا نفسه.` },
            { text: "وَبَنَيْنَا فَوْقَكُمْ سَبْعًا شِدَادًا", tafsir: `أي خلقنا وصنعنا فوقكم أيها البشر ( سَبْعاً ) أي سبع سماوات ، والمراد بها مدارات الكواكب السيارة ، أو ما أشبه ( شِداداً ) جمع « شديد » أي محكمة الصنع متقنة الأسلوب والنظام.` },
            { text: "وَجَعَلْنَا سِرَاجًا وَهَّاجًا", tafsir: `في السماوات ( سِراجاً ) أي مصباحا ، والمراد به الشمس ( وَهَّاجاً ) أي وقادا متلألأ بالنور ، من « وهج » بمعنى أنار وأضاء.` },
            { text: "وَأَنزَلْنَا مِنَ ٱلْمُعْصِرَٰتِ مَآءً ثَجَّاجًا", tafsir: `بصيغة اسم الفاعل ، والمراد بها السحائب ، فإنها تعصر نفسها ، بما أودع فيها من الطاقات العاصرة حتى تمطر ، كالغسالة التي تعصر الثوب حتى تخرج قطرات الماء منه. أو المراد بالمعصرات الرياح التي تعصر السحائب ، ومعنى « من » نشوية ( ماءً ثَجَّاجاً ) أي صبابا دفاعا في الصبابة ، من « ثج » بمعنى انصب بكثرة ، والمراد المطر الكثير الانصباب. لِنُخْرِجَ بِهِ حَبًّا وَنَباتاً (15) وَجَنَّاتٍ أَلْفافاً (16) إِنَّ يَوْمَ الْفَصْلِ كانَ مِيقاتاً (17) يَوْمَ يُنْفَخُ فِي الصُّورِ فَتَأْتُونَ أَفْواجاً (18) وَفُتِحَتِ السَّماءُ فَكانَتْ أَبْواباً (19) [16] وإنّا أنزلنا المطر ( لِنُخْرِجَ بِهِ ) أي بواسطة ماء المطر ( حَبًّا ) كالحنطة ونحوها ( وَنَباتاً ) كل ما ينبت من أنواع المزروعات.` },
            { text: "لِّنُخْرِجَ بِهِۦ حَبًّا وَنَبَاتًا", tafsir: `` },
            { text: "وَجَنَّٰتٍ أَلْفَافًا", tafsir: `نخرج به ( جَنَّاتٍ ) أي بساتين ( أَلْفافاً ) أي ملتفة الشجر ، وهو جمع « لف » يراد به الشجر الملتف بعضه ببعض ، ويسمى البستان « جنة » لتسترها بالأشجار. [18] ثم يأتي السياق لبيان المعاد ، بعد ما ذكر جملة من أدلة الألوهية ( إِنَّ يَوْمَ الْفَصْلِ ) الذي يفصل فيه بين الخلائق ، ليجزي كل إنسان بما عمل من خير وشر ، وهو يوم القيامة ( كانَ مِيقاتاً ) أي وقتا وزمانا لما وعد الله سبحانه من الحساب والجزاء ، فإن « الميقات » يستعمل بمعنى الزمان وبمعنى المكان ـ كمواقيت الحج ـ . [19] ثم بين ذلك بقوله : ( يَوْمَ ) بدل من « يوم الفصل » ( يُنْفَخُ فِي الصُّورِ ) أي البوق ، ينفخ فيه إسرافيل لحشر الخلائق وحياتهم بعد الموت ، كما ينفخ النافخ في البوق لحركة القافلة أو الجيش أو من أشبه ، وهذه هي النفخة الثانية ( فَتَأْتُونَ ) أيها البشر من قبوركم أحياء ( أَفْواجاً ) جمع « فوج » ، أي جماعات جماعات ، كأن كل جماعة تشتمل على المشاكلين في العمل.` },
            { text: "إِنَّ يَوْمَ ٱلْفَصْلِ كَانَ مِيقَٰتًا", tafsir: `` },
            { text: "يَوْمَ يُنفَخُ فِى ٱلصُّورِ فَتَأْتُونَ أَفْوَاجًا", tafsir: `` },
            { text: "وَفُتِحَتِ ٱلسَّمَآءُ فَكَانَتْ أَبْوَٰبًا", tafsir: `أي انشقت وظهرت فيها أبواب ( فَكانَتْ ) السماء ( أَبْواباً ) فإن كلما تتبدل بشكل أبواب تنزل الملائكة منها للحساب وَسُيِّرَتِ الْجِبالُ فَكانَتْ سَراباً (20) إِنَّ جَهَنَّمَ كانَتْ مِرْصاداً (21) لِلطَّاغِينَ مَآباً (22) لابِثِينَ فِيها أَحْقاباً (23) والجزاء وإطاعة الأوامر.` },
            { text: "وَسُيِّرَتِ ٱلْجِبَالُ فَكَانَتْ سَرَابًا", tafsir: `أي سارت عن أماكنها بعد أن انقلعت وإنما يسيرها الله سبحانه ( فَكانَتْ ) الجبال ( سَراباً ) أي كالسراب ـ الذي هو خيال الماء في الصحراء وقت الظهيرة ـ فإن الجبال إذا رآها الإنسان حسبها جامدة كسابقها ، بينما هي صارت كالهباء ، ترى شيئا جامدا وليس بجامد ، كالضباب الذي يحسبه البعيد شيئا وليس بشيء.` },
            { text: "إِنَّ جَهَنَّمَ كَانَتْ مِرْصَادًا", tafsir: `كالمحل الذي يرصد فيه لحفظ الدار أو البستان أو ما أشبه ، فإنها محل لرصد الملائكة للناس ، حيث يرون منها أيّ إنسان يجرم حتى يستحق النار ، وأيّا يحسن حتى لا يستحقها فإن « المرصاد » هو المكان الذي يراقب فيه العدو.` },
            { text: "لِّلطَّٰغِينَ مَـَٔابًا", tafsir: `أي الذين طغوا وجاوزوا حدود الله سبحانه ( مَآباً ) من « آب » بمعنى رجع ، والمراد به المنزل ، ويسمى المنزل « مآبا » لأن الإنسان كلما خرج منه رجع إليه.` },
            { text: "لَّٰبِثِينَ فِيهَآ أَحْقَابًا", tafsir: `من « لبث » بمعنى بقي ، أي يبقى الطاغون ( فِيها ) أي في جهنم ( أَحْقاباً ) جمع « حقب » على وزن عرف ، وهو جمع « حقبة » ، والمراد بها الزمان الطويل ، أي يمكثون في جهنم دهورا طويلة. وقد روي عن الإمام الصادق عليه‌السلام أنه قال : الأحقاب ثمانية حقب ، والحقب ثمانون سنة ، والسنة ثلاثمائة وستون يوما ، واليوم ( كَأَلْفِ سَنَةٍ لا يَذُوقُونَ فِيها بَرْداً وَلا شَراباً (24) إِلاَّ حَمِيماً وَغَسَّاقاً (25) جَزاءً وِفاقاً (26) إِنَّهُمْ كانُوا لا يَرْجُونَ حِساباً (27) وَكَذَّبُوا بِآياتِنا كِذَّاباً (28) مِمَّا تَعُدُّونَ ) (1) (2) أقول : أما المعاند من أهل الباطل فلا مخرج له منها. وأما العصاة فإنهم يخرجون بعد أزمنة طويلة ـ حسب اختلاف عصيانهم ـ .` },
            { text: "لَّا يَذُوقُونَ فِيهَا بَرْدًا وَلَا شَرَابًا", tafsir: `أي في جهنم ( بَرْداً وَلا شَراباً ) فلا هواء بارد ، ولا طعام بارد ، ولا شيء بارد لهم هناك ، ولا شراب يشربون ليروى عطشهم المتزايد.` },
            { text: "إِلَّا حَمِيمًا وَغَسَّاقًا", tafsir: `وهو الماء الحار المغلي ( وَغَسَّاقاً ) وهو صديد أهل النار ، والاستثناء منقطع ، أي لا يذوقون إلا الحميم والغساق أما البرد والشراب فليس لهم ، أو متصل بقوله « شرابا » . [27] وإنما يجزون بذلك ( جَزاءً ) على كفرهم وعصيانهم ( وِفاقاً ) أي وفق أعمالهم وبقدرها. [28] ثم يأتي البيان ليبين أعمالهم التي استحقوا بها هذا العذاب : ( إِنَّهُمْ كانُوا ) في الدنيا ( لا يَرْجُونَ حِساباً ) أي لم يكونوا يتوقعون القيامة ، بل كانوا يكذّبون بها ، وكأن لفظة « لا يرجون » باعتبار أن كل متوقع لشيء إنما يحتمل النجاح فيه.` },
            { text: "جَزَآءً وِفَاقًا", tafsir: `` },
            { text: "إِنَّهُمْ كَانُوا۟ لَا يَرْجُونَ حِسَابًا", tafsir: `` },
            { text: "وَكَذَّبُوا۟ بِـَٔايَٰتِنَا كِذَّابًا", tafsir: `التي أقمناها على المبدأ والرسالة والمعاد ( كِذَّاباً ) أي تكذيبا ، فلم يكونوا يقبلون الآيات الدالة على الألوهية والرسالة والمعاد. ( 1) معاني الأخبار : ص 220. ( 2) الحج : 48. وَكُلَّ شَيْءٍ أَحْصَيْناهُ كِتاباً (29) فَذُوقُوا فَلَنْ نَزِيدَكُمْ إِلاَّ عَذاباً (30) إِنَّ لِلْمُتَّقِينَ مَفازاً (31) حَدائِقَ وَأَعْناباً (32) وَكَواعِبَ أَتْراباً (33) [30] وهل زعم هؤلاء أن أعمالهم الباطلة لا تأخذهم ؟ ( وَكُلَّ شَيْءٍ أَحْصَيْناهُ ) أي جميع ما عملوه جمعناه وعددناه وبيناه ، ( كِتاباً ) أي إحصاء في الكتاب لا بالقول فقط. [31] وهناك يقال لهم : ( فَذُوقُوا ) هذا العذاب والنكال جزاء على أعمالكم الباطلة ( فَلَنْ نَزِيدَكُمْ إِلَّا عَذاباً ) فليس الأمر محتمل النقص والانقطاع ، بل تزدادون عذابا ونكالا كل يوم وساعة ، وذلك باعتبار أن كل يوم يضاف عذاب ذلك اليوم على الأيام السابقة ـ وإن كان بقدرة في الكيفية ـ . [32] وإذا عرفنا أحوال المجرمين في الآخرة فلنتعرف بالمؤمنين ( إِنَّ لِلْمُتَّقِينَ مَفازاً ) مصدر ميمي ، أي أن لهم فوزا وفلاحا « والمتقي » هو المؤمن الذي يتقي الله فلا يذنب.` },
            { text: "وَكُلَّ شَىْءٍ أَحْصَيْنَٰهُ كِتَٰبًا", tafsir: `` },
            { text: "فَذُوقُوا۟ فَلَن نَّزِيدَكُمْ إِلَّا عَذَابًا", tafsir: `` },
            { text: "إِنَّ لِلْمُتَّقِينَ مَفَازًا", tafsir: `` },
            { text: "حَدَآئِقَ وَأَعْنَٰبًا", tafsir: `بدل من « مفاز » جمع حديقة وهي البستان الصغير المنظم ، أو هي الجنة المحوطة بالسور وإن كانت كبيرة ، من « حدق » بمعنى أحاط ( وَأَعْناباً ) جمع « عنب » خصّ بالذكر مثالا ، ولكثرة الالتذاذ به.` },
            { text: "وَكَوَاعِبَ أَتْرَابًا", tafsir: `جمع « كاعبة » ، وهي المرأة التي استدار ثديها لكونها في أول زمان رشدها ( أَتْراباً ) جمع « ترب » ، عمر الواحدة بعمر الأخرى كأنهم أتراب بعضهن لبعض ، أو بعضهن مع أزواجهن ، فليس عمر إحداهن أقل من عمر الزوج أو أكثر ، ليرى العنت والصعوبة في معاشرتها. وَكَأْساً دِهاقاً (34) لا يَسْمَعُونَ فِيها لَغْواً وَلا كِذَّاباً (35) جَزاءً مِنْ رَبِّكَ عَطاءً حِساباً (36) رَبِّ السَّماواتِ وَالْأَرْضِ وَما بَيْنَهُمَا الرَّحْمنِ لا يَمْلِكُونَ مِنْهُ خِطاباً (37) يَوْمَ يَقُومُ الرُّوحُ وَالْمَلائِكَةُ صَفًّا` },
            { text: "وَكَأْسًا دِهَاقًا", tafsir: `وهو إناء الشراب ( دِهاقاً ) أي مملوءة ، من « الدهق » بمعنى شدة الضغط ، كأنه لا مجال فيها للماء أو الشراب بعد ذلك.` },
            { text: "لَّا يَسْمَعُونَ فِيهَا لَغْوًا وَلَا كِذَّٰبًا", tafsir: `أي المتقون ( فِيها ) أي في الجنة كلاما ( لَغْواً ) لا فائدة فيه ( وَلا كِذَّاباً ) أي تكذيبا من بعضهم لبعض. [37] وإنما يكون المتقون في هذا النعيم الأبدي ( جَزاءً مِنْ رَبِّكَ ) يا رسول الله لهم ، على أعمالهم الحسنة في الدنيا ، في حال كون ذلك الجزاء ( عَطاءً حِساباً ) أي عطاء بالحساب ، فليس الأمر اعتباطا. [38] ثم بين ربك بما يدل على عظمته سبحانه بقوله : ( رَبِّ السَّماواتِ وَالْأَرْضِ وَما بَيْنَهُمَا ) فكل شيء له خلقا وتربية ( الرَّحْمنِ ) وجيء بهذا الوصف للدلالة على أنه سبحانه رحيم بعباده يتفضل عليهم بالمغفرة والرحمة ، وأنهم إنما استحقوا الثواب برحمته لا بأعمالهم ( لا يَمْلِكُونَ ) أي البشر ( مِنْهُ ) تعالى ( خِطاباً ) فلا يقدر أحد أن يكلم الله سبحانه أو يشفع لأحد إلا بإذنه ، فهو رحيم ذو هيبة وجلال ، وليس كرحيم الدنيا الذي إذا عطف قلبه على أحد يمكن التسلط عليه للين قلبه. [39] ثم بين معنى ( لا يَمْلِكُونَ مِنْهُ خِطاباً ) بقوله : ( يَوْمَ يَقُومُ الرُّوحُ ) وهو ملك عظيم كما ورد في الأحاديث (1) ( وَالْمَلائِكَةُ صَفًّا ) كما يصطف ( 1) راجع مجمع البيان : ج 10 ص 247. لا يَتَكَلَّمُونَ إِلاَّ مَنْ أَذِنَ لَهُ الرَّحْمنُ وَقالَ صَواباً (38) ذلِكَ الْيَوْمُ الْحَقُّ فَمَنْ شاءَ اتَّخَذَ إِلى رَبِّهِ مَآباً (39) إِنَّا أَنْذَرْناكُمْ عَذاباً قَرِيباً يَوْمَ يَنْظُرُ الْمَرْءُ ما قَدَّمَتْ الجيش أمام الملك ، وذلك مما يزيد القيامة هيبة وهولا ( لا يَتَكَلَّمُونَ ) أي أولئك الملائكة والروح ، أو أيّ متكلم ( إِلَّا مَنْ أَذِنَ لَهُ الرَّحْمنُ ) بالكلام ، في أي شأن من الشؤون ( وَقالَ صَواباً ) وكأن هذا في بعض المواقف ، وفي بعض المواقف الأخر يتكلم كل أحد بما يريد من صدق وكذب كما قال سبحانه : ( انْظُرْ كَيْفَ كَذَبُوا عَلى أَنْفُسِهِمْ ) (1) أو المراد بالتكلم ـ الشفاعة ـ .` },
            { text: "جَزَآءً مِّن رَّبِّكَ عَطَآءً حِسَابًا", tafsir: `` },
            { text: "رَّبِّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ٱلرَّحْمَٰنِ لَا يَمْلِكُونَ مِنْهُ خِطَابًا", tafsir: `` },
            { text: "يَوْمَ يَقُومُ ٱلرُّوحُ وَٱلْمَلَٰٓئِكَةُ صَفًّا لَّا يَتَكَلَّمُونَ إِلَّا مَنْ أَذِنَ لَهُ ٱلرَّحْمَٰنُ وَقَالَ صَوَابًا", tafsir: `` },
            { text: "ذَٰلِكَ ٱلْيَوْمُ ٱلْحَقُّ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ مَـَٔابًا", tafsir: `الذي وصف هو اليوم ( الْحَقُ ) الكائن لا محالة ، فلا كذب في الإخبار به. قالوا : إذا طابق الخبر الواقع فباعتبار كونه مطابقا للواقع يسمى صدقا ، وباعتبار مطابقة الواقع له يسمى حقا ( فَمَنْ شاءَ ) منكم أيها الناس ( اتَّخَذَ إِلى رَبِّهِ ) أي إلى رضاه وثوابه ( مَآباً ) ، بالإيمان والطاعة ، كأن المؤمن اتخذ إلى ربه مآبا ، والكافر اتخذ إلى ربه غيره مآبا ، حيث يبتعد عن لطفه ورحمته بسبب الكفر والعصيان فليس مآبه إليه.` },
            { text: "إِنَّآ أَنذَرْنَٰكُمْ عَذَابًا قَرِيبًا يَوْمَ يَنظُرُ ٱلْمَرْءُ مَا قَدَّمَتْ يَدَاهُ وَيَقُولُ ٱلْكَافِرُ يَٰلَيْتَنِى كُنتُ تُرَٰبًۢا", tafsir: `` }
        ]
    },
    79: { // سورة النازعات
        name: "النازعات",
        basmalaTafsir: ``,
        verses: [
            { text: "وَٱلنَّٰزِعَٰتِ غَرْقًا", tafsir: `أي قسما بالنازعات ، وهي الملائكة التي تنزع أرواح الكفار عن أبدانهم بشدة ( غَرْقاً ) أي إغراقا في النزع ، كما يغرق النازع في القوس فيبلغ به غاية مدّ الوتر.` },
            { text: "وَٱلنَّٰشِطَٰتِ نَشْطًا", tafsir: `أي قسما بالملائكة الناشطات التي تنشط في قبض أرواح الكفار نشاطا ، أو تنشط في الذهاب بأرواحهم نحو الهاوية بعد نزعها.` },
            { text: "وَٱلسَّٰبِحَٰتِ سَبْحًا", tafsir: `أي قسما بالملائكة التي تسبح في الفضاء بعد قبض الأرواح ، و « السبح » هي الحركة بسهولة كحركة السابح في الماء ( سَبْحاً ) مصدر تأكيدي. و روي : أن المراد بذلك الملائكة التي تقبض أرواح المؤمنين يسلّونها سلّا رقيقا.` },
            { text: "فَٱلسَّٰبِقَٰتِ سَبْقًا", tafsir: `أي قسما بالملائكة التي تسبق بالأرواح ـ أو بأرواح المؤمنين ـ نحو الملأ الأعلى ، والإتيان بالفاء هنا وبالواو قبله للتفنن في الكلام الذي هو نوع من البلاغة.` },
            { text: "فَٱلْمُدَبِّرَٰتِ أَمْرًا", tafsir: `أي قسما بالملائكة التي تدبر الأمور بإذن الله سبحانه. [7] قسما بأولئك الطوائف من الملائكة أن ما يأتي من أهوال القيامة وأخبار الجنة والنار صدق مطابق للواقع. وقد حذف هذا في الكلام لدلالة الآيات التالية عليه ، أذكر يا رسول الله ( يَوْمَ تَرْجُفُ ) أي تتحرك وتضطرب ( الرَّاجِفَةُ ) أي الأرض ، كما قال سبحانه ( يَوْمَ تَرْجُفُ تَتْبَعُهَا الرَّادِفَةُ (7) قُلُوبٌ يَوْمَئِذٍ واجِفَةٌ (8) أَبْصارُها خاشِعَةٌ (9) يَقُولُونَ أَ إِنَّا لَمَرْدُودُونَ فِي الْحافِرَةِ (10) أَ إِذا كُنَّا عِظاماً نَخِرَةً (11) الْأَرْضُ وَالْجِبالُ ) (1) .` },
            { text: "يَوْمَ تَرْجُفُ ٱلرَّاجِفَةُ", tafsir: `` },
            { text: "تَتْبَعُهَا ٱلرَّادِفَةُ", tafsir: `أي تتبع رجفة الأرض ( الرَّادِفَةُ ) أي التي تردف وتتبع الأرض في اختلال النظام والاضطراب ، وهي السماء ، أو المراد بالراجفة النفخة الأولى ، وبالرادفة النفخة الثانية.` },
            { text: "قُلُوبٌ يَوْمَئِذٍ وَاجِفَةٌ", tafsir: `أي في هذا اليوم ، وهو يوم القيامة ( واجِفَةٌ ) أي شديدة الاضطراب.` },
            { text: "أَبْصَٰرُهَا خَٰشِعَةٌ", tafsir: `أي الأبصار المنسوبة إلى تلك القلوب ، أو أبصار أصحابها ( خاشِعَةٌ ) أي ذليلة ، لا تنظر إلا من طرف خفي خشية ورهبة وخوفا وخجلا.` },
            { text: "يَقُولُونَ أَءِنَّا لَمَرْدُودُونَ فِى ٱلْحَافِرَةِ", tafsir: `أصحاب تلك القلوب ( أَ إِنَّا لَمَرْدُودُونَ فِي الْحافِرَةِ ) أي الطريقة التي جئنا فيها ، فإن « الحافرة » هي الطريقة التي مرّ فيها الإنسان ، تسمى بذلك باعتبار أنه حفرها بتأثير أقدامه فيها. وهذا حكاية عن أولئك ، حال كونهم في الدنيا حيث يتساءلون : هل نحن نرجع إلى الحياة بعد الموت حتى نكون كالسابق ؟ وهذا استفهام إنكاري منهم للمعاد.` },
            { text: "أَءِذَا كُنَّا عِظَٰمًا نَّخِرَةً", tafsir: `أي وقت كنا عظاما بالية ، من « نخر » : إذا ( 1) المزمل : 15. قالُوا تِلْكَ إِذاً كَرَّةٌ خاسِرَةٌ (12) فَإِنَّما هِيَ زَجْرَةٌ واحِدَةٌ (13) فَإِذا هُمْ بِالسَّاهِرَةِ (14) هَلْ أَتاكَ حَدِيثُ مُوسى (15) بلى. أي كيف نرجع إلى حالتنا الأولى بعد أن متنا وصرنا عظاما ؟.` },
            { text: "قَالُوا۟ تِلْكَ إِذًا كَرَّةٌ خَاسِرَةٌ", tafsir: `هؤلاء المنكرون للمعاد ( تِلْكَ ) أي تلك الرجعة التي تقولون بها أنتم المؤمنون ( إِذاً ) أي إذا كانت كما تقولون ( كَرَّةٌ ) أي رجعة إلى الدنيا ( خاسِرَةٌ ) فإن الإنسان خاسر في تلك الكرة ، وإنما أسندت الخسارة إلى الكرة مجازا ، بعلاقة الظرف والمظروف. وقد قال الكفار ذلك على وجه الاستهزاء ، لأنهم لم يكونوا يرضون بذلك. [14] وجاء الردّ عليهم بقوله : ( فَإِنَّما هِيَ زَجْرَةٌ واحِدَةٌ ) أي أن الكرة ليست صعبة على الله سبحانه ، وإنما الكرة هي صيحة واحدة يصيح بها إسرافيل في الصور ـ في النفخة الثانية ـ وسميت الصيحة « زجرة » لأنها تزجر وتردع المخاطب عن سيره الأول إلى نحو السير الثاني.` },
            { text: "فَإِنَّمَا هِىَ زَجْرَةٌ وَٰحِدَةٌ", tafsir: `` },
            { text: "فَإِذَا هُم بِٱلسَّاهِرَةِ", tafsir: `أي البشر كلهم ( بِالسَّاهِرَةِ ) أي راجعون عن بطون الأرض إلى ظاهرها ، فإن « الساهرة » هي وجه الأرض ، وإنما سميت بذلك لأن الإنسان يسهر عليها ولا ينام ـ إذا كان في صحراء ـ خوفا من العدو والسبع ـ بعلاقة الحال والمحل ، فإن الإنسان يسهر في الأرض ، لكن السهر نسب إلى المحل. وفيه إشارة إلى أن المحشر يكون في أرض مستوية كالفلات لا اعوجاج فيها ولا بناء ولا شجر. [16] ثم يأتي السياق ليبين طرفا من قصة موسى وفرعون ليعتبر الكفار كيف عوقب فرعون لما لم يؤمن ( هَلْ أَتاكَ ) أي هل جاءك وهل سمعت ( حَدِيثُ مُوسى ) أي قصته. إِذْ ناداهُ رَبُّهُ بِالْوادِ الْمُقَدَّسِ طُوىً (16) اذْهَبْ إِلى فِرْعَوْنَ إِنَّهُ طَغى (17) فَقُلْ هَلْ لَكَ إِلى أَنْ تَزَكَّى (18) وَأَهْدِيَكَ إِلى رَبِّكَ فَتَخْشى (19) فَأَراهُ الْآيَةَ الْكُبْرى (20) فَكَذَّبَ وَعَصى (21) ثُمَّ أَدْبَرَ يَسْعى (22)` },
            { text: "هَلْ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ", tafsir: `` },
            { text: "إِذْ نَادَىٰهُ رَبُّهُۥ بِٱلْوَادِ ٱلْمُقَدَّسِ طُوًى", tafsir: `أي في حين ( ناداهُ رَبُّهُ بِالْوادِ الْمُقَدَّسِ ) أول ما أوحى سبحانه إليه عند مرجعه من « مدين » شعيب إلى أرض مصر ( طُوىً ) اسم للوادي الذي كلّم الله فيه موسى ، وأوحى إليه بالنبوة. [18] قائلا له ( اذْهَبْ إِلى فِرْعَوْنَ ) الملك الطاغي ( إِنَّهُ طَغى ) أي تجاوز الحد في الكفر والعصيان.` },
            { text: "ٱذْهَبْ إِلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغَىٰ", tafsir: `` },
            { text: "فَقُلْ هَل لَّكَ إِلَىٰٓ أَن تَزَكَّىٰ", tafsir: `يا موسى له ( هَلْ لَكَ ) طلب بصورة الاستفهام تأدبا ( إِلى أَنْ تَزَكَّى ) أي هل لك رغبة في أن تسلم ، وتطهر نفسك عن الكفر والعصيان ؟` },
            { text: "وَأَهْدِيَكَ إِلَىٰ رَبِّكَ فَتَخْشَىٰ", tafsir: `هل لك أن ( أَهْدِيَكَ إِلى رَبِّكَ ) أي أدلك عليه ، فإن الإنسان لا يعرف مزاياه سبحانه إلا بعد الإرشاد والهداية ( فَتَخْشى ) أي تخشاه باجتناب الكفر والعصيان ، إذ الخشية إنما تكون بعد المعرفة.` },
            { text: "فَأَرَىٰهُ ٱلْـَٔايَةَ ٱلْكُبْرَىٰ", tafsir: `أي أرى موسى عليه‌السلام فرعون ( الْآيَةَ ) أي المعجزة ( الْكُبْرى ) وهي العصا ، أو المراد جنس الآية من جميع آياته التسع.` },
            { text: "فَكَذَّبَ وَعَصَىٰ", tafsir: `فرعون بالآيات ( وَعَصى ) موسى فلم يتمثل أمره في الإذعان لله سبحانه.` },
            { text: "ثُمَّ أَدْبَرَ يَسْعَىٰ", tafsir: `فرعون ، أي ولّى الدبر ( يَسْعى ) ويجتهد ليطلب ما يكسر فَحَشَرَ فَنادى (23) فَقالَ أَنَا رَبُّكُمُ الْأَعْلى (24) فَأَخَذَهُ اللهُ نَكالَ الْآخِرَةِ وَالْأُولى (25) إِنَّ فِي ذلِكَ لَعِبْرَةً لِمَنْ يَخْشى (26) أَ أَنْتُمْ أَشَدُّ خَلْقاً أَمِ السَّماءُ بَناها (27) به حجة موسى ، ويبطل به نبوته.` },
            { text: "فَحَشَرَ فَنَادَىٰ", tafsir: `فرعون ، أي جمع حاشيته وجنوده ( فَنادى ) وخطب فيهم.` },
            { text: "فَقَالَ أَنَا۠ رَبُّكُمُ ٱلْأَعْلَىٰ", tafsir: `لهم : ( أَنَا رَبُّكُمُ الْأَعْلى ) فإن الأصنام تحت ألوهيتي ، وإنما الرب الأعلى ـ الذي لا رب فوقه ـ هو أنا ، لا كما يزعم موسى بأن لي إلها فوقي.` },
            { text: "فَأَخَذَهُ ٱللَّهُ نَكَالَ ٱلْـَٔاخِرَةِ وَٱلْأُولَىٰٓ", tafsir: `بالعذاب ، وهو إغراقه وجنوده في البحر وإدخاله النار ( نَكالَ الْآخِرَةِ وَالْأُولى ) « النكال » هو العقوبة ، وهو مصدر تأكيدي ، لأن معنى « أخذ » نكل به ، أي عاقبه سبحانه عقوبة الآخرة في النار ، وعقوبة الأولى بالغرق ، أي عذبه بالصنفين من العذاب.` },
            { text: "إِنَّ فِى ذَٰلِكَ لَعِبْرَةً لِّمَن يَخْشَىٰٓ", tafsir: `النكال الذي حلّ بفرعون ( لَعِبْرَةً ) أي لعظة واعتبارا ( لِمَنْ يَخْشى ) النكال والعقاب ، كي يعتبر به ويعلم أن الكفر عاقبته العقاب والنكال. [28] وبعد ما أتم قصة فرعون ـ في سرعة موقظة ـ يأتي السياق ليحدد من اعتزاز الكفار بقوتهم أمام أمر الله سبحانه ، مبينا أنهم لا شيء قبال خلق الله سبحانه ، فكيف بهم في قبال أمره سبحانه ؟ ( أَ أَنْتُمْ ) أيها البشر ، أو يا كفار مكة ( أَشَدُّ خَلْقاً ) وأقوى استحكاما ( أَمِ السَّماءُ ) ولا شك أن الجواب : كون السماء أشد. وهذا لا ينافي كون الإنسان ألطف وأدق وأجمل خلقا ، لأن الكلام في الشدة لا في الجمال والدقة ( بَناها ) الله رَفَعَ سَمْكَها فَسَوَّاها (28) وَأَغْطَشَ لَيْلَها وَأَخْرَجَ ضُحاها (29) وَالْأَرْضَ بَعْدَ ذلِكَ دَحاها (30) أَخْرَجَ مِنْها ماءَها وَمَرْعاها (31) وَالْجِبالَ أَرْساها (32) سبحانه ، وباني السماء لا يصعب عليه شيء ، ولا تعادل قوته قوة.` },
            { text: "ءَأَنتُمْ أَشَدُّ خَلْقًا أَمِ ٱلسَّمَآءُ بَنَىٰهَا", tafsir: `` },
            { text: "رَفَعَ سَمْكَهَا فَسَوَّىٰهَا", tafsir: `الله ( سَمْكَها ) أي سقفها ، فإن السمك هو الارتفاع أي أنه سبحانه رفع كثيرا السماوات في جهة الطول ( فَسَوَّاها ) أي عدلها بلا شقوق ولا فطور ولا فساد وخلل.` },
            { text: "وَأَغْطَشَ لَيْلَهَا وَأَخْرَجَ ضُحَىٰهَا", tafsir: `أي أظلمها ( وَأَخْرَجَ ضُحاها ) أي أظهر ضياءها. وإنما نسب الأمران إلى السماء لأنها مصدرهما ، بطلوع الشمس وغروبها.` },
            { text: "وَٱلْأَرْضَ بَعْدَ ذَٰلِكَ دَحَىٰهَآ", tafsir: `أي بعد خلق السماوات وتنظيم أمورها ( دَحاها ) أي بسطها ، فإنه سبحانه أولا خلق الأرض غير مدحوة ، ثم خلق السماوات ، ثم دحى الأرض ، و « الدحو » هو البسط ، وقد استدلّ علماء الفلك بهذه الآية على حركة الأرض ، لأن الدحو هو الرمي المستلزم للحركة ، ولذا يقال للإمام أمير المؤمنين عليه‌السلام « داحي الباب » كذا استدلوا بقوله ( أَ لَمْ نَجْعَلِ الْأَرْضَ كِفاتاً ) (1) من كفت الطير : إذ طار والله العالم.` },
            { text: "أَخْرَجَ مِنْهَا مَآءَهَا وَمَرْعَىٰهَا", tafsir: `أي من الأرض ( ماءَها ) بأن فجّر العيون وفلق البحار ( وَمَرْعاها ) أي مروجها التي هي محل رعي الحيوانات والبهائم وذلك بمعنى أنه سبحانه خلق فيها الأعشاب والنبات.` },
            { text: "وَٱلْجِبَالَ أَرْسَىٰهَا", tafsir: `أي أثبتها في أطراف الأرض لئلا تتزلزل ( 1) المرسلات : 26. مَتاعاً لَكُمْ وَلِأَنْعامِكُمْ (33) فَإِذا جاءَتِ الطَّامَّةُ الْكُبْرى (34) يَوْمَ يَتَذَكَّرُ الْإِنْسانُ ما سَعى (35) وَبُرِّزَتِ الْجَحِيمُ لِمَنْ يَرى (36) فَأَمَّا مَنْ طَغى (37) وَآثَرَ الْحَياةَ الدُّنْيا (38) الأرض وتضطرب. [34] وإنما فعل كل ذلك ( مَتاعاً لَكُمْ وَلِأَنْعامِكُمْ ) أي لأجل تمتعكم ومنفعتكم أنتم البشر ، وتمتع أنعامكم بالسكون في الأرض ، وتحصيلكم المعايش ورعي البهائم ، « وأنعام » جمع نعم ، وهي الإبل والبقر والغنم.` },
            { text: "مَتَٰعًا لَّكُمْ وَلِأَنْعَٰمِكُمْ", tafsir: `` },
            { text: "فَإِذَا جَآءَتِ ٱلطَّآمَّةُ ٱلْكُبْرَىٰ", tafsir: `هي القيامة ، سميت بذلك لأنها تطم أي تعلو وتغلب على كل شيء ، يقال « طم الطائر الشجرة » أي علاها وتسمى الداهية « طامة » لأنها تعلو الشيء وتغلبه ( الْكُبْرى ) لأنها أكبر من كل داهية هائلة. [36] وذلك ( يَوْمَ يَتَذَكَّرُ الْإِنْسانُ ما سَعى ) أي ما عمله من خير وشر ، فإن الإنسان في ذلك اليوم يتذكر كل عمل عمله إما ذكرا في الخاطر ، وإما ذكرا من مطالعة كتابه الذي كتبه الملكان الموكلان به.` },
            { text: "يَوْمَ يَتَذَكَّرُ ٱلْإِنسَٰنُ مَا سَعَىٰ", tafsir: `` },
            { text: "وَبُرِّزَتِ ٱلْجَحِيمُ لِمَن يَرَىٰ", tafsir: `يوم ( بُرِّزَتِ ) أي أظهرت ، والمظهر لها هو الله سبحانه ( الْجَحِيمُ ) هي جهنم ( لِمَنْ يَرى ) أي لكل من تأتي منه الرؤية ، فإنهم يرونها ظاهرة مكشوفة ، وجواب « إذا » محذوف ، أي كان الناس قسمين ، وإنما حذف لدلالة ما بعده عليه.` },
            { text: "فَأَمَّا مَن طَغَىٰ", tafsir: `أي تكبر وتجاوز الحد في كفره وعصيانه.` },
            { text: "وَءَاثَرَ ٱلْحَيَوٰةَ ٱلدُّنْيَا", tafsir: `أي اختار ( الْحَياةَ الدُّنْيا ) على الحياة الآخرة ، بأن كانت فَإِنَّ الْجَحِيمَ هِيَ الْمَأْوى (39) وَأَمَّا مَنْ خافَ مَقامَ رَبِّهِ وَنَهَى النَّفْسَ عَنِ الْهَوى (40) فَإِنَّ الْجَنَّةَ هِيَ الْمَأْوى (41) يَسْئَلُونَكَ عَنِ السَّاعَةِ أَيَّانَ مُرْساها (42) فِيمَ أَنْتَ مِنْ ذِكْراها (43) أعماله للدنيا ولم يعمل شيئا للآخرة.` },
            { text: "فَإِنَّ ٱلْجَحِيمَ هِىَ ٱلْمَأْوَىٰ", tafsir: `له ، « والمأوى » من آوى ، بمعنى اتخذ المنزل ، أي أن مصيره إلى النار الكثيرة ـ فإن الجحيم بمعنى ذلك.` },
            { text: "وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِۦ وَنَهَى ٱلنَّفْسَ عَنِ ٱلْهَوَىٰ", tafsir: `أي المقام المربوط بالرب تعالى وهو يوم القيامة ، والإضافة تشريفية ، من قبيل « بيت الله » بمعنى خاف عذاب الآخرة ( وَنَهَى النَّفْسَ عَنِ الْهَوى ) أي نهى نفسه وحفظها من أن يتبع هواها ومشتهياتها في ارتكاب المحرمات وترك الواجبات.` },
            { text: "فَإِنَّ ٱلْجَنَّةَ هِىَ ٱلْمَأْوَىٰ", tafsir: `له ، فإنه يصير إليها. [43] وحيث كان الكلام في القيامة أتى السياق لجواب سؤال الناس عن وقت القيامة ( يَسْئَلُونَكَ ) يا رسول الله ( عَنِ السَّاعَةِ ) أي القيامة ( أَيَّانَ مُرْساها ) أي متى يكون قيامها ، من « الإرساء » وهو الثبوت والاستقرار.` },
            { text: "يَسْـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَيَّانَ مُرْسَىٰهَا", tafsir: `` },
            { text: "فِيمَ أَنتَ مِن ذِكْرَىٰهَآ", tafsir: `أي فيما ذا أنت يا رسول الله ( مِنْ ذِكْراها ) أي من تذكر الساعة فإنك لا تعلم وقت قيامها ، كأن الإنسان إذا كان داخلا في شيء علم مزاياه ، أما إذا كان خارجا لا يعلم خصوصياته ، و « فيم أنت » للإنكار ، أي لست من ذكراها في شيء حتى تعلمها فإنما علمها خاص بالله سبحانه. إِلى رَبِّكَ مُنْتَهاها (44) إِنَّما أَنْتَ مُنْذِرُ مَنْ يَخْشاها (45) كَأَنَّهُمْ يَوْمَ يَرَوْنَها لَمْ يَلْبَثُوا إِلاَّ عَشِيَّةً أَوْ ضُحاها (46)` },
            { text: "إِلَىٰ رَبِّكَ مُنتَهَىٰهَآ", tafsir: `يا رسول الله ( مُنْتَهاها ) أي انتهاء علم الساعة إلى الله سبحانه ، فإذا سئل شخص عن الساعة حوّله المسئول عنه إلى غيره وغيره إلى آخر ، وهكذا حتى ينتهي إلى الله الذي هو عالم بوقتها ، والمنتهى أضيف إلى الساعة ، والمراد بها وقتها ـ بعلاقة الملابسة ـ . [46] وليس علم وقت الساعة مربوطا بك ، ف ( إِنَّما أَنْتَ ) يا رسول الله ( مُنْذِرُ مَنْ يَخْشاها ) أي شأنك الإنذار لمن يخشى من الساعة ، وإنما خص الإنذار بهم لأنهم المنتفعون بالإنذار دون سواهم. [47] ثم جاء السياق لينذر الناس ويذكرهم بأن لبثهم في الدنيا قليل حتى ( كَأَنَّهُمْ ) أي الناس ( يَوْمَ يَرَوْنَها ) أي يرون الساعة ، فيما إذا قامت عليهم ( لَمْ يَلْبَثُوا ) أي لم يمكثوا ولم يبقوا في الدنيا ( إِلَّا عَشِيَّةً ) أي مقدار عصر يوم ( أَوْ ضُحاها ) أو صبح تلك العشية ، والمعنى يظنون أنهم لم يكونوا في الدنيا إلا نصف يوم صباحا أو مساء. (80)` },
            { text: "إِنَّمَآ أَنتَ مُنذِرُ مَن يَخْشَىٰهَا", tafsir: `` },
            { text: "كَأَنَّهُمْ يَوْمَ يَرَوْنَهَا لَمْ يَلْبَثُوٓا۟ إِلَّا عَشِيَّةً أَوْ ضُحَىٰهَا", tafsir: `` }
        ]
    }
});
